def _metadata_prepare_request_context(request: dict[str, Any]) -> dict[str, Any]:
    source_url = request.get("source_url") or request.get("source") or request.get("source_link") or request.get("url")
    source_info = request.get("source_info") if isinstance(request.get("source_info"), dict) else {}
    context = {
        "job_id": request.get("job_id") or request.get("parent_job_id") or request.get("retorrent_job_id"),
        "parent_job_id": request.get("parent_job_id") or request.get("job_id") or request.get("retorrent_job_id"),
        "source_url": str(source_url) if source_url else None,
        "source": str(source_url) if source_url else request.get("source"),
        "source_tracker": request.get("source_tracker") or request.get("from") or source_info.get("tracker"),
        "target": request.get("target") or request.get("target_tracker") or request.get("target_trackers"),
        "target_tracker": request.get("target_tracker"),
        "target_trackers": request.get("target_trackers"),
        "accept_rules": _truthy(request.get("accept_rules")),
        "confirm_upload": _truthy(request.get("confirm_upload")),
        "path": request.get("path") or request.get("content_path"),
        "content_path": request.get("content_path") or request.get("path"),
        "save_path": request.get("save_path"),
        "config": request.get("config"),
        "base_dir": request.get("base_dir"),
        "dry_run": _truthy(request.get("dry_run")),
        "fetch_ptgen": _truthy(request.get("fetch_ptgen")),
        "source_info": source_info,
        "metadata_file": request.get("metadata_file"),
        "ptgen_description_file": request.get("ptgen_description_file"),
        "imdb_id": request.get("imdb_id"),
        "tmdb_id": request.get("tmdb_id"),
        "tmdb_type": request.get("tmdb_type"),
        "douban_id": request.get("douban_id"),
        "douban_url": request.get("douban_url"),
        "qbit_category": request.get("qbit_category"),
        "qbit_tags": request.get("qbit_tags"),
        "qbit_upload_limit": request.get("qbit_upload_limit"),
        "qbit_download_limit": request.get("qbit_download_limit"),
        "uploaded_qbit_category": request.get("uploaded_qbit_category"),
        "uploaded_qbit_tags": request.get("uploaded_qbit_tags"),
        "uploaded_qbit_upload_limit": request.get("uploaded_qbit_upload_limit"),
        "uploaded_qbit_download_limit": request.get("uploaded_qbit_download_limit"),
    }
    if source_url:
        try:
            context["source_reference"] = resolve_source_reference(str(source_url), tracker=context.get("source_tracker"))
        except Exception as exc:
            context["source_reference"] = {"requested_source": str(source_url), "error": str(exc)}
    return context


def _metadata_prepare_dry_run_payload(context: dict[str, Any]) -> dict[str, Any]:
    overrides = _metadata_prepare_overrides(context)
    source_info = dict(context["source_info"]) if isinstance(context.get("source_info"), dict) else {}
    material_options = _metadata_prepare_material_options({**source_info, **overrides}, context)
    blockers = [] if source_info or context.get("source_url") or overrides else ["source_info, source_url, or metadata overrides are required."]
    handoff = _metadata_prepare_handoff(context, material_options, not blockers, blockers)
    return {
        "kind": "ptcli.metadata_prepare",
        "status": "ok" if not blockers else "blocked",
        "ok": not blockers,
        "ready": not blockers,
        "dry_run": True,
        "mutates_state": False,
        "mutates_filesystem": False,
        "mutates_network": False,
        "live_upload": False,
        "request": context,
        "source_reference": context.get("source_reference"),
        "source_info": source_info,
        "metadata_enrichment": {"status": "dry_run", "ready": not blockers, "applied": overrides, "missing": [], "readiness": {}, "field_evidence": {}, "sources": ["overrides"] if overrides else [], "ptgen_evidence": {}, "blockers": blockers},
        "material_options": material_options,
        "material_evidence": _metadata_prepare_evidence({**source_info, **overrides}, material_options, {}),
        "metadata_prepare_handoff": handoff,
        "resume_handoff": handoff,
        "recommended_request": handoff.get("recommended_request"),
        "blockers": blockers,
        "next_actions": _metadata_prepare_next_actions(not blockers, blockers),
        "safety": _metadata_prepare_safety(context),
    }


def _metadata_prepare_overrides(context: dict[str, Any]) -> dict[str, Any]:
    overrides: dict[str, Any] = {}
    try:
        overrides.update(load_metadata_overrides(context.get("metadata_file")))
        overrides.update(load_ptgen_description_override(context.get("ptgen_description_file")))
    except (OSError, ValueError, json.JSONDecodeError) as exc:
        overrides["_load_error"] = str(exc)
    overrides.update(
        normalize_metadata_overrides(
            {
                "imdb_id": context.get("imdb_id"),
                "tmdb_id": context.get("tmdb_id"),
                "tmdb_type": context.get("tmdb_type"),
                "douban_id": context.get("douban_id"),
                "douban_url": context.get("douban_url"),
            }
        )
    )
    return {key: value for key, value in overrides.items() if value not in (None, "", [])}


def _metadata_prepare_readiness_blockers(result: dict[str, Any], *, fetch_ptgen: bool) -> list[str]:
    blockers = []
    missing = _string_list(result.get("missing"))
    if missing:
        blockers.append(f"Missing metadata after enrichment: {', '.join(missing)}")
    source_info = result.get("source_info") if isinstance(result.get("source_info"), dict) else {}
    if fetch_ptgen and not source_info.get("ptgen_description"):
        blockers.append("PTGen/Douban description is missing after enrichment.")
    return blockers


def _metadata_prepare_material_options(source_info: dict[str, Any], context: dict[str, Any]) -> dict[str, Any]:
    options: dict[str, Any] = {}
    for key in ("metadata_file", "ptgen_description_file"):
        if context.get(key) not in (None, ""):
            options[key] = context[key]
    for key in ("imdb_id", "tmdb_id", "tmdb_type", "douban_id", "douban_url"):
        if source_info.get(key) not in (None, ""):
            options[key] = source_info[key]
    if source_info.get("ptgen_description"):
        options["fetch_ptgen"] = True
    return options


def _metadata_prepare_evidence(source_info: dict[str, Any], material_options: dict[str, Any], result: dict[str, Any]) -> dict[str, Any]:
    ptgen_description = str(source_info.get("ptgen_description") or "")
    return {
        "metadata_fields": {
            key: {"ready": bool(source_info.get(key)), "value": source_info.get(key)}
            for key in ("imdb_id", "tmdb_id", "tmdb_type", "douban_id", "douban_url")
        },
        "ptgen_description": {"ready": bool(ptgen_description), "length": len(ptgen_description)},
        "metadata_file": _materials_path_evidence(material_options.get("metadata_file")),
        "ptgen_description_file": _materials_path_evidence(material_options.get("ptgen_description_file")),
        "field_evidence": result.get("field_evidence") if isinstance(result.get("field_evidence"), dict) else {},
        "ptgen_evidence": result.get("ptgen_evidence") if isinstance(result.get("ptgen_evidence"), dict) else {},
    }


def _metadata_prepare_handoff(context: dict[str, Any], material_options: dict[str, Any], ready: bool, blockers: list[str]) -> dict[str, Any]:
    parent_job_id = str(context.get("parent_job_id") or context.get("job_id") or "").strip()
    resume_endpoint = f"/v1/jobs/{parent_job_id}/resume" if parent_job_id else "/v1/jobs/{job_id}/resume"
    resume_request = {"overrides": material_options, "dry_run": True, **({"job_id": parent_job_id} if parent_job_id else {})}
    submit_request = _materials_prepare_submit_request(context, material_options)
    next_step = _materials_prepare_next_step(parent_job_id, submit_request, resume_request, ready, blockers)
    return {
        "kind": "ptcli.metadata_prepare_handoff",
        "ready": ready,
        "parent_job_id": parent_job_id or None,
        "material_options": material_options,
        "accepted_override_keys": sorted(material_options),
        "recommended_tool": next_step.get("tool"),
        "recommended_endpoint": next_step.get("endpoint") or resume_endpoint,
        "method": "POST",
        "recommended_request": next_step.get("request") or resume_request,
        "resume_request": resume_request,
        "execute_request": {**resume_request, "dry_run": False},
        "source_url_check_and_submit_request": submit_request,
        "next_step": next_step,
        "continue_when": "Use resume_request for an existing blocked job, or source_url_check_and_submit_request for a fresh source URL flow after duplicate/rule/confirmation gates are ready.",
        "stop_when": ["blockers is not empty", "live upload confirmations are missing", "site policy gate is not ready"],
        "blockers": blockers,
        "next_actions": _metadata_prepare_next_actions(ready, blockers),
    }


def _metadata_prepare_next_actions(ready: bool, blockers: list[str]) -> list[str]:
    if ready:
        return ["Use metadata_prepare_handoff.next_step to resume an existing retorrent job or continue source_url_check_and_submit with metadata material_options."]
    if blockers:
        return ["Resolve metadata_prepare.blockers, provide source_info/source_url or metadata overrides, then rerun metadata_prepare."]
    return ["Provide source_url/source_info and set fetch_ptgen=true when a PTGen/Douban description is required."]


def _metadata_prepare_safety(context: dict[str, Any]) -> dict[str, Any]:
    return {
        "does_not_upload_to_tracker": True,
        "live_upload": False,
        "requires_confirmation": [],
        "may_contact_source_tracker": bool(context.get("source_url")),
        "may_contact_tmdb": True,
        "may_contact_ptgen_or_douban": bool(context.get("fetch_ptgen")),
    }


def _metadata_prepare_needs_tmdb_api(source_info: dict[str, Any], overrides: dict[str, Any]) -> bool:
    merged = {**source_info, **{key: value for key, value in overrides.items() if not key.startswith("_")}}
    return bool((merged.get("imdb_id") and not merged.get("tmdb_id")) or (merged.get("tmdb_id") and not merged.get("imdb_id")))


def _target_package_prepare_context(request: dict[str, Any]) -> dict[str, Any]:
    raw_target = request.get("target") or request.get("target_trackers") or "MTEAM"
    target_trackers = parse_tracker_list(",".join(str(item) for item in raw_target)) if isinstance(raw_target, list) else parse_tracker_list(str(raw_target))
    source_info = request.get("source_info") if isinstance(request.get("source_info"), dict) else {}
    metadata_options = request.get("metadata_options") if isinstance(request.get("metadata_options"), dict) else {}
    material_options = request.get("material_options") if isinstance(request.get("material_options"), dict) else {}
    flat_options = _request_material_options(request)
    merged_material_options = {**metadata_options, **material_options, **flat_options}
    merged_source_info = {**source_info}
    for key in ("imdb_id", "tmdb_id", "tmdb_type", "douban_id", "douban_url"):
        if merged_material_options.get(key) not in (None, "") and not merged_source_info.get(key):
            merged_source_info[key] = merged_material_options[key]
    metadata_enrichment = request.get("metadata_enrichment") if isinstance(request.get("metadata_enrichment"), dict) else {}
    return {
        "source_info": merged_source_info,
        "metadata_enrichment": metadata_enrichment,
        "target": target_trackers[0] if len(target_trackers) == 1 else target_trackers,
        "target_trackers": target_trackers,
        "path": request.get("path") or request.get("content_path"),
        "content_path": request.get("content_path") or request.get("path"),
        "output_dir": str(request.get("output_dir") or request.get("target_output_dir") or "./tmp/target"),
        "package_dir": request.get("package_dir"),
        "target_torrent_file": request.get("target_torrent_file") or request.get("torrent_file"),
        "accept_rules": _truthy(request.get("accept_rules")),
        "target_execute": _truthy(request.get("target_execute") or request.get("execute")),
        "write_payload": _truthy(request.get("write_payload")),
        "dry_run": _truthy(request.get("dry_run")),
        "material_options": merged_material_options,
        "duplicate_check": request.get("duplicate_check") if isinstance(request.get("duplicate_check"), dict) else {},
        "rule_check": request.get("rule_check") if isinstance(request.get("rule_check"), dict) else {},
        "qbit_evidence": request.get("qbit_evidence") if isinstance(request.get("qbit_evidence"), dict) else {},
        "content_verified": _truthy(request.get("content_verified")),
        "parent_job_id": request.get("parent_job_id") or request.get("job_id") or request.get("retorrent_job_id"),
    }


def _target_package_prepare_dry_run_payload(context: dict[str, Any]) -> dict[str, Any]:
    blockers = _target_package_prepare_context_blockers(context)
    ready = not blockers
    package_preview = {"package_dir": context.get("package_dir"), "files": {}, "blockers": blockers}
    preflight = {"status": "blocked" if blockers else "dry_run", "blockers": blockers}
    handoff = _target_package_prepare_handoff(context, package_preview, preflight, ready, blockers)
    return {
        "kind": "ptcli.target_package_prepare",
        "status": "ok" if ready else "blocked",
        "ok": ready,
        "ready": ready,
        "dry_run": True,
        "mutates_state": False,
        "mutates_filesystem": False,
        "mutates_network": False,
        "live_upload": False,
        "request": context,
        "package_dir": context.get("package_dir"),
        "files": {},
        "description_draft": None,
        "package": package_preview,
        "target_upload_preflight": preflight,
        "target_package_handoff": handoff,
        "recommended_request": handoff.get("recommended_request"),
        "blockers": blockers,
        "next_actions": _target_package_prepare_next_actions(ready, blockers),
        "safety": _target_package_prepare_safety(context),
    }


def _target_package_prepare_context_blockers(context: dict[str, Any]) -> list[str]:
    blockers: list[str] = []
    if "MTEAM" not in context.get("target_trackers", []):
        blockers.append("target must include MTEAM for target package preparation.")
    if not context.get("source_info"):
        blockers.append("source_info is required to prepare an MTEAM package.")
    if not context.get("path"):
        blockers.append("path or content_path is required for package content evidence.")
    return blockers


def _target_package_prepare_stages(context: dict[str, Any]) -> list[dict[str, Any]]:
    stages = []
    rule_check = context.get("rule_check") if isinstance(context.get("rule_check"), dict) else {}
    if rule_check:
        stages.append({"stage": "rule-check", "ok": bool(rule_check.get("ready")), "result": rule_check})
    else:
        stages.append({"stage": "rule-check", "ok": False, "result": {"ready": False, "checks": [], "rule_obligations": [], "blockers": ["rule_check is required before live upload."]}})
    duplicate_check = context.get("duplicate_check") if isinstance(context.get("duplicate_check"), dict) else {}
    if duplicate_check:
        stages.append({"stage": "target-dupe-check", "ok": duplicate_check.get("searched") is True and not duplicate_check.get("exists"), "result": duplicate_check})
    else:
        stages.append({"stage": "target-dupe-check", "ok": False, "result": {"searched": False, "count": 0, "dupes": [], "blockers": ["duplicate_check is required before live upload."]}})
    if context.get("content_verified"):
        stages.append({"stage": "match", "ok": True, "result": {"matches": [{"hash": context.get("qbit_evidence", {}).get("hash") or "verified", "content_path": context.get("path")}], "source": "target_package_prepare_request"}})
    return stages


def _target_package_description_evidence(package: dict[str, Any]) -> dict[str, Any] | None:
    files = package.get("files") if isinstance(package.get("files"), dict) else {}
    description_file = files.get("description_draft")
    if not description_file:
        return None
    evidence = _materials_path_evidence(description_file)
    if not evidence:
        return None
    text = ""
    if evidence.get("exists"):
        try:
            text = Path(str(description_file)).expanduser().read_text(encoding="utf-8", errors="replace")
        except OSError:
            text = ""
    return {**evidence, "length": len(text), "has_ptgen": "[b]Movie information[/b]" in text and "PTGen/Douban description: missing" not in text, "has_screenshots": "[img]" in text}


def _target_package_prepare_handoff(context: dict[str, Any], package: dict[str, Any], preflight: dict[str, Any], ready: bool, blockers: list[str]) -> dict[str, Any]:
    package_dir = package.get("package_dir") or context.get("package_dir")
    target_upload_request = {
        "package_dir": package_dir,
        "torrent_file": context.get("target_torrent_file") or "<MTEAM-safe target torrent file>",
        "write_payload": True,
    }
    resume_request = {"overrides": {"package_dir": package_dir}, "dry_run": True}
    if context.get("parent_job_id"):
        resume_request["job_id"] = context["parent_job_id"]
    next_step = {
        "tool": "target_upload_preflight" if ready else "target_package_prepare",
        "endpoint": "/v1/target/upload/preflight" if ready else "/v1/target/package/prepare",
        "method": "POST",
        "request": target_upload_request if ready else None,
        "reason": "package_ready_for_target_upload_preflight" if ready else "target_package_blocked",
    }
    return {
        "kind": "ptcli.target_package_handoff",
        "ready": ready,
        "package_dir": package_dir,
        "description_draft": _target_package_description_evidence(package),
        "target_upload_preflight_status": preflight.get("status"),
        "target_upload_request": target_upload_request,
        "resume_request": resume_request,
        "recommended_tool": next_step.get("tool"),
        "recommended_endpoint": next_step.get("endpoint"),
        "recommended_request": next_step.get("request"),
        "next_step": next_step,
        "continue_when": "Run target upload preflight only after package blockers, duplicate check, rule review, material checks, and MTEAM-safe torrent are ready.",
        "stop_when": ["blockers is not empty", "target_upload_preflight.blockers is not empty", "confirm_upload missing for live upload"],
        "blockers": blockers,
        "next_actions": _target_package_prepare_next_actions(ready, blockers),
    }


def _target_package_prepare_next_actions(ready: bool, blockers: list[str]) -> list[str]:
    if ready:
        return ["Review target_package_handoff.target_upload_request, then run target upload preflight with an MTEAM-safe torrent file before any live upload."]
    if blockers:
        return ["Resolve target_package_prepare.blockers, especially duplicate_check/rule_check/content/material evidence, then regenerate the package."]
    return ["Inspect target package and MTEAM upload preflight before live upload."]


def _target_package_prepare_safety(context: dict[str, Any]) -> dict[str, Any]:
    return {
        "does_not_upload_to_tracker": True,
        "live_upload": False,
        "writes_files": not bool(context.get("dry_run")),
        "requires_confirmation_before_live_upload": ["accept_rules=true", "confirm_upload=true"],
        "requires_before_ready": ["target duplicate check clear", "site rules acknowledged", "qBittorrent content evidence", "metadata/material evidence", "MTEAM-safe torrent file"],
    }


def _target_upload_request_context(request: dict[str, Any]) -> tuple[dict[str, Any], argparse.Namespace, list[str]]:
    package_dir = str(request.get("package_dir") or "").strip()
    if not package_dir:
        raise ServiceError("package_dir is required.", status=HTTPStatus.BAD_REQUEST)
    execute = _truthy(request.get("execute") or request.get("target_execute"))
    uploaded_torrent_id = request.get("uploaded_torrent_id")
    uploaded_torrent_file = request.get("uploaded_torrent_file")
    write_summary = _truthy_default(request.get("write_summary"), bool(execute or uploaded_torrent_id or uploaded_torrent_file or request.get("inject_uploaded_torrent") or request.get("wait_uploaded_complete")))
    context = {
        "config": request.get("config"),
        "package_dir": package_dir,
        "torrent_file": request.get("torrent_file") or request.get("target_torrent_file"),
        "write_payload": _truthy(request.get("write_payload")),
        "execute": execute,
        "confirm_upload": _truthy(request.get("confirm_upload")),
        "download_uploaded_torrent": _truthy(request.get("download_uploaded_torrent")),
        "uploaded_output_dir": request.get("uploaded_output_dir"),
        "uploaded_torrent_id": str(uploaded_torrent_id) if uploaded_torrent_id else None,
        "uploaded_torrent_file": str(uploaded_torrent_file) if uploaded_torrent_file else None,
        "inject_uploaded_torrent": _truthy(request.get("inject_uploaded_torrent")),
        "uploaded_save_path": request.get("uploaded_save_path") or request.get("path") or request.get("content_path"),
        "uploaded_qbit_category": request.get("uploaded_qbit_category"),
        "uploaded_qbit_tags": request.get("uploaded_qbit_tags"),
        "uploaded_qbit_upload_limit": request.get("uploaded_qbit_upload_limit"),
        "uploaded_qbit_download_limit": request.get("uploaded_qbit_download_limit"),
        "policy_enforcement_bundle": request.get("policy_enforcement_bundle") if isinstance(request.get("policy_enforcement_bundle"), dict) else None,
        "policy_enforcement_gate": request.get("policy_enforcement_gate") if isinstance(request.get("policy_enforcement_gate"), dict) else None,
        "uploaded_paused": _truthy(request.get("uploaded_paused")),
        "wait_uploaded_complete": _truthy(request.get("wait_uploaded_complete")),
        "uploaded_wait_timeout": _float_or_default(request.get("uploaded_wait_timeout"), 600.0),
        "uploaded_wait_interval": _float_or_default(request.get("uploaded_wait_interval"), 15.0),
        "check_runtime": _truthy(request.get("check_runtime")),
        "write_summary": write_summary,
        "summary_output_dir": request.get("summary_output_dir"),
        "client": str(request.get("client") or "default"),
        "json": True,
    }
    args = argparse.Namespace(**context)
    return context, args, _target_upload_command_argv(context)


def _target_upload_command_argv(context: dict[str, Any]) -> list[str]:
    argv = ["target-upload", "--package-dir", str(context["package_dir"])]
    option_map = {
        "config": "--config",
        "torrent_file": "--torrent-file",
        "uploaded_output_dir": "--uploaded-output-dir",
        "uploaded_torrent_id": "--uploaded-torrent-id",
        "uploaded_torrent_file": "--uploaded-torrent-file",
        "uploaded_save_path": "--uploaded-save-path",
        "uploaded_qbit_category": "--uploaded-qbit-category",
        "uploaded_qbit_tags": "--uploaded-qbit-tags",
        "uploaded_qbit_upload_limit": "--uploaded-qbit-upload-limit",
        "uploaded_qbit_download_limit": "--uploaded-qbit-download-limit",
        "summary_output_dir": "--summary-output-dir",
        "client": "--client",
    }
    for key, flag in option_map.items():
        value = context.get(key)
        if value not in (None, ""):
            argv.extend([flag, str(value)])
    flag_map = {
        "write_payload": "--write-payload",
        "execute": "--execute",
        "confirm_upload": "--confirm-upload",
        "download_uploaded_torrent": "--download-uploaded-torrent",
        "inject_uploaded_torrent": "--inject-uploaded-torrent",
        "uploaded_paused": "--uploaded-paused",
        "wait_uploaded_complete": "--wait-uploaded-complete",
        "check_runtime": "--check-runtime",
        "write_summary": "--write-summary",
    }
    for key, flag in flag_map.items():
        if context.get(key):
            argv.append(flag)
    argv.extend(["--uploaded-wait-timeout", str(context["uploaded_wait_timeout"]), "--uploaded-wait-interval", str(context["uploaded_wait_interval"]), "--json"])
    return argv


def _target_upload_service_diagnostics(result: dict[str, Any]) -> dict[str, Any]:
    summary = result.get("summary") if isinstance(result.get("summary"), dict) else {}
    artifacts = result.get("artifacts") if isinstance(result.get("artifacts"), dict) else {}
    preflight = result.get("preflight") if isinstance(result.get("preflight"), dict) else result
    preparation = summary.get("target_preparation_audit") if isinstance(summary.get("target_preparation_audit"), dict) else artifacts.get("target_preparation_audit") if isinstance(artifacts.get("target_preparation_audit"), dict) else {}
    completion = summary.get("completion_review") if isinstance(summary.get("completion_review"), dict) else {}
    payload_review = preparation.get("payload_review") if isinstance(preparation.get("payload_review"), dict) else {}
    blockers = list(dict.fromkeys(_string_list(result.get("blockers")) + _string_list(summary.get("blockers")) + _string_list(preparation.get("blockers"))))
    return {
        "mode": summary.get("mode") or result.get("status"),
        "ready": bool(summary.get("ready")) if isinstance(summary.get("ready"), bool) else result.get("status") in {"ready", "uploaded"} and not blockers,
        "uploaded": bool(summary.get("uploaded")),
        "ready_for_uploaded_seeding": bool(completion.get("complete")),
        "uploaded_torrent_id": summary.get("uploaded_torrent_id") or result.get("uploaded_torrent_id"),
        "uploaded_torrent_hash": summary.get("uploaded_torrent_hash"),
        "uploaded_torrent_path": summary.get("uploaded_torrent_path"),
        "preflight": {
            "ready": preparation.get("ready") if isinstance(preparation.get("ready"), bool) else preflight.get("status") == "ready",
            "status": preflight.get("status"),
            "payload_ready": _nested_bool(preparation, "payload", "payload_checks_ready"),
            "materials_ready": preparation.get("materials_ready"),
            "metadata_ready": preparation.get("metadata_ready"),
            "assets_ready": preparation.get("assets_ready"),
            "description_ready": preparation.get("description_ready"),
            "materials_ready_required": _nested_bool(preparation, "payload", "materials_ready_required"),
            "missing": _string_list(preparation.get("missing")),
            "description_missing": _nested_string_list(preparation, "description", "missing"),
            "blockers": list(dict.fromkeys(_string_list(preflight.get("blockers")) + _string_list(preparation.get("blockers")))),
        },
        "completion": completion,
        "payload_review": payload_review,
        "fresh_duplicate_check": summary.get("fresh_duplicate_check") if isinstance(summary.get("fresh_duplicate_check"), dict) else result.get("fresh_duplicate_check") if isinstance(result.get("fresh_duplicate_check"), dict) else None,
        "blockers": blockers,
        "next_actions": _string_list(result.get("next_actions")),
    }


def _target_upload_service_handoff(context: dict[str, Any], result: dict[str, Any], diagnostics: dict[str, Any], ready: bool, blockers: list[str]) -> dict[str, Any]:
    request = _target_upload_retry_request(context, execute=bool(context.get("execute")))
    synthetic_job = {"kind": "ptcli.target_upload", "request": context, "result": result, "status": "complete" if ready else "blocked", "blockers": blockers}
    return {
        "kind": "ptcli.target_upload_handoff",
        "ready": ready,
        "action": "complete" if ready else "resolve_blockers",
        "ready_for_live_upload": diagnostics.get("preflight", {}).get("ready") and not blockers,
        "uploaded_seeding_ready": bool(diagnostics.get("ready_for_uploaded_seeding")),
        "uploaded_seeding_evidence": _target_upload_uploaded_seeding_evidence(synthetic_job, result, diagnostics),
        "preflight": diagnostics.get("preflight"),
        "completion": diagnostics.get("completion"),
        "summary_file": result.get("summary_file"),
        "next_step": {"tool": "target_upload_job", "endpoint": "/v1/jobs/target/upload", "method": "POST", "request": request, "reason": "retry_or_complete_target_upload"},
        "recommended_tool": "target_upload_job",
        "recommended_endpoint": "/v1/jobs/target/upload",
        "recommended_request": request,
        "blockers": blockers,
        "next_actions": _target_upload_service_next_actions(ready, context, result, blockers),
    }


def _target_upload_retry_request(context: dict[str, Any], *, execute: bool) -> dict[str, Any]:
    request = {key: value for key, value in context.items() if key != "json" and value not in (None, "", False)}
    if execute:
        request["execute"] = True
    return request


def _target_upload_service_next_actions(ready: bool, context: dict[str, Any], result: dict[str, Any], blockers: list[str]) -> list[str]:
    if ready:
        return ["Target upload closure is complete; report summary_file, uploaded_torrent_hash, injected_torrent_hash, qBittorrent wait evidence, and duplicate/rule gates."]
    if blockers:
        return ["Resolve target_upload.blockers, then retry /v1/jobs/target/upload with target_upload_handoff.recommended_request."]
    if context.get("execute") and result.get("status") == "uploaded":
        return ["Download the uploaded MTEAM torrent, inject it into qBittorrent, wait for completion, then rerun target upload summary verification."]
    return ["Inspect target_upload_handoff and target_upload_diagnostics before attempting live upload."]


def _target_upload_service_safety(context: dict[str, Any]) -> dict[str, Any]:
    return {
        "live_upload": bool(context.get("execute")),
        "requires_confirmation_before_live_upload": ["accept_rules=true via package rule review", "confirm_upload=true"],
        "requires_for_full_closure": ["download_uploaded_torrent=true", "inject_uploaded_torrent=true", "wait_uploaded_complete=true", "uploaded_save_path/path available"],
        "does_not_skip_duplicate_check": True,
        "does_not_skip_rule_gate": True,
        "mutates_qbittorrent": bool(context.get("inject_uploaded_torrent")),
    }


def _target_upload_preflight_next_actions(preflight: dict[str, Any]) -> list[str]:
    blockers = _string_list(preflight.get("blockers"))
    if blockers:
        return ["Resolve target_upload_preflight.blockers before attempting live upload."]
    return ["Review target_upload_preflight.upload_payload, then run target-upload live only with explicit confirm_upload and uploaded torrent injection/seeding options."]


def _job_target_upload_service_gate(job: dict[str, Any], summary_payload: dict[str, Any] | None = None) -> dict[str, Any] | None:
    for payload in (summary_payload, job.get("result")):
        if isinstance(payload, dict) and isinstance(payload.get("target_upload_service_gate"), dict):
            return payload["target_upload_service_gate"]
    request = job.get("request")
    if str(job.get("kind") or "") != "ptcli.target_upload" or not isinstance(request, dict):
        return None
    return _target_upload_service_gate(request)


def _materials_prepare_dry_run_payload(context: dict[str, Any]) -> dict[str, Any]:
    blockers = [] if context["actions"] else ["No material preparation action was requested."]
    request_template = {
        "path": context.get("path") or "/downloads/content",
        "output_dir": context["output_dir"],
        "generate_mediainfo": True,
        "generate_screenshots": True,
        "screenshot_count": context["screenshot_count"],
        "upload_screenshots": True,
        "image_host": context.get("image_host") or "<configured image host>",
        "dry_run": False,
    }
    return {
        "kind": "ptcli.materials_prepare",
        "status": "ok" if not blockers else "blocked",
        "ok": not blockers,
        "dry_run": True,
        "mutates_state": False,
        "mutates_filesystem": False,
        "mutates_network": False,
        "live_upload": False,
        "request": context,
        "output_dir": context["output_dir"],
        "planned_actions": context["actions"],
        "stages": [{"stage": action.replace("_", "-"), "ok": True, "dry_run": True} for action in context["actions"]],
        "material_options": _materials_prepare_existing_options(context),
        "material_evidence": _materials_prepare_evidence(_materials_prepare_existing_options(context)),
        "resume_handoff": _materials_prepare_handoff(context, _materials_prepare_existing_options(context), not blockers, blockers),
        "recommended_request": request_template,
        "blockers": blockers,
        "next_actions": _materials_prepare_next_actions(not blockers, blockers),
        "safety": _materials_prepare_safety(context),
    }


def _materials_prepare_existing_options(context: dict[str, Any]) -> dict[str, Any]:
    options: dict[str, Any] = {}
    for key in ("metadata_file", "ptgen_description_file", "mediainfo_file", "bdinfo_file", "image_host_file", "image_host", "imdb_id", "tmdb_id", "tmdb_type", "douban_id", "douban_url"):
        if context.get(key) not in (None, ""):
            options[key] = context.get(key)
    if context.get("screenshot_files"):
        options["screenshot_files"] = list(context["screenshot_files"])
    return options


def _materials_prepare_stage(stage_name: str, result: dict[str, Any], *, ready_statuses: set[str]) -> dict[str, Any]:
    status = str(result.get("status") or "")
    ok = status in ready_statuses and not _string_list(result.get("blockers"))
    return {
        "stage": stage_name,
        "ok": ok,
        "result": result,
        "message": f"{stage_name} completed." if ok else f"{stage_name} is blocked.",
    }


def _materials_prepare_missing_path_stage(stage_name: str, flag: str) -> dict[str, Any]:
    return {
        "stage": stage_name,
        "ok": False,
        "result": {"status": "blocked", "blockers": [f"{flag} requires path or content_path."]},
        "message": f"{stage_name} requires path or content_path.",
    }


def _materials_prepare_stage_blockers(stages: list[dict[str, Any]]) -> list[str]:
    blockers: list[str] = []
    for stage in stages:
        if stage.get("ok") is True:
            continue
        stage_name = str(stage.get("stage") or "materials")
        result = stage.get("result") if isinstance(stage.get("result"), dict) else {}
        stage_blockers = _string_list(result.get("blockers")) or [str(stage.get("message") or f"{stage_name} failed.")]
        blockers.extend(f"{stage_name}: {blocker}" for blocker in stage_blockers)
    return blockers


def _materials_prepare_evidence(material_options: dict[str, Any]) -> dict[str, Any]:
    return {
        "metadata_file": _materials_path_evidence(material_options.get("metadata_file")),
        "ptgen_description_file": _materials_path_evidence(material_options.get("ptgen_description_file")),
        "mediainfo_file": _materials_path_evidence(material_options.get("mediainfo_file")),
        "bdinfo_file": _materials_path_evidence(material_options.get("bdinfo_file")),
        "image_host_file": _materials_path_evidence(material_options.get("image_host_file")),
        "screenshot_files": [_materials_path_evidence(path) for path in _string_list(material_options.get("screenshot_files"))],
    }


def _materials_path_evidence(value: Any) -> dict[str, Any] | None:
    if value in (None, ""):
        return None
    path = Path(str(value)).expanduser()
    evidence: dict[str, Any] = {"path": str(path), "exists": path.is_file()}
    if path.is_file():
        evidence.update({"size_bytes": path.stat().st_size, "sha1": _sha1_file(path)})
    return evidence


def _sha1_file(path: Path) -> str:
    digest = hashlib.sha1()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def _materials_prepare_handoff(context: dict[str, Any], material_options: dict[str, Any], ready: bool, blockers: list[str]) -> dict[str, Any]:
    resume_overrides = {key: value for key, value in material_options.items() if value not in (None, "", [])}
    parent_job_id = str(context.get("parent_job_id") or context.get("job_id") or "").strip()
    resume_endpoint = f"/v1/jobs/{parent_job_id}/resume" if parent_job_id else "/v1/jobs/{job_id}/resume"
    recommended_request = {"overrides": resume_overrides, "dry_run": True}
    resume_request = {**recommended_request, **({"job_id": parent_job_id} if parent_job_id else {})}
    execute_resume_request = {**resume_request, "dry_run": False}
    submit_request = _materials_prepare_submit_request(context, resume_overrides)
    check_and_submit_handoff = _materials_prepare_check_and_submit_handoff(submit_request, ready, blockers)
    next_step = _materials_prepare_next_step(parent_job_id, submit_request, resume_request, ready, blockers)
    return {
        "kind": "ptcli.materials_prepare_handoff",
        "ready": ready,
        "recommended_tool": "resume_job",
        "recommended_endpoint": resume_endpoint,
        "method": "POST",
        "parent_job_id": parent_job_id or None,
        "material_options": material_options,
        "accepted_override_keys": sorted(resume_overrides),
        "recommended_request": resume_request,
        "resume_request": resume_request,
        "execute_request": execute_resume_request,
        "source_url_check_and_submit_handoff": check_and_submit_handoff,
        "source_url_check_and_submit_request": submit_request,
        "next_step": next_step,
        "continue_when": "Use resume_request for an existing blocked job, or source_url_check_and_submit_request for a fresh source URL flow after duplicate/rule/confirmation gates are ready.",
        "stop_when": ["blockers is not empty", "live upload confirmations are missing", "site policy gate is not ready"],
        "blockers": blockers,
        "next_actions": _materials_prepare_next_actions(ready, blockers),
        "target_job_request_template": {
            "source_url": "<source tracker details url>",
            "target": "MTEAM",
            "accept_rules": True,
            "confirm_upload": True,
            **resume_overrides,
        },
        "request": context,
    }


def _materials_prepare_submit_request(context: dict[str, Any], material_options: dict[str, Any]) -> dict[str, Any] | None:
    source_url = context.get("source_url") or context.get("source")
    target = context.get("target") or context.get("target_trackers") or context.get("target_tracker")
    if not source_url or not target:
        return None
    request: dict[str, Any] = {
        "source_url": source_url,
        "source": source_url,
        "source_tracker": context.get("source_tracker"),
        "target": target,
        "accept_rules": bool(context.get("accept_rules")),
        "confirm_upload": bool(context.get("confirm_upload")),
        **material_options,
    }
    for key in (
        "path",
        "content_path",
        "save_path",
        "config",
        "base_dir",
        "client",
        "qbit_category",
        "qbit_tags",
        "qbit_upload_limit",
        "qbit_download_limit",
        "uploaded_qbit_category",
        "uploaded_qbit_tags",
        "uploaded_qbit_upload_limit",
        "uploaded_qbit_download_limit",
    ):
        if context.get(key) not in (None, ""):
            request[key] = context[key]
    return {key: value for key, value in request.items() if value not in (None, "", [])}


def _materials_prepare_check_and_submit_handoff(submit_request: dict[str, Any] | None, ready: bool, blockers: list[str]) -> dict[str, Any]:
    return {
        "ready": bool(ready and submit_request),
        "tool": "source_url_check_and_submit",
        "endpoint": "/v1/jobs/retorrent/from-url/check-and-submit",
        "method": "POST",
        "request": submit_request,
        "continue_when": "duplicate_check.exists=false and submitted_job.job_id is returned",
        "stop_when": ["blockers is not empty", "duplicate_check.exists=true", "accept_rules/confirm_upload/policy gate missing"],
        "blockers": blockers if blockers else ([] if submit_request else ["source_url and target are required to build source_url_check_and_submit_request."]),
    }


def _materials_prepare_next_step(parent_job_id: str, submit_request: dict[str, Any] | None, resume_request: dict[str, Any], ready: bool, blockers: list[str]) -> dict[str, Any]:
    if blockers or not ready:
        return {"tool": "materials_prepare_job", "endpoint": "/v1/jobs/materials/prepare", "method": "POST", "request": None, "reason": "materials_prepare_blocked"}
    if parent_job_id:
        return {"tool": "resume_job", "endpoint": f"/v1/jobs/{parent_job_id}/resume", "method": "POST", "request": resume_request, "reason": "resume_existing_retorrent_job_with_materials"}
    if submit_request:
        return {"tool": "source_url_check_and_submit", "endpoint": "/v1/jobs/retorrent/from-url/check-and-submit", "method": "POST", "request": submit_request, "reason": "start_checked_source_url_retorrent_with_materials"}
    return {"tool": "resume_job", "endpoint": "/v1/jobs/{job_id}/resume", "method": "POST", "request": resume_request, "reason": "materials_ready_missing_parent_job"}


def _materials_prepare_next_actions(ready: bool, blockers: list[str]) -> list[str]:
    if ready:
        return ["Use materials_prepare_handoff.next_step: resume an existing retorrent job when parent_job_id is known, otherwise submit source_url_check_and_submit_request after duplicate/rule/confirmation gates are ready."]
    if blockers:
        return ["Resolve materials_prepare.blockers, then rerun /v1/materials/prepare with explicit material actions."]
    return ["Choose explicit material actions such as generate_mediainfo, generate_screenshots, or upload_screenshots."]


def _materials_prepare_safety(context: dict[str, Any]) -> dict[str, Any]:
    return {
        "does_not_contact_trackers": True,
        "does_not_upload_to_tracker": True,
        "live_upload": False,
        "requires_confirmation": [],
        "writes_files": any(context.get(key) for key in ("generate_bdinfo", "generate_mediainfo", "generate_screenshots")),
        "may_contact_image_host": bool(context.get("upload_screenshots")),
        "dry_run": bool(context.get("dry_run")),
    }


def _append_common_options(argv: list[str], request: dict[str, Any]) -> None:
    _append_optional(argv, "--config", request.get("config"))
    _append_optional(argv, "--client", request.get("client"))
    _append_optional(argv, "--base-dir", request.get("base_dir"))


def _append_metadata_options(argv: list[str], request: dict[str, Any]) -> None:
    _append_optional(argv, "--imdb-id", request.get("imdb_id"))
    _append_optional(argv, "--tmdb-id", request.get("tmdb_id"))
    _append_optional(argv, "--tmdb-type", request.get("tmdb_type"))
    _append_optional(argv, "--douban-id", request.get("douban_id"))
    _append_optional(argv, "--douban-url", request.get("douban_url"))


def _append_execute_bool_options(argv: list[str], request: dict[str, Any]) -> None:
    bool_options = {
        "accept_rules": "--accept-rules",
        "confirm_upload": "--confirm-upload",
        "paused": "--paused",
        "uploaded_paused": "--uploaded-paused",
        "write_payload": "--write-payload",
        "export_target_torrent": "--export-target-torrent",
        "enrich_metadata": "--enrich-metadata",
        "fetch_ptgen": "--fetch-ptgen",
        "generate_bdinfo": "--generate-bdinfo",
        "generate_mediainfo": "--generate-mediainfo",
        "generate_screenshots": "--generate-screenshots",
        "upload_screenshots": "--upload-screenshots",
        "download_uploaded_torrent": "--download-uploaded-torrent",
        "inject_uploaded_torrent": "--inject-uploaded-torrent",
    }
    for key, option in bool_options.items():
        if request.get(key):
            argv.append(option)
    negative_bool_options = {
        "no_enrich_metadata": "--no-enrich-metadata",
        "no_fetch_ptgen": "--no-fetch-ptgen",
        "no_generate_bdinfo": "--no-generate-bdinfo",
        "no_generate_mediainfo": "--no-generate-mediainfo",
        "no_generate_screenshots": "--no-generate-screenshots",
        "no_upload_screenshots": "--no-upload-screenshots",
        "no_sanitize_target_torrent": "--no-sanitize-target-torrent",
    }
    for key, option in negative_bool_options.items():
        if request.get(key):
            argv.append(option)


def _append_optional(argv: list[str], option: str, value: Any) -> None:
    if value is None or value == "":
        return
    argv.extend([option, str(value)])


def _list_value(value: Any) -> list[Any]:
    if value is None:
        return []
    if isinstance(value, list):
        return value
    return [value]


def _normalized_request(request: dict[str, Any], source: dict[str, Any], target_trackers: str, *, execute: bool) -> dict[str, Any]:
    return {
        "source": source,
        "source_reference": source,
        "source_input": source.get("requested_source"),
        "source_url": source.get("details_url"),
        "target_trackers": target_trackers,
        "execute": execute,
        "accept_rules": bool(request.get("accept_rules")),
        "confirm_upload": bool(request.get("confirm_upload")),
        "client": request.get("client") or "default",
        "config": request.get("config"),
        "path": request.get("path") or request.get("content_path"),
        "save_path": request.get("save_path"),
        "output_dir": request.get("output_dir"),
        "source_torrent_file": request.get("source_torrent_file"),
        "package_dir": request.get("package_dir"),
        "target_output_dir": request.get("target_output_dir"),
        "target_torrent_file": request.get("target_torrent_file"),
        "target_torrent_output_dir": request.get("target_torrent_output_dir"),
        "uploaded_output_dir": request.get("uploaded_output_dir"),
        "uploaded_torrent_id": request.get("uploaded_torrent_id"),
        "uploaded_torrent_file": request.get("uploaded_torrent_file"),
        "uploaded_save_path": request.get("uploaded_save_path"),
        "qbit_category": request.get("qbit_category"),
        "qbit_tags": request.get("qbit_tags"),
        "qbit_upload_limit": request.get("qbit_upload_limit"),
        "qbit_download_limit": request.get("qbit_download_limit"),
        "uploaded_qbit_category": request.get("uploaded_qbit_category"),
        "uploaded_qbit_tags": request.get("uploaded_qbit_tags"),
        "uploaded_qbit_upload_limit": request.get("uploaded_qbit_upload_limit"),
        "uploaded_qbit_download_limit": request.get("uploaded_qbit_download_limit"),
        "material_options": _request_material_options(request),
        "policy_qbit_defaults": request.get("policy_qbit_defaults"),
        "policy_execution_plan": request.get("policy_execution_plan"),
        "policy_enforcement_bundle": request.get("policy_enforcement_bundle"),
        "policy_runtime_contract": request.get("policy_runtime_contract"),
        "policy_application_handoff": request.get("policy_application_handoff"),
        "policy_config_apply_handoff": request.get("policy_config_apply_handoff"),
        "site_policy_profiles": request.get("site_policy_profiles"),
        "site_policy_execution_profiles": request.get("site_policy_execution_profiles"),
        "site_policy_profile_handoff": request.get("site_policy_profile_handoff"),
        "policy_coverage": _request_policy_coverage(request, source, target_trackers),
    }


def _request_material_options(request: dict[str, Any]) -> dict[str, Any]:
    options: dict[str, Any] = {}
    value_keys = (
        "metadata_file",
        "ptgen_description_file",
        "mediainfo_file",
        "bdinfo_file",
        "bdinfo_playlist",
        "image_host_file",
        "image_host",
        "screenshot_count",
        "imdb_id",
        "tmdb_id",
        "tmdb_type",
        "douban_id",
        "douban_url",
    )
    for key in value_keys:
        value = request.get(key)
        if value not in (None, ""):
            options[key] = value
    screenshot_files = _list_value(request.get("screenshot_file") or request.get("screenshot_files"))
    if screenshot_files:
        options["screenshot_files"] = [str(item) for item in screenshot_files]
    for key in ("enrich_metadata", "fetch_ptgen", "generate_bdinfo", "generate_mediainfo", "generate_screenshots", "upload_screenshots"):
        if key in request:
            options[key] = bool(request.get(key))
    return options


def _request_with_policy_qbit_defaults(request: dict[str, Any], source: dict[str, Any], target_trackers: str) -> dict[str, Any]:
    enriched = dict(request)
    if isinstance(enriched.get("policy_qbit_defaults"), dict):
        return enriched
    defaults: dict[str, Any] = {"applied": {}, "sources": {}, "request_overrides": {}, "errors": []}
    source_tracker = str(source.get("tracker") or "")
    targets = parse_tracker_list(target_trackers)
    try:
        config = load_config(enriched.get("config"))
        source_limits = qbit_limits_for_tracker(config, source_tracker, role="source") if source_tracker else {}
        _apply_policy_qbit_default(enriched, defaults, "qbit_upload_limit", source_limits.get("upload_limit"), source_tracker)
        _apply_policy_qbit_default(enriched, defaults, "qbit_download_limit", source_limits.get("download_limit"), source_tracker)
        if targets:
            target = targets[0]
            target_limits = qbit_limits_for_tracker(config, target, role="target")
            _apply_policy_qbit_default(enriched, defaults, "uploaded_qbit_upload_limit", target_limits.get("upload_limit"), target)
            _apply_policy_qbit_default(enriched, defaults, "uploaded_qbit_download_limit", target_limits.get("download_limit"), target)
    except Exception as exc:
        defaults["errors"].append(str(exc))
    defaults["application_report"] = _policy_qbit_defaults_application_report(enriched, defaults, source_tracker, targets)
    enriched["policy_qbit_defaults"] = defaults
    return enriched


def _request_with_policy_execution_context(request: dict[str, Any], source: dict[str, Any], target_trackers: str) -> dict[str, Any]:
    enriched = _request_with_policy_qbit_defaults(request, source, target_trackers)
    if not isinstance(enriched.get("policy_execution_plan"), dict):
        enriched["policy_execution_plan"] = _request_policy_execution_plan(enriched, source, target_trackers)
    if not isinstance(enriched.get("policy_enforcement_bundle"), dict):
        enriched["policy_enforcement_bundle"] = _request_policy_enforcement_bundle(enriched, source, target_trackers)
    if not isinstance(enriched.get("policy_runtime_contract"), dict):
        bundle = enriched.get("policy_enforcement_bundle") if isinstance(enriched.get("policy_enforcement_bundle"), dict) else {}
        if isinstance(bundle.get("runtime_contract"), dict):
            enriched["policy_runtime_contract"] = bundle["runtime_contract"]
        elif isinstance(enriched.get("policy_execution_plan"), dict):
            enriched["policy_runtime_contract"] = _site_policy_runtime_contract(
                enriched["policy_execution_plan"],
                {
                    "ready": bundle.get("ready") is True and enriched["policy_execution_plan"].get("ready") is True,
                    "request_template": bundle.get("live_request_template") if isinstance(bundle.get("live_request_template"), dict) else _site_policy_execution_sequence_request_template(enriched["policy_execution_plan"]),
                    "blockers": _string_list(bundle.get("blockers")) + _string_list(enriched["policy_execution_plan"].get("blockers")),
                },
                bundle,
            )
    if not isinstance(enriched.get("policy_application_handoff"), dict):
        enriched["policy_application_handoff"] = _request_policy_application_handoff(enriched, source, target_trackers)
    if not isinstance(enriched.get("policy_config_apply_handoff"), dict):
        enriched["policy_config_apply_handoff"] = _request_policy_config_apply_handoff(enriched, source, target_trackers)
    if not isinstance(enriched.get("site_policy_profiles"), dict) or not isinstance(enriched.get("site_policy_execution_profiles"), dict):
        profiles = _request_policy_profiles(enriched, source, target_trackers)
        if not isinstance(enriched.get("site_policy_profiles"), dict):
            enriched["site_policy_profiles"] = profiles.get("site_policy_profiles")
        if not isinstance(enriched.get("site_policy_execution_profiles"), dict):
            enriched["site_policy_execution_profiles"] = profiles.get("site_policy_execution_profiles")
    if not isinstance(enriched.get("site_policy_profile_handoff"), dict):
        enriched["site_policy_profile_handoff"] = _request_site_policy_profile_handoff(enriched, source, target_trackers)
    return enriched


def _request_policy_profiles(request: dict[str, Any], source: dict[str, Any], target_trackers: str) -> dict[str, Any]:
    policy_request = {
        "source_tracker": source.get("tracker"),
        "target": target_trackers,
        "accept_rules": bool(request.get("accept_rules")),
    }
    if request.get("config"):
        policy_request["config"] = request.get("config")
    try:
        payload = site_policies_payload(policy_request)
        return {
            "site_policy_profiles": payload.get("site_policy_profiles") if isinstance(payload.get("site_policy_profiles"), dict) else {},
            "site_policy_execution_profiles": payload.get("site_policy_execution_profiles") if isinstance(payload.get("site_policy_execution_profiles"), dict) else {},
            "site_policy_status": payload.get("status"),
            "site_policy_ready": payload.get("ready"),
            "blockers": _string_list(payload.get("blockers")),
        }
    except Exception as exc:
        return {
            "site_policy_profiles": {},
            "site_policy_execution_profiles": {},
            "site_policy_status": "blocked",
            "site_policy_ready": False,
            "blockers": [f"site_policy_profiles could not be generated: {exc}"],
        }


def _request_site_policy_profile_handoff(request: dict[str, Any], source: dict[str, Any], target_trackers: str) -> dict[str, Any]:
    source_tracker = str(source.get("tracker") or "")
    targets = parse_tracker_list(target_trackers)
    profiles = request.get("site_policy_profiles") if isinstance(request.get("site_policy_profiles"), dict) else {}
    execution_profiles = request.get("site_policy_execution_profiles") if isinstance(request.get("site_policy_execution_profiles"), dict) else {}
    blockers = _site_policy_profile_handoff_blockers(source_tracker, targets, profiles, execution_profiles)
    ready = not blockers and bool(execution_profiles) and all((execution_profiles.get(tracker) or {}).get("ready") is True for tracker in [source_tracker, *targets] if tracker)
    return {
        "kind": "ptcli.job_site_policy_profile_handoff",
        "ready": ready,
        "status": "ready" if ready else "blocked",
        "accepted_rules": request.get("accept_rules") is True,
        "source_tracker": source_tracker or None,
        "target_trackers": targets,
        "source": _site_policy_profile_handoff_item(source_tracker, "source", profiles, execution_profiles) if source_tracker else None,
        "targets": [_site_policy_profile_handoff_item(target, "target", profiles, execution_profiles) for target in targets],
        "site_policy_profiles": profiles,
        "site_policy_execution_profiles": execution_profiles,
        "next_step": _site_policy_profile_handoff_next_step(source, target_trackers, request, ready, blockers),
        "continue_when": "site_policy_profile_handoff.ready=true and policy_application_handoff.ready=true before live automation",
        "stop_when": ["site_policy_profile_handoff.ready=false", "rule_obligations.ready=false", "execution_profile.manual_review.ready=false"],
        "blockers": blockers,
        "next_actions": _site_policy_profile_handoff_next_actions(ready, blockers),
        "safety": {"mutates_state": False, "contacts_trackers": False, "contacts_qbittorrent": False, "live_upload": False, "does_not_override_site_rules": True},
    }


def _site_policy_profile_handoff_item(tracker: str, role: str, profiles: dict[str, Any], execution_profiles: dict[str, Any]) -> dict[str, Any]:
    profile = profiles.get(tracker) if isinstance(profiles.get(tracker), dict) else {}
    execution_profile = execution_profiles.get(tracker) if isinstance(execution_profiles.get(tracker), dict) else {}
    manual_review = execution_profile.get("manual_review") if isinstance(execution_profile.get("manual_review"), dict) else {}
    automation = execution_profile.get("automation") if isinstance(execution_profile.get("automation"), dict) else {}
    qbit = execution_profile.get("qbit") if isinstance(execution_profile.get("qbit"), dict) else {}
    seeding = execution_profile.get("seeding") if isinstance(execution_profile.get("seeding"), dict) else {}
    return {
        "tracker": tracker,
        "role": role,
        "ready": execution_profile.get("ready") is True,
        "config_ready": ((profile.get("config_audit") or {}).get("ready") is True) if isinstance(profile.get("config_audit"), dict) else None,
        "rules_ready": manual_review.get("ready") is True and manual_review.get("rule_obligations_ready") is True,
        "manual_review": manual_review,
        "automation": automation,
        "qbit": qbit,
        "seeding": seeding,
        "required_fields": _string_list(profile.get("required_fields")),
        "missing_fields": _string_list(profile.get("missing_fields")),
        "disabled_automation": _string_list(profile.get("disabled_automation")),
        "blockers": _string_list(execution_profile.get("blockers")),
        "next_actions": _string_list(profile.get("next_actions")),
    }


def _site_policy_profile_handoff_blockers(source_tracker: str, targets: list[str], profiles: dict[str, Any], execution_profiles: dict[str, Any]) -> list[str]:
    blockers: list[str] = []
    for tracker in [source_tracker, *targets]:
        if not tracker:
            continue
        if not isinstance(profiles.get(tracker), dict):
            blockers.append(f"{tracker}.site_policy_profile missing")
        execution_profile = execution_profiles.get(tracker) if isinstance(execution_profiles.get(tracker), dict) else None
        if not isinstance(execution_profile, dict):
            blockers.append(f"{tracker}.site_policy_execution_profile missing")
            continue
        blockers.extend(f"{tracker}.{item}" for item in _string_list(execution_profile.get("blockers")))
        if execution_profile.get("ready") is not True:
            blockers.append(f"{tracker}.execution_profile.ready=false")
    return list(dict.fromkeys(blockers))


def _site_policy_profile_handoff_next_step(source: dict[str, Any], target_trackers: str, request: dict[str, Any], ready: bool, blockers: list[str]) -> dict[str, Any]:
    policy_request = {
        "source_tracker": source.get("tracker"),
        "target": target_trackers,
        "accept_rules": bool(request.get("accept_rules")),
    }
    if request.get("config"):
        policy_request["config"] = request.get("config")
    if ready and not blockers:
        return {"tool": "get_job_summary", "endpoint": None, "method": "GET", "request": None, "reason": "site_policy_profiles_ready"}
    return {"tool": "site_policies", "endpoint": "/v1/site-policies", "method": "POST", "request": policy_request, "reason": "site_policy_profiles_not_ready"}


def _site_policy_profile_handoff_next_actions(ready: bool, blockers: list[str]) -> list[str]:
    if ready:
        return ["Use site_policy_profile_handoff.site_policy_execution_profiles as the per-tracker rule/limit/seeding source for this job."]
    if blockers:
        return ["Resolve site_policy_profile_handoff.blockers with /v1/site-policies before resuming live automation."]
    return ["Read site_policy_profile_handoff before applying policy defaults to a live job."]


