def _agent_resume_summary(resume_state: dict[str, Any], payload: dict[str, Any]) -> dict[str, Any]:
    materials = resume_state.get("materials") if isinstance(resume_state.get("materials"), dict) else {}
    return {
        "available": resume_state.get("resume_available"),
        "ready": resume_state.get("ready"),
        "next_stage": resume_state.get("next_stage") or _nested_value(payload, "next_stage"),
        "next_command": resume_state.get("next_command") or _nested_value(payload, "next_command"),
        "next_command_argv": _argv_list(resume_state.get("next_command_argv")) or _result_next_command_argv(payload),
        "materials_missing": _string_list(materials.get("target_materials_missing")) or _string_list(materials.get("target_preparation_missing")),
        "material_recovery_hints": materials.get("recovery_hints") if isinstance(materials.get("recovery_hints"), list) else [],
    }


def _candidate_payload(payload: Any) -> dict[str, Any] | None:
    if not isinstance(payload, dict):
        return None
    kind = str(payload.get("kind") or "")
    if kind in {"ptcli.daily_candidates", "ptcli.service.daily_candidates"}:
        return payload
    nested = payload.get("result")
    if isinstance(nested, dict) and str(nested.get("kind") or "") in {"ptcli.daily_candidates", "ptcli.service.daily_candidates"}:
        return nested
    return payload if isinstance(payload.get("digest"), dict) and isinstance(payload.get("candidates"), list) else None


def _candidate_digest_from_payload(payload: Any) -> dict[str, Any] | None:
    candidate_payload = _candidate_payload(payload)
    if not candidate_payload:
        return None
    digest = candidate_payload.get("digest")
    if isinstance(digest, dict):
        return digest
    nested = candidate_payload.get("result")
    if isinstance(nested, dict) and isinstance(nested.get("digest"), dict):
        return nested["digest"]
    return None


def _candidate_control_summary_from_payload(payload: Any) -> dict[str, Any] | None:
    if not isinstance(payload, dict):
        return None
    digest = _candidate_digest_from_payload(payload)
    if isinstance(digest, dict) and isinstance(digest.get("candidate_control_summary"), dict):
        return digest["candidate_control_summary"]
    schedule_digest = payload.get("schedule_digest")
    if isinstance(schedule_digest, dict) and isinstance(schedule_digest.get("candidate_control_summary"), dict):
        return schedule_digest["candidate_control_summary"]
    nested = payload.get("result")
    if isinstance(nested, dict):
        return _candidate_control_summary_from_payload(nested)
    return payload.get("candidate_control_summary") if isinstance(payload.get("candidate_control_summary"), dict) else None


def _nested_dict(payload: dict[str, Any], key: str) -> dict[str, Any]:
    value = _nested_value(payload, key)
    return value if isinstance(value, dict) else {}


def _metadata_ready(metadata_fields: dict[str, Any], external_id_readiness: dict[str, Any]) -> bool | None:
    checks = [
        _field_ready(metadata_fields, "imdb") or _field_ready(metadata_fields, "imdb_id") or external_id_readiness.get("imdb"),
        _field_ready(metadata_fields, "tmdb") or _field_ready(metadata_fields, "tmdb_id") or external_id_readiness.get("tmdb"),
        _field_ready(metadata_fields, "douban") or _field_ready(metadata_fields, "douban_id") or external_id_readiness.get("douban"),
        _field_ready(metadata_fields, "ptgen_description"),
    ]
    boolean_checks = [check for check in checks if isinstance(check, bool)]
    return all(boolean_checks) if boolean_checks else None


def _field_ready(metadata_fields: dict[str, Any], key: str) -> bool | None:
    field = metadata_fields.get(key)
    if isinstance(field, dict) and isinstance(field.get("ready"), bool):
        return field["ready"]
    return None


def _metadata_field_value(metadata_fields: dict[str, Any], key: str, field_name: str) -> Any:
    field = metadata_fields.get(key)
    if isinstance(field, dict):
        return field.get(field_name)
    return None


def _resolve_job_dir(root: str | Path | None) -> Path:
    if root:
        return Path(root).expanduser()
    configured = os.environ.get("PTCLI_JOB_DIR")
    if configured:
        return Path(configured).expanduser()
    return Path(os.environ.get("TMPDIR") or tempfile.gettempdir()) / "ptcli-jobs"


def _validate_job_id(job_id: str) -> None:
    if not JOB_ID_PATTERN.fullmatch(job_id):
        raise ServiceError("Invalid job id.", status=HTTPStatus.BAD_REQUEST)


def _bounded_int(value: Any, *, default: int, minimum: int, maximum: int) -> int:
    try:
        parsed = int(value)
    except (TypeError, ValueError):
        parsed = default
    return max(minimum, min(maximum, parsed))


def _first_int(*values: Any, default: int = 0) -> int:
    for value in values:
        if value in (None, ""):
            continue
        try:
            return int(value)
        except (TypeError, ValueError):
            continue
    return default


def _resolve_max_concurrent_jobs(value: int | str | None = None) -> int:
    configured = value if value is not None else os.environ.get("PTCLI_MAX_CONCURRENT_JOBS")
    return _bounded_int(configured, default=DEFAULT_MAX_CONCURRENT_JOBS, minimum=1, maximum=16)


def _job_queue_summary(status_counts: dict[str, int], max_concurrent_jobs: int) -> dict[str, Any]:
    queued_count = int(status_counts.get("queued") or 0)
    running_count = int(status_counts.get("running") or 0)
    available_slots = max(0, max_concurrent_jobs - running_count)
    return {
        "max_concurrent_jobs": max_concurrent_jobs,
        "running_count": running_count,
        "queued_count": queued_count,
        "available_slots": available_slots,
        "backlog_count": max(0, queued_count - available_slots),
    }


def _timestamp(value: Any) -> int | None:
    try:
        return int(value)
    except (TypeError, ValueError):
        return None


def _job_runtime(job: dict[str, Any]) -> dict[str, Any]:
    status = str(job.get("status") or "unknown")
    terminal = status not in {"queued", "running"}
    now = int(time.time())
    created_at = _timestamp(job.get("created_at"))
    updated_at = _timestamp(job.get("updated_at"))
    started_at = _timestamp(job.get("started_at"))
    completed_at = _timestamp(job.get("completed_at"))
    end_at = completed_at or now
    elapsed_seconds = max(0, end_at - created_at) if created_at is not None else None
    status_age_seconds = max(0, now - updated_at) if updated_at is not None and not terminal else None
    queued_until = started_at or completed_at or now
    queued_seconds = max(0, queued_until - created_at) if created_at is not None else None
    running_seconds = max(0, end_at - started_at) if started_at is not None else None
    job_id = job.get("job_id")
    return {
        "status": status,
        "created_at": created_at,
        "updated_at": updated_at,
        "started_at": started_at,
        "completed_at": completed_at,
        "elapsed_seconds": elapsed_seconds,
        "status_age_seconds": status_age_seconds,
        "queued_seconds": queued_seconds,
        "running_seconds": running_seconds,
        "terminal": terminal,
        "should_poll": not terminal,
        "poll_after_seconds": DEFAULT_JOB_POLL_AFTER_SECONDS if not terminal else None,
        "status_endpoint": f"/v1/jobs/{job_id}" if job_id else None,
        "summary_endpoint": f"/v1/jobs/{job_id}/summary" if job_id else None,
        "resume_endpoint": f"/v1/jobs/{job_id}/resume" if job_id else None,
    }


def _job_handoff(job: dict[str, Any], payload: dict[str, Any] | None = None) -> dict[str, Any]:
    job_id = str(job.get("job_id") or "")
    status = str(job.get("status") or "unknown")
    runtime = _job_runtime(job)
    agent_decision = _agent_decision(job)
    resume_plan = _job_resume_plan(job)
    resume_requirements = _job_resume_requirements(job, payload if isinstance(payload, dict) else None)
    resume_summary = _job_resume_summary(job)
    submit_if_clear = _job_submit_if_clear_handoff(job)
    candidate_submission_summary = _job_candidate_submission_summary(job, payload if isinstance(payload, dict) else None)
    candidate_execution = candidate_submission_summary.get("execution_handoff") if isinstance(candidate_submission_summary, dict) and isinstance(candidate_submission_summary.get("execution_handoff"), dict) else None
    closure_handoff = _job_closure_handoff(job, payload if isinstance(payload, dict) else None)
    retorrent_stage_handoff = _job_retorrent_stage_handoff(job, payload if isinstance(payload, dict) else None)
    material_gap_summary = _job_material_gap_summary(job, payload if isinstance(payload, dict) else None)
    material_preparation_final_report = _job_material_preparation_final_report(job, payload if isinstance(payload, dict) else None)
    qbit_limit_audit = _job_qbit_limit_audit(job, payload if isinstance(payload, dict) else None)
    qbit_handoff = _job_qbit_handoff(job, payload if isinstance(payload, dict) else None)
    qbit_enforcement_summary = _job_qbit_enforcement_summary(job, payload if isinstance(payload, dict) else None)
    qbit_execution_gate = _job_qbit_execution_gate(job, payload if isinstance(payload, dict) else None)
    qbit_rate_limit_repair_plan = _job_qbit_rate_limit_repair_plan(job, payload if isinstance(payload, dict) else None)
    site_policy_profile_handoff = _job_site_policy_profile_handoff(job)
    next_step = closure_handoff.get("next_step") if isinstance(closure_handoff.get("next_step"), dict) else {}
    action = str(agent_decision.get("decision") or "inspect")
    recommended_tool = agent_decision.get("next_tool")
    recommended_endpoint = None
    recommended_method = None
    recommended_request = None
    continue_when = None
    stop_when: list[str] = []

    if runtime.get("should_poll"):
        action = "wait"
        recommended_tool = "get_job_status"
        recommended_endpoint = runtime.get("status_endpoint")
        recommended_method = "GET"
        continue_when = "status not in queued,running"
        stop_when = ["status in blocked,failed,cancelled"]
    elif isinstance(candidate_execution, dict):
        action = str(candidate_execution.get("state") or action)
        candidate_material_template = candidate_execution.get("material_input_template") if isinstance(candidate_execution.get("material_input_template"), dict) else {}
        candidate_material_dry_run_request = candidate_material_template.get("dry_run_request") if action == "prepare_materials" and isinstance(candidate_material_template.get("dry_run_request"), dict) else None
        recommended_tool = candidate_execution.get("recommended_tool")
        recommended_endpoint = candidate_execution.get("recommended_endpoint")
        recommended_method = candidate_execution.get("recommended_method")
        recommended_request = candidate_material_dry_run_request or candidate_execution.get("recommended_request")
        if candidate_material_dry_run_request:
            recommended_tool = "resume_job"
            recommended_endpoint = candidate_execution.get("recommended_endpoint") or runtime.get("resume_endpoint")
            recommended_method = "POST"
        continue_when = candidate_execution.get("continue_when")
        stop_when = _string_list(candidate_execution.get("stop_when"))
    elif action == "submit_if_clear" and isinstance(submit_if_clear, dict):
        recommended_tool = submit_if_clear.get("tool")
        recommended_endpoint = submit_if_clear.get("endpoint")
        recommended_method = submit_if_clear.get("method")
        recommended_request = submit_if_clear.get("request")
        continue_when = "job_id is returned"
        stop_when = ["duplicate_check.exists=true", "submit_if_clear_handoff.ready=false"]
    elif isinstance(retorrent_stage_handoff, dict) and retorrent_stage_handoff.get("ready") is True and retorrent_stage_handoff.get("action") in {"prepare_target_package", "target_upload_closure"}:
        action = str(retorrent_stage_handoff["action"])
        recommended_tool = retorrent_stage_handoff.get("recommended_tool")
        recommended_endpoint = retorrent_stage_handoff.get("recommended_endpoint")
        recommended_method = retorrent_stage_handoff.get("recommended_method")
        recommended_request = retorrent_stage_handoff.get("recommended_request")
        continue_when = retorrent_stage_handoff.get("continue_when")
        stop_when = _string_list(retorrent_stage_handoff.get("stop_when"))
    elif resume_plan.get("recommended") or resume_summary.get("recommended"):
        action = "resume"
        recommended_tool = "resume_job"
        recommended_endpoint = resume_plan.get("endpoint")
        recommended_method = "POST"
        recommended_request = resume_requirements.get("dry_run_request") or resume_requirements.get("request_template")
        continue_when = "resume_preview.ok=true; then call execute_request after user review"
        stop_when = ["resume_plan.allowed=false", "next_command_argv not allowlisted"]
    elif status == "complete":
        action = "done"
        recommended_tool = "get_job_summary"
        recommended_endpoint = runtime.get("summary_endpoint")
        recommended_method = "GET"
        continue_when = "report summary/evidence to user"
    elif status == "cancelled":
        action = "stop"
        recommended_tool = None
        stop_when = ["job.status=cancelled"]
    elif isinstance(next_step, dict) and next_step.get("tool"):
        recommended_tool = next_step.get("tool")
        recommended_endpoint = next_step.get("endpoint")
        recommended_method = next_step.get("method")
        recommended_request = next_step.get("request")
        continue_when = next_step.get("continue_when")
    else:
        recommended_tool = recommended_tool or agent_decision.get("recommended_tool")

    candidate_material_dry_run_request = _job_handoff_candidate_material_request(candidate_execution, "dry_run_request")
    candidate_material_execute_request = _job_handoff_candidate_material_request(candidate_execution, "execute_request")
    dry_run_request = candidate_material_dry_run_request or (resume_requirements.get("dry_run_request") if isinstance(resume_requirements.get("dry_run_request"), dict) else None)
    execute_request = candidate_material_execute_request or (resume_requirements.get("execute_request") if isinstance(resume_requirements.get("execute_request"), dict) else None)
    recommended_call = _job_handoff_recommended_call(
        recommended_tool,
        recommended_endpoint,
        recommended_method,
        recommended_request,
        dry_run_request,
        execute_request,
        action,
        status,
        stop_when,
    )

    return {
        "kind": "ptcli.job_handoff",
        "job_id": job_id or None,
        "job_kind": job.get("kind"),
        "status": status,
        "terminal": bool(runtime.get("terminal")),
        "action": action,
        "recommended_tool": recommended_tool,
        "recommended_endpoint": recommended_endpoint,
        "recommended_method": recommended_method,
        "recommended_request": recommended_request,
        "recommended_call": recommended_call,
        "continue_when": continue_when,
        "stop_when": stop_when,
        "status_endpoint": runtime.get("status_endpoint"),
        "summary_endpoint": runtime.get("summary_endpoint"),
        "resume_endpoint": runtime.get("resume_endpoint"),
        "poll_after_seconds": runtime.get("poll_after_seconds"),
        "should_poll": bool(runtime.get("should_poll")),
        "can_resume": bool(resume_plan.get("allowed")),
        "resume_recommended": bool(resume_plan.get("recommended")),
        "can_attempt_live": bool(agent_decision.get("can_attempt_live")),
        "summary_file": _job_summary_file(job),
        "resume_plan": resume_plan,
        "resume_requirements": resume_requirements,
        "resume_execution_handoff": _job_resume_execution_handoff(job, payload if isinstance(payload, dict) else None),
        "candidate_submission_execution": candidate_execution,
        "retorrent_stage_handoff": retorrent_stage_handoff,
        "material_gap_summary": material_gap_summary,
        "material_preparation_final_report": material_preparation_final_report,
        "site_policy_profile_handoff": site_policy_profile_handoff,
        "qbit_limit_audit": qbit_limit_audit,
        "qbit_handoff": qbit_handoff,
        "qbit_enforcement_summary": qbit_enforcement_summary,
        "qbit_execution_gate": qbit_execution_gate,
        "qbit_rate_limit_repair_plan": qbit_rate_limit_repair_plan,
        "material_input_template": candidate_execution.get("material_input_template") if isinstance(candidate_execution, dict) else None,
        "dry_run_request": dry_run_request,
        "execute_request": execute_request,
        "agent_decision": agent_decision,
        "blockers": _string_list(job.get("blockers")),
        "next_actions": _job_handoff_next_actions(status, runtime, resume_plan, recommended_tool, job_id, _string_list(job.get("next_actions"))),
    }


def _job_handoff_recommended_call(
    tool: Any,
    endpoint: Any,
    method: Any,
    request: Any,
    dry_run_request: dict[str, Any] | None,
    execute_request: dict[str, Any] | None,
    action: str,
    status: str,
    stop_when: list[str],
) -> dict[str, Any]:
    requires_user_review = action not in {"wait", "done", "stop"} and bool(dry_run_request or execute_request or action in {"resume", "prepare_materials", "target_upload_closure"})
    request_value = request if isinstance(request, dict) else None
    gates = _job_handoff_recommended_call_gates(action, request_value, dry_run_request, execute_request)
    safety = _job_handoff_recommended_call_safety(gates, stop_when)
    if not tool or not endpoint:
        return {
            "ready": False,
            "safe_to_call_now": False,
            "tool": None,
            "endpoint": None,
            "method": None,
            "request": None,
            "action": action,
            "status": status,
            "dry_run_request": dry_run_request,
            "execute_request": execute_request,
            "requires_user_review": requires_user_review,
            "gates": gates,
            "safety": safety,
            "stop_when": stop_when,
        }
    method_value = str(method or ("GET" if str(endpoint).endswith("/summary") or action == "wait" else "POST"))
    return {
        "ready": True,
        "safe_to_call_now": bool(gates.get("safe_to_call_now")),
        "tool": tool,
        "endpoint": endpoint,
        "method": method_value,
        "request": request_value,
        "action": action,
        "status": status,
        "dry_run_request": dry_run_request,
        "execute_request": execute_request,
        "requires_user_review": requires_user_review,
        "gates": gates,
        "safety": safety,
        "stop_when": stop_when,
    }


def _job_handoff_recommended_call_gates(action: str, request: dict[str, Any] | None, dry_run_request: dict[str, Any] | None, execute_request: dict[str, Any] | None) -> dict[str, Any]:
    call_request = request if isinstance(request, dict) else {}
    dry_run_preview = action not in {"wait", "done", "stop"} and bool(call_request.get("dry_run") is True or (isinstance(dry_run_request, dict) and dry_run_request.get("dry_run") is True))
    execute_available = isinstance(execute_request, dict) and bool(execute_request)
    accept_rules_present = _job_handoff_call_flag_present("accept_rules", call_request, execute_request)
    confirm_upload_present = _job_handoff_call_flag_present("confirm_upload", call_request, execute_request)
    requires_rules = action in {"resume", "prepare_materials", "prepare_target_package", "target_upload_closure", "submit_if_clear"}
    requires_upload_confirmation = action in {"resume", "target_upload_closure", "submit_if_clear"}
    live_execute_requested = execute_available and not dry_run_preview
    missing: list[str] = []
    if requires_rules and not accept_rules_present and live_execute_requested:
        missing.append("accept_rules")
    if requires_upload_confirmation and not confirm_upload_present and live_execute_requested:
        missing.append("confirm_upload")
    return {
        "dry_run_preview": dry_run_preview,
        "execute_available": execute_available,
        "requires_rules": requires_rules,
        "requires_upload_confirmation": requires_upload_confirmation,
        "accept_rules_present": accept_rules_present,
        "confirm_upload_present": confirm_upload_present,
        "live_execute_requested": live_execute_requested,
        "safe_to_call_now": action in {"wait", "done"} or dry_run_preview or not missing,
        "missing": missing,
    }


def _job_handoff_call_flag_present(key: str, request: dict[str, Any], execute_request: dict[str, Any] | None) -> bool:
    if request.get(key) is True:
        return True
    if isinstance(request.get("overrides"), dict) and request["overrides"].get(key) is True:
        return True
    if isinstance(execute_request, dict):
        if execute_request.get(key) is True:
            return True
        if isinstance(execute_request.get("overrides"), dict) and execute_request["overrides"].get(key) is True:
            return True
    return False


def _job_handoff_recommended_call_safety(gates: dict[str, Any], stop_when: list[str]) -> dict[str, Any]:
    return {
        "live_upload_requires_confirm_upload": True,
        "rules_must_be_accepted": True,
        "use_dry_run_first": bool(gates.get("dry_run_preview")),
        "safe_to_call_now": bool(gates.get("safe_to_call_now")),
        "missing_required_flags": _string_list(gates.get("missing")),
        "do_not_call_when": stop_when,
    }


def _job_handoff_candidate_material_request(candidate_execution: dict[str, Any] | None, key: str) -> dict[str, Any] | None:
    if not isinstance(candidate_execution, dict) or candidate_execution.get("state") != "prepare_materials":
        return None
    material_template = candidate_execution.get("material_input_template") if isinstance(candidate_execution.get("material_input_template"), dict) else {}
    request = material_template.get(key)
    return request if isinstance(request, dict) else None


def _job_handoff_next_actions(status: str, runtime: dict[str, Any], resume_plan: dict[str, Any], recommended_tool: Any, job_id: str, job_actions: list[str]) -> list[str]:
    actions: list[str] = []
    if runtime.get("should_poll"):
        actions.append(f"Poll /v1/jobs/{job_id} after {runtime.get('poll_after_seconds')} seconds.")
    elif resume_plan.get("recommended"):
        actions.append(f"Preview resume with POST /v1/jobs/{job_id}/resume dry_run=true, review command_argv, then execute when safe.")
    elif status == "complete":
        actions.append(f"Read /v1/jobs/{job_id}/summary and report closure_summary/evidence.")
    elif status == "cancelled":
        actions.append("Submit a new job if the work is still needed; cancelled jobs are terminal.")
    elif recommended_tool:
        actions.append(f"Call recommended_tool={recommended_tool} after reviewing blockers and site rules.")
    actions.extend(job_actions)
    return list(dict.fromkeys(action for action in actions if action))


def _job_recovery_handoff(job: dict[str, Any], payload: dict[str, Any] | None = None) -> dict[str, Any]:
    job_id = str(job.get("job_id") or "")
    status = str(job.get("status") or "unknown")
    runtime = _job_runtime(job)
    job_handoff = job.get("job_handoff") if isinstance(job.get("job_handoff"), dict) else {}
    if not job_handoff:
        stage_handoff = _job_retorrent_stage_handoff(job, payload if isinstance(payload, dict) else None)
        if isinstance(stage_handoff, dict) and stage_handoff.get("ready") is True and stage_handoff.get("action") in {"prepare_target_package", "target_upload_closure"}:
            job_handoff = {
                "action": stage_handoff.get("action"),
                "recommended_tool": stage_handoff.get("recommended_tool"),
                "recommended_endpoint": stage_handoff.get("recommended_endpoint"),
                "recommended_method": stage_handoff.get("recommended_method"),
                "recommended_request": stage_handoff.get("recommended_request"),
            }
    resume_plan = _job_resume_plan(job)
    resume_requirements = _job_resume_requirements(job, payload if isinstance(payload, dict) else None)
    resume_execution = _job_resume_execution_handoff(job, payload if isinstance(payload, dict) else None)
    materials_handoff = _job_materials_handoff(job, payload if isinstance(payload, dict) else None)
    target_upload_handoff = _job_target_upload_handoff(job, payload if isinstance(payload, dict) else None)
    closure_handoff = _job_closure_handoff(job, payload if isinstance(payload, dict) else None)
    qbit_limit_audit = _job_qbit_limit_audit(job, payload if isinstance(payload, dict) else None)
    qbit_handoff = _job_qbit_handoff(job, payload if isinstance(payload, dict) else None)
    qbit_enforcement_summary = _job_qbit_enforcement_summary(job, payload if isinstance(payload, dict) else None)
    qbit_execution_gate = _job_qbit_execution_gate(job, payload if isinstance(payload, dict) else None)
    candidate_submission_summary = _job_candidate_submission_summary(job, payload if isinstance(payload, dict) else None)
    policy_application_report = _job_policy_application_report(job, payload if isinstance(payload, dict) else None)
    policy_config_apply_handoff = _job_policy_config_apply_handoff(job)

    action, phase, reason = _job_recovery_decision(status, runtime, job_handoff, materials_handoff, target_upload_handoff, closure_handoff, resume_plan, candidate_submission_summary, policy_config_apply_handoff, policy_application_report)
    next_step = _job_recovery_next_step(action, job_handoff, materials_handoff, target_upload_handoff, closure_handoff, resume_execution, runtime, policy_config_apply_handoff, policy_application_report)
    recommended_request = next_step.get("request") if isinstance(next_step, dict) else None
    dry_run_request = _job_recovery_dry_run_request(action, materials_handoff, resume_execution, resume_requirements, recommended_request)
    execute_request = _job_recovery_execute_request(action, materials_handoff, resume_execution, resume_requirements)
    blockers = _job_recovery_blockers(job, materials_handoff, target_upload_handoff, closure_handoff, resume_execution, qbit_handoff, policy_application_report)
    return {
        "kind": "ptcli.job_recovery_handoff",
        "job_id": job_id or None,
        "job_kind": job.get("kind"),
        "status": status,
        "terminal": bool(runtime.get("terminal")),
        "phase": phase,
        "action": action,
        "reason": reason,
        "ready": action in {"poll", "preview_resume", "execute_resume", "prepare_materials", "prepare_target_package", "target_upload_closure", "repair_target_payload", "repair_qbit", "repair_policy_application", "read_summary", "configure_policy"},
        "should_poll": bool(runtime.get("should_poll")),
        "should_resume": action in {"preview_resume", "execute_resume", "prepare_materials", "repair_target_payload", "repair_qbit", "repair_policy_application"},
        "resume_preview_required": action in {"preview_resume", "prepare_materials", "repair_target_payload", "repair_qbit", "repair_policy_application"},
        "recommended_tool": next_step.get("tool") if isinstance(next_step, dict) else None,
        "recommended_endpoint": next_step.get("endpoint") if isinstance(next_step, dict) else None,
        "recommended_method": next_step.get("method") if isinstance(next_step, dict) else None,
        "recommended_request": recommended_request,
        "dry_run_request": dry_run_request,
        "execute_request": execute_request,
        "policy_application_report": policy_application_report,
        "policy_config_apply_handoff": policy_config_apply_handoff,
        "status_endpoint": runtime.get("status_endpoint"),
        "summary_endpoint": runtime.get("summary_endpoint"),
        "resume_endpoint": runtime.get("resume_endpoint"),
        "poll_after_seconds": runtime.get("poll_after_seconds"),
        "gates": _job_recovery_gates(runtime, resume_plan, materials_handoff, target_upload_handoff, closure_handoff, qbit_handoff, policy_config_apply_handoff, policy_application_report),
        "handoff_sources": {
            "job_handoff_action": job_handoff.get("action"),
            "resume_recommended": bool(resume_plan.get("recommended")),
            "retorrent_stage_action": job_handoff.get("action") if job_handoff.get("action") in {"prepare_target_package", "target_upload_closure"} else None,
            "materials_ready": materials_handoff.get("ready") if isinstance(materials_handoff, dict) else None,
            "target_upload_action": target_upload_handoff.get("action") if isinstance(target_upload_handoff, dict) else None,
            "closure_action": closure_handoff.get("action") if isinstance(closure_handoff, dict) else None,
            "candidate_submission_action": candidate_submission_summary.get("execution_state") if isinstance(candidate_submission_summary, dict) else None,
            "policy_config_apply_ready": policy_config_apply_handoff.get("ready") if isinstance(policy_config_apply_handoff, dict) else None,
            "policy_config_apply_action": policy_config_apply_handoff.get("action") if isinstance(policy_config_apply_handoff, dict) else None,
            "policy_application_ready": policy_application_report.get("ready") if isinstance(policy_application_report, dict) else None,
            "policy_application_verdict": policy_application_report.get("verdict") if isinstance(policy_application_report, dict) else None,
            "qbit_limit_ready": qbit_limit_audit.get("ready") if isinstance(qbit_limit_audit, dict) else None,
            "qbit_enforcement_ready": qbit_enforcement_summary.get("ready") if isinstance(qbit_enforcement_summary, dict) else None,
            "qbit_execution_ready": qbit_execution_gate.get("ready") if isinstance(qbit_execution_gate, dict) else None,
        },
        "read_fields": [
            "recovery_handoff",
            "policy_application_report",
            "policy_config_apply_handoff",
            "job_handoff",
            "resume_execution_handoff",
            "resume_requirements",
            "materials_handoff",
            "retorrent_stage_handoff",
            "target_upload_handoff",
            "closure_handoff",
            "qbit_limit_audit",
            "qbit_handoff",
            "qbit_enforcement_summary",
            "qbit_execution_gate",
            "closure_summary",
        ],
        "continue_when": _job_recovery_continue_when(action),
        "stop_when": _job_recovery_stop_when(action),
        "blockers": blockers,
        "next_actions": _job_recovery_next_actions(action, next_step, blockers, runtime),
    }


def _job_blocked_recovery_report(job: dict[str, Any], payload: dict[str, Any] | None = None) -> dict[str, Any]:
    """Top-level recovery verdict for agents handling blocked or terminal jobs."""
    job_id = str(job.get("job_id") or "")
    status = str(job.get("status") or "unknown")
    payload = payload if isinstance(payload, dict) else None
    runtime = _job_runtime(job)
    recovery_handoff = _job_recovery_handoff(job, payload)
    resume_final_report = _job_resume_final_report(job, payload)
    materials_handoff = _job_materials_handoff(job, payload)
    target_upload_handoff = _job_target_upload_handoff(job, payload)
    closure_handoff = _job_closure_handoff(job, payload)
    policy_config_apply_handoff = _job_policy_config_apply_handoff(job)
    policy_application_report = _job_policy_application_report(job, payload)
    qbit_limit_audit = _job_qbit_limit_audit(job, payload)
    qbit_handoff = _job_qbit_handoff(job, payload)
    qbit_enforcement_summary = _job_qbit_enforcement_summary(job, payload)
    qbit_execution_gate = _job_qbit_execution_gate(job, payload)
    qbit_rate_limit_repair_plan = _job_qbit_rate_limit_repair_plan(job, payload)
    duplicate_check = _job_duplicate_check(job)
    action = _job_blocked_recovery_action(status, runtime, recovery_handoff, resume_final_report, duplicate_check)
    blockers = _job_blocked_recovery_blockers(job, recovery_handoff, resume_final_report, materials_handoff, target_upload_handoff, closure_handoff, duplicate_check, policy_config_apply_handoff, policy_application_report)
    recommended_call = _job_blocked_recovery_recommended_call(job_id, action, recovery_handoff, resume_final_report, runtime, blockers)
    recoverable = _job_blocked_recovery_recoverable(action, recommended_call, blockers)
    return {
        "kind": "ptcli.blocked_recovery_report",
        "ready": recoverable or action in {"poll", "read_summary", "stop_duplicate"},
        "recoverable": recoverable,
        "action": action,
        "status": status,
        "job_id": job_id or None,
        "job_kind": job.get("kind"),
        "terminal": bool(runtime.get("terminal")),
        "should_poll": bool(runtime.get("should_poll")) or action == "poll",
        "should_resume": action in {"preview_resume", "execute_resume", "prepare_materials", "repair_target_payload", "repair_qbit", "repair_policy_application"},
        "resume_preview_required": bool(recovery_handoff.get("resume_preview_required") or resume_final_report.get("safety", {}).get("dry_run_first")),
        "recommended_tool": recommended_call.get("tool"),
        "recommended_endpoint": recommended_call.get("endpoint"),
        "recommended_method": recommended_call.get("method"),
        "recommended_request": recommended_call.get("request"),
        "recommended_call": recommended_call,
        "dry_run_request": recovery_handoff.get("dry_run_request") or resume_final_report.get("dry_run_request"),
        "execute_request": recovery_handoff.get("execute_request") or resume_final_report.get("execute_request"),
        "policy_application_report": policy_application_report,
        "policy_config_apply_handoff": policy_config_apply_handoff,
        "qbit_limit_audit": qbit_limit_audit,
        "qbit_handoff": qbit_handoff,
        "qbit_enforcement_summary": qbit_enforcement_summary,
        "qbit_execution_gate": qbit_execution_gate,
        "qbit_rate_limit_repair_plan": qbit_rate_limit_repair_plan,
        "blocked_domains": _job_blocked_recovery_domains(materials_handoff, target_upload_handoff, closure_handoff, duplicate_check, blockers, policy_config_apply_handoff, policy_application_report),
        "read_order": [
            "blocked_recovery_report",
            "policy_application_report",
            "policy_config_apply_handoff",
            "qbit_execution_gate",
            "qbit_rate_limit_repair_plan",
            "qbit_enforcement_summary",
            "qbit_limit_audit",
            "recovery_handoff",
            "job_control_summary",
            "resume_final_report",
            "job_progress_handoff",
            "materials_handoff",
            "target_upload_handoff",
            "closure_handoff",
            "job_final_report",
        ],
        "complete_when": _job_blocked_recovery_complete_when(action),
        "stop_when": _job_blocked_recovery_stop_when(action, recovery_handoff, resume_final_report, duplicate_check),
        "sources": {
            "recovery_action": recovery_handoff.get("action"),
            "recovery_phase": recovery_handoff.get("phase"),
            "resume_verdict": resume_final_report.get("verdict"),
            "duplicate_exists": duplicate_check.get("exists"),
            "materials_ready": materials_handoff.get("ready") if isinstance(materials_handoff, dict) else None,
            "target_upload_ready": target_upload_handoff.get("ready_for_live_upload") if isinstance(target_upload_handoff, dict) else None,
            "closure_action": closure_handoff.get("action") if isinstance(closure_handoff, dict) else None,
            "policy_config_apply_ready": policy_config_apply_handoff.get("ready") if isinstance(policy_config_apply_handoff, dict) else None,
            "policy_config_apply_action": policy_config_apply_handoff.get("action") if isinstance(policy_config_apply_handoff, dict) else None,
            "policy_application_ready": policy_application_report.get("ready") if isinstance(policy_application_report, dict) else None,
            "policy_application_verdict": policy_application_report.get("verdict") if isinstance(policy_application_report, dict) else None,
            "qbit_limit_ready": qbit_limit_audit.get("ready") if isinstance(qbit_limit_audit, dict) else None,
            "qbit_enforcement_ready": qbit_enforcement_summary.get("ready") if isinstance(qbit_enforcement_summary, dict) else None,
            "qbit_execution_ready": qbit_execution_gate.get("ready") if isinstance(qbit_execution_gate, dict) else None,
            "qbit_repair_action": qbit_rate_limit_repair_plan.get("action") if isinstance(qbit_rate_limit_repair_plan, dict) else None,
        },
        "blockers": blockers,
        "next_actions": _job_blocked_recovery_next_actions(action, recommended_call, blockers, job_id),
    }


def _job_blocked_recovery_action(status: str, runtime: dict[str, Any], recovery_handoff: dict[str, Any], resume_final_report: dict[str, Any], duplicate_check: dict[str, Any]) -> str:
    if runtime.get("should_poll"):
        return "poll"
    if duplicate_check.get("exists") is True:
        return "stop_duplicate"
    if status == "complete" or recovery_handoff.get("action") == "read_summary":
        return "read_summary"
    if status == "cancelled":
        return "stop_cancelled"
    recovery_action = str(recovery_handoff.get("action") or "")
    if recovery_action in {"preview_resume", "execute_resume", "prepare_materials", "repair_target_payload", "repair_qbit", "repair_policy_application", "prepare_target_package", "target_upload_closure", "configure_policy"}:
        return recovery_action
    resume_action = str(resume_final_report.get("action") or "")
    if resume_action in {"preview_resume", "execute_resume", "poll", "read_summary"}:
        return resume_action
    if status == "failed":
        return "failed"
    if status == "blocked":
        return "resolve_blockers"
    return "inspect"


def _job_blocked_recovery_recommended_call(
    job_id: str,
    action: str,
    recovery_handoff: dict[str, Any],
    resume_final_report: dict[str, Any],
    runtime: dict[str, Any],
    blockers: list[str],
) -> dict[str, Any]:
    if action == "poll":
        return {
            "tool": "get_job_status",
            "endpoint": runtime.get("status_endpoint") or (f"/v1/jobs/{job_id}" if job_id else None),
            "method": "GET",
            "request": {"job_id": job_id} if job_id else None,
            "safe_to_call_now": True,
            "requires_user_review": False,
        }
    if action == "read_summary":
        return {
            "tool": "get_job_summary",
            "endpoint": runtime.get("summary_endpoint") or (f"/v1/jobs/{job_id}/summary" if job_id else None),
            "method": "GET",
            "request": {"job_id": job_id} if job_id else None,
            "safe_to_call_now": True,
            "requires_user_review": False,
        }
    resume_call = resume_final_report.get("recommended_call") if isinstance(resume_final_report.get("recommended_call"), dict) else {}
    if resume_call.get("tool") and action in {"preview_resume", "execute_resume"}:
        return dict(resume_call)
    if action in {"preview_resume", "execute_resume", "prepare_materials", "repair_target_payload", "repair_qbit", "repair_policy_application", "prepare_target_package", "target_upload_closure", "configure_policy"} and recovery_handoff.get("recommended_tool"):
        return {
            "tool": recovery_handoff.get("recommended_tool"),
            "endpoint": recovery_handoff.get("recommended_endpoint"),
            "method": recovery_handoff.get("recommended_method"),
            "request": recovery_handoff.get("recommended_request"),
            "dry_run_request": recovery_handoff.get("dry_run_request"),
            "execute_request": recovery_handoff.get("execute_request"),
            "safe_to_call_now": (action == "configure_policy" and recovery_handoff.get("recommended_tool") in {"site_policies", "site_policy_rule_review"})
            or action == "poll"
            or (action in {"prepare_target_package", "target_upload_closure"} and not blockers),
            "requires_user_review": action not in {"poll", "read_summary", "configure_policy"},
            "reason": f"recovery_handoff.{action}",
        }
    return {
        "tool": None,
        "endpoint": recovery_handoff.get("recommended_endpoint") or resume_call.get("endpoint"),
        "method": recovery_handoff.get("recommended_method") or resume_call.get("method"),
        "request": None,
        "dry_run_request": recovery_handoff.get("dry_run_request") or resume_final_report.get("dry_run_request"),
        "execute_request": recovery_handoff.get("execute_request") or resume_final_report.get("execute_request"),
        "safe_to_call_now": False,
        "requires_user_review": True,
        "reason": "blocked_recovery_report.no_safe_call",
    }


def _job_blocked_recovery_recoverable(action: str, recommended_call: dict[str, Any], blockers: list[str]) -> bool:
    if action in {"poll", "read_summary", "stop_duplicate", "stop_cancelled", "failed"}:
        return False
    if action in {"preview_resume", "execute_resume", "prepare_materials", "repair_target_payload", "repair_qbit", "repair_policy_application", "prepare_target_package", "target_upload_closure", "configure_policy"}:
        return bool(recommended_call.get("tool") or recommended_call.get("dry_run_request") or recommended_call.get("execute_request"))
    return bool(recommended_call.get("tool") and not blockers)


def _job_blocked_recovery_blockers(
    job: dict[str, Any],
    recovery_handoff: dict[str, Any],
    resume_final_report: dict[str, Any],
    materials_handoff: dict[str, Any],
    target_upload_handoff: dict[str, Any],
    closure_handoff: dict[str, Any],
    duplicate_check: dict[str, Any],
    policy_config_apply_handoff: dict[str, Any] | None,
    policy_application_report: dict[str, Any] | None,
) -> list[str]:
    blockers = [
        *_string_list(job.get("blockers")),
        *_string_list(recovery_handoff.get("blockers")),
        *_string_list(resume_final_report.get("blockers")),
        *_string_list(materials_handoff.get("blockers") if isinstance(materials_handoff, dict) else []),
        *_string_list(target_upload_handoff.get("blockers") if isinstance(target_upload_handoff, dict) else []),
        *_string_list(closure_handoff.get("blockers") if isinstance(closure_handoff, dict) else []),
        *_string_list(policy_config_apply_handoff.get("blockers") if isinstance(policy_config_apply_handoff, dict) else []),
        *_string_list(policy_application_report.get("blockers") if isinstance(policy_application_report, dict) else []),
    ]
    if duplicate_check.get("exists") is True:
        blockers.append("duplicate_check.exists")
    return list(dict.fromkeys(str(item) for item in blockers if item))


def _job_blocked_recovery_domains(
    materials_handoff: dict[str, Any],
    target_upload_handoff: dict[str, Any],
    closure_handoff: dict[str, Any],
    duplicate_check: dict[str, Any],
    blockers: list[str],
    policy_config_apply_handoff: dict[str, Any] | None,
    policy_application_report: dict[str, Any] | None,
) -> list[str]:
    domains: list[str] = []
    if duplicate_check.get("exists") is True:
        domains.append("duplicate")
    if isinstance(materials_handoff, dict) and materials_handoff.get("ready") is False:
        domains.append("materials")
    if isinstance(target_upload_handoff, dict) and target_upload_handoff.get("ready_for_live_upload") is False:
        domains.append("target_upload")
    if isinstance(closure_handoff, dict) and closure_handoff.get("complete") is False:
        domains.append("closure")
    if isinstance(policy_config_apply_handoff, dict) and policy_config_apply_handoff.get("ready") is False:
        domains.append("site_policy_config")
    if isinstance(policy_application_report, dict):
        if policy_application_report.get("request_patch_applied") is False or policy_application_report.get("protected_fields_ok") is False:
            domains.append("policy_application")
        if policy_application_report.get("qbit_evidence_ready") is False:
            domains.append("qbit")
        if policy_application_report.get("confirmations_ok") is False:
            domains.append("confirmation")
    for blocker in blockers:
        text = str(blocker)
        if "qbit" in text.lower():
            domains.append("qbit")
        if "policy" in text.lower() or "rule" in text.lower():
            domains.append("site_policy")
        if "confirm" in text.lower() or "accept_rules" in text:
            domains.append("confirmation")
        if "resume" in text.lower():
            domains.append("resume")
    return list(dict.fromkeys(domains))


def _job_blocked_recovery_complete_when(action: str) -> list[str]:
    if action == "poll":
        return ["blocked_recovery_report.action!=poll", "then re-read blocked_recovery_report"]
    if action == "read_summary":
        return ["job_final_report.report_allowed=true or live_user_report.report_allowed=true"]
    if action == "stop_duplicate":
        return ["duplicate_check.exists=true has been reported to the user"]
    if action == "configure_policy":
        return ["policy_config_apply_handoff.verification succeeds", "policy_repair_gate.ready=true", "policy_execution_sequence.ready=true"]
    if action == "repair_policy_application":
        return ["policy_application_report.ready_for_live_audit=true", "policy_application_report.missing_request_fields=[]", "policy_application_report.missing_protected_fields=[]"]
    return ["resume dry-run has been reviewed", "follow-up child job reaches complete", "job_final_report.report_allowed=true"]


def _job_blocked_recovery_stop_when(action: str, recovery_handoff: dict[str, Any], resume_final_report: dict[str, Any], duplicate_check: dict[str, Any]) -> list[str]:
    stop_when = [
        "site rule obligations are not ready",
        "live upload confirmations are missing",
        "recommended_call.safe_to_call_now=false without explicit user review",
        *_string_list(recovery_handoff.get("stop_when")),
        *_string_list(resume_final_report.get("stop_when")),
    ]
    if duplicate_check.get("exists") is True or action == "stop_duplicate":
        stop_when.append("duplicate_check.exists=true")
    if action == "configure_policy":
        stop_when.append("policy_config_apply_handoff.blockers remains non-empty")
    if action == "repair_policy_application":
        stop_when.append("policy_application_report.blockers remains non-empty after resume preview")
    if action in {"stop_cancelled", "failed", "resolve_blockers"}:
        stop_when.append(f"blocked_recovery_report.action={action}")
    return list(dict.fromkeys(stop_when))


def _job_blocked_recovery_next_actions(action: str, recommended_call: dict[str, Any], blockers: list[str], job_id: str) -> list[str]:
    if action == "poll":
        return [f"Poll /v1/jobs/{job_id} until status leaves queued/running."]
    if action == "read_summary":
        return [f"Read /v1/jobs/{job_id}/summary and report job_final_report plus live evidence."]
    if action == "stop_duplicate":
        return ["Report duplicate_check evidence and do not resume or upload."]
    if action in {"preview_resume", "prepare_materials", "repair_target_payload", "repair_qbit", "repair_policy_application"} and recommended_call.get("dry_run_request"):
        return ["Call blocked_recovery_report.recommended_call.dry_run_request or recommended_request first; review preview before execute_request."]
    if action == "configure_policy":
        return ["Call blocked_recovery_report.recommended_call if it is site_policies or site_policy_rule_review; otherwise apply policy_config_apply_handoff.edit_config manually, then rerun verification."]
    if action == "execute_resume" and recommended_call.get("execute_request"):
        return ["Execute blocked_recovery_report.recommended_call.execute_request only after user review, then poll the child job."]
    if recommended_call.get("tool") and not blockers:
        return [f"Call blocked_recovery_report.recommended_call.tool={recommended_call.get('tool')} after reading stop_when."]
    if blockers:
        return ["Resolve blocked_recovery_report.blockers before continuing automation."]
    return ["Inspect blocked_recovery_report.read_order before choosing the next job action."]


def _job_control_summary(job: dict[str, Any], payload: dict[str, Any] | None = None) -> dict[str, Any]:
    """Single short control-plane field for agents deciding the next job call."""
    job_id = str(job.get("job_id") or "")
    status = str(job.get("status") or "unknown")
    runtime = _job_runtime(job)
    job_handoff = _job_handoff(job, payload if isinstance(payload, dict) else None)
    recovery_handoff = _job_recovery_handoff(job, payload if isinstance(payload, dict) else None)
    completion_report = _job_seedbox_live_validation_completion_report(job, payload if isinstance(payload, dict) else None)
    closure_summary = _job_closure_summary(job, payload if isinstance(payload, dict) else None)
    action = _job_control_action(status, runtime, job_handoff, recovery_handoff, completion_report, closure_summary)
    recommended_call = _job_control_recommended_call(job_handoff, recovery_handoff, completion_report, closure_summary)
    blockers = _job_control_blockers(job, recovery_handoff, completion_report, closure_summary)
    ready = action in {"poll", "read_summary", "configure_policy"} or (action in {"resume_preview", "resume_execute", "prepare_materials", "prepare_target_package", "target_upload_closure"} and not blockers)
    if action in {"stop", "stop_duplicate", "blocked", "failed", "cancelled"}:
        ready = False
    return {
        "kind": "ptcli.job_control_summary",
        "job_id": job_id or None,
        "job_kind": job.get("kind"),
        "status": status,
        "state": _job_control_state(action, status),
        "action": action,
        "ready": ready,
        "terminal": bool(runtime.get("terminal")),
        "should_poll": bool(runtime.get("should_poll")),
        "should_resume": bool(recovery_handoff.get("should_resume") or job_handoff.get("resume_recommended")),
        "resume_preview_required": bool(recovery_handoff.get("resume_preview_required")),
        "safe_to_call_now": bool((recommended_call or {}).get("safe_to_call_now")),
        "recommended_tool": (recommended_call or {}).get("tool") or recovery_handoff.get("recommended_tool") or job_handoff.get("recommended_tool"),
        "recommended_endpoint": (recommended_call or {}).get("endpoint") or recovery_handoff.get("recommended_endpoint") or job_handoff.get("recommended_endpoint"),
        "recommended_method": (recommended_call or {}).get("method") or recovery_handoff.get("recommended_method") or job_handoff.get("recommended_method"),
        "recommended_request": (recommended_call or {}).get("request") or recovery_handoff.get("recommended_request") or job_handoff.get("recommended_request"),
        "recommended_call": recommended_call,
        "dry_run_request": recovery_handoff.get("dry_run_request") or job_handoff.get("dry_run_request"),
        "execute_request": recovery_handoff.get("execute_request") or job_handoff.get("execute_request"),
        "poll_after_seconds": runtime.get("poll_after_seconds"),
        "status_endpoint": runtime.get("status_endpoint"),
        "summary_endpoint": runtime.get("summary_endpoint"),
        "resume_endpoint": runtime.get("resume_endpoint"),
        "read_order": _job_control_read_order(action),
        "poll_resume_summary_sequence": _job_poll_resume_summary_sequence(job_id, status, action, runtime, recommended_call, recovery_handoff, job_handoff),
        "continue_when": _job_control_continue_when(action, recovery_handoff, job_handoff, completion_report),
        "stop_when": _job_control_stop_when(action, recovery_handoff, job_handoff, completion_report, closure_summary),
        "complete_when": _job_control_complete_when(completion_report, closure_summary),
        "sources": {
            "job_handoff_action": job_handoff.get("action"),
            "recovery_action": recovery_handoff.get("action"),
            "recovery_phase": recovery_handoff.get("phase"),
            "completion_status": completion_report.get("status"),
            "closure_action": closure_summary.get("action"),
            "closure_complete": closure_summary.get("complete"),
        },
        "blockers": blockers,
        "next_actions": _job_control_next_actions(action, recommended_call, blockers, runtime, job_id),
    }


def _job_poll_resume_summary_sequence(
    job_id: str,
    status: str,
    action: str,
    runtime: dict[str, Any],
    recommended_call: dict[str, Any] | None,
    recovery_handoff: dict[str, Any],
    job_handoff: dict[str, Any],
) -> dict[str, Any]:
    status_endpoint = str(runtime.get("status_endpoint") or f"/v1/jobs/{job_id}")
    summary_endpoint = str(runtime.get("summary_endpoint") or f"/v1/jobs/{job_id}/summary")
    resume_endpoint = str(runtime.get("resume_endpoint") or f"/v1/jobs/{job_id}/resume")
    dry_run_request = recovery_handoff.get("dry_run_request") if isinstance(recovery_handoff.get("dry_run_request"), dict) else job_handoff.get("dry_run_request") if isinstance(job_handoff.get("dry_run_request"), dict) else None
    execute_request = recovery_handoff.get("execute_request") if isinstance(recovery_handoff.get("execute_request"), dict) else job_handoff.get("execute_request") if isinstance(job_handoff.get("execute_request"), dict) else None
    recommended_request = (recommended_call or {}).get("request") if isinstance((recommended_call or {}).get("request"), dict) else None
    if dry_run_request is None and action in {"resume_preview", "resume_execute", "prepare_materials", "prepare_target_package", "target_upload_closure"}:
        dry_run_request = recommended_request or {"job_id": job_id, "dry_run": True}
    if execute_request is None and action in {"resume_execute", "prepare_materials", "prepare_target_package", "target_upload_closure"}:
        execute_request = {"job_id": job_id}
    steps: list[dict[str, Any]] = []
    if runtime.get("should_poll") or action == "poll":
        steps.append(
            {
                "index": 1,
                "name": "poll_status",
                "tool": "get_job_status",
                "endpoint": status_endpoint,
                "method": "GET",
                "request": {"job_id": job_id},
                "repeat_when": "status in queued,running",
                "continue_when": "status in blocked,failed,cancelled,complete",
            }
        )
        steps.append(
            {
                "index": 2,
                "name": "read_summary_when_terminal",
                "tool": "get_job_summary",
                "endpoint": summary_endpoint,
                "method": "GET",
                "request": {"job_id": job_id},
                "continue_when": "job_final_report or live_user_report is readable",
            }
        )
    elif action in {"read_summary", "done"} or status == "complete":
        steps.append(
            {
                "index": 1,
                "name": "read_summary",
                "tool": "get_job_summary",
                "endpoint": summary_endpoint,
                "method": "GET",
                "request": {"job_id": job_id},
                "continue_when": "job_final_report.report_allowed=true or live_user_report.report_allowed=true",
            }
        )
    elif action in {"resume_preview", "resume_execute", "prepare_materials", "prepare_target_package", "target_upload_closure"}:
        steps.append(
            {
                "index": 1,
                "name": "preview_resume",
                "tool": "resume_job",
                "endpoint": resume_endpoint,
                "method": "POST",
                "request": dry_run_request,
                "continue_when": "resume_preview.dry_run=true and command_argv is allowlisted",
            }
        )
        steps.append(
            {
                "index": 2,
                "name": "execute_resume",
                "tool": "resume_job",
                "endpoint": resume_endpoint,
                "method": "POST",
                "request": execute_request,
                "requires_user_review": True,
                "continue_when": "child job_id is returned",
            }
        )
        steps.append(
            {
                "index": 3,
                "name": "poll_child",
                "tool": "get_job_status",
                "endpoint": "/v1/jobs/{child_job_id}",
                "method": "GET",
                "request": {"job_id": "<child_job_id>"},
                "repeat_when": "child.status in queued,running",
            }
        )
        steps.append(
            {
                "index": 4,
                "name": "read_child_summary",
                "tool": "get_job_summary",
                "endpoint": "/v1/jobs/{child_job_id}/summary",
                "method": "GET",
                "request": {"job_id": "<child_job_id>"},
                "continue_when": "child.job_final_report is readable",
            }
        )
    elif action in {"blocked", "failed", "cancelled", "stop", "stop_duplicate"}:
        steps.append(
            {
                "index": 1,
                "name": "inspect_terminal_blockers",
                "tool": "get_job_summary",
                "endpoint": summary_endpoint,
                "method": "GET",
                "request": {"job_id": job_id},
                "continue_when": "blockers and next_actions are reported to the user",
            }
        )
    else:
        call = recommended_call if isinstance(recommended_call, dict) else {}
        steps.append(
            {
                "index": 1,
                "name": "follow_recommended_call",
                "tool": call.get("tool"),
                "endpoint": call.get("endpoint"),
                "method": call.get("method"),
                "request": call.get("request"),
                "continue_when": "recommended_call.safe_to_call_now=true or user has reviewed required gates",
            }
        )
    return {
        "kind": "ptcli.job_poll_resume_summary_sequence",
        "job_id": job_id or None,
        "status": status,
        "action": action,
        "ready": bool(steps),
        "primary_next_step": steps[0] if steps else None,
        "steps": steps,
        "complete_when": ["terminal status reached", "job_final_report or live_user_report read", "blockers reported or completion evidence reported"],
        "stop_when": ["duplicate_check.exists=true", "recommended_call.safe_to_call_now=false without user review", "resume preview command is not allowlisted"],
    }


def _job_resume_handoff(job: dict[str, Any], payload: dict[str, Any] | None = None) -> dict[str, Any]:
    """Narrow read-only resume handoff for agents that only need the next recovery call."""
    job_id = str(job.get("job_id") or "")
    status = str(job.get("status") or "unknown")
    runtime = _job_runtime(job)
    summary = _job_resume_summary(job)
    requirements = _job_resume_requirements(job, payload if isinstance(payload, dict) else None)
    execution = _job_resume_execution_handoff(job, payload if isinstance(payload, dict) else None)
    blockers = _job_resume_handoff_blockers(status, runtime, summary, execution)
    action = _job_resume_handoff_action(status, runtime, summary, execution, blockers)
    dry_run_request = execution.get("dry_run_request") if isinstance(execution.get("dry_run_request"), dict) else None
    execute_request = execution.get("execute_request") if isinstance(execution.get("execute_request"), dict) else None
    recommended_request = dry_run_request if action == "preview_resume" and dry_run_request else execute_request if action == "execute_resume" else None
    return {
        "kind": "ptcli.job_resume_handoff",
        "job_id": job_id or None,
        "job_kind": job.get("kind"),
        "status": status,
        "action": action,
        "ready": action in {"poll", "preview_resume", "execute_resume", "read_summary"},
        "available": bool(summary.get("available")),
        "allowed": bool(summary.get("allowed")),
        "recommended": bool(summary.get("recommended")),
        "terminal": bool(runtime.get("terminal")),
        "should_poll": bool(runtime.get("should_poll")),
        "preview_required": bool(execution.get("preview_required")),
        "subcommand": summary.get("subcommand"),
        "recommended_tool": "get_job_status" if action == "poll" else "get_job_summary" if action == "read_summary" else "resume_job" if action in {"preview_resume", "execute_resume"} else None,
        "recommended_endpoint": runtime.get("status_endpoint") if action == "poll" else runtime.get("summary_endpoint") if action == "read_summary" else execution.get("endpoint") if action in {"preview_resume", "execute_resume"} else None,
        "recommended_method": "GET" if action in {"poll", "read_summary"} else execution.get("method") if action in {"preview_resume", "execute_resume"} else None,
        "recommended_request": recommended_request,
        "dry_run_request": dry_run_request,
        "execute_request": execute_request,
        "required_overrides": requirements.get("required_overrides") if isinstance(requirements.get("required_overrides"), list) else [],
        "suggested_overrides": requirements.get("suggested_overrides") if isinstance(requirements.get("suggested_overrides"), list) else [],
        "recommended_inputs": requirements.get("recommended_inputs") if isinstance(requirements.get("recommended_inputs"), list) else [],
        "unresolved_recommended_inputs": execution.get("unresolved_recommended_inputs") if isinstance(execution.get("unresolved_recommended_inputs"), list) else [],
        "missing_confirmations": requirements.get("missing_confirmations") if isinstance(requirements.get("missing_confirmations"), list) else [],
        "allowed_overrides": requirements.get("allowed_overrides") if isinstance(requirements.get("allowed_overrides"), dict) else {},
        "safety": {
            "read_only": True,
            "dry_run_first": bool(execution.get("preview_required")),
            "execute_mutates_state": bool(execute_request),
            "live_upload_requires_accept_rules_confirm_upload": True,
            "do_not_execute_when": _string_list(execution.get("stop_when")) or ["job_resume_handoff.blockers is non-empty"],
        },
        "read_before_execute": ["job_resume_handoff", "resume_execution_handoff", "resume_requirements", "job_control_summary", "blockers"],
        "continue_when": _job_resume_handoff_continue_when(action),
        "stop_when": _job_resume_handoff_stop_when(action, blockers, execution),
        "blockers": blockers,
        "next_actions": _job_resume_handoff_next_actions(action, blockers, runtime, job_id),
    }


def _job_resume_handoff_action(status: str, runtime: dict[str, Any], summary: dict[str, Any], execution: dict[str, Any], blockers: list[str]) -> str:
    if runtime.get("should_poll"):
        return "poll"
    if status == "complete":
        return "read_summary"
    if status == "cancelled":
        return "stop_cancelled"
    if not summary.get("available"):
        return "unavailable"
    if not summary.get("allowed") or blockers:
        return "blocked"
    if execution.get("preview_required"):
        return "preview_resume"
    if execution.get("execute_request"):
        return "execute_resume"
    return "inspect"


def _job_resume_handoff_blockers(status: str, runtime: dict[str, Any], summary: dict[str, Any], execution: dict[str, Any]) -> list[str]:
    if runtime.get("should_poll") or status == "complete":
        return []
    blockers = [
        *_string_list(summary.get("blockers")),
        *_string_list(execution.get("blockers")),
    ]
    if status == "cancelled":
        blockers.append("job_cancelled")
    if not summary.get("available"):
        blockers.append(str(summary.get("blocker") or "No executable resume command is available for this job."))
    return list(dict.fromkeys(blocker for blocker in blockers if blocker))


def _job_resume_handoff_continue_when(action: str) -> str | None:
    if action == "poll":
        return "status not in queued,running"
    if action == "preview_resume":
        return "resume dry-run returns ok=true and command_argv plus safety gates have been reviewed"
    if action == "execute_resume":
        return "resume_job returns a child job_id; poll the child job_control_summary"
    if action == "read_summary":
        return "summary has been read and closure/live evidence is reported"
    return None


def _job_resume_handoff_stop_when(action: str, blockers: list[str], execution: dict[str, Any]) -> list[str]:
    stop_when = _string_list(execution.get("stop_when"))
    if blockers:
        stop_when.append("job_resume_handoff.blockers is non-empty")
    if action in {"stop_cancelled", "unavailable", "blocked"}:
        stop_when.append(f"job_resume_handoff.action={action}")
    return list(dict.fromkeys(stop_when))


def _job_resume_handoff_next_actions(action: str, blockers: list[str], runtime: dict[str, Any], job_id: str) -> list[str]:
    if action == "poll":
        return [f"Poll {runtime.get('status_endpoint') or f'/v1/jobs/{job_id}'} before attempting resume."]
    if action == "preview_resume":
        return ["Call job_resume_handoff.dry_run_request first; review command_argv, ignored_overrides, and safety gates before execute_request."]
    if action == "execute_resume":
        return ["Call job_resume_handoff.execute_request and poll the returned child job."]
    if action == "read_summary":
        return ["Read job summary and report closure_summary/live_completion_gate evidence."]
    if blockers:
        return ["Resolve job_resume_handoff.blockers before attempting resume."]
    return ["Inspect job_resume_handoff and job_control_summary before choosing the next job action."]


def _job_resume_final_report(job: dict[str, Any], payload: dict[str, Any] | None = None) -> dict[str, Any]:
    job_id = str(job.get("job_id") or "")
    status = str(job.get("status") or "unknown")
    handoff = _job_resume_handoff(job, payload if isinstance(payload, dict) else None)
    execution = _job_resume_execution_handoff(job, payload if isinstance(payload, dict) else None)
    action = str(handoff.get("action") or "inspect")
    blockers = list(dict.fromkeys([*_string_list(handoff.get("blockers")), *_string_list(execution.get("blockers"))]))
    recommended_call = _job_resume_final_report_recommended_call(job_id, action, handoff, execution, blockers)
    ready = action in {"poll", "preview_resume", "execute_resume", "read_summary"} and not blockers
    return {
        "kind": "ptcli.resume_final_report",
        "ready": ready,
        "resume_report_allowed": action in {"poll", "preview_resume", "execute_resume", "read_summary", "blocked", "unavailable"},
        "job_complete_report_allowed": False,
        "verdict": _job_resume_final_report_verdict(action, blockers),
        "action": action,
        "status": status,
        "job_id": job_id or None,
        "job_kind": job.get("kind"),
        "summary_file": _job_summary_file(job),
        "recommended_call": recommended_call,
        "recommended_tool": recommended_call.get("tool"),
        "recommended_endpoint": recommended_call.get("endpoint"),
        "recommended_method": recommended_call.get("method"),
        "recommended_request": recommended_call.get("request"),
        "dry_run_request": handoff.get("dry_run_request") if isinstance(handoff.get("dry_run_request"), dict) else None,
        "execute_request": handoff.get("execute_request") if isinstance(handoff.get("execute_request"), dict) else None,
        "requirements": {
            "preview_required": bool(handoff.get("preview_required")),
            "required_overrides": handoff.get("required_overrides") if isinstance(handoff.get("required_overrides"), list) else [],
            "missing_confirmations": handoff.get("missing_confirmations") if isinstance(handoff.get("missing_confirmations"), list) else [],
            "unresolved_recommended_inputs": handoff.get("unresolved_recommended_inputs") if isinstance(handoff.get("unresolved_recommended_inputs"), list) else [],
        },
        "read_order": ["resume_final_report", "job_resume_handoff", "resume_execution_handoff", "resume_requirements", "resume_summary", "job_control_summary", "recovery_handoff"],
        "complete_when": ["resume_final_report.verdict=read_summary", "then read job_final_report/live_user_report for actual job completion"],
        "stop_when": _string_list(handoff.get("stop_when")) or ["resume_final_report.blockers is non-empty", "resume_final_report.verdict=blocked"],
        "safety": {
            "read_only": True,
            "mutates_state": False,
            "resume_call_mutates_state": recommended_call.get("tool") == "resume_job" and recommended_call.get("dry_run") is not True,
            "dry_run_first": bool(handoff.get("preview_required")),
            "execute_requires_user_review": bool(recommended_call.get("requires_user_review")),
            "unknown_overrides_ignored": True,
            "must_not_report_job_complete": True,
        },
        "blockers": blockers,
        "next_actions": _job_resume_final_report_next_actions(action, recommended_call, blockers, job_id),
    }


def _job_resume_final_report_verdict(action: str, blockers: list[str]) -> str:
    if blockers and action not in {"poll", "read_summary"}:
        return "blocked"
    if action == "poll":
        return "poll"
    if action == "preview_resume":
        return "preview_resume"
    if action == "execute_resume":
        return "execute_resume"
    if action == "read_summary":
        return "read_summary"
    if action == "unavailable":
        return "unavailable"
    return "inspect"


def _job_resume_final_report_recommended_call(job_id: str, action: str, handoff: dict[str, Any], execution: dict[str, Any], blockers: list[str]) -> dict[str, Any]:
    if action == "poll":
        endpoint = handoff.get("recommended_endpoint") or (f"/v1/jobs/{job_id}" if job_id else None)
        return {"tool": "get_job_status", "endpoint": endpoint, "method": "GET", "request": {"job_id": job_id} if job_id else None, "safe_to_call_now": True, "requires_user_review": False}
    if action == "read_summary":
        endpoint = handoff.get("recommended_endpoint") or (f"/v1/jobs/{job_id}/summary" if job_id else None)
        return {"tool": "get_job_summary", "endpoint": endpoint, "method": "GET", "request": {"job_id": job_id} if job_id else None, "safe_to_call_now": True, "requires_user_review": False}
    dry_run_request = handoff.get("dry_run_request") if isinstance(handoff.get("dry_run_request"), dict) else execution.get("dry_run_request") if isinstance(execution.get("dry_run_request"), dict) else None
    execute_request = handoff.get("execute_request") if isinstance(handoff.get("execute_request"), dict) else execution.get("execute_request") if isinstance(execution.get("execute_request"), dict) else None
    endpoint = handoff.get("recommended_endpoint") or execution.get("endpoint")
    method = handoff.get("recommended_method") or execution.get("method") or "POST"
    if action == "preview_resume" and dry_run_request and not blockers:
        return {
            "tool": "resume_job",
            "endpoint": endpoint,
            "method": method,
            "request": dry_run_request,
            "dry_run_request": dry_run_request,
            "execute_request": execute_request,
            "dry_run": True,
            "safe_to_call_now": True,
            "requires_user_review": True,
            "continue_with": "resume_final_report.recommended_call.execute_request after dry-run preview is reviewed",
        }
    if action == "execute_resume" and execute_request and not blockers:
        return {
            "tool": "resume_job",
            "endpoint": endpoint,
            "method": method,
            "request": execute_request,
            "dry_run_request": dry_run_request,
            "execute_request": execute_request,
            "dry_run": False,
            "safe_to_call_now": False,
            "requires_user_review": True,
            "continue_with": "poll returned child job until job_final_report is ready",
        }
    return {
        "tool": None,
        "endpoint": endpoint,
        "method": method,
        "request": None,
        "dry_run_request": dry_run_request,
        "execute_request": execute_request,
        "safe_to_call_now": False,
        "requires_user_review": True,
        "reason": "resume_final_report.blocked_or_unavailable",
    }


def _job_resume_final_report_next_actions(action: str, recommended_call: dict[str, Any], blockers: list[str], job_id: str) -> list[str]:
    if action == "poll":
        return [f"Poll /v1/jobs/{job_id} until the job leaves queued/running."]
    if action == "read_summary":
        return [f"Read /v1/jobs/{job_id}/summary, then use job_final_report to decide whether user reporting is allowed."]
    if action == "preview_resume" and recommended_call.get("request"):
        return ["Call resume_final_report.recommended_call.request as a dry-run preview, then inspect resume_preview.command_argv and ignored_overrides."]
    if action == "execute_resume" and recommended_call.get("execute_request"):
        return ["Execute resume_final_report.recommended_call.execute_request only after user review, then poll the returned child job."]
    if blockers:
        return ["Resolve resume_final_report.blockers before calling resume_job."]
    return ["Inspect resume_final_report.read_order before choosing the next resume action."]


def _job_lifecycle_final_report(job: dict[str, Any], payload: dict[str, Any] | None = None) -> dict[str, Any]:
    """Single final report for AI job polling, resume, and summary handoff."""
    job_id = str(job.get("job_id") or "")
    status = str(job.get("status") or "unknown")
    runtime = _job_runtime(job)
    control = _job_control_summary(job, payload if isinstance(payload, dict) else None)
    resume_report = _job_resume_final_report(job, payload if isinstance(payload, dict) else None)
    final_report = _job_final_report(job, payload if isinstance(payload, dict) else None)
    sequence = control.get("poll_resume_summary_sequence") if isinstance(control.get("poll_resume_summary_sequence"), dict) else {}
    primary_next_step = sequence.get("primary_next_step") if isinstance(sequence.get("primary_next_step"), dict) else None
    recommended_call = _job_lifecycle_recommended_call(control, resume_report, final_report, primary_next_step)
    action = _job_lifecycle_action(status, runtime, control, resume_report, final_report)
    blockers = list(dict.fromkeys([*_string_list(control.get("blockers")), *_string_list(resume_report.get("blockers")), *_string_list(final_report.get("blockers"))]))
    report_allowed = bool(final_report.get("report_allowed") or final_report.get("ready_for_user_report"))
    return {
        "kind": "ptcli.job_lifecycle_final_report",
        "ready": action in {"poll", "preview_resume", "execute_resume", "read_summary", "report_complete"} and not (blockers and action not in {"poll", "read_summary"}),
        "report_allowed": report_allowed,
        "verdict": _job_lifecycle_verdict(action, status, blockers, report_allowed),
        "action": action,
        "status": status,
        "job_id": job_id or None,
        "job_kind": job.get("kind"),
        "terminal": bool(runtime.get("terminal")),
        "should_poll": bool(runtime.get("should_poll")),
        "should_resume": bool(control.get("should_resume") or resume_report.get("ready")),
        "resume_preview_required": bool(control.get("resume_preview_required") or resume_report.get("requirements", {}).get("preview_required")),
        "summary_file": _job_summary_file(job),
        "status_endpoint": runtime.get("status_endpoint"),
        "summary_endpoint": runtime.get("summary_endpoint"),
        "resume_endpoint": runtime.get("resume_endpoint"),
        "primary_next_step": primary_next_step,
        "recommended_call": recommended_call,
        "recommended_tool": recommended_call.get("tool"),
        "recommended_endpoint": recommended_call.get("endpoint"),
        "recommended_method": recommended_call.get("method"),
        "recommended_request": recommended_call.get("request"),
        "dry_run_request": control.get("dry_run_request") if isinstance(control.get("dry_run_request"), dict) else resume_report.get("dry_run_request") if isinstance(resume_report.get("dry_run_request"), dict) else None,
        "execute_request": control.get("execute_request") if isinstance(control.get("execute_request"), dict) else resume_report.get("execute_request") if isinstance(resume_report.get("execute_request"), dict) else None,
        "sequence": sequence,
        "read_order": ["job_lifecycle_final_report", "job_control_summary", "resume_final_report", "job_final_report", "recovery_handoff", "job_handoff"],
        "complete_when": [
            "job_lifecycle_final_report.verdict=report_complete",
            "job_final_report.report_allowed=true",
            "live_user_report.report_allowed=true when live upload evidence is required",
        ],
        "stop_when": _job_lifecycle_stop_when(action, control, resume_report, final_report),
        "safety": {
            "read_only": True,
            "mutates_state": False,
            "resume_execute_requires_user_review": True,
            "live_upload_requires_accept_rules_confirm_upload": True,
            "must_not_report_complete_until_summary_read": True,
            "safe_to_call_now": bool(recommended_call.get("safe_to_call_now")),
        },
        "blockers": blockers,
        "next_actions": _job_lifecycle_next_actions(action, recommended_call, blockers, job_id),
    }


def _job_lifecycle_action(status: str, runtime: dict[str, Any], control: dict[str, Any], resume_report: dict[str, Any], final_report: dict[str, Any]) -> str:
    if runtime.get("should_poll"):
        return "poll"
    if final_report.get("ready_for_user_report") or final_report.get("report_allowed"):
        return "report_complete"
    control_action = str(control.get("action") or "")
    resume_action = str(resume_report.get("action") or "")
    if control_action in {"resume_preview", "prepare_materials", "prepare_target_package", "target_upload_closure"} or resume_action == "preview_resume":
        return "preview_resume"
    if control_action == "resume_execute" or resume_action == "execute_resume":
        return "execute_resume"
    if control_action in {"read_summary", "done"} or resume_action == "read_summary" or status == "complete":
        return "read_summary"
    if control_action in {"stop_duplicate", "stop", "blocked", "failed", "cancelled"}:
        return control_action
    if status in {"blocked", "failed", "cancelled"}:
        return status
    return control_action or resume_action or "inspect"


def _job_lifecycle_recommended_call(control: dict[str, Any], resume_report: dict[str, Any], final_report: dict[str, Any], primary_next_step: dict[str, Any] | None) -> dict[str, Any]:
    for source in (control.get("recommended_call"), resume_report.get("recommended_call"), final_report.get("recommended_call")):
        if isinstance(source, dict) and source.get("tool"):
            return source
    if isinstance(primary_next_step, dict) and primary_next_step.get("tool"):
        return {
            "ready": True,
            "safe_to_call_now": primary_next_step.get("tool") in {"get_job_status", "get_job_summary"},
            "tool": primary_next_step.get("tool"),
            "endpoint": primary_next_step.get("endpoint"),
            "method": primary_next_step.get("method"),
            "request": primary_next_step.get("request"),
            "requires_user_review": bool(primary_next_step.get("requires_user_review")),
        }
    return {"ready": False, "safe_to_call_now": False, "tool": None, "endpoint": None, "method": None, "request": None, "requires_user_review": True}


def _job_lifecycle_verdict(action: str, status: str, blockers: list[str], report_allowed: bool) -> str:
    if report_allowed:
        return "report_complete"
    if action == "poll":
        return "poll"
    if action == "preview_resume":
        return "preview_resume"
    if action == "execute_resume":
        return "execute_resume_after_review"
    if action == "read_summary":
        return "read_summary"
    if action == "stop_duplicate":
        return "stop_duplicate"
    if status == "cancelled" or action == "cancelled":
        return "cancelled"
    if blockers:
        return "blocked"
    if status == "failed" or action == "failed":
        return "failed"
    return "inspect"


def _job_lifecycle_stop_when(action: str, control: dict[str, Any], resume_report: dict[str, Any], final_report: dict[str, Any]) -> list[str]:
    stop_when = [*_string_list(control.get("stop_when")), *_string_list(resume_report.get("stop_when")), *_string_list(final_report.get("stop_when"))]
    if action == "execute_resume":
        stop_when.append("do not execute resume without reviewing the dry-run preview and required confirmations")
    if action == "stop_duplicate":
        stop_when.append("duplicate_check.exists=true")
    return list(dict.fromkeys(stop_when))


def _job_lifecycle_next_actions(action: str, recommended_call: dict[str, Any], blockers: list[str], job_id: str) -> list[str]:
    if action == "poll":
        return [f"Poll /v1/jobs/{job_id}, then read job_lifecycle_final_report again."]
    if action == "preview_resume" and recommended_call.get("request"):
        return ["Call job_lifecycle_final_report.recommended_call as a dry-run preview, review command_argv and safety gates, then execute the returned execute_request if approved."]
    if action == "execute_resume" and recommended_call.get("execute_request"):
        return ["Execute resume only after user review, then poll the returned child job and read its summary."]
    if action in {"read_summary", "report_complete"}:
        return [f"Read /v1/jobs/{job_id}/summary and report job_final_report/live_user_report evidence."]
    if blockers:
        return ["Resolve job_lifecycle_final_report.blockers before continuing this job."]
    return ["Inspect job_lifecycle_final_report.read_order and follow the recommended_call only when safe_to_call_now=true or after user review."]


def _job_lifecycle_control(job: dict[str, Any], payload: dict[str, Any] | None = None) -> dict[str, Any]:
    """Short AI control surface for job status, summary, list, and resume loops."""
    lifecycle = _job_lifecycle_final_report(job, payload if isinstance(payload, dict) else None)
    recommended_call = lifecycle.get("recommended_call") if isinstance(lifecycle.get("recommended_call"), dict) else {}
    job_id = str(job.get("job_id") or "")
    action = str(lifecycle.get("action") or "inspect")
    status = str(lifecycle.get("status") or job.get("status") or "unknown")
    return {
        "kind": "ptcli.job_lifecycle_control",
        "ready": bool(lifecycle.get("ready")),
        "status": status,
        "verdict": lifecycle.get("verdict"),
        "action": action,
        "job_id": job_id or None,
        "job_kind": lifecycle.get("job_kind") or job.get("kind"),
        "terminal": bool(lifecycle.get("terminal")),
        "should_poll": bool(lifecycle.get("should_poll")),
        "should_resume": bool(lifecycle.get("should_resume")),
        "report_allowed": bool(lifecycle.get("report_allowed")),
        "safe_to_call_now": bool(recommended_call.get("safe_to_call_now")),
        "recommended_tool": recommended_call.get("tool"),
        "recommended_endpoint": recommended_call.get("endpoint"),
        "recommended_method": recommended_call.get("method"),
        "recommended_request": recommended_call.get("request"),
        "dry_run_request": lifecycle.get("dry_run_request"),
        "execute_request": lifecycle.get("execute_request"),
        "status_endpoint": lifecycle.get("status_endpoint"),
        "summary_endpoint": lifecycle.get("summary_endpoint"),
        "resume_endpoint": lifecycle.get("resume_endpoint"),
        "poll_after_seconds": _job_runtime(job).get("poll_after_seconds"),
        "allowed_transitions": _job_lifecycle_control_transitions(action, lifecycle, recommended_call),
        "read_order": ["job_lifecycle_control", "job_lifecycle_final_report", "job_control_summary", "job_summary_final_report", "job_final_report"],
        "complete_when": lifecycle.get("complete_when") if isinstance(lifecycle.get("complete_when"), list) else [],
        "stop_when": lifecycle.get("stop_when") if isinstance(lifecycle.get("stop_when"), list) else [],
        "safety": {
            "read_only": True,
            "mutates_state": False,
            "safe_to_call_now": bool(recommended_call.get("safe_to_call_now")),
            "resume_execute_requires_user_review": True,
            "live_upload_requires_accept_rules_confirm_upload": True,
            "does_not_upload": True,
        },
        "blockers": _string_list(lifecycle.get("blockers")),
        "next_actions": _string_list(lifecycle.get("next_actions")),
    }


def _job_lifecycle_control_transitions(action: str, lifecycle: dict[str, Any], recommended_call: dict[str, Any]) -> list[dict[str, Any]]:
    transitions: list[dict[str, Any]] = []
    if action == "poll":
        transitions.append(_job_lifecycle_control_transition("poll_status", lifecycle.get("status_endpoint"), "GET", None, safe=True, requires_user_review=False))
    if action in {"read_summary", "report_complete"}:
        transitions.append(_job_lifecycle_control_transition("read_summary", lifecycle.get("summary_endpoint"), "GET", None, safe=True, requires_user_review=False))
    if action == "preview_resume":
        transitions.append(_job_lifecycle_control_transition("preview_resume", lifecycle.get("resume_endpoint"), "POST", lifecycle.get("dry_run_request") or recommended_call.get("request"), safe=True, requires_user_review=True))
    if action == "execute_resume":
        transitions.append(_job_lifecycle_control_transition("execute_resume", lifecycle.get("resume_endpoint"), "POST", lifecycle.get("execute_request") or recommended_call.get("execute_request"), safe=False, requires_user_review=True))
    if recommended_call.get("tool") and not any(item.get("tool") == recommended_call.get("tool") and item.get("endpoint") == recommended_call.get("endpoint") for item in transitions):
        transitions.append(
            {
                "name": str(recommended_call.get("action") or action or "recommended_call"),
                "tool": recommended_call.get("tool"),
                "endpoint": recommended_call.get("endpoint"),
                "method": recommended_call.get("method"),
                "request": recommended_call.get("request"),
                "safe_to_call_now": bool(recommended_call.get("safe_to_call_now")),
                "requires_user_review": bool(recommended_call.get("requires_user_review", not recommended_call.get("safe_to_call_now"))),
            }
        )
    return transitions


def _job_lifecycle_control_transition(name: str, endpoint: Any, method: str, request: Any, *, safe: bool, requires_user_review: bool) -> dict[str, Any]:
    tool = {"GET": "get_job_status" if name == "poll_status" else "get_job_summary", "POST": "resume_job"}.get(method)
    return {
        "name": name,
        "tool": tool,
        "endpoint": endpoint,
        "method": method,
        "request": request,
        "safe_to_call_now": safe,
        "requires_user_review": requires_user_review,
    }


def _job_summary_final_report(job: dict[str, Any], payload: dict[str, Any] | None = None) -> dict[str, Any]:
    """Top-level first-read report for job status and summary endpoints."""
    job_id = str(job.get("job_id") or "")
    status = str(job.get("status") or "unknown")
    payload_dict = payload if isinstance(payload, dict) else None
    lifecycle = _job_lifecycle_final_report(job, payload_dict)
    final_report = _job_final_report(job, payload_dict)
    live_audit = _job_live_validation_completion_audit(job, payload_dict)
    live_report = _job_live_user_report(job, payload_dict)
    resume_report = _job_resume_final_report(job, payload_dict)
    control = _job_control_summary(job, payload_dict)
    recommended_call = lifecycle.get("recommended_call") if isinstance(lifecycle.get("recommended_call"), dict) else {}
    live_required = _job_live_evidence_required(job, payload_dict)
    blockers = list(dict.fromkeys([*_string_list(lifecycle.get("blockers")), *_string_list(final_report.get("blockers")), *_string_list(live_audit.get("blockers"))]))
    report_allowed = bool(lifecycle.get("report_allowed") and (not live_required or live_audit.get("report_allowed") is True) and not blockers)
    return {
        "kind": "ptcli.job_summary_final_report",
        "ready": bool(lifecycle.get("ready")),
        "report_allowed": report_allowed,
        "verdict": _job_summary_final_report_verdict(status, lifecycle, final_report, live_audit, blockers, live_required),
        "action": lifecycle.get("action"),
        "status": status,
        "job_id": job_id or None,
        "job_kind": job.get("kind"),
        "terminal": lifecycle.get("terminal"),
        "should_poll": lifecycle.get("should_poll"),
        "should_resume": lifecycle.get("should_resume"),
        "resume_preview_required": lifecycle.get("resume_preview_required"),
        "summary_file": _job_summary_file(job),
        "status_endpoint": lifecycle.get("status_endpoint"),
        "summary_endpoint": lifecycle.get("summary_endpoint"),
        "resume_endpoint": lifecycle.get("resume_endpoint"),
        "primary_report_field": "live_validation_completion_audit" if live_required else "job_final_report",
        "control_field": "job_lifecycle_final_report",
        "lifecycle": {
            "verdict": lifecycle.get("verdict"),
            "action": lifecycle.get("action"),
            "report_allowed": lifecycle.get("report_allowed"),
            "recommended_tool": lifecycle.get("recommended_tool"),
        },
        "completion_gate": {
            "job_final_report_allowed": final_report.get("report_allowed"),
            "live_evidence_required": live_required,
            "live_validation_completion_audit_allowed": live_audit.get("report_allowed"),
            "live_user_report_allowed": live_report.get("report_allowed"),
            "resume_report_allowed": resume_report.get("resume_report_allowed"),
        },
        "recommended_call": recommended_call,
        "recommended_tool": recommended_call.get("tool"),
        "recommended_endpoint": recommended_call.get("endpoint"),
        "recommended_method": recommended_call.get("method"),
        "recommended_request": recommended_call.get("request"),
        "dry_run_request": lifecycle.get("dry_run_request"),
        "execute_request": lifecycle.get("execute_request"),
        "read_order": ["job_summary_final_report", "job_lifecycle_final_report", "job_final_report", "live_validation_completion_audit", "job_control_summary", "resume_final_report", "recovery_handoff", "job_handoff"],
        "complete_when": _job_summary_final_report_complete_when(live_required),
        "stop_when": _job_summary_final_report_stop_when(lifecycle, final_report, live_audit),
        "safety": {
            "read_only": True,
            "mutates_state": False,
            "safe_to_call_now": bool(recommended_call.get("safe_to_call_now")),
            "resume_execute_requires_user_review": True,
            "live_upload_requires_accept_rules_confirm_upload": True,
            "must_not_report_live_complete_until_completion_audit": live_required,
            "source_control_action": control.get("action"),
        },
        "blockers": blockers,
        "next_actions": _job_summary_final_report_next_actions(lifecycle, recommended_call, blockers, job_id, live_required),
    }


def _job_live_evidence_required(job: dict[str, Any], payload: dict[str, Any] | None = None) -> bool:
    request = job.get("request") if isinstance(job.get("request"), dict) else {}
    if request.get("confirm_upload") is True or request.get("execute") is True or request.get("target_execute") is True:
        return True
    if request.get("live_validation_submission") or request.get("live_validation_followup"):
        return True
    if str(job.get("kind") or "") in {"ptcli.retorrent", "ptcli.source_url_retorrent", "ptcli.checked_retorrent", "ptcli.target_upload"}:
        return True
    return bool(isinstance(payload, dict) and (payload.get("live_validation_completion_audit") or payload.get("live_user_report")))


def _job_summary_final_report_verdict(status: str, lifecycle: dict[str, Any], final_report: dict[str, Any], live_audit: dict[str, Any], blockers: list[str], live_required: bool) -> str:
    action = str(lifecycle.get("action") or "")
    if blockers and action not in {"poll", "read_summary"}:
        return "blocked"
    if status in {"queued", "running"} or action == "poll":
        return "poll"
    if live_required and live_audit.get("report_allowed") is True:
        return "report_complete"
    if not live_required and final_report.get("report_allowed") is True:
        return "report_complete"
    return str(lifecycle.get("verdict") or final_report.get("verdict") or status or "inspect")


def _job_summary_final_report_complete_when(live_required: bool) -> list[str]:
    if live_required:
        return ["job_summary_final_report.verdict=report_complete", *LIVE_VALIDATION_COMPLETE_WHEN]
    return ["job_summary_final_report.verdict=report_complete", "job_final_report.report_allowed=true"]


def _job_summary_final_report_stop_when(lifecycle: dict[str, Any], final_report: dict[str, Any], live_audit: dict[str, Any]) -> list[str]:
    return list(dict.fromkeys([*_string_list(lifecycle.get("stop_when")), *_string_list(final_report.get("stop_when")), *_string_list(live_audit.get("stop_when")), "job_summary_final_report.blockers is non-empty"]))


def _job_summary_final_report_next_actions(lifecycle: dict[str, Any], recommended_call: dict[str, Any], blockers: list[str], job_id: str, live_required: bool) -> list[str]:
    if blockers:
        return ["Resolve job_summary_final_report.blockers before continuing this job."]
    action = str(lifecycle.get("action") or "")
    if action == "poll":
        return [f"Poll /v1/jobs/{job_id} until terminal, then read job_summary_final_report again."]
    if action == "preview_resume" and recommended_call.get("request"):
        return ["Call job_summary_final_report.recommended_call as a dry-run preview, then review command_argv and safety gates before execute."]
    if action == "execute_resume" and recommended_call.get("execute_request"):
        return ["Execute resume only after user review, then poll the returned child job."]
    if live_required:
        return ["Read live_validation_completion_audit and report completion only when job_summary_final_report.complete_when is satisfied."]
    return ["Read job_final_report and report only when job_summary_final_report.report_allowed=true."]


def _job_progress_handoff(job: dict[str, Any], payload: dict[str, Any] | None = None) -> dict[str, Any]:
    job_id = str(job.get("job_id") or "")
    status = str(job.get("status") or "unknown")
    runtime = _job_runtime(job)
    source_reference = _job_source_reference(job)
    duplicate_check = _job_duplicate_check(job)
    policy_handoff = _job_policy_handoff(job) or {}
    policy_gate = _job_policy_enforcement_gate(job) or {}
    material_evidence = _job_material_evidence_summary(job, payload if isinstance(payload, dict) else None) or {}
    materials_handoff = _job_materials_handoff(job, payload if isinstance(payload, dict) else None) or {}
    target_package = _job_target_package_handoff(job, payload if isinstance(payload, dict) else None) or {}
    target_upload = _job_target_upload_handoff(job, payload if isinstance(payload, dict) else None) or {}
    closure_summary = _job_closure_summary(job, payload if isinstance(payload, dict) else None)
    live_user_report = _job_live_user_report(job, payload if isinstance(payload, dict) else None)
    job_control = _job_control_summary(job, payload if isinstance(payload, dict) else None)
    source_ready = bool(source_reference and source_reference.get("tracker") and (source_reference.get("source_id") or source_reference.get("url")))
    duplicate_searched = duplicate_check.get("searched") is True
    duplicate_clear = duplicate_searched and duplicate_check.get("exists") is False
    policy_ready = policy_gate.get("ready") is True or policy_handoff.get("ready") is True
    materials_ready = material_evidence.get("ready") is True or materials_handoff.get("ready") is True
    target_package_ready = target_package.get("ready") is True or bool(target_package.get("package_dir"))
    target_upload_ready = target_upload.get("ready_for_live_upload") is True
    uploaded_seeding_ready = target_upload.get("uploaded_seeding_ready") is True
    closure_ready = closure_summary.get("complete") is True or live_user_report.get("report_allowed") is True
    stages = [
        _job_progress_stage("source_identified", "Source torrent identified", source_ready, not source_ready and status not in {"queued", "running"}, source_reference, "source_url_retorrent_preflight"),
        _job_progress_stage("target_duplicate_checked", "Target duplicate check completed", duplicate_searched, not duplicate_searched and status not in {"queued", "running"}, duplicate_check, "retorrent_check"),
        _job_progress_stage("target_duplicate_clear", "Target duplicate gate clear", duplicate_clear, duplicate_check.get("exists") is True, duplicate_check, None),
        _job_progress_stage("site_policy_ready", "Site policy and rule gate ready", policy_ready, policy_gate.get("ready") is False or policy_handoff.get("ready") is False, {"policy_handoff": policy_handoff, "policy_enforcement_gate": policy_gate}, "site_policies"),
        _job_progress_stage("materials_ready", "Metadata, description, media info, screenshots, and image host ready", materials_ready, bool(material_evidence.get("blockers") or materials_handoff.get("blockers")), {"material_evidence_summary": material_evidence, "materials_handoff": materials_handoff}, "resume_job"),
        _job_progress_stage("target_package_ready", "Target package prepared", target_package_ready, bool(target_package.get("blockers")), target_package, "target_package_prepare_job"),
        _job_progress_stage("target_upload_ready", "Target upload payload ready", target_upload_ready, bool(target_upload.get("blockers")), target_upload, "target_upload_job"),
        _job_progress_stage("uploaded_seeding_ready", "Uploaded target torrent seeding verified", uploaded_seeding_ready, bool(target_upload.get("blockers")) and target_upload_ready, target_upload, "resume_job"),
        _job_progress_stage("closure_ready", "Closure evidence ready for user report", closure_ready, bool(closure_summary.get("blockers") or live_user_report.get("blockers")), {"closure_summary": closure_summary, "live_user_report": live_user_report}, "get_job_summary"),
    ]
    completed = [stage for stage in stages if stage["ready"]]
    blocked = [stage for stage in stages if stage["blocked"] and not stage["ready"]]
    current_stage = next((stage for stage in stages if not stage["ready"]), stages[-1] if stages else None)
    next_step = _job_progress_next_step(current_stage, job_control)
    ready = closure_ready
    action = "poll" if runtime.get("should_poll") else "read_summary" if ready else "resolve_blockers" if blocked else "continue"
    return {
        "kind": "ptcli.job_progress_handoff",
        "job_id": job_id or None,
        "job_kind": job.get("kind"),
        "status": status,
        "ready": ready,
        "action": action,
        "progress": {
            "completed_count": len(completed),
            "total_count": len(stages),
            "blocked_count": len(blocked),
            "percent": round((len(completed) / len(stages)) * 100, 1) if stages else 0.0,
        },
        "current_stage": current_stage,
        "stages": stages,
        "next_step": next_step,
        "recommended_tool": next_step.get("tool") if isinstance(next_step, dict) else None,
        "recommended_endpoint": next_step.get("endpoint") if isinstance(next_step, dict) else None,
        "recommended_request": next_step.get("request") if isinstance(next_step, dict) else None,
        "read_order": ["job_progress_handoff", "job_control_summary", "job_resume_handoff", "manual_retorrent_handoff", "closure_summary", "live_user_report"],
        "continue_when": "job_progress_handoff.ready=true and live_user_report.report_allowed=true",
        "stop_when": ["duplicate_check.exists=true", "site policy/rule gate blocked", "live upload missing accept_rules or confirm_upload", "job_progress_handoff.current_stage.blocked=true"],
        "blockers": list(dict.fromkeys(blocker for stage in blocked for blocker in _string_list(stage.get("blockers")))),
        "next_actions": _job_progress_next_actions(action, next_step, blocked, runtime, job_id),
    }


def _job_progress_stage(name: str, label: str, ready: bool, blocked: bool, evidence: Any, recommended_tool: str | None) -> dict[str, Any]:
    evidence_dict = evidence if isinstance(evidence, dict) else {}
    blockers = _string_list(evidence_dict.get("blockers"))
    return {
        "name": name,
        "label": label,
        "ready": bool(ready),
        "blocked": bool(blocked) and not ready,
        "recommended_tool": recommended_tool,
        "evidence": evidence,
        "blockers": blockers,
    }


def _job_progress_next_step(current_stage: dict[str, Any] | None, job_control: dict[str, Any]) -> dict[str, Any]:
    control_call = job_control.get("recommended_call") if isinstance(job_control.get("recommended_call"), dict) else {}
    if control_call.get("tool"):
        return {
            "tool": control_call.get("tool"),
            "endpoint": control_call.get("endpoint"),
            "method": control_call.get("method"),
            "request": control_call.get("request"),
            "reason": f"job_control_summary.{job_control.get('action')}",
        }
    if current_stage and current_stage.get("recommended_tool"):
        return {
            "tool": current_stage.get("recommended_tool"),
            "endpoint": job_control.get("recommended_endpoint"),
            "method": job_control.get("recommended_method"),
            "request": job_control.get("recommended_request"),
            "reason": f"current_stage.{current_stage.get('name')}",
        }
    return {
        "tool": job_control.get("recommended_tool"),
        "endpoint": job_control.get("recommended_endpoint"),
        "method": job_control.get("recommended_method"),
        "request": job_control.get("recommended_request"),
        "reason": f"job_control_summary.{job_control.get('action') or 'inspect'}",
    }


def _job_progress_next_actions(action: str, next_step: dict[str, Any], blocked: list[dict[str, Any]], runtime: dict[str, Any], job_id: str) -> list[str]:
    if action == "poll":
        return [f"Poll {runtime.get('status_endpoint') or f'/v1/jobs/{job_id}'} before evaluating progress again."]
    if action == "read_summary":
        return ["Read live_user_report, closure_summary, and job_progress_handoff before reporting completion."]
    if blocked:
        first = blocked[0]
        return [f"Resolve job_progress_handoff.current_stage={first.get('name')} before continuing."]
    if next_step.get("tool"):
        return [f"Call job_progress_handoff.next_step.tool={next_step.get('tool')} after reviewing site rules and safety gates."]
    return ["Inspect job_progress_handoff.stages and job_control_summary before choosing the next action."]


def _job_control_action(
    status: str,
    runtime: dict[str, Any],
    job_handoff: dict[str, Any],
    recovery_handoff: dict[str, Any],
    completion_report: dict[str, Any],
    closure_summary: dict[str, Any],
) -> str:
    if runtime.get("should_poll"):
        return "poll"
    completion_status = str(completion_report.get("status") or "")
    if completion_status == "duplicate_stopped" or closure_summary.get("action") == "stop_duplicate":
        return "stop_duplicate"
    if completion_report.get("ready_for_user_report") is True:
        return "read_summary"
    if status == "cancelled":
        return "cancelled"
    if status == "failed":
        return "failed"
    recovery_action = str(recovery_handoff.get("action") or "")
    if recovery_action in {"preview_resume", "prepare_materials", "repair_target_payload", "repair_qbit"}:
        return "resume_preview"
    if recovery_action == "execute_resume":
        return "resume_execute"
    if recovery_action in {"prepare_target_package", "target_upload_closure", "repair_qbit", "read_summary", "stop", "poll", "configure_policy"}:
        return recovery_action
    job_action = str(job_handoff.get("action") or "")
    if job_action in {"prepare_materials", "prepare_target_package", "target_upload_closure", "resume", "done", "stop", "stop_duplicate", "collect_confirmations", "configure_policy"}:
        return "resume_preview" if job_action == "resume" else job_action
    if status == "complete":
        return "read_summary"
    if status == "blocked":
        return "blocked"
    return "inspect"


def _job_control_recommended_call(
    job_handoff: dict[str, Any],
    recovery_handoff: dict[str, Any],
    completion_report: dict[str, Any],
    closure_summary: dict[str, Any],
) -> dict[str, Any] | None:
    job_call = job_handoff.get("recommended_call") if isinstance(job_handoff.get("recommended_call"), dict) else None
    if job_call and job_call.get("ready"):
        return job_call
    completion_call = completion_report.get("recommended_call") if isinstance(completion_report.get("recommended_call"), dict) else None
    if completion_call and completion_call.get("ready"):
        return completion_call
    next_step = closure_summary.get("next_step") if isinstance(closure_summary.get("next_step"), dict) else {}
    if next_step.get("tool"):
        return {
            "ready": True,
            "safe_to_call_now": False,
            "tool": next_step.get("tool"),
            "endpoint": next_step.get("endpoint"),
            "method": next_step.get("method"),
            "request": next_step.get("request"),
            "action": closure_summary.get("action"),
            "status": None,
            "dry_run_request": recovery_handoff.get("dry_run_request"),
            "execute_request": recovery_handoff.get("execute_request"),
            "requires_user_review": True,
            "gates": {},
            "safety": {"safe_to_call_now": False, "do_not_call_when": _string_list(closure_summary.get("stop_when"))},
            "stop_when": _string_list(closure_summary.get("stop_when")),
        }
    if recovery_handoff.get("recommended_tool"):
        return {
            "ready": True,
            "safe_to_call_now": recovery_handoff.get("action") in {"poll", "configure_policy"},
            "tool": recovery_handoff.get("recommended_tool"),
            "endpoint": recovery_handoff.get("recommended_endpoint"),
            "method": recovery_handoff.get("recommended_method"),
            "request": recovery_handoff.get("recommended_request"),
            "action": recovery_handoff.get("action"),
            "status": recovery_handoff.get("status"),
            "dry_run_request": recovery_handoff.get("dry_run_request"),
            "execute_request": recovery_handoff.get("execute_request"),
            "requires_user_review": recovery_handoff.get("resume_preview_required") is True and recovery_handoff.get("action") != "configure_policy",
            "gates": recovery_handoff.get("gates") if isinstance(recovery_handoff.get("gates"), dict) else {},
            "safety": {"safe_to_call_now": recovery_handoff.get("action") in {"poll", "configure_policy"}, "do_not_call_when": _string_list(recovery_handoff.get("stop_when"))},
            "stop_when": _string_list(recovery_handoff.get("stop_when")),
        }
    return None


def _job_control_state(action: str, status: str) -> str:
    if action == "poll":
        return "waiting"
    if action == "read_summary":
        return "complete"
    if action.startswith("stop") or action in {"cancelled", "failed"}:
        return "terminal"
    if action in {"resume_preview", "resume_execute", "prepare_materials", "prepare_target_package", "target_upload_closure", "repair_qbit", "configure_policy"}:
        return "action_required"
    if status == "blocked":
        return "blocked"
    return "inspect"


def _job_control_blockers(
    job: dict[str, Any],
    recovery_handoff: dict[str, Any],
    completion_report: dict[str, Any],
    closure_summary: dict[str, Any],
) -> list[str]:
    blockers = [
        *_string_list(job.get("blockers")),
        *_string_list(recovery_handoff.get("blockers")),
        *_string_list(completion_report.get("blockers")),
        *_string_list(closure_summary.get("blockers")),
    ]
    return list(dict.fromkeys(blockers))


def _job_control_read_order(action: str) -> list[str]:
    base = ["job_control_summary", "live_completion_gate", "job_handoff", "recovery_handoff", "seedbox_live_validation_completion_report"]
    if action == "configure_policy":
        return [*base, "policy_config_apply_handoff", "policy_application_handoff", "site_policy_rule_review", "blockers", "next_actions"]
    if action in {"resume_preview", "resume_execute", "prepare_materials", "repair_qbit"}:
        return [*base, "material_gap_summary", "material_preparation_final_report", "qbit_execution_gate", "qbit_enforcement_summary", "qbit_limit_audit", "resume_execution_handoff", "resume_requirements", "materials_handoff", "qbit_handoff"]
    if action in {"read_summary", "stop_duplicate"}:
        return [*base, "closure_summary", "closure_handoff", "qbit_enforcement_summary", "summary"]
    return [*base, "closure_summary", "closure_handoff", "blockers", "next_actions"]


def _job_control_continue_when(action: str, recovery_handoff: dict[str, Any], job_handoff: dict[str, Any], completion_report: dict[str, Any]) -> str | None:
    if action == "poll":
        return "status not in queued,running"
    if action == "read_summary":
        return "report live_completion_gate, seedbox_live_validation_completion_report, and closure_summary evidence to the user"
    if action == "resume_preview":
        return "resume preview returns ok=true; review command_argv, gates, and ignored_overrides before execute_request"
    if action == "resume_execute":
        return "execute_request creates a child job; poll child job_control_summary"
    if action == "configure_policy":
        return "policy_config_apply_handoff.verification succeeds and policy_execution_sequence.ready=true"
    return recovery_handoff.get("continue_when") or job_handoff.get("continue_when") or (completion_report.get("complete_when") if isinstance(completion_report.get("complete_when"), str) else None)


def _job_control_stop_when(
    action: str,
    recovery_handoff: dict[str, Any],
    job_handoff: dict[str, Any],
    completion_report: dict[str, Any],
    closure_summary: dict[str, Any],
) -> list[str]:
    stop_when = [
        *_string_list(recovery_handoff.get("stop_when")),
        *_string_list(job_handoff.get("stop_when")),
        *_string_list(completion_report.get("stop_when")),
        *_string_list(closure_summary.get("stop_when")),
    ]
    if action in {"stop_duplicate", "cancelled", "failed"}:
        stop_when.append(f"job_control_summary.action={action}")
    if action == "configure_policy":
        stop_when.append("policy_config_apply_handoff.blockers remains non-empty")
    return list(dict.fromkeys(stop_when))


def _job_control_complete_when(completion_report: dict[str, Any], closure_summary: dict[str, Any]) -> list[str]:
    complete_when = _string_list(completion_report.get("complete_when"))
    if not complete_when:
        complete_when = _string_list(closure_summary.get("complete_when"))
    if not complete_when:
        complete_when = ["live_completion_gate.ready_for_user_report=true", "seedbox_live_validation_completion_report.ready_for_user_report=true", "closure_summary.complete=true"]
    return complete_when


def _job_control_next_actions(action: str, recommended_call: dict[str, Any] | None, blockers: list[str], runtime: dict[str, Any], job_id: str) -> list[str]:
    if blockers and action not in {"poll", "read_summary"}:
        return ["Resolve job_control_summary.blockers before making any live tracker call."]
    if action == "poll":
        return [f"Poll {runtime.get('status_endpoint') or f'/v1/jobs/{job_id}'} after {runtime.get('poll_after_seconds')} seconds."]
    if action == "read_summary":
        return ["Read job_control_summary.read_order and report live_completion_gate plus closure evidence."]
    if action == "resume_preview":
        return ["Call job_control_summary.dry_run_request first, review command_argv and safety gates, then use execute_request only after user approval."]
    if action == "resume_execute":
        return ["Submit job_control_summary.execute_request and poll the returned child job."]
    if action == "configure_policy":
        return ["Call job_control_summary.recommended_call to review/apply site policy config, then rerun policy verification before any live tracker call."]
    if recommended_call and recommended_call.get("tool"):
        return [f"Call job_control_summary.recommended_call.tool={recommended_call.get('tool')} only when safe_to_call_now=true or after required user review."]
    return ["Inspect job_control_summary.sources, blockers, and read_order before choosing the next job call."]


def _job_final_report(job: dict[str, Any], payload: dict[str, Any] | None = None) -> dict[str, Any]:
    job_id = str(job.get("job_id") or "")
    status = str(job.get("status") or "unknown")
    control = _job_control_summary(job, payload if isinstance(payload, dict) else None)
    progress = _job_progress_handoff(job, payload if isinstance(payload, dict) else None)
    live_report = _job_live_user_report(job, payload if isinstance(payload, dict) else None)
    manual_report = _job_manual_retorrent_final_report(job, payload if isinstance(payload, dict) else None)
    closure_summary = _job_closure_summary(job, payload if isinstance(payload, dict) else None)
    recommended_call = control.get("recommended_call") if isinstance(control.get("recommended_call"), dict) else {}
    blockers = _job_final_report_blockers(job, control, progress, live_report, manual_report, closure_summary)
    verdict = _job_final_report_verdict(status, control, live_report, manual_report, closure_summary, blockers)
    final_recommended_call = _job_final_report_recommended_call(job_id, verdict, control, live_report, manual_report) if verdict == "duplicate_stopped" or not recommended_call else recommended_call
    report_allowed = bool(live_report.get("report_allowed") is True or verdict in {"duplicate_stopped", "failed", "cancelled"})
    ready_for_user_report = bool(live_report.get("ready_for_user_report") is True or verdict == "duplicate_stopped")
    return {
        "kind": "ptcli.job_final_report",
        "ready": ready_for_user_report and not blockers,
        "ready_for_user_report": ready_for_user_report,
        "report_allowed": report_allowed and not (blockers and verdict not in {"duplicate_stopped", "failed", "cancelled"}),
        "verdict": verdict,
        "status": status,
        "job_id": job_id or None,
        "job_kind": job.get("kind"),
        "summary_file": _job_summary_file(job),
        "control": {
            "state": control.get("state"),
            "action": control.get("action"),
            "terminal": control.get("terminal"),
            "should_poll": control.get("should_poll"),
            "should_resume": control.get("should_resume"),
            "safe_to_call_now": control.get("safe_to_call_now"),
        },
        "progress": {
            "percent": (progress.get("progress") or {}).get("percent") if isinstance(progress.get("progress"), dict) else None,
            "current_stage": (progress.get("current_stage") or {}).get("name") if isinstance(progress.get("current_stage"), dict) else None,
            "blocked_count": (progress.get("progress") or {}).get("blocked_count") if isinstance(progress.get("progress"), dict) else None,
        },
        "source_reference": _job_source_reference(job),
        "target_trackers": (job.get("request") or {}).get("target_trackers") if isinstance(job.get("request"), dict) else None,
        "duplicate_check": {
            "searched": _job_duplicate_check(job).get("searched"),
            "exists": _job_duplicate_check(job).get("exists"),
            "count": _job_duplicate_check(job).get("count"),
            "clear": _job_duplicate_check(job).get("searched") is True and _job_duplicate_check(job).get("exists") is False,
        },
        "manual_retorrent": {
            "verdict": manual_report.get("verdict") if isinstance(manual_report, dict) else None,
            "report_allowed": manual_report.get("report_allowed") if isinstance(manual_report, dict) else None,
            "ready": manual_report.get("ready") if isinstance(manual_report, dict) else None,
        },
        "live": {
            "verdict": live_report.get("verdict"),
            "ready_for_user_report": live_report.get("ready_for_user_report"),
            "report_allowed": live_report.get("report_allowed"),
            "missing_evidence": (live_report.get("evidence") or {}).get("missing_evidence") if isinstance(live_report.get("evidence"), dict) else [],
        },
        "closure": {
            "complete": closure_summary.get("complete"),
            "action": closure_summary.get("action"),
            "ready_for_report": closure_summary.get("ready_for_report"),
        },
        "recommended_call": final_recommended_call,
        "read_order": ["job_final_report", "job_control_summary", "live_validation_completion_audit", "live_user_report", "manual_retorrent_final_report", "job_progress_handoff", "closure_summary", "recovery_handoff", "job_handoff"],
        "complete_when": ["job_final_report.verdict=ready_to_report", *LIVE_VALIDATION_COMPLETE_WHEN, "closure_summary.complete=true"],
        "stop_when": ["job_final_report.verdict=duplicate_stopped", "job_final_report.verdict=blocked", "job_final_report.verdict=failed", "job_final_report.verdict=cancelled", "blockers is non-empty"],
        "blockers": blockers,
        "next_actions": _job_final_report_next_actions(verdict, control, recommended_call, blockers, job_id),
    }


def _job_final_report_verdict(
    status: str,
    control: dict[str, Any],
    live_report: dict[str, Any],
    manual_report: dict[str, Any] | None,
    closure_summary: dict[str, Any],
    blockers: list[str],
) -> str:
    action = str(control.get("action") or "")
    manual_verdict = str(manual_report.get("verdict") or "") if isinstance(manual_report, dict) else ""
    if live_report.get("report_allowed") is True and not blockers:
        return "ready_to_report"
    if manual_verdict == "duplicate_stopped" or action == "stop_duplicate" or closure_summary.get("action") == "stop_duplicate":
        return "duplicate_stopped"
    if status == "cancelled":
        return "cancelled"
    if status == "failed":
        return "failed"
    if action == "poll" or status in {"queued", "running"}:
        return "poll"
    if action == "resume_preview":
        return "needs_resume_preview"
    if action == "resume_execute":
        return "needs_resume_execute"
    if action in {"prepare_materials", "prepare_target_package", "target_upload_closure", "repair_qbit"}:
        return action
    if blockers or status == "blocked" or action == "blocked":
        return "blocked"
    if action == "read_summary":
        return "summary_ready"
    return "inspect"


def _job_final_report_blockers(
    job: dict[str, Any],
    control: dict[str, Any],
    progress: dict[str, Any],
    live_report: dict[str, Any],
    manual_report: dict[str, Any] | None,
    closure_summary: dict[str, Any],
) -> list[str]:
    blockers = [
        *_string_list(job.get("blockers")),
        *_string_list(control.get("blockers")),
        *_string_list(progress.get("blockers")),
        *_string_list(live_report.get("blockers")),
        *_string_list(closure_summary.get("blockers")),
    ]
    if isinstance(manual_report, dict):
        blockers.extend(_string_list(manual_report.get("blockers")))
    return list(dict.fromkeys(blocker for blocker in blockers if blocker))


def _job_final_report_recommended_call(job_id: str, verdict: str, control: dict[str, Any], live_report: dict[str, Any], manual_report: dict[str, Any] | None) -> dict[str, Any]:
    if verdict in {"ready_to_report", "summary_ready"}:
        return {"tool": "get_job_summary", "endpoint": f"/v1/jobs/{job_id}/summary" if job_id else None, "method": "GET", "request": {"job_id": job_id} if job_id else None, "safe_to_call_now": True}
    if verdict == "poll":
        return {"tool": "get_job_status", "endpoint": f"/v1/jobs/{job_id}" if job_id else None, "method": "GET", "request": {"job_id": job_id} if job_id else None, "safe_to_call_now": True}
    if verdict == "duplicate_stopped":
        return {"tool": None, "endpoint": None, "method": None, "request": None, "safe_to_call_now": False, "reason": "target_duplicate_exists"}
    report_call = live_report.get("recommended_call") if isinstance(live_report.get("recommended_call"), dict) else None
    if report_call:
        return report_call
    if isinstance(manual_report, dict) and isinstance(manual_report.get("recommended_call"), dict):
        return manual_report["recommended_call"]
    return control.get("recommended_call") if isinstance(control.get("recommended_call"), dict) else {"tool": None, "endpoint": None, "method": None, "request": None, "safe_to_call_now": False}


def _job_final_report_next_actions(verdict: str, control: dict[str, Any], recommended_call: dict[str, Any], blockers: list[str], job_id: str) -> list[str]:
    if verdict == "ready_to_report":
        return ["Report live_user_report and closure_summary evidence to the user."]
    if verdict == "duplicate_stopped":
        return ["Report duplicate_check evidence to the user and do not create or resume a live upload."]
    if verdict == "poll":
        return [f"Poll /v1/jobs/{job_id} until terminal, then read job_final_report again."]
    if verdict == "needs_resume_preview":
        return ["Call job_final_report.recommended_call only after dry-run preview and user review of safety gates."]
    if blockers:
        return ["Resolve job_final_report.blockers before making any live tracker call."]
    if recommended_call and recommended_call.get("tool"):
        return [f"Call job_final_report.recommended_call.tool={recommended_call.get('tool')} after reviewing stop_when and site rules."]
    return _string_list(control.get("next_actions")) or ["Inspect job_final_report.read_order before choosing the next job action."]


def _job_recovery_decision(
    status: str,
    runtime: dict[str, Any],
    job_handoff: dict[str, Any],
    materials_handoff: dict[str, Any] | None,
    target_upload_handoff: dict[str, Any] | None,
    closure_handoff: dict[str, Any] | None,
    resume_plan: dict[str, Any],
    candidate_submission_summary: dict[str, Any] | None,
    policy_config_apply_handoff: dict[str, Any] | None,
    policy_application_report: dict[str, Any] | None,
) -> tuple[str, str, str]:
    if runtime.get("should_poll"):
        return "poll", "runtime", "job_not_terminal"
    stage_action = str(job_handoff.get("action") or "")
    if stage_action in {"prepare_target_package", "target_upload_closure"} and job_handoff.get("recommended_request"):
        return stage_action, "retorrent_stage", f"retorrent_stage.{stage_action}"
    if status == "complete":
        return "read_summary", "complete", "job_complete"
    if status == "cancelled":
        return "stop", "cancelled", "job_cancelled"
    candidate_execution = candidate_submission_summary.get("execution_handoff") if isinstance(candidate_submission_summary, dict) and isinstance(candidate_submission_summary.get("execution_handoff"), dict) else None
    candidate_state = str(candidate_execution.get("state") or "") if isinstance(candidate_execution, dict) else ""
    if candidate_state in {"prepare_materials", "repair_target_payload", "repair_qbit", "resume"}:
        return candidate_state if candidate_state != "resume" else "preview_resume", "candidate_submission", f"candidate_submission.{candidate_state}"
    closure_action = str(closure_handoff.get("action") or "") if isinstance(closure_handoff, dict) else ""
    if closure_action in {"prepare_materials", "repair_target_payload", "repair_qbit"}:
        return closure_action, "closure", f"closure.{closure_action}"
    target_action = str(target_upload_handoff.get("action") or "") if isinstance(target_upload_handoff, dict) else ""
    if target_action in {"prepare_materials", "repair_target_payload", "collect_confirmations"}:
        return ("stop" if target_action == "collect_confirmations" else target_action), "target_upload", f"target_upload.{target_action}"
    if isinstance(materials_handoff, dict) and materials_handoff.get("ready") is False and isinstance(materials_handoff.get("resume_handoff"), dict) and materials_handoff["resume_handoff"].get("resume_recommended"):
        return "prepare_materials", "materials", "materials_resume_recommended"
    if stage_action == "configure_policy" and isinstance(policy_config_apply_handoff, dict) and policy_config_apply_handoff.get("ready") is False and _string_list(policy_config_apply_handoff.get("blockers")):
        return "configure_policy", "site_policy_config", "policy_config_apply_handoff.blocked"
    if _job_policy_application_report_needs_repair(policy_application_report):
        return "repair_policy_application", "policy_application", f"policy_application_report.{policy_application_report.get('verdict')}"
    if resume_plan.get("recommended"):
        return "preview_resume", "resume", "resume_plan_recommended"
    if isinstance(policy_config_apply_handoff, dict) and policy_config_apply_handoff.get("ready") is False and _string_list(policy_config_apply_handoff.get("blockers")):
        return "configure_policy", "site_policy_config", "policy_config_apply_handoff.blocked"
    if job_handoff.get("action") == "done":
        return "read_summary", "complete", "job_handoff_done"
    if job_handoff.get("action") in {"stop", "stop_duplicate", "collect_confirmations", "configure_policy"}:
        return "stop", "blocked", str(job_handoff.get("action"))
    return "inspect", "unknown", "no_recovery_action_selected"


def _job_policy_application_report_needs_repair(policy_application_report: dict[str, Any] | None) -> bool:
    if not isinstance(policy_application_report, dict):
        return False
    if policy_application_report.get("ready_for_live_audit") is True:
        return False
    verdict = str(policy_application_report.get("verdict") or "")
    if verdict not in {"request_patch_missing", "protected_fields_missing", "confirmations_missing"}:
        return False
    repair_request = _job_policy_application_resume_request(policy_application_report)
    return any(key != "dry_run" for key in repair_request)


def _job_policy_application_resume_request(policy_application_report: dict[str, Any]) -> dict[str, Any]:
    request: dict[str, Any] = {"dry_run": True}
    full_patch = policy_application_report.get("request_patch") if isinstance(policy_application_report.get("request_patch"), dict) else {}
    missing_fields = _string_list(policy_application_report.get("missing_request_fields"))
    request_patch = {key: value for key, value in full_patch.items() if key in missing_fields and value not in (None, "")}
    # If the report came from a protected-field mismatch, use the expected values from the protected field status.
    for item in policy_application_report.get("protected_field_status", []) if isinstance(policy_application_report.get("protected_field_status"), list) else []:
        if isinstance(item, dict) and item.get("status") != "present" and item.get("field"):
            request_patch[str(item["field"])] = item.get("expected")
    request.update({key: value for key, value in request_patch.items() if value not in (None, "")})
    if "accept_rules" in _string_list(policy_application_report.get("missing_confirmations")):
        request["accept_rules"] = True
    if "confirm_upload" in _string_list(policy_application_report.get("missing_confirmations")):
        request["confirm_upload"] = True
    return request


def _job_recovery_next_step(
    action: str,
    job_handoff: dict[str, Any],
    materials_handoff: dict[str, Any] | None,
    target_upload_handoff: dict[str, Any] | None,
    closure_handoff: dict[str, Any] | None,
    resume_execution: dict[str, Any],
    runtime: dict[str, Any],
    policy_config_apply_handoff: dict[str, Any] | None,
    policy_application_report: dict[str, Any] | None,
) -> dict[str, Any]:
    if action == "poll":
        return {"tool": "get_job_status", "endpoint": runtime.get("status_endpoint"), "method": "GET", "request": None, "reason": "poll_running_job"}
    if action == "read_summary":
        return {"tool": "get_job_summary", "endpoint": runtime.get("summary_endpoint"), "method": "GET", "request": None, "reason": "read_terminal_summary"}
    if action == "configure_policy" and isinstance(policy_config_apply_handoff, dict):
        next_step = policy_config_apply_handoff.get("next_step") if isinstance(policy_config_apply_handoff.get("next_step"), dict) else {}
        verification = policy_config_apply_handoff.get("verification") if isinstance(policy_config_apply_handoff.get("verification"), dict) else {}
        return {
            "tool": next_step.get("tool") or verification.get("tool") or "site_policies",
            "endpoint": next_step.get("endpoint") or verification.get("endpoint") or "/v1/site-policies",
            "method": next_step.get("method") or verification.get("method") or "POST",
            "request": next_step.get("request") or verification.get("request"),
            "reason": "policy_config_apply_handoff",
            "policy_config_apply_handoff": policy_config_apply_handoff,
        }
    if action == "repair_policy_application" and isinstance(policy_application_report, dict):
        recommended_call = policy_application_report.get("recommended_call") if isinstance(policy_application_report.get("recommended_call"), dict) else {}
        repair_request = _job_policy_application_resume_request(policy_application_report)
        return {
            "tool": recommended_call.get("tool") or "resume_job",
            "endpoint": recommended_call.get("endpoint"),
            "method": recommended_call.get("method") or "POST",
            "request": repair_request,
            "reason": "policy_application_report",
            "policy_application_report": policy_application_report,
        }
    if action in {"prepare_target_package", "target_upload_closure"}:
        return {
            "tool": job_handoff.get("recommended_tool"),
            "endpoint": job_handoff.get("recommended_endpoint"),
            "method": job_handoff.get("recommended_method"),
            "request": job_handoff.get("recommended_request"),
            "reason": action,
        }
    if action == "prepare_materials" and isinstance(materials_handoff, dict):
        resume_handoff = materials_handoff.get("resume_handoff") if isinstance(materials_handoff.get("resume_handoff"), dict) else {}
        if resume_handoff.get("recommended_tool"):
            return {
                "tool": resume_handoff.get("recommended_tool"),
                "endpoint": resume_handoff.get("recommended_endpoint"),
                "method": resume_handoff.get("method"),
                "request": resume_handoff.get("recommended_request"),
                "reason": "materials_missing",
            }
    for handoff in (target_upload_handoff, closure_handoff):
        next_step = handoff.get("next_step") if isinstance(handoff, dict) and isinstance(handoff.get("next_step"), dict) else None
        if next_step and next_step.get("tool"):
            return next_step
    if action in {"preview_resume", "execute_resume", "repair_target_payload", "repair_qbit", "prepare_materials"}:
        request = resume_execution.get("dry_run_request") or resume_execution.get("recommended_request") or job_handoff.get("recommended_request")
        return {"tool": "resume_job", "endpoint": resume_execution.get("endpoint") or job_handoff.get("resume_endpoint"), "method": "POST", "request": request, "reason": action}
    return {
        "tool": job_handoff.get("recommended_tool"),
        "endpoint": job_handoff.get("recommended_endpoint"),
        "method": job_handoff.get("recommended_method"),
        "request": job_handoff.get("recommended_request"),
        "reason": action,
    }


def _job_recovery_dry_run_request(action: str, materials_handoff: dict[str, Any] | None, resume_execution: dict[str, Any], resume_requirements: dict[str, Any], recommended_request: Any) -> dict[str, Any] | None:
    if action == "prepare_materials" and isinstance(materials_handoff, dict):
        resume_handoff = materials_handoff.get("resume_handoff") if isinstance(materials_handoff.get("resume_handoff"), dict) else {}
        request = resume_handoff.get("dry_run_request")
        if isinstance(request, dict):
            return request
    if action == "repair_policy_application" and isinstance(recommended_request, dict) and recommended_request.get("dry_run") is True:
        return recommended_request
    for request in (resume_execution.get("dry_run_request"), resume_requirements.get("dry_run_request"), recommended_request):
        if isinstance(request, dict) and request.get("dry_run") is True:
            return request
    return None


def _job_recovery_execute_request(action: str, materials_handoff: dict[str, Any] | None, resume_execution: dict[str, Any], resume_requirements: dict[str, Any]) -> dict[str, Any] | None:
    if action == "prepare_materials" and isinstance(materials_handoff, dict):
        resume_handoff = materials_handoff.get("resume_handoff") if isinstance(materials_handoff.get("resume_handoff"), dict) else {}
        request = resume_handoff.get("execute_request")
        if isinstance(request, dict):
            return request
    for request in (resume_execution.get("execute_request"), resume_requirements.get("execute_request")):
        if isinstance(request, dict):
            return request
    return None


def _job_recovery_gates(
    runtime: dict[str, Any],
    resume_plan: dict[str, Any],
    materials_handoff: dict[str, Any] | None,
    target_upload_handoff: dict[str, Any] | None,
    closure_handoff: dict[str, Any] | None,
    qbit_handoff: dict[str, Any] | None,
    policy_config_apply_handoff: dict[str, Any] | None,
    policy_application_report: dict[str, Any] | None,
) -> dict[str, Any]:
    return {
        "terminal": bool(runtime.get("terminal")),
        "resume_available": bool(resume_plan.get("available")),
        "resume_allowed": bool(resume_plan.get("allowed")),
        "resume_recommended": bool(resume_plan.get("recommended")),
        "materials_ready": materials_handoff.get("ready") if isinstance(materials_handoff, dict) else None,
        "target_upload_ready": target_upload_handoff.get("ready_for_live_upload") if isinstance(target_upload_handoff, dict) else None,
        "uploaded_seeding_ready": target_upload_handoff.get("uploaded_seeding_ready") if isinstance(target_upload_handoff, dict) else None,
        "closure_complete": closure_handoff.get("complete") if isinstance(closure_handoff, dict) else None,
        "qbit_ready": qbit_handoff.get("ready") if isinstance(qbit_handoff, dict) else None,
        "policy_config_apply_ready": policy_config_apply_handoff.get("ready") if isinstance(policy_config_apply_handoff, dict) else None,
        "policy_application_ready": policy_application_report.get("ready") if isinstance(policy_application_report, dict) else None,
        "policy_application_live_audit_ready": policy_application_report.get("ready_for_live_audit") if isinstance(policy_application_report, dict) else None,
        "policy_application_verdict": policy_application_report.get("verdict") if isinstance(policy_application_report, dict) else None,
    }


def _job_recovery_blockers(
    job: dict[str, Any],
    materials_handoff: dict[str, Any] | None,
    target_upload_handoff: dict[str, Any] | None,
    closure_handoff: dict[str, Any] | None,
    resume_execution: dict[str, Any],
    qbit_handoff: dict[str, Any] | None,
    policy_application_report: dict[str, Any] | None,
) -> list[str]:
    blockers = _string_list(job.get("blockers"))
    for handoff in (materials_handoff, target_upload_handoff, closure_handoff, resume_execution, qbit_handoff):
        if isinstance(handoff, dict):
            blockers.extend(_string_list(handoff.get("blockers")))
    if isinstance(policy_application_report, dict):
        blockers.extend(_string_list(policy_application_report.get("blockers")))
    return list(dict.fromkeys(str(item) for item in blockers if item))


def _job_recovery_continue_when(action: str) -> str | None:
    return {
        "poll": "job status leaves queued/running",
        "preview_resume": "resume dry_run returns ok=true and command_argv has been reviewed",
        "execute_resume": "resume execute_request creates a child job or completes the requested step",
        "prepare_materials": "materials_handoff.ready=true and target_upload_handoff.preflight.payload_ready=true",
        "repair_target_payload": "target_upload_handoff.ready_for_live_upload=true",
        "repair_qbit": "qbit_handoff.ready=true and closure_handoff.complete=true",
        "repair_policy_application": "policy_application_report.ready_for_live_audit=true and qbit_execution_gate.ready=true",
        "read_summary": "closure_summary.complete=true or blockers are reported to the user",
    }.get(action)


def _job_recovery_stop_when(action: str) -> list[str]:
    common = ["duplicate_check.exists=true", "site rule obligations are not ready", "resume preview contains unexpected ignored_overrides"]
    if action == "poll":
        return ["job status becomes blocked, failed, or cancelled"]
    if action == "read_summary":
        return ["closure_summary.blockers is non-empty"]
    if action == "configure_policy":
        return ["policy_config_apply_handoff.blockers is non-empty after verification", "manual_review.required=true without site_policy_rule_review.ready=true"]
    if action == "repair_policy_application":
        return ["policy_application_report.request_patch_applied=false after resume preview", "policy_application_report.missing_protected_fields is non-empty", "policy_application_report.missing_confirmations is non-empty"]
    if action == "stop":
        return ["current blockers require user action before automation continues"]
    return common


def _job_recovery_next_actions(action: str, next_step: dict[str, Any], blockers: list[str], runtime: dict[str, Any]) -> list[str]:
    if action == "poll":
        return [f"Poll recovery_handoff.status_endpoint after {runtime.get('poll_after_seconds')} seconds."]
    if action in {"preview_resume", "prepare_materials", "repair_target_payload", "repair_qbit", "repair_policy_application"}:
        return ["Call recovery_handoff.dry_run_request first, review command_argv and site-rule gates, then use execute_request only after approval."]
    if action == "read_summary":
        return ["Read recovery_handoff.summary_endpoint and report closure_summary/evidence."]
    if action == "configure_policy":
        return ["Follow recovery_handoff.policy_config_apply_handoff: complete manual review/edit_config when required, then run verification before resuming live automation."]
    if blockers:
        return ["Resolve recovery_handoff.blockers before continuing automation."]
    if next_step.get("tool"):
        return [f"Call recovery_handoff.recommended_tool={next_step.get('tool')} after reviewing blockers."]
    return ["Inspect recovery_handoff.read_fields before taking the next automation step."]


def _job_lineage_summary(job: dict[str, Any], all_jobs: list[dict[str, Any]] | None = None) -> dict[str, Any]:
    all_jobs = all_jobs or [job]
    job_id = str(job.get("job_id") or "")
    by_id = {str(item.get("job_id")): item for item in all_jobs if isinstance(item, dict) and item.get("job_id")}
    parent_job_id = _job_parent_job_id(job)
    children = [item for item in all_jobs if _job_parent_job_id(item) == job_id]
    children.sort(key=lambda item: _timestamp(item.get("created_at")) or 0)
    chain = _job_lineage_chain(job, by_id)
    root_job_id = chain[0].get("job_id") if chain else job_id or None
    latest_child = _job_lineage_item(children[-1]) if children else None
    return {
        "kind": "ptcli.job_lineage",
        "job_id": job_id or None,
        "parent_job_id": parent_job_id,
        "root_job_id": root_job_id,
        "depth": max(0, len(chain) - 1),
        "is_resume_job": bool(parent_job_id or str(job.get("kind") or "") == "ptcli.resume"),
        "chain": chain,
        "child_count": len(children),
        "children": [_job_lineage_item(child) for child in children],
        "latest_child": latest_child,
        "has_active_child": any(child.get("status") in {"queued", "running"} for child in children),
        "terminal_child_count": sum(1 for child in children if child.get("status") not in {"queued", "running"}),
        "next_actions": _job_lineage_next_actions(job_id, children, latest_child),
    }


def _job_parent_job_id(job: dict[str, Any]) -> str | None:
    request = job.get("request") if isinstance(job.get("request"), dict) else {}
    lineage = request.get("resume_lineage") if isinstance(request.get("resume_lineage"), dict) else {}
    context = request.get("resume_context") if isinstance(request.get("resume_context"), dict) else {}
    parent = request.get("parent_job_id") or lineage.get("parent_job_id") or context.get("parent_job_id")
    return str(parent) if parent else None


def _job_lineage_chain(job: dict[str, Any], by_id: dict[str, dict[str, Any]]) -> list[dict[str, Any]]:
    chain = [_job_lineage_item(job)]
    seen = {str(job.get("job_id") or "")}
    current = job
    while True:
        parent_id = _job_parent_job_id(current)
        if not parent_id or parent_id in seen:
            break
        parent = by_id.get(parent_id)
        if not parent:
            chain.insert(0, {"job_id": parent_id, "missing": True})
            break
        chain.insert(0, _job_lineage_item(parent))
        seen.add(parent_id)
        current = parent
    return chain


def _job_lineage_item(job: dict[str, Any]) -> dict[str, Any]:
    job_id = str(job.get("job_id") or "")
    return {
        "job_id": job_id or None,
        "kind": job.get("kind"),
        "status": job.get("status"),
        "parent_job_id": _job_parent_job_id(job),
        "created_at": job.get("created_at"),
        "completed_at": job.get("completed_at"),
        "status_endpoint": f"/v1/jobs/{job_id}" if job_id else None,
        "summary_endpoint": f"/v1/jobs/{job_id}/summary" if job_id else None,
        "resume_endpoint": f"/v1/jobs/{job_id}/resume" if job_id else None,
    }


def _job_lineage_next_actions(job_id: str, children: list[dict[str, Any]], latest_child: dict[str, Any] | None) -> list[str]:
    if not children:
        return []
    if any(child.get("status") in {"queued", "running"} for child in children):
        return [f"Poll active child jobs before resuming parent job {job_id} again."]
    if latest_child:
        return [f"Inspect latest_child.summary_endpoint before deciding whether parent job {job_id} still needs another resume."]
    return []


