def _job_list_next_actions(jobs: list[dict[str, Any]], total: int, limit: int) -> list[str]:
    actions: list[str] = []
    if total > limit:
        actions.append("Increase limit or filter by status/kind to inspect additional jobs.")
    if any(job.get("status") in {"queued", "running"} for job in jobs):
        actions.append("Poll running jobs with jobs[].status_endpoint until they complete or block.")
    if any((job.get("resume_plan") or {}).get("recommended") for job in jobs if isinstance(job.get("resume_plan"), dict)):
        actions.append("Resume recommended blocked jobs with jobs[].resume_endpoint after reviewing blockers and site rules.")
    return actions


def _daily_candidate_jobs_batch_summary(
    all_jobs: list[dict[str, Any]],
    *,
    filters: dict[str, Any],
    limit: int,
    visible_count: int,
    total: int,
    source_tracker: str = "",
    target_trackers: list[str] | None = None,
) -> dict[str, Any]:
    target_trackers = target_trackers or []
    candidate_jobs = [
        job
        for job in all_jobs
        if str(job.get("kind") or "") == "ptcli.daily_candidates" and _daily_candidate_job_matches_batch_filter(job, source_tracker=source_tracker, target_trackers=target_trackers)
    ]
    candidate_job_ids = {str(job.get("job_id") or "") for job in candidate_jobs}
    if candidate_job_ids:
        submitted_jobs = [job for job in all_jobs if _job_candidate_submission(job) and str((_job_candidate_submission(job) or {}).get("candidate_job_id") or "") in candidate_job_ids]
    elif source_tracker or target_trackers:
        submitted_jobs = []
    else:
        submitted_jobs = [job for job in all_jobs if _job_candidate_submission(job)]
    submitted_by_parent: dict[str, list[dict[str, Any]]] = {}
    for job in submitted_jobs:
        submission = _job_candidate_submission(job) or {}
        parent_id = str(submission.get("candidate_job_id") or "")
        submitted_by_parent.setdefault(parent_id, []).append(job)
    items = [_daily_candidate_jobs_batch_item(job, submitted_by_parent.get(str(job.get("job_id") or ""), [])) for job in candidate_jobs]
    status_counts: dict[str, int] = {}
    action_counts: dict[str, int] = {}
    for job in submitted_jobs:
        status = str(job.get("status") or "unknown")
        status_counts[status] = status_counts.get(status, 0) + 1
        followup = _job_candidate_submit_followup(job) or {}
        action = str(followup.get("action") or "unknown")
        action_counts[action] = action_counts.get(action, 0) + 1
    available_submit_requests = _daily_candidate_batch_submit_requests(items)
    ready_to_submit_count = sum(int((item.get("candidate_counts") or {}).get("safe_to_submit") or 0) for item in items)
    submitted_count = len(submitted_jobs)
    unsubmitted_safe_count = len(available_submit_requests)
    blockers = _daily_candidate_jobs_batch_blockers(items, submitted_jobs)
    return {
        "kind": "ptcli.daily_candidate_jobs_batch_summary",
        "ready": bool(candidate_jobs) and not blockers,
        "filters": filters,
        "list_window": {"visible_count": visible_count, "total_matching_filter": total, "limit": limit},
        "candidate_job_count": len(candidate_jobs),
        "submitted_retorrent_job_count": submitted_count,
        "ready_to_submit_count": ready_to_submit_count,
        "available_submit_request_count": len(available_submit_requests),
        "unsubmitted_safe_count": unsubmitted_safe_count,
        "retorrent_status_counts": status_counts,
        "retorrent_action_counts": action_counts,
        "complete_count": status_counts.get("complete", 0),
        "running_count": status_counts.get("running", 0) + status_counts.get("queued", 0),
        "blocked_count": status_counts.get("blocked", 0) + status_counts.get("failed", 0) + status_counts.get("cancelled", 0),
        "items": items,
        "read_order": ["daily_candidate_batch_summary", "daily_candidate_batch_summary.items[].submitted_jobs[].job_final_report", "jobs[].candidate_batch_handoff", "jobs[].manual_retorrent_final_report", "jobs[].candidate_submit_sequence", "jobs[].candidate_submit_followup", "jobs[].job_control_summary"],
        "continue_when": "unsubmitted_safe_count=0 and every submitted candidate job reaches complete or an explicit stop action",
        "stop_when": ["daily_candidate_batch_summary.blockers is not empty", "retorrent_action_counts.stop_duplicate>0", "retorrent_action_counts.configure_policy>0"],
        "blockers": blockers,
        "next_actions": _daily_candidate_jobs_batch_next_actions(candidate_jobs, submitted_jobs, unsubmitted_safe_count, blockers),
    }


def _daily_candidate_batch_gate(summary: dict[str, Any]) -> dict[str, Any]:
    items = [item for item in summary.get("items", []) if isinstance(item, dict)]
    blockers = _string_list(summary.get("blockers"))
    unsubmitted_safe_count = int(summary.get("unsubmitted_safe_count") or 0)
    running_count = int(summary.get("running_count") or 0)
    submitted_count = int(summary.get("submitted_retorrent_job_count") or 0)
    complete_count = int(summary.get("complete_count") or 0)
    first_submit = _daily_candidate_batch_gate_first_submit(items)
    first_submitted = _daily_candidate_batch_gate_first_submitted(items)
    if not items:
        action = "inspect_empty"
        next_step = {"tool": "daily_candidates_schedule_job", "endpoint": "/v1/jobs/candidates/daily/schedule", "method": "POST", "request": None, "reason": "no_daily_candidate_jobs"}
    elif unsubmitted_safe_count and first_submit:
        action = "submit_candidate"
        endpoint = first_submit.get("endpoint")
        next_step = {"tool": "submit_daily_candidate_job", "endpoint": endpoint, "method": "POST", "request": first_submit.get("request"), "reason": "safe_candidate_not_submitted"}
    elif running_count and first_submitted:
        action = "poll_submitted_jobs"
        next_step = {"tool": "get_job_status", "endpoint": first_submitted.get("status_endpoint"), "method": "GET", "request": None, "reason": "submitted_candidate_jobs_still_running"}
    elif blockers:
        action = "resolve_blockers"
        next_step = _daily_candidate_batch_gate_blocker_step(first_submitted, blockers)
    elif submitted_count and complete_count >= submitted_count:
        action = "complete"
        next_step = {"tool": "get_job_summary", "endpoint": first_submitted.get("summary_endpoint") if first_submitted else None, "method": "GET", "request": None, "reason": "submitted_candidate_jobs_complete"}
    else:
        action = "inspect_batch"
        next_step = {"tool": "daily_candidate_batch_status", "endpoint": "/v1/jobs/candidates/daily/batch", "method": "GET", "request": None, "reason": "inspect_daily_candidate_batch"}
    ready = action in {"submit_candidate", "complete"} and not blockers
    return {
        "kind": "ptcli.daily_candidate_batch_gate",
        "ready": ready,
        "action": action,
        "candidate_job_count": int(summary.get("candidate_job_count") or 0),
        "submitted_retorrent_job_count": submitted_count,
        "ready_to_submit_count": int(summary.get("ready_to_submit_count") or 0),
        "unsubmitted_safe_count": unsubmitted_safe_count,
        "complete_count": complete_count,
        "running_count": running_count,
        "blocked_count": int(summary.get("blocked_count") or 0),
        "retorrent_status_counts": summary.get("retorrent_status_counts") if isinstance(summary.get("retorrent_status_counts"), dict) else {},
        "retorrent_action_counts": summary.get("retorrent_action_counts") if isinstance(summary.get("retorrent_action_counts"), dict) else {},
        "first_submit_request": first_submit.get("request") if first_submit else None,
        "first_submit_endpoint": first_submit.get("endpoint") if first_submit else None,
        "first_submitted_job": first_submitted,
        "next_step": next_step,
        "recommended_tool": next_step.get("tool"),
        "recommended_endpoint": next_step.get("endpoint"),
        "recommended_request": next_step.get("request"),
        "read_order": ["daily_candidate_batch_gate", "daily_candidate_batch_summary", "daily_candidate_batch_summary.items[].submitted_jobs[].job_final_report", "jobs[].manual_retorrent_final_report", "jobs[].candidate_submit_sequence", "jobs[].candidate_submit_followup", "jobs[].job_control_summary"],
        "continue_when": "daily_candidate_batch_gate.action=complete or all safe candidates have submitted jobs and submitted jobs are terminal",
        "stop_when": "daily_candidate_batch_gate.action=resolve_blockers or any submitted job stops on duplicate/policy/confirmation blockers",
        "first_blocker": blockers[0] if blockers else None,
        "blockers": blockers,
        "next_actions": _daily_candidate_batch_gate_next_actions(action, unsubmitted_safe_count, running_count, blockers),
    }


def _daily_candidate_batch_gate_first_submit(items: list[dict[str, Any]]) -> dict[str, Any] | None:
    for item in items:
        request = item.get("recommended_request") if isinstance(item.get("recommended_request"), dict) else None
        candidate_job_id = item.get("candidate_job_id")
        if request and candidate_job_id:
            return {"endpoint": f"/v1/jobs/candidates/{candidate_job_id}/submit", "request": request}
    return None


def _daily_candidate_batch_gate_first_submitted(items: list[dict[str, Any]]) -> dict[str, Any] | None:
    for item in items:
        submitted_jobs = item.get("submitted_jobs") if isinstance(item.get("submitted_jobs"), list) else []
        for submitted in submitted_jobs:
            if isinstance(submitted, dict):
                return submitted
    return None


def _daily_candidate_batch_gate_blocker_step(first_submitted: dict[str, Any] | None, blockers: list[str]) -> dict[str, Any]:
    if first_submitted and first_submitted.get("recommended_tool"):
        tool = first_submitted.get("recommended_tool")
        return {
            "tool": tool,
            "endpoint": first_submitted.get("recommended_endpoint") or first_submitted.get("summary_endpoint") or first_submitted.get("status_endpoint"),
            "method": "POST" if tool in {"resume_job", "site_policies"} else "GET",
            "request": None,
            "reason": "submitted_candidate_job_blocked",
            "blockers": blockers,
        }
    return {"tool": "daily_candidate_batch_status", "endpoint": "/v1/jobs/candidates/daily/batch", "method": "GET", "request": None, "reason": "inspect_daily_candidate_batch_blockers", "blockers": blockers}


def _daily_candidate_batch_gate_next_actions(action: str, unsubmitted_safe_count: int, running_count: int, blockers: list[str]) -> list[str]:
    if action == "submit_candidate":
        return [f"Submit {unsubmitted_safe_count} approved safe candidate(s) through daily_candidate_batch_gate.first_submit_endpoint after explicit user confirmation."]
    if action == "poll_submitted_jobs":
        return [f"Poll {running_count} submitted retorrent job(s), then read daily_candidate_batch_gate again."]
    if action == "resolve_blockers":
        return ["Resolve daily_candidate_batch_gate.blockers before treating the daily candidate batch as complete."]
    if action == "complete":
        return ["Read submitted job summaries and report completed daily candidate retorrent outcomes."]
    if blockers:
        return ["Inspect daily_candidate_batch_gate.blockers before continuing."]
    return ["Create or rerun daily candidate jobs before expecting a batch result."]


def _daily_candidate_batch_submission_plan(summary: dict[str, Any], gate: dict[str, Any]) -> dict[str, Any]:
    items = [item for item in summary.get("items", []) if isinstance(item, dict)]
    blockers = _string_list(summary.get("blockers"))
    shortfall_blockers = [blocker for blocker in blockers if "ready_target_shortfall" in blocker or "selected_target_shortfall" in blocker]
    hard_blockers = [blocker for blocker in blockers if blocker not in shortfall_blockers]
    submit_requests = _daily_candidate_batch_submit_requests(items)
    first_submit_request = submit_requests[0] if submit_requests else None
    target_count = sum(int((item.get("candidate_counts") or {}).get("target") or 0) for item in items)
    selected_count = sum(int((item.get("candidate_counts") or {}).get("selected") or 0) for item in items)
    ready_count = sum(int((item.get("candidate_counts") or {}).get("ready") or 0) for item in items)
    shortfall_count = sum(int((item.get("candidate_counts") or {}).get("shortfall") or 0) for item in items)
    running_count = int(summary.get("running_count") or 0)
    if hard_blockers:
        action = "resolve_blockers"
    elif submit_requests:
        action = "submit_candidate"
    elif running_count:
        action = "poll_submitted_jobs"
    elif shortfall_count or shortfall_blockers:
        action = "rerun_for_shortfall"
    else:
        action = str(gate.get("action") or "inspect_batch")
    shortfall_recovery = _daily_candidate_batch_shortfall_recovery(items, target_count=target_count, selected_count=selected_count, ready_count=ready_count, shortfall_count=shortfall_count)
    recommended_tool = "submit_daily_candidate_job" if first_submit_request else shortfall_recovery.get("recommended_tool") if action == "rerun_for_shortfall" else gate.get("recommended_tool")
    recommended_endpoint = first_submit_request.get("endpoint") if first_submit_request else shortfall_recovery.get("recommended_endpoint") if action == "rerun_for_shortfall" else gate.get("recommended_endpoint")
    recommended_request = first_submit_request.get("request") if first_submit_request else shortfall_recovery.get("recommended_request") if action == "rerun_for_shortfall" else gate.get("recommended_request")
    ready = bool(submit_requests) and not hard_blockers
    return {
        "kind": "ptcli.daily_candidate_submission_plan",
        "ready": ready,
        "action": action,
        "target_count": target_count,
        "selected_count": selected_count,
        "ready_count": ready_count,
        "safe_to_submit_count": len(submit_requests),
        "submitted_retorrent_job_count": int(summary.get("submitted_retorrent_job_count") or 0),
        "running_count": running_count,
        "shortfall_count": shortfall_count,
        "target_met": bool(target_count) and shortfall_count == 0,
        "ready_target_met": bool(target_count) and ready_count >= target_count,
        "first_submit_request": first_submit_request,
        "submit_requests": submit_requests,
        "shortfall_recovery": shortfall_recovery,
        "recommended_tool": recommended_tool,
        "recommended_endpoint": recommended_endpoint,
        "recommended_method": "POST" if recommended_endpoint and recommended_tool not in {"get_job_status", "get_job_summary"} else gate.get("recommended_method") or "GET",
        "recommended_request": recommended_request,
        "required_user_inputs": ["confirm_upload=true", "save_path or path"],
        "read_order": ["daily_candidate_submission_plan", "daily_candidate_batch_gate", "daily_candidate_batch_summary.items[].submit_requests", "daily_candidate_batch_summary.items[].submitted_jobs"],
        "continue_when": "daily_candidate_submission_plan.ready=true and the user approves one submit_requests[] entry; if shortfall_count>0, rerun shortfall_recovery after submitting or reviewing available candidates",
        "stop_when": [
            "daily_candidate_submission_plan.hard_blockers is not empty",
            "candidate duplicate_clear=false",
            "candidate policy_execution.ready=false",
            "live upload lacks explicit confirm_upload=true",
        ],
        "shortfall_blockers": shortfall_blockers,
        "hard_blockers": hard_blockers,
        "blockers": blockers,
        "next_actions": _daily_candidate_batch_submission_plan_next_actions(action, len(submit_requests), shortfall_count, hard_blockers),
    }


def _daily_candidate_batch_submit_requests(items: list[dict[str, Any]]) -> list[dict[str, Any]]:
    requests: list[dict[str, Any]] = []
    seen: set[tuple[str, str]] = set()
    for item in items:
        submitted_source_ids = {
            str(submitted.get("candidate_source_id"))
            for submitted in item.get("submitted_jobs", [])
            if isinstance(submitted, dict) and submitted.get("candidate_source_id") is not None
        }
        submit_items = item.get("submit_requests") if isinstance(item.get("submit_requests"), list) else []
        for submit_item in submit_items:
            if not isinstance(submit_item, dict):
                continue
            source_id = str(submit_item.get("source_id") or "")
            candidate_job_id = str(submit_item.get("candidate_job_id") or item.get("candidate_job_id") or "")
            if source_id in submitted_source_ids:
                continue
            key = (candidate_job_id, source_id)
            if key in seen:
                continue
            seen.add(key)
            enriched = dict(submit_item)
            candidate_request = item.get("candidate_request") if isinstance(item.get("candidate_request"), dict) else {}
            if candidate_request:
                enriched.setdefault("source_tracker", candidate_request.get("source_tracker"))
                enriched.setdefault("target_trackers", candidate_request.get("target_trackers") or candidate_request.get("target"))
            requests.append(enriched)
    return requests


def _daily_candidate_batch_shortfall_recovery(items: list[dict[str, Any]], *, target_count: int, selected_count: int, ready_count: int, shortfall_count: int) -> dict[str, Any]:
    scan_state = _daily_candidate_batch_scan_state(items)
    if not items:
        return {
            "kind": "ptcli.daily_candidate_batch_shortfall_recovery",
            "action": "none",
            "reason": None,
            "target_count": 0,
            "selected_count": 0,
            "ready_count": 0,
            "selected_shortfall_count": 0,
            "ready_shortfall_count": 0,
            "shortfall_count": 0,
            "recommended_tool": None,
            "recommended_endpoint": None,
            "recommended_method": None,
            "recommended_request": None,
            "scan_limit": scan_state["scan_limit"],
            "next_scan_limit": scan_state["next_scan_limit"],
            "max_scan_limit": scan_state["max_scan_limit"],
            "pagination_supported": scan_state["pagination_supported"],
            "continue_when": None,
            "stop_when": None,
        }
    first_request = next((item.get("candidate_request") for item in items if isinstance(item.get("candidate_request"), dict)), {})
    source_tracker = str(first_request.get("source_tracker") or "")
    target = first_request.get("target") or first_request.get("target_trackers")
    exclude_source_ids = _daily_candidate_batch_covered_source_ids(items)
    request = {
        key: value
        for key, value in {
            "source_tracker": source_tracker or None,
            "target": target,
            "limit": target_count or DEFAULT_CANDIDATE_LIMIT,
            "scan_limit": scan_state["next_scan_limit"] if scan_state["can_increase_scan_limit"] else scan_state["scan_limit"],
            "accept_rules": first_request.get("accept_rules", True),
            "check_dupes": first_request.get("check_dupes", True),
            "exclude_source_ids": exclude_source_ids or None,
        }.items()
        if value is not None
    }
    ready_shortfall = max(0, (target_count or DEFAULT_CANDIDATE_LIMIT) - ready_count)
    selected_shortfall = max(0, (target_count or DEFAULT_CANDIDATE_LIMIT) - selected_count)
    return {
        "kind": "ptcli.daily_candidate_batch_shortfall_recovery",
        "action": "rerun_daily_candidates" if ready_shortfall else "none",
        "reason": "ready_target_shortfall" if ready_shortfall else None,
        "target_count": target_count,
        "selected_count": selected_count,
        "ready_count": ready_count,
        "selected_shortfall_count": selected_shortfall,
        "ready_shortfall_count": ready_shortfall,
        "shortfall_count": shortfall_count,
        "exclude_source_ids": exclude_source_ids,
        "scan_limit": scan_state["scan_limit"],
        "next_scan_limit": scan_state["next_scan_limit"],
        "max_scan_limit": scan_state["max_scan_limit"],
        "pagination_supported": scan_state["pagination_supported"],
        "recommended_tool": "daily_candidates_job" if ready_shortfall else None,
        "recommended_endpoint": "/v1/jobs/candidates/daily" if ready_shortfall else None,
        "recommended_method": "POST" if ready_shortfall else None,
        "recommended_request": request if ready_shortfall else None,
        "continue_when": "a follow-up daily_candidates_job increases safe_to_submit_count or target_met=true",
        "stop_when": "ready_shortfall_count=0 or site/rule blockers require manual repair",
    }


def _daily_candidate_batch_scan_state(items: list[dict[str, Any]]) -> dict[str, Any]:
    scan_limits: list[int] = []
    max_scan_limits: list[int] = []
    pagination_supported = False
    recommended_scan_limits: list[int] = []
    for item in items:
        if not isinstance(item, dict):
            continue
        counts = item.get("candidate_counts") if isinstance(item.get("candidate_counts"), dict) else {}
        request = item.get("candidate_request") if isinstance(item.get("candidate_request"), dict) else {}
        scan_limits.append(_bounded_int(counts.get("scan_limit") or request.get("scan_limit"), default=MAX_CANDIDATE_SCAN, minimum=1, maximum=HARD_MAX_CANDIDATE_SCAN))
        max_scan_limits.append(_bounded_int(counts.get("max_scan_limit"), default=HARD_MAX_CANDIDATE_SCAN, minimum=1, maximum=HARD_MAX_CANDIDATE_SCAN))
        plan = item.get("pagination_plan") if isinstance(item.get("pagination_plan"), dict) else {}
        pagination_supported = pagination_supported or bool(plan.get("pagination_supported"))
        if plan.get("next_scan_limit"):
            recommended_scan_limits.append(_bounded_int(plan.get("next_scan_limit"), default=MAX_CANDIDATE_SCAN, minimum=1, maximum=HARD_MAX_CANDIDATE_SCAN))
        recommended_request = plan.get("recommended_request") if isinstance(plan.get("recommended_request"), dict) else {}
        if recommended_request.get("scan_limit"):
            recommended_scan_limits.append(_bounded_int(recommended_request.get("scan_limit"), default=MAX_CANDIDATE_SCAN, minimum=1, maximum=HARD_MAX_CANDIDATE_SCAN))
    scan_limit = max(scan_limits) if scan_limits else MAX_CANDIDATE_SCAN
    max_scan_limit = max(max_scan_limits) if max_scan_limits else HARD_MAX_CANDIDATE_SCAN
    next_scan_limit = max(recommended_scan_limits) if recommended_scan_limits else min(max_scan_limit, scan_limit + MAX_CANDIDATE_SCAN)
    can_increase = scan_limit < max_scan_limit
    return {
        "scan_limit": scan_limit,
        "next_scan_limit": next_scan_limit if can_increase else None,
        "max_scan_limit": max_scan_limit,
        "can_increase_scan_limit": can_increase,
        "scan_exhausted": not can_increase,
        "pagination_supported": pagination_supported,
    }


def _daily_candidate_batch_submission_plan_next_actions(action: str, submit_count: int, shortfall_count: int, hard_blockers: list[str]) -> list[str]:
    if hard_blockers:
        return ["Resolve daily_candidate_submission_plan.hard_blockers before submitting batch candidates."]
    if action == "submit_candidate":
        actions = [f"Ask the user to approve one of {submit_count} daily_candidate_submission_plan.submit_requests[], then call submit_daily_candidate_job."]
        if shortfall_count:
            actions.append("After handling available safe candidates, call daily_candidate_submission_plan.shortfall_recovery.recommended_tool to fill the daily target.")
        return actions
    if action == "poll_submitted_jobs":
        return ["Poll submitted retorrent jobs, then read daily_candidate_submission_plan again."]
    if action == "rerun_for_shortfall":
        return ["Call daily_candidate_submission_plan.shortfall_recovery.recommended_tool with recommended_request to fill the daily target."]
    if action == "complete":
        return ["Read submitted job summaries and report completed daily candidate retorrent outcomes."]
    return ["Create or rerun daily candidate jobs before expecting a submission plan."]


def _daily_candidate_batch_execution_summary(summary: dict[str, Any], gate: dict[str, Any], submission_plan: dict[str, Any]) -> dict[str, Any]:
    submitted_jobs = _daily_candidate_batch_submitted_jobs(summary)
    complete_jobs = [job for job in submitted_jobs if job.get("status") == "complete" or job.get("action") in {"complete", "read_summary"}]
    running_jobs = [job for job in submitted_jobs if job.get("status") in {"queued", "running"} or job.get("action") == "wait"]
    blocked_jobs = [
        job
        for job in submitted_jobs
        if job.get("status") in {"blocked", "failed", "cancelled"} or job.get("action") in {"stop_duplicate", "collect_confirmations", "configure_policy", "blocked", "failed", "cancelled"}
    ]
    terminal_jobs = [job for job in submitted_jobs if job.get("status") not in {"queued", "running"}]
    remaining_submit_count = int(submission_plan.get("safe_to_submit_count") or 0)
    shortfall_recovery = submission_plan.get("shortfall_recovery") if isinstance(submission_plan.get("shortfall_recovery"), dict) else {}
    summary_blockers = [
        blocker
        for blocker in _string_list(summary.get("blockers"))
        if "ready_target_shortfall" not in blocker and "selected_target_shortfall" not in blocker
    ]
    blockers = list(dict.fromkeys(summary_blockers + _string_list(submission_plan.get("hard_blockers"))))
    if remaining_submit_count:
        action = "submit_remaining"
        next_step = {
            "tool": "submit_daily_candidate_job",
            "endpoint": submission_plan.get("recommended_endpoint"),
            "method": "POST",
            "request": submission_plan.get("recommended_request"),
            "reason": "unsubmitted_safe_candidates",
        }
    elif running_jobs:
        first_running = running_jobs[0]
        action = "poll_submitted_jobs"
        next_step = {"tool": "get_job_status", "endpoint": first_running.get("status_endpoint"), "method": "GET", "request": None, "reason": "submitted_candidate_jobs_running"}
    elif blocked_jobs:
        first_blocked = blocked_jobs[0]
        action = "resolve_submitted_blockers"
        next_step = {
            "tool": first_blocked.get("recommended_tool") or gate.get("recommended_tool") or "get_job_summary",
            "endpoint": first_blocked.get("recommended_endpoint") or first_blocked.get("summary_endpoint") or first_blocked.get("status_endpoint"),
            "method": first_blocked.get("recommended_method") or ("POST" if first_blocked.get("recommended_tool") in {"resume_job", "site_policies"} else "GET"),
            "request": first_blocked.get("recommended_request"),
            "reason": "submitted_candidate_job_blocked",
        }
    elif shortfall_recovery.get("recommended_request") and int(shortfall_recovery.get("ready_shortfall_count") or 0):
        action = "rerun_for_shortfall"
        next_step = {
            "tool": shortfall_recovery.get("recommended_tool"),
            "endpoint": shortfall_recovery.get("recommended_endpoint"),
            "method": shortfall_recovery.get("recommended_method"),
            "request": shortfall_recovery.get("recommended_request"),
            "reason": "daily_ready_target_shortfall",
        }
    elif submitted_jobs and len(complete_jobs) >= len(submitted_jobs):
        first_complete = complete_jobs[0]
        action = "complete"
        next_step = {"tool": "get_job_summary", "endpoint": first_complete.get("summary_endpoint"), "method": "GET", "request": None, "reason": "all_submitted_candidates_complete"}
    else:
        action = str(gate.get("action") or "inspect_batch")
        next_step = gate.get("next_step") if isinstance(gate.get("next_step"), dict) else {"tool": "daily_candidate_batch_status", "endpoint": "/v1/jobs/candidates/daily/batch", "method": "GET", "request": None, "reason": "inspect_batch"}
    completed_source_ids = [str(job.get("candidate_source_id")) for job in complete_jobs if job.get("candidate_source_id")]
    blocked_source_ids = [str(job.get("candidate_source_id")) for job in blocked_jobs if job.get("candidate_source_id")]
    running_source_ids = [str(job.get("candidate_source_id")) for job in running_jobs if job.get("candidate_source_id")]
    ready = action == "complete" and not blockers
    return {
        "kind": "ptcli.daily_candidate_execution_summary",
        "ready": ready,
        "action": action,
        "target_count": int(submission_plan.get("target_count") or 0),
        "ready_count": int(submission_plan.get("ready_count") or 0),
        "safe_to_submit_count": int(submission_plan.get("safe_to_submit_count") or 0),
        "submitted_retorrent_job_count": len(submitted_jobs),
        "complete_count": len(complete_jobs),
        "running_count": len(running_jobs),
        "blocked_count": len(blocked_jobs),
        "terminal_count": len(terminal_jobs),
        "remaining_submit_count": remaining_submit_count,
        "ready_shortfall_count": int(shortfall_recovery.get("ready_shortfall_count") or 0),
        "target_met": bool(submission_plan.get("target_met")),
        "ready_target_met": bool(submission_plan.get("ready_target_met")),
        "completion_ratio": f"{len(complete_jobs)}/{len(submitted_jobs)}" if submitted_jobs else "0/0",
        "completed_source_ids": completed_source_ids,
        "running_source_ids": running_source_ids,
        "blocked_source_ids": blocked_source_ids,
        "submitted_jobs": submitted_jobs,
        "running_jobs": running_jobs,
        "blocked_jobs": blocked_jobs,
        "complete_jobs": complete_jobs,
        "next_step": next_step,
        "recommended_tool": next_step.get("tool"),
        "recommended_endpoint": next_step.get("endpoint"),
        "recommended_method": next_step.get("method"),
        "recommended_request": next_step.get("request"),
        "read_order": ["daily_candidate_execution_summary", "daily_candidate_submission_plan", "daily_candidate_batch_gate", "daily_candidate_batch_summary.items[].submitted_jobs[].job_final_report", "jobs[].manual_retorrent_final_report", "jobs[].candidate_submit_sequence", "jobs[].candidate_submit_followup"],
        "continue_when": "daily_candidate_execution_summary.action=complete or every safe candidate has a terminal submitted job and shortfall_recovery is exhausted",
        "stop_when": [
            "daily_candidate_execution_summary.blocked_count>0",
            "daily_candidate_execution_summary.action='resolve_submitted_blockers'",
            "retorrent_action_counts.stop_duplicate>0",
            "site policy or material blockers remain unresolved",
        ],
        "blockers": blockers,
        "next_actions": _daily_candidate_batch_execution_next_actions(action, remaining_submit_count, len(running_jobs), len(blocked_jobs), int(shortfall_recovery.get("ready_shortfall_count") or 0)),
    }


def _daily_candidate_batch_submitted_jobs(summary: dict[str, Any]) -> list[dict[str, Any]]:
    submitted: list[dict[str, Any]] = []
    for item in summary.get("items", []):
        if not isinstance(item, dict) or not isinstance(item.get("submitted_jobs"), list):
            continue
        submitted.extend(job for job in item["submitted_jobs"] if isinstance(job, dict))
    return submitted


def _daily_candidate_batch_execution_next_actions(action: str, remaining_submit_count: int, running_count: int, blocked_count: int, ready_shortfall_count: int) -> list[str]:
    if action == "submit_remaining":
        return [f"Submit {remaining_submit_count} remaining approved candidate(s) via daily_candidate_execution_summary.next_step after explicit user approval."]
    if action == "poll_submitted_jobs":
        return [f"Poll {running_count} submitted candidate retorrent job(s), then refresh daily_candidate_execution_summary."]
    if action == "resolve_submitted_blockers":
        return [f"Resolve {blocked_count} submitted candidate job blocker(s) before marking the daily batch complete."]
    if action == "rerun_for_shortfall":
        return [f"Rerun daily candidate discovery to fill {ready_shortfall_count} ready candidate shortfall(s)."]
    if action == "complete":
        return ["Read complete_jobs[].summary_endpoint and report completed daily candidate retorrent evidence."]
    return ["Inspect daily_candidate_execution_summary.submitted_jobs and daily_candidate_submission_plan before continuing."]


def _daily_candidate_batch_refill_plan(summary: dict[str, Any], submission_plan: dict[str, Any], execution_summary: dict[str, Any]) -> dict[str, Any]:
    items = [item for item in summary.get("items", []) if isinstance(item, dict)]
    scan_state = _daily_candidate_batch_scan_state(items)
    target_count = int(submission_plan.get("target_count") or 0)
    ready_count = int(submission_plan.get("ready_count") or 0)
    remaining_submit_count = int(execution_summary.get("remaining_submit_count") or 0)
    running_count = int(execution_summary.get("running_count") or 0)
    blocked_count = int(execution_summary.get("blocked_count") or 0)
    complete_count = int(execution_summary.get("complete_count") or 0)
    ready_shortfall_count = max(0, target_count - ready_count)
    scan_count = sum(int((item.get("candidate_counts") or {}).get("scan") or 0) for item in items)
    shortfall_recovery = submission_plan.get("shortfall_recovery") if isinstance(submission_plan.get("shortfall_recovery"), dict) else {}
    summary_filters = summary.get("filters") if isinstance(summary.get("filters"), dict) else {}
    candidate_request = next((item.get("candidate_request") for item in items if isinstance(item.get("candidate_request"), dict)), None)
    if not isinstance(candidate_request, dict) or not candidate_request:
        candidate_request = {
            "source_tracker": summary_filters.get("source_tracker"),
            "target": summary_filters.get("target") or summary_filters.get("target_trackers"),
            "accept_rules": True,
            "check_dupes": True,
        }
    covered_source_ids = _daily_candidate_batch_covered_source_ids(items)
    submitted_source_ids = _string_list(execution_summary.get("completed_source_ids")) + _string_list(execution_summary.get("running_source_ids")) + _string_list(execution_summary.get("blocked_source_ids"))
    excluded_source_ids = list(dict.fromkeys([*covered_source_ids, *(str(item) for item in submitted_source_ids if item)]))
    hard_blockers = _string_list(submission_plan.get("hard_blockers"))
    if not items:
        action = "create_daily_candidates"
    elif running_count:
        action = "wait_for_submitted_jobs"
    elif hard_blockers or blocked_count:
        action = "resolve_blockers"
    elif remaining_submit_count:
        action = "submit_available_first"
    elif ready_shortfall_count:
        action = "rerun_for_shortfall"
    else:
        action = "none"
    recommended_request = _daily_candidate_refill_request(candidate_request, shortfall_recovery, target_count, excluded_source_ids, scan_limit=scan_state["next_scan_limit"] or scan_state["scan_limit"])
    if action == "create_daily_candidates":
        recommended_tool = "daily_candidates_job"
        recommended_endpoint = "/v1/jobs/candidates/daily"
        recommended_method = "POST"
    elif action == "rerun_for_shortfall":
        recommended_tool = shortfall_recovery.get("recommended_tool") or "daily_candidates_job"
        recommended_endpoint = shortfall_recovery.get("recommended_endpoint") or "/v1/jobs/candidates/daily"
        recommended_method = shortfall_recovery.get("recommended_method") or "POST"
    elif action == "submit_available_first":
        recommended_tool = submission_plan.get("recommended_tool")
        recommended_endpoint = submission_plan.get("recommended_endpoint")
        recommended_method = submission_plan.get("recommended_method")
        recommended_request = submission_plan.get("recommended_request")
    elif action == "wait_for_submitted_jobs":
        recommended_tool = execution_summary.get("recommended_tool")
        recommended_endpoint = execution_summary.get("recommended_endpoint")
        recommended_method = execution_summary.get("recommended_method")
        recommended_request = execution_summary.get("recommended_request")
    elif action == "resolve_blockers":
        recommended_tool = execution_summary.get("recommended_tool") or submission_plan.get("recommended_tool")
        recommended_endpoint = execution_summary.get("recommended_endpoint") or submission_plan.get("recommended_endpoint")
        recommended_method = execution_summary.get("recommended_method") or submission_plan.get("recommended_method")
        recommended_request = execution_summary.get("recommended_request") or submission_plan.get("recommended_request")
    else:
        recommended_tool = None
        recommended_endpoint = None
        recommended_method = None
        recommended_request = None
    refill_request_contract = _daily_candidate_refill_request_contract(
        action=action,
        target_count=target_count,
        ready_count=ready_count,
        ready_shortfall_count=ready_shortfall_count,
        scan_count=scan_count,
        scan_limit=scan_state["scan_limit"],
        next_scan_limit=scan_state["next_scan_limit"],
        max_scan_limit=scan_state["max_scan_limit"],
        scan_exhausted=scan_state["scan_exhausted"],
        pagination_supported=scan_state["pagination_supported"],
        covered_source_ids=excluded_source_ids,
        submitted_source_ids=list(dict.fromkeys(str(item) for item in submitted_source_ids if item)),
        recommended_tool=recommended_tool,
        recommended_endpoint=recommended_endpoint,
        recommended_method=recommended_method,
        recommended_request=recommended_request,
        blockers=hard_blockers,
    )
    refill_job_handoff = _daily_candidate_refill_job_handoff(
        action=action,
        target_count=target_count,
        ready_count=ready_count,
        ready_shortfall_count=ready_shortfall_count,
        scan_count=scan_count,
        scan_limit=scan_state["scan_limit"],
        next_scan_limit=scan_state["next_scan_limit"],
        max_scan_limit=scan_state["max_scan_limit"],
        scan_exhausted=scan_state["scan_exhausted"],
        pagination_supported=scan_state["pagination_supported"],
        excluded_source_ids=excluded_source_ids,
        recommended_tool=recommended_tool,
        recommended_endpoint=recommended_endpoint,
        recommended_method=recommended_method,
        recommended_request=recommended_request,
        blockers=hard_blockers,
    )
    return {
        "kind": "ptcli.daily_candidate_refill_plan",
        "ready": action in {"create_daily_candidates", "rerun_for_shortfall", "submit_available_first"} and not hard_blockers,
        "action": action,
        "target_count": target_count,
        "ready_count": ready_count,
        "complete_count": complete_count,
        "remaining_submit_count": remaining_submit_count,
        "ready_shortfall_count": ready_shortfall_count,
        "scan_count": scan_count,
        "max_scan_count": MAX_CANDIDATE_SCAN,
        "scan_limit": scan_state["scan_limit"],
        "next_scan_limit": scan_state["next_scan_limit"],
        "max_scan_limit": scan_state["max_scan_limit"],
        "scan_exhausted": scan_state["scan_exhausted"],
        "candidate_job_count": int(summary.get("candidate_job_count") or 0),
        "covered_source_ids": covered_source_ids,
        "submitted_source_ids": list(dict.fromkeys(str(item) for item in submitted_source_ids if item)),
        "completed_source_ids": _string_list(execution_summary.get("completed_source_ids")),
        "running_source_ids": _string_list(execution_summary.get("running_source_ids")),
        "blocked_source_ids": _string_list(execution_summary.get("blocked_source_ids")),
        "exclude_source_ids_hint": excluded_source_ids,
        "refill_request_contract": refill_request_contract,
        "refill_job_handoff": refill_job_handoff,
        "refill_followup": refill_job_handoff.get("followup") if isinstance(refill_job_handoff.get("followup"), dict) else None,
        "pagination_supported": scan_state["pagination_supported"],
        "dedupe_strategy": "Do not submit a source_id already present in covered_source_ids or submitted_source_ids; current discovery reruns the recent list without offset support.",
        "recommended_tool": recommended_tool,
        "recommended_endpoint": recommended_endpoint,
        "recommended_method": recommended_method,
        "recommended_request": recommended_request,
        "recommended_overrides": {"limit": target_count or DEFAULT_CANDIDATE_LIMIT, "scan_limit": scan_state["next_scan_limit"] or scan_state["scan_limit"], "check_dupes": True},
        "read_order": ["daily_candidate_refill_plan", "daily_candidate_execution_summary", "daily_candidate_submission_plan", "daily_candidate_batch_summary"],
        "continue_when": "ready_shortfall_count=0 or daily_candidate_submission_plan.safe_to_submit_count increases after rerun",
        "stop_when": [
            "pagination_supported=false and rerun returns no new safe candidates",
            "scan_exhausted=true and ready_shortfall_count>0",
            "daily_candidate_refill_plan.blockers is not empty",
        ],
        "blockers": hard_blockers,
        "next_actions": _daily_candidate_refill_next_actions(action, ready_shortfall_count, remaining_submit_count, running_count, blocked_count),
    }


def _daily_candidate_refill_request(candidate_request: dict[str, Any], shortfall_recovery: dict[str, Any], target_count: int, exclude_source_ids: list[str], *, scan_limit: int | None = None) -> dict[str, Any] | None:
    if isinstance(shortfall_recovery.get("recommended_request"), dict):
        request = dict(shortfall_recovery["recommended_request"])
        if exclude_source_ids:
            request.setdefault("exclude_source_ids", exclude_source_ids)
        if scan_limit:
            request.setdefault("scan_limit", scan_limit)
        return request
    request = {
        key: value
        for key, value in {
            "source_tracker": candidate_request.get("source_tracker"),
            "target": candidate_request.get("target") or candidate_request.get("target_trackers"),
            "limit": target_count or DEFAULT_CANDIDATE_LIMIT,
            "scan_limit": scan_limit,
            "accept_rules": candidate_request.get("accept_rules", True),
            "check_dupes": candidate_request.get("check_dupes", True),
            "base_dir": candidate_request.get("base_dir"),
            "exclude_source_ids": exclude_source_ids or None,
        }.items()
        if value is not None and value != ""
    }
    return request or None


def _daily_candidate_refill_request_contract(
    *,
    action: str,
    target_count: int,
    ready_count: int,
    ready_shortfall_count: int,
    scan_count: int,
    scan_limit: int,
    next_scan_limit: int | None,
    max_scan_limit: int,
    scan_exhausted: bool,
    pagination_supported: bool,
    covered_source_ids: list[str],
    submitted_source_ids: list[str],
    recommended_tool: str | None,
    recommended_endpoint: str | None,
    recommended_method: str | None,
    recommended_request: dict[str, Any] | None,
    blockers: list[str],
) -> dict[str, Any]:
    refill_action = "refill_candidates" if action in {"create_daily_candidates", "rerun_for_shortfall"} else action
    return {
        "kind": "ptcli.daily_candidate_refill_request_contract",
        "ready": action in {"create_daily_candidates", "rerun_for_shortfall"} and bool(recommended_request) and not blockers,
        "action": refill_action,
        "target_count": target_count,
        "ready_count": ready_count,
        "ready_shortfall_count": ready_shortfall_count,
        "scan_count": scan_count,
        "scan_limit": scan_limit,
        "next_scan_limit": next_scan_limit,
        "max_scan_limit": max_scan_limit,
        "scan_exhausted": scan_exhausted,
        "pagination_supported": pagination_supported,
        "excluded_source_ids": covered_source_ids,
        "submitted_source_ids": submitted_source_ids,
        "dedupe_key": "source_tracker,target,source_id",
        "recommended_tool": recommended_tool,
        "recommended_endpoint": recommended_endpoint,
        "recommended_method": recommended_method,
        "recommended_request": recommended_request,
        "safe_to_call_now": action in {"create_daily_candidates", "rerun_for_shortfall"} and bool(recommended_request) and not blockers,
        "requires_user_review": False,
        "read_before_call": ["daily_candidate_refill_plan", "daily_candidate_tracking_report", "daily_candidate_submission_plan"],
        "continue_when": "daily_candidate_tracking_report.ready_count increases or ready_shortfall_count becomes 0",
        "stop_when": [
            "daily_candidate_refill_plan.scan_exhausted=true and no new safe candidates are returned",
            "daily_candidate_refill_plan.blockers is non-empty",
            "a returned candidate source_id is already in excluded_source_ids",
        ],
        "blockers": blockers,
        "next_actions": _daily_candidate_refill_contract_next_actions(action, ready_shortfall_count, blockers),
    }


def _daily_candidate_refill_contract_next_actions(action: str, ready_shortfall_count: int, blockers: list[str]) -> list[str]:
    if blockers:
        return ["Resolve daily_candidate_refill_plan.blockers before creating more daily candidate jobs."]
    if action in {"create_daily_candidates", "rerun_for_shortfall"}:
        return [f"Call daily_candidate_refill_plan.refill_request_contract.recommended_tool to fill {ready_shortfall_count} missing ready candidate(s)."]
    return ["Do not refill yet; follow daily_candidate_tracking_report.action first."]


def _daily_candidate_refill_job_handoff(
    *,
    action: str,
    target_count: int,
    ready_count: int,
    ready_shortfall_count: int,
    scan_count: int,
    scan_limit: int,
    next_scan_limit: int | None,
    max_scan_limit: int,
    scan_exhausted: bool,
    pagination_supported: bool,
    excluded_source_ids: list[str],
    recommended_tool: str | None,
    recommended_endpoint: str | None,
    recommended_method: str | None,
    recommended_request: dict[str, Any] | None,
    blockers: list[str],
) -> dict[str, Any]:
    request = recommended_request if isinstance(recommended_request, dict) else {}
    source_tracker = request.get("source_tracker") or request.get("source")
    target = request.get("target") or request.get("target_trackers")
    batch_status_request = {key: value for key, value in {"source_tracker": source_tracker, "target": target}.items() if value}
    ready = action in {"create_daily_candidates", "rerun_for_shortfall"} and bool(request) and not blockers
    return {
        "kind": "ptcli.daily_candidate_refill_job_handoff",
        "ready": ready,
        "action": "create_refill_job" if ready else action,
        "target_count": target_count,
        "ready_count": ready_count,
        "ready_shortfall_count": ready_shortfall_count,
        "scan_count": scan_count,
        "scan_limit": scan_limit,
        "next_scan_limit": next_scan_limit,
        "max_scan_limit": max_scan_limit,
        "scan_exhausted": scan_exhausted,
        "pagination_supported": pagination_supported,
        "excluded_source_ids": excluded_source_ids,
        "dedupe_key": "source_tracker,target,source_id",
        "recommended_call": {
            "tool": recommended_tool,
            "endpoint": recommended_endpoint,
            "method": recommended_method,
            "request": request or None,
            "safe_to_call_now": ready,
            "requires_user_review": False,
            "reason": "daily_candidate_refill_plan.ready_shortfall",
        },
        "followup": {
            "tool": "daily_candidate_batch_status",
            "endpoint": "/v1/jobs/candidates/daily/batch",
            "method": "GET",
            "request": batch_status_request or None,
            "read_after_create": ["job_id", "status_endpoint", "summary_endpoint", "candidate_digest", "candidate_batch_handoff"],
            "continue_when": "candidate_job_count increases, ready_count increases, or ready_shortfall_count becomes 0",
            "repeat_when": "daily_candidate_refill_plan.refill_job_handoff.ready=true and ready_shortfall_count>0",
            "stop_when": [
                "refill returns no new safe candidates",
                "new source_id appears in excluded_source_ids",
                "daily_candidate_batch_status.daily_candidate_refill_plan.blockers is non-empty",
            ],
        },
        "continue_when": "recommended_call returns job_id, then followup reads daily_candidate_batch_status",
        "stop_when": [
            "recommended_call.safe_to_call_now=false",
            "recommended_call.request is missing",
            "refill returns no new safe candidates while ready_shortfall_count>0",
        ],
        "blockers": blockers,
        "next_actions": _daily_candidate_refill_job_handoff_next_actions(ready, ready_shortfall_count),
    }


def _daily_candidate_refill_job_handoff_next_actions(ready: bool, ready_shortfall_count: int) -> list[str]:
    if ready:
        return [f"Call refill_job_handoff.recommended_call to create a refill job for {ready_shortfall_count} missing ready candidate(s), then read refill_job_handoff.followup."]
    return ["Follow daily_candidate_refill_plan.action before creating another refill job."]


def _daily_candidate_batch_covered_source_ids(items: list[dict[str, Any]]) -> list[str]:
    source_ids: list[str] = []
    for item in items:
        source_ids.extend(_string_list(item.get("safe_source_ids")))
        submit_requests = item.get("submit_requests", []) if isinstance(item.get("submit_requests"), list) else []
        source_ids.extend(str(submit_request["source_id"]) for submit_request in submit_requests if isinstance(submit_request, dict) and submit_request.get("source_id"))
        submitted_jobs = item.get("submitted_jobs", []) if isinstance(item.get("submitted_jobs"), list) else []
        source_ids.extend(str(submitted["candidate_source_id"]) for submitted in submitted_jobs if isinstance(submitted, dict) and submitted.get("candidate_source_id"))
    return list(dict.fromkeys(source_ids))


def _daily_candidate_refill_next_actions(action: str, ready_shortfall_count: int, remaining_submit_count: int, running_count: int, blocked_count: int) -> list[str]:
    if action == "create_daily_candidates":
        return ["Create a daily_candidates_job for this source/target pair before attempting refill."]
    if action == "submit_available_first":
        return [f"Submit {remaining_submit_count} available safe candidate(s) before rerunning discovery for the remaining shortfall."]
    if action == "wait_for_submitted_jobs":
        return [f"Poll {running_count} submitted retorrent job(s) before deciding whether refill is still needed."]
    if action == "resolve_blockers":
        return [f"Resolve {blocked_count} blocked submitted job(s) or policy blockers before rerunning candidate discovery."]
    if action == "rerun_for_shortfall":
        return [f"Rerun daily candidate discovery to fill {ready_shortfall_count} missing ready candidate(s); do not resubmit source ids in exclude_source_ids_hint."]
    return ["No refill is needed for this daily candidate batch."]


def _daily_candidate_batch_sequence(
    summary: dict[str, Any],
    gate: dict[str, Any],
    submission_plan: dict[str, Any],
    execution_summary: dict[str, Any],
    refill_plan: dict[str, Any],
) -> dict[str, Any]:
    action = _daily_candidate_batch_sequence_action(gate, submission_plan, execution_summary, refill_plan)
    blockers = list(dict.fromkeys(_string_list(summary.get("blockers")) + _string_list(submission_plan.get("hard_blockers")) + _string_list(execution_summary.get("blockers")) + _string_list(refill_plan.get("blockers"))))
    steps = _daily_candidate_batch_sequence_steps(action, gate, submission_plan, execution_summary, refill_plan)
    loop_control = _daily_candidate_batch_loop_control(action, submission_plan, execution_summary, refill_plan, steps, blockers)
    return {
        "kind": "ptcli.daily_candidate_batch_sequence",
        "ready": action in {"submit_candidate", "poll_submitted_jobs", "rerun_for_shortfall", "report_complete"} and not (blockers and action != "report_complete"),
        "action": action,
        "target_count": int(submission_plan.get("target_count") or 0),
        "ready_count": int(submission_plan.get("ready_count") or 0),
        "safe_to_submit_count": int(submission_plan.get("safe_to_submit_count") or 0),
        "submitted_retorrent_job_count": int(summary.get("submitted_retorrent_job_count") or 0),
        "complete_count": int(execution_summary.get("complete_count") or 0),
        "running_count": int(execution_summary.get("running_count") or 0),
        "ready_shortfall_count": int(refill_plan.get("ready_shortfall_count") or execution_summary.get("ready_shortfall_count") or 0),
        "steps": steps,
        "next_step": steps[0] if steps else None,
        "loop_control": loop_control,
        "read_order": ["daily_candidate_batch_sequence", "daily_candidate_execution_summary", "daily_candidate_submission_plan", "daily_candidate_batch_gate", "daily_candidate_refill_plan", "jobs[].manual_retorrent_final_report"],
        "complete_when": [
            "daily_candidate_batch_sequence.action=report_complete",
            "daily_candidate_execution_summary.action=complete",
            "daily_candidate_execution_summary.blocked_count=0",
            "daily_candidate_refill_plan.ready_shortfall_count=0",
        ],
        "stop_when": [
            "daily_candidate_batch_sequence.action=resolve_blockers",
            "daily_candidate_submission_plan.hard_blockers is not empty",
            "submitted retorrent job live_completion_gate.action=stop_duplicate",
        ],
        "blockers": blockers,
        "next_actions": _daily_candidate_batch_sequence_next_actions(action, steps, blockers),
    }


def _daily_candidate_batch_loop_control(
    action: str,
    submission_plan: dict[str, Any],
    execution_summary: dict[str, Any],
    refill_plan: dict[str, Any],
    steps: list[dict[str, Any]],
    blockers: list[str],
) -> dict[str, Any]:
    target_count = int(submission_plan.get("target_count") or execution_summary.get("target_count") or 0)
    ready_count = int(submission_plan.get("ready_count") or execution_summary.get("ready_count") or 0)
    remaining_submit_count = int(execution_summary.get("remaining_submit_count") or 0)
    running_count = int(execution_summary.get("running_count") or 0)
    blocked_count = int(execution_summary.get("blocked_count") or 0)
    ready_shortfall_count = int(refill_plan.get("ready_shortfall_count") or execution_summary.get("ready_shortfall_count") or 0)
    refill_contract = refill_plan.get("refill_request_contract") if isinstance(refill_plan.get("refill_request_contract"), dict) else {}
    next_step = steps[0] if steps else {}
    complete = action == "report_complete" and not running_count and not blocked_count and not ready_shortfall_count
    return {
        "kind": "ptcli.daily_candidate_batch_loop_control",
        "ready": action in {"submit_candidate", "poll_submitted_jobs", "rerun_for_shortfall", "create_daily_candidates", "report_complete"} and not (blockers and action != "report_complete"),
        "action": action,
        "complete": complete,
        "target_count": target_count,
        "ready_count": ready_count,
        "ready_shortfall_count": ready_shortfall_count,
        "remaining_submit_count": remaining_submit_count,
        "running_count": running_count,
        "blocked_count": blocked_count,
        "should_submit": action == "submit_candidate" and remaining_submit_count > 0,
        "should_poll": action == "poll_submitted_jobs" or running_count > 0,
        "should_refill": action in {"rerun_for_shortfall", "create_daily_candidates"} and bool(refill_contract.get("recommended_request") or refill_plan.get("recommended_request")),
        "should_report": action == "report_complete",
        "refill_request_contract": refill_contract or None,
        "next_step": next_step or None,
        "after_step": {
            "tool": "daily_candidate_batch_status",
            "endpoint": "/v1/jobs/candidates/daily/batch",
            "method": "GET",
            "request": None,
            "reason": "refresh_daily_candidate_batch_loop",
        },
        "repeat_until": [
            "daily_candidate_batch_loop_control.complete=true",
            "daily_candidate_batch_loop_control.blockers is non-empty",
            "daily_candidate_batch_loop_control.should_refill=true and refill returns no new safe candidates",
            "submitted job duplicate_check.exists=true",
        ],
        "read_order": ["daily_candidate_batch_loop_control", "daily_candidate_tracking_report", "daily_candidate_batch_sequence", "daily_candidate_refill_plan", "daily_candidate_execution_summary"],
        "blockers": blockers,
        "next_actions": _daily_candidate_batch_loop_next_actions(action, ready_shortfall_count, remaining_submit_count, running_count, blocked_count, blockers),
    }


def _daily_candidate_batch_loop_next_actions(action: str, ready_shortfall_count: int, remaining_submit_count: int, running_count: int, blocked_count: int, blockers: list[str]) -> list[str]:
    if blockers and action != "report_complete":
        return ["Resolve daily_candidate_batch_loop_control.blockers, then refresh daily_candidate_batch_status."]
    if action == "submit_candidate":
        return [f"Submit {remaining_submit_count} approved candidate(s), then refresh daily_candidate_batch_loop_control."]
    if action == "poll_submitted_jobs":
        return [f"Poll {running_count} submitted job(s), then refresh daily_candidate_batch_loop_control."]
    if action in {"rerun_for_shortfall", "create_daily_candidates"}:
        return [f"Create/refill daily candidate jobs for {ready_shortfall_count} missing ready candidate(s), then refresh daily_candidate_batch_loop_control."]
    if action == "report_complete":
        return ["Read completed job summaries and report daily candidate completion evidence."]
    if blocked_count:
        return [f"Resolve {blocked_count} blocked submitted job(s), then refresh daily_candidate_batch_loop_control."]
    return ["Refresh daily_candidate_batch_status before taking another daily candidate action."]


def _daily_candidate_batch_sequence_action(
    gate: dict[str, Any],
    submission_plan: dict[str, Any],
    execution_summary: dict[str, Any],
    refill_plan: dict[str, Any],
) -> str:
    if _string_list(submission_plan.get("hard_blockers")) or _string_list(execution_summary.get("blockers")) or _string_list(refill_plan.get("blockers")):
        return "resolve_blockers"
    if int(submission_plan.get("safe_to_submit_count") or 0):
        return "submit_candidate"
    if int(execution_summary.get("running_count") or 0):
        return "poll_submitted_jobs"
    if str(execution_summary.get("action") or "") == "complete":
        return "report_complete"
    if int(refill_plan.get("ready_shortfall_count") or 0) and refill_plan.get("recommended_tool"):
        return "rerun_for_shortfall"
    if str(gate.get("action") or "") == "inspect_empty":
        return "create_daily_candidates"
    return str(gate.get("action") or execution_summary.get("action") or "inspect_batch")


def _daily_candidate_batch_sequence_steps(
    action: str,
    gate: dict[str, Any],
    submission_plan: dict[str, Any],
    execution_summary: dict[str, Any],
    refill_plan: dict[str, Any],
) -> list[dict[str, Any]]:
    if action == "submit_candidate":
        return [
            _daily_candidate_batch_sequence_step(1, "submit_candidate", "submit_daily_candidate_job", submission_plan.get("recommended_endpoint"), "POST", submission_plan.get("recommended_request"), ["retorrent_job_id", "status_endpoint", "summary_endpoint", "manual_retorrent_final_report", "candidate_submit_sequence", "candidate_submit_followup"], "retorrent_job_id is returned", "duplicate_check.exists=true or policy_execution.ready=false", "call_tool"),
            _daily_candidate_batch_sequence_step(2, "poll_submitted_job", "get_job_status", "/v1/jobs/{retorrent_job_id}", "GET", {"job_id": "<retorrent_job_id from submit_candidate>"}, ["status", "manual_retorrent_final_report", "candidate_submit_sequence", "live_action_sequence", "live_completion_gate", "candidate_submit_followup"], "candidate_submit_sequence.action changes or status is terminal", "status=failed or status=cancelled", "poll", repeat_when="status in queued,running"),
            _daily_candidate_batch_sequence_step(3, "continue_submitted_job", "resume_job or get_job_summary", "/v1/jobs/{retorrent_job_id}/resume or /v1/jobs/{retorrent_job_id}/summary", "POST or GET", "live_action_sequence.next_step.request or null", ["manual_retorrent_final_report", "live_action_sequence", "live_completion_gate", "closure_summary"], "live_completion_gate.ready_for_user_report=true or action is stop_duplicate/resolve_blockers", "live_completion_gate.action=stop_duplicate", "branch_on_live_action_sequence"),
        ]
    if action == "poll_submitted_jobs":
        next_step = execution_summary.get("next_step") if isinstance(execution_summary.get("next_step"), dict) else {}
        return [
            _daily_candidate_batch_sequence_step(1, "poll_submitted_jobs", next_step.get("tool") or "get_job_status", next_step.get("endpoint"), next_step.get("method") or "GET", next_step.get("request"), ["status", "manual_retorrent_final_report", "candidate_submit_sequence", "live_action_sequence", "candidate_submit_followup"], "all submitted jobs are terminal", "any submitted job fails or is cancelled", "poll", repeat_when="submitted jobs are queued/running"),
        ]
    if action == "rerun_for_shortfall":
        return [
            _daily_candidate_batch_sequence_step(1, "rerun_daily_candidates", refill_plan.get("recommended_tool") or "daily_candidates_job", refill_plan.get("recommended_endpoint") or "/v1/jobs/candidates/daily", refill_plan.get("recommended_method") or "POST", refill_plan.get("recommended_request"), ["job_id", "status_endpoint", "summary_endpoint"], "new candidate job is created", "site/rule blockers remain", "call_tool"),
            _daily_candidate_batch_sequence_step(2, "refresh_batch", "daily_candidate_batch_status", "/v1/jobs/candidates/daily/batch", "GET", None, ["daily_candidate_batch_sequence", "daily_candidate_submission_plan", "daily_candidate_refill_plan"], "safe_to_submit_count increases or ready_shortfall_count=0", "ready_shortfall_count remains and no new candidates appear", "read"),
        ]
    if action == "report_complete":
        return [
            _daily_candidate_batch_sequence_step(1, "read_completed_summaries", "get_job_summary", "/v1/jobs/{completed_retorrent_job_id}/summary", "GET", None, ["manual_retorrent_final_report", "live_completion_gate", "closure_summary", "candidate_submission_summary"], "completed summaries are reported to the user", None, "read"),
        ]
    if action == "create_daily_candidates":
        return [
            _daily_candidate_batch_sequence_step(1, "create_daily_candidates", "daily_candidates_job", "/v1/jobs/candidates/daily", "POST", refill_plan.get("recommended_request"), ["job_id", "status_endpoint", "summary_endpoint"], "daily candidate job is created", "schedule/config blockers remain", "call_tool"),
        ]
    if action == "resolve_blockers":
        next_step = execution_summary.get("next_step") if isinstance(execution_summary.get("next_step"), dict) else gate.get("next_step") if isinstance(gate.get("next_step"), dict) else {}
        return [
            _daily_candidate_batch_sequence_step(1, "inspect_blockers", next_step.get("tool") or "daily_candidate_batch_status", next_step.get("endpoint") or "/v1/jobs/candidates/daily/batch", next_step.get("method") or "GET", next_step.get("request"), ["manual_retorrent_final_report", "daily_candidate_batch_sequence.blockers", "daily_candidate_execution_summary", "daily_candidate_submission_plan"], "blockers are resolved and batch sequence is regenerated", "blockers remain", "read"),
        ]
    next_step = gate.get("next_step") if isinstance(gate.get("next_step"), dict) else {}
    return [
        _daily_candidate_batch_sequence_step(1, "inspect_batch", next_step.get("tool") or "daily_candidate_batch_status", next_step.get("endpoint") or "/v1/jobs/candidates/daily/batch", next_step.get("method") or "GET", next_step.get("request"), ["daily_candidate_batch_sequence", "daily_candidate_batch_summary"], "next action is known", None, "read"),
    ]


def _daily_candidate_batch_sequence_step(
    index: int,
    name: str,
    tool: Any,
    endpoint: Any,
    method: Any,
    request: Any,
    read: list[str],
    continue_when: Any,
    stop_when: Any,
    action: str,
    *,
    repeat_when: Any = None,
) -> dict[str, Any]:
    return {
        "index": index,
        "name": name,
        "action": action,
        "tool": tool,
        "endpoint": endpoint,
        "method": method,
        "request": request,
        "read": read,
        "continue_when": continue_when,
        "repeat_when": repeat_when,
        "stop_when": stop_when,
    }


def _daily_candidate_batch_sequence_next_actions(action: str, steps: list[dict[str, Any]], blockers: list[str]) -> list[str]:
    if blockers and action != "report_complete":
        return ["Resolve daily_candidate_batch_sequence.blockers before submitting or refilling candidates."]
    if steps:
        return [f"Execute daily_candidate_batch_sequence.steps[0].name={steps[0].get('name')}, then refresh daily_candidate_batch_sequence."]
    return ["Inspect daily_candidate_batch_sequence.read_order before continuing."]


def _daily_candidate_batch_execution_context(
    summary: dict[str, Any],
    gate: dict[str, Any],
    submission_plan: dict[str, Any],
    execution_summary: dict[str, Any],
    refill_plan: dict[str, Any],
    batch_sequence: dict[str, Any],
    approval_sequence: dict[str, Any],
) -> dict[str, Any]:
    action = str(batch_sequence.get("action") or execution_summary.get("action") or gate.get("action") or "inspect_batch")
    next_step = batch_sequence.get("next_step") if isinstance(batch_sequence.get("next_step"), dict) else execution_summary.get("next_step") if isinstance(execution_summary.get("next_step"), dict) else gate.get("next_step") if isinstance(gate.get("next_step"), dict) else {}
    first_submit_request = submission_plan.get("first_submit_request") if isinstance(submission_plan.get("first_submit_request"), dict) else None
    first_submitted_job = gate.get("first_submitted_job") if isinstance(gate.get("first_submitted_job"), dict) else None
    blockers = list(dict.fromkeys(_string_list(summary.get("blockers")) + _string_list(submission_plan.get("hard_blockers")) + _string_list(execution_summary.get("blockers")) + _string_list(refill_plan.get("blockers")) + _string_list(batch_sequence.get("blockers"))))
    ready = action in {"submit_candidate", "poll_submitted_jobs", "rerun_for_shortfall", "report_complete"} and not (blockers and action != "report_complete")
    return {
        "kind": "ptcli.daily_candidate_batch_execution_context",
        "ready": ready,
        "action": action,
        "candidate_job_count": int(summary.get("candidate_job_count") or 0),
        "ready_to_submit_count": int(summary.get("ready_to_submit_count") or 0),
        "unsubmitted_safe_count": int(summary.get("unsubmitted_safe_count") or 0),
        "submitted_retorrent_job_count": int(summary.get("submitted_retorrent_job_count") or 0),
        "complete_count": int(execution_summary.get("complete_count") or 0),
        "running_count": int(execution_summary.get("running_count") or 0),
        "blocked_count": int(execution_summary.get("blocked_count") or 0),
        "remaining_submit_count": int(execution_summary.get("remaining_submit_count") or 0),
        "ready_shortfall_count": int(refill_plan.get("ready_shortfall_count") or execution_summary.get("ready_shortfall_count") or 0),
        "target_met": bool(execution_summary.get("target_met") or submission_plan.get("target_met")),
        "recommended_tool": next_step.get("tool") or execution_summary.get("recommended_tool") or submission_plan.get("recommended_tool") or gate.get("recommended_tool"),
        "recommended_endpoint": next_step.get("endpoint") or execution_summary.get("recommended_endpoint") or submission_plan.get("recommended_endpoint") or gate.get("recommended_endpoint"),
        "recommended_method": next_step.get("method") or execution_summary.get("recommended_method") or submission_plan.get("recommended_method"),
        "recommended_request": next_step.get("request") if next_step.get("request") is not None else execution_summary.get("recommended_request") if execution_summary.get("recommended_request") is not None else submission_plan.get("recommended_request") if submission_plan.get("recommended_request") is not None else gate.get("recommended_request"),
        "first_submit_request": first_submit_request,
        "first_submitted_job": first_submitted_job,
        "running_jobs": execution_summary.get("running_jobs") if isinstance(execution_summary.get("running_jobs"), list) else [],
        "blocked_jobs": execution_summary.get("blocked_jobs") if isinstance(execution_summary.get("blocked_jobs"), list) else [],
        "complete_jobs": execution_summary.get("complete_jobs") if isinstance(execution_summary.get("complete_jobs"), list) else [],
        "completed_source_ids": _string_list(execution_summary.get("completed_source_ids")),
        "running_source_ids": _string_list(execution_summary.get("running_source_ids")),
        "blocked_source_ids": _string_list(execution_summary.get("blocked_source_ids")),
        "approval_items": approval_sequence.get("approval_items") if isinstance(approval_sequence.get("approval_items"), list) else [],
        "shortfall_recovery": refill_plan,
        "refill_job_handoff": refill_plan.get("refill_job_handoff") if isinstance(refill_plan.get("refill_job_handoff"), dict) else None,
        "next_step": next_step,
        "read_before_action": ["daily_candidate_batch_execution_context", "daily_candidate_execution_summary", "daily_candidate_submission_plan", "daily_candidate_batch_sequence", "daily_candidate_approval_sequence"],
        "continue_when": _daily_candidate_batch_execution_context_continue_when(action),
        "stop_when": _daily_candidate_batch_execution_context_stop_when(action),
        "safety": {
            "mutates_state": action in {"submit_candidate", "rerun_for_shortfall"},
            "live_upload": action == "submit_candidate",
            "requires_human_approval": action == "submit_candidate",
            "does_not_bypass_site_rules": True,
            "does_not_bypass_duplicate_check": True,
            "poll_or_read_only": action in {"poll_submitted_jobs", "report_complete", "inspect_batch"},
        },
        "blockers": blockers,
        "next_actions": _daily_candidate_batch_execution_context_next_actions(action, blockers, int(execution_summary.get("running_count") or 0), int(refill_plan.get("ready_shortfall_count") or execution_summary.get("ready_shortfall_count") or 0)),
    }


def _daily_candidate_batch_execution_context_continue_when(action: str) -> str | None:
    if action == "submit_candidate":
        return "the user approves first_submit_request and submit_daily_candidate_job returns a retorrent_job_id"
    if action == "poll_submitted_jobs":
        return "running submitted jobs leave queued/running and candidate_submit_sequence.action is known"
    if action == "rerun_for_shortfall":
        return "a follow-up daily_candidates_job increases safe_to_submit_count or ready_shortfall_count becomes 0"
    if action == "report_complete":
        return "completed job summaries have been read and closure evidence is reported"
    return None


def _daily_candidate_batch_execution_context_stop_when(action: str) -> list[str]:
    if action == "submit_candidate":
        return ["user approval missing", "first_submit_request.candidate_execution_context.blockers is not empty", "duplicate_check.exists=true"]
    if action == "poll_submitted_jobs":
        return ["submitted job status becomes failed/cancelled/blocked with no resume action"]
    if action == "rerun_for_shortfall":
        return ["refill returns no new safe candidates", "site/rule blockers remain"]
    if action == "report_complete":
        return ["live_completion_gate.ready=false for any completed job"]
    return ["daily_candidate_batch_execution_context.blockers is not empty"]


def _daily_candidate_batch_execution_context_next_actions(action: str, blockers: list[str], running_count: int, ready_shortfall_count: int) -> list[str]:
    if blockers and action != "report_complete":
        return ["Resolve daily_candidate_batch_execution_context.blockers before continuing the daily candidate batch."]
    if action == "submit_candidate":
        return ["Ask the user to approve first_submit_request, then call recommended_tool with recommended_request."]
    if action == "poll_submitted_jobs":
        return [f"Poll {running_count} running submitted retorrent job(s), then refresh daily_candidate_batch_execution_context."]
    if action == "rerun_for_shortfall":
        return [f"Run shortfall_recovery.recommended_tool to fill {ready_shortfall_count} missing ready candidate(s)."]
    if action == "report_complete":
        return ["Read complete_jobs[].summary_endpoint and report closure evidence."]
    return ["Inspect daily_candidate_batch_execution_context.read_before_action before continuing."]


def _daily_candidate_tracking_report(
    summary: dict[str, Any],
    gate: dict[str, Any],
    submission_plan: dict[str, Any],
    execution_summary: dict[str, Any],
    refill_plan: dict[str, Any],
    batch_sequence: dict[str, Any],
    approval_sequence: dict[str, Any],
    execution_context: dict[str, Any],
    final_report: dict[str, Any],
) -> dict[str, Any]:
    """Single daily-candidate control surface for AI batch tracking."""
    action = str(execution_context.get("action") or batch_sequence.get("action") or execution_summary.get("action") or gate.get("action") or "inspect_batch")
    next_step = execution_context.get("next_step") if isinstance(execution_context.get("next_step"), dict) else batch_sequence.get("next_step") if isinstance(batch_sequence.get("next_step"), dict) else execution_summary.get("next_step") if isinstance(execution_summary.get("next_step"), dict) else gate.get("next_step") if isinstance(gate.get("next_step"), dict) else {}
    blockers = list(
        dict.fromkeys(
            _string_list(summary.get("blockers"))
            + _string_list(gate.get("blockers"))
            + _string_list(submission_plan.get("hard_blockers"))
            + _string_list(execution_summary.get("blockers"))
            + _string_list(refill_plan.get("blockers"))
            + _string_list(batch_sequence.get("blockers"))
            + _string_list(execution_context.get("blockers"))
            + _string_list(final_report.get("blockers"))
        )
    )
    target_count = int(submission_plan.get("target_count") or execution_summary.get("target_count") or batch_sequence.get("target_count") or 0)
    ready_count = int(submission_plan.get("ready_count") or execution_summary.get("ready_count") or batch_sequence.get("ready_count") or 0)
    safe_to_submit_count = int(submission_plan.get("safe_to_submit_count") or execution_summary.get("safe_to_submit_count") or batch_sequence.get("safe_to_submit_count") or 0)
    submitted_count = int(summary.get("submitted_retorrent_job_count") or execution_summary.get("submitted_retorrent_job_count") or 0)
    complete_count = int(execution_summary.get("complete_count") or execution_context.get("complete_count") or 0)
    running_count = int(execution_summary.get("running_count") or execution_context.get("running_count") or 0)
    blocked_count = int(execution_summary.get("blocked_count") or execution_context.get("blocked_count") or 0)
    remaining_submit_count = int(execution_summary.get("remaining_submit_count") or execution_context.get("remaining_submit_count") or 0)
    ready_shortfall_count = int(refill_plan.get("ready_shortfall_count") or execution_summary.get("ready_shortfall_count") or execution_context.get("ready_shortfall_count") or 0)
    recommended_call = _daily_candidate_tracking_recommended_call(action, next_step, submission_plan, execution_summary, refill_plan, execution_context, blockers)
    loop_control = batch_sequence.get("loop_control") if isinstance(batch_sequence.get("loop_control"), dict) else {}
    can_submit_now = action == "submit_candidate" and bool(recommended_call.get("tool") == "submit_daily_candidate_job") and not blockers
    should_poll = action == "poll_submitted_jobs" or running_count > 0
    should_refill = action in {"rerun_for_shortfall", "create_daily_candidates"} or (ready_shortfall_count > 0 and not remaining_submit_count and not running_count and not blocked_count)
    should_report = action == "report_complete" or str(final_report.get("verdict") or "") in {"complete", "ready_to_report"}
    ready = bool(can_submit_now or should_poll or should_refill or should_report) and not (blockers and action not in {"report_complete"})
    return {
        "kind": "ptcli.daily_candidate_tracking_report",
        "ready": ready,
        "status": "blocked" if blockers else "ready" if ready else "inspect",
        "action": action,
        "verdict": final_report.get("verdict"),
        "target_count": target_count,
        "candidate_job_count": int(summary.get("candidate_job_count") or 0),
        "ready_count": ready_count,
        "safe_to_submit_count": safe_to_submit_count,
        "submitted_retorrent_job_count": submitted_count,
        "complete_count": complete_count,
        "running_count": running_count,
        "blocked_count": blocked_count,
        "remaining_submit_count": remaining_submit_count,
        "ready_shortfall_count": ready_shortfall_count,
        "target_met": bool(submission_plan.get("target_met") or execution_summary.get("target_met") or execution_context.get("target_met")),
        "ready_target_met": bool(submission_plan.get("ready_target_met") or execution_summary.get("ready_target_met")),
        "can_submit_now": can_submit_now,
        "should_poll": should_poll,
        "should_refill": should_refill,
        "should_report": should_report,
        "approval_required": bool(approval_sequence.get("approval_items")) or action == "submit_candidate",
        "completed_source_ids": _string_list(execution_summary.get("completed_source_ids")) or _string_list(execution_context.get("completed_source_ids")),
        "running_source_ids": _string_list(execution_summary.get("running_source_ids")) or _string_list(execution_context.get("running_source_ids")),
        "blocked_source_ids": _string_list(execution_summary.get("blocked_source_ids")) or _string_list(execution_context.get("blocked_source_ids")),
        "covered_source_ids": _string_list(refill_plan.get("covered_source_ids")),
        "recommended_tool": recommended_call.get("tool"),
        "recommended_endpoint": recommended_call.get("endpoint"),
        "recommended_method": recommended_call.get("method"),
        "recommended_request": recommended_call.get("request"),
        "recommended_call": recommended_call,
        "refill_request_contract": refill_plan.get("refill_request_contract") if isinstance(refill_plan.get("refill_request_contract"), dict) else None,
        "refill_job_handoff": refill_plan.get("refill_job_handoff") if isinstance(refill_plan.get("refill_job_handoff"), dict) else None,
        "loop_control": loop_control or None,
        "read_order": [
            "daily_candidate_tracking_report",
            "daily_candidate_batch_execution_context",
            "daily_candidate_final_report",
            "daily_candidate_execution_summary",
            "daily_candidate_submission_plan",
            "daily_candidate_refill_plan",
            "daily_candidate_batch_sequence",
            "daily_candidate_batch_summary.items[].submitted_jobs",
        ],
        "complete_when": [
            "daily_candidate_tracking_report.should_report=true",
            "daily_candidate_tracking_report.running_count=0",
            "daily_candidate_tracking_report.blocked_count=0",
            "daily_candidate_tracking_report.ready_shortfall_count=0",
        ],
        "stop_when": [
            "daily_candidate_tracking_report.blockers is non-empty",
            "submitted job duplicate_check.exists=true",
            "submitted job policy/rule/confirmation blockers require user action",
            "refill returns no new safe candidates while ready_shortfall_count>0",
        ],
        "blockers": blockers,
        "next_actions": _daily_candidate_tracking_next_actions(action, blockers, running_count, remaining_submit_count, ready_shortfall_count),
    }


def _daily_candidate_tracking_recommended_call(
    action: str,
    next_step: dict[str, Any],
    submission_plan: dict[str, Any],
    execution_summary: dict[str, Any],
    refill_plan: dict[str, Any],
    execution_context: dict[str, Any],
    blockers: list[str],
) -> dict[str, Any]:
    if blockers and action not in {"poll_submitted_jobs", "report_complete"}:
        return {
            "tool": next_step.get("tool") or execution_summary.get("recommended_tool") or "daily_candidate_batch_status",
            "endpoint": next_step.get("endpoint") or execution_summary.get("recommended_endpoint") or "/v1/jobs/candidates/daily/batch",
            "method": next_step.get("method") or execution_summary.get("recommended_method") or "GET",
            "request": next_step.get("request"),
            "safe_to_call_now": False,
            "requires_user_review": True,
            "reason": "daily_candidate_tracking_report.blocked",
        }
    if action == "submit_candidate":
        request = execution_context.get("recommended_request") or submission_plan.get("recommended_request")
        return {
            "tool": "submit_daily_candidate_job",
            "endpoint": execution_context.get("recommended_endpoint") or submission_plan.get("recommended_endpoint"),
            "method": "POST",
            "request": request,
            "safe_to_call_now": False,
            "requires_user_review": True,
            "reason": "approved_daily_candidate_submit",
        }
    if action == "poll_submitted_jobs":
        return {
            "tool": "get_job_status",
            "endpoint": execution_summary.get("recommended_endpoint") or next_step.get("endpoint"),
            "method": "GET",
            "request": execution_summary.get("recommended_request") or next_step.get("request"),
            "safe_to_call_now": True,
            "requires_user_review": False,
            "reason": "poll_submitted_daily_candidate_jobs",
        }
    if action in {"rerun_for_shortfall", "create_daily_candidates"}:
        refill_contract = refill_plan.get("refill_request_contract") if isinstance(refill_plan.get("refill_request_contract"), dict) else {}
        return {
            "tool": refill_contract.get("recommended_tool") or refill_plan.get("recommended_tool") or next_step.get("tool") or "daily_candidates_job",
            "endpoint": refill_contract.get("recommended_endpoint") or refill_plan.get("recommended_endpoint") or next_step.get("endpoint") or "/v1/jobs/candidates/daily",
            "method": refill_contract.get("recommended_method") or refill_plan.get("recommended_method") or next_step.get("method") or "POST",
            "request": refill_contract.get("recommended_request") or refill_plan.get("recommended_request") or next_step.get("request"),
            "safe_to_call_now": bool(refill_contract.get("safe_to_call_now", True)),
            "requires_user_review": bool(refill_contract.get("requires_user_review", False)),
            "reason": "daily_candidate_refill_or_create",
        }
    if action in {"report_complete", "complete"}:
        return {
            "tool": "get_job_summary",
            "endpoint": execution_summary.get("recommended_endpoint") or next_step.get("endpoint"),
            "method": "GET",
            "request": execution_summary.get("recommended_request") or next_step.get("request"),
            "safe_to_call_now": True,
            "requires_user_review": False,
            "reason": "report_daily_candidate_batch_completion",
        }
    return {
        "tool": next_step.get("tool") or "daily_candidate_batch_status",
        "endpoint": next_step.get("endpoint") or "/v1/jobs/candidates/daily/batch",
        "method": next_step.get("method") or "GET",
        "request": next_step.get("request"),
        "safe_to_call_now": True,
        "requires_user_review": False,
        "reason": "inspect_daily_candidate_batch",
    }


def _daily_candidate_tracking_next_actions(action: str, blockers: list[str], running_count: int, remaining_submit_count: int, ready_shortfall_count: int) -> list[str]:
    if blockers and action != "report_complete":
        return ["Resolve daily_candidate_tracking_report.blockers, then refresh daily_candidate_tracking_report."]
    if action == "submit_candidate":
        return [f"Ask the user to approve one of {remaining_submit_count} remaining candidate(s), then call submit_daily_candidate_job with daily_candidate_tracking_report.recommended_request."]
    if action == "poll_submitted_jobs":
        return [f"Poll {running_count} submitted retorrent job(s), then refresh daily_candidate_tracking_report."]
    if action in {"rerun_for_shortfall", "create_daily_candidates"}:
        return [f"Run daily candidate discovery to fill {ready_shortfall_count} missing ready candidate(s), then refresh daily_candidate_tracking_report."]
    if action in {"report_complete", "complete"}:
        return ["Read completed submitted job summaries and report daily candidate closure evidence."]
    return ["Inspect daily_candidate_tracking_report.read_order before choosing the next daily-candidate action."]


def _daily_candidate_completion_gate(
    tracking_report: dict[str, Any],
    final_report: dict[str, Any],
    execution_summary: dict[str, Any],
    refill_plan: dict[str, Any],
    batch_sequence: dict[str, Any],
) -> dict[str, Any]:
    """Compact gate for the daily 10-candidate operational loop."""
    completion_report = final_report.get("completion_report") if isinstance(final_report.get("completion_report"), dict) else {}
    final_counts = final_report.get("counts") if isinstance(final_report.get("counts"), dict) else {}
    target_count = int(tracking_report.get("target_count") or final_counts.get("target_count") or 0)
    ready_count = int(tracking_report.get("ready_count") or 0)
    safe_to_submit_count = int(tracking_report.get("safe_to_submit_count") or 0)
    submitted_count = int(tracking_report.get("submitted_retorrent_job_count") or 0)
    complete_count = int(tracking_report.get("complete_count") or completion_report.get("complete_count") or 0)
    running_count = int(tracking_report.get("running_count") or completion_report.get("running_count") or 0)
    blocked_count = int(tracking_report.get("blocked_count") or completion_report.get("blocked_count") or 0)
    remaining_submit_count = int(tracking_report.get("remaining_submit_count") or 0)
    ready_shortfall_count = int(tracking_report.get("ready_shortfall_count") or 0)
    blockers = [
        blocker
        for blocker in (_string_list(tracking_report.get("blockers")) or _string_list(final_report.get("blockers")))
        if "ready_target_shortfall" not in blocker and "selected_target_shortfall" not in blocker
    ]
    next_step = _daily_candidate_completion_gate_next_step(tracking_report, refill_plan, execution_summary, batch_sequence)
    complete = bool(target_count and complete_count >= target_count and running_count == 0 and blocked_count == 0 and ready_shortfall_count == 0 and remaining_submit_count == 0 and not blockers)
    reportable = bool(complete or tracking_report.get("should_report") or completion_report.get("report_allowed"))
    action = _daily_candidate_completion_gate_action(complete, blockers, running_count, remaining_submit_count, ready_shortfall_count, safe_to_submit_count, reportable)
    refill_handoff = _daily_candidate_completion_refill_handoff(action, refill_plan)
    return {
        "kind": "ptcli.daily_candidate_completion_gate",
        "ready": complete or action in {"submit_next", "poll_running", "refill_shortfall", "report_partial"},
        "complete": complete,
        "report_allowed": reportable and not (blockers and not complete),
        "action": action,
        "target_count": target_count,
        "ready_count": ready_count,
        "safe_to_submit_count": safe_to_submit_count,
        "submitted_retorrent_job_count": submitted_count,
        "complete_count": complete_count,
        "running_count": running_count,
        "blocked_count": blocked_count,
        "remaining_submit_count": remaining_submit_count,
        "ready_shortfall_count": ready_shortfall_count,
        "progress": {
            "ready": f"{ready_count}/{target_count}" if target_count else "0/0",
            "submitted": f"{submitted_count}/{target_count}" if target_count else "0/0",
            "complete": f"{complete_count}/{target_count}" if target_count else "0/0",
        },
        "next_step": next_step,
        "refill_handoff": refill_handoff,
        "recommended_tool": next_step.get("tool"),
        "recommended_endpoint": next_step.get("endpoint"),
        "recommended_method": next_step.get("method"),
        "recommended_request": next_step.get("request"),
        "recommended_call": {
            "tool": next_step.get("tool"),
            "endpoint": next_step.get("endpoint"),
            "method": next_step.get("method"),
            "request": next_step.get("request"),
            "safe_to_call_now": action in {"poll_running", "refill_shortfall", "report_complete", "report_partial"},
            "requires_user_review": action == "submit_next",
            "reason": next_step.get("reason"),
        },
        "read_order": ["daily_candidate_completion_gate", "daily_candidate_tracking_report", "daily_candidate_final_report.completion_report", "daily_candidate_batch_sequence", "daily_candidate_refill_plan"],
        "complete_when": [
            "complete=true",
            "complete_count>=target_count",
            "running_count=0",
            "blocked_count=0",
            "ready_shortfall_count=0",
            "remaining_submit_count=0",
        ],
        "stop_when": [
            "blocked_count>0",
            "blockers is non-empty",
            "submitted job duplicate_check.exists=true",
            "ready_shortfall_count>0 and refill returns no new safe candidates",
            "submit_next without explicit user approval",
        ],
        "blockers": blockers,
        "next_actions": _daily_candidate_completion_gate_next_actions(action, target_count, complete_count, running_count, ready_shortfall_count, blockers),
    }


def _daily_candidate_completion_refill_handoff(action: str, refill_plan: dict[str, Any]) -> dict[str, Any]:
    contract = refill_plan.get("refill_request_contract") if isinstance(refill_plan.get("refill_request_contract"), dict) else {}
    request = contract.get("recommended_request") if isinstance(contract.get("recommended_request"), dict) else refill_plan.get("recommended_request") if isinstance(refill_plan.get("recommended_request"), dict) else None
    ready = action == "refill_shortfall" and bool(contract.get("ready")) and bool(request)
    followup = _daily_candidate_completion_refill_followup(request, refill_plan)
    return {
        "kind": "ptcli.daily_candidate_completion_refill_handoff",
        "ready": ready,
        "action": "create_refill_job" if ready else action,
        "target_count": int(refill_plan.get("target_count") or contract.get("target_count") or 0),
        "ready_count": int(refill_plan.get("ready_count") or contract.get("ready_count") or 0),
        "ready_shortfall_count": int(refill_plan.get("ready_shortfall_count") or contract.get("ready_shortfall_count") or 0),
        "excluded_source_ids": _string_list(contract.get("excluded_source_ids")) or _string_list(refill_plan.get("exclude_source_ids_hint")),
        "submitted_source_ids": _string_list(contract.get("submitted_source_ids")),
        "scan_limit": int(refill_plan.get("scan_limit") or contract.get("scan_limit") or 0),
        "next_scan_limit": refill_plan.get("next_scan_limit") or contract.get("next_scan_limit"),
        "max_scan_limit": int(refill_plan.get("max_scan_limit") or contract.get("max_scan_limit") or 0),
        "scan_exhausted": bool(refill_plan.get("scan_exhausted") or contract.get("scan_exhausted")),
        "pagination_supported": bool(refill_plan.get("pagination_supported")),
        "dedupe_key": contract.get("dedupe_key") or "source_tracker,target,source_id",
        "recommended_tool": contract.get("recommended_tool") or refill_plan.get("recommended_tool"),
        "recommended_endpoint": contract.get("recommended_endpoint") or refill_plan.get("recommended_endpoint"),
        "recommended_method": contract.get("recommended_method") or refill_plan.get("recommended_method"),
        "recommended_request": request,
        "recommended_call": {
            "tool": contract.get("recommended_tool") or refill_plan.get("recommended_tool"),
            "endpoint": contract.get("recommended_endpoint") or refill_plan.get("recommended_endpoint"),
            "method": contract.get("recommended_method") or refill_plan.get("recommended_method"),
            "request": request,
            "safe_to_call_now": ready and bool(contract.get("safe_to_call_now", True)),
            "requires_user_review": False,
            "reason": "daily_candidate_completion_gate.refill_shortfall",
        },
        "followup": followup,
        "read_before_call": _string_list(contract.get("read_before_call")) or ["daily_candidate_completion_gate", "daily_candidate_refill_plan"],
        "continue_when": contract.get("continue_when") or followup.get("continue_when") or "a refill daily_candidates_job is created and daily_candidate_completion_gate.ready_count increases",
        "stop_when": _string_list(contract.get("stop_when")) or _string_list(refill_plan.get("stop_when")),
        "blockers": _string_list(contract.get("blockers")) or _string_list(refill_plan.get("blockers")),
        "next_actions": _daily_candidate_completion_refill_next_actions(ready, int(refill_plan.get("ready_shortfall_count") or contract.get("ready_shortfall_count") or 0)),
    }


def _daily_candidate_completion_refill_followup(request: dict[str, Any] | None, refill_plan: dict[str, Any]) -> dict[str, Any]:
    request = request if isinstance(request, dict) else {}
    source_tracker = request.get("source_tracker") or request.get("source")
    target = request.get("target") or request.get("target_trackers")
    batch_request = {key: value for key, value in {"source_tracker": source_tracker, "target": target}.items() if value}
    ready_shortfall = int(refill_plan.get("ready_shortfall_count") or 0)
    return {
        "kind": "ptcli.daily_candidate_refill_followup",
        "ready": bool(batch_request),
        "batch_status_call": {
            "tool": "daily_candidate_batch_status",
            "endpoint": "/v1/jobs/candidates/daily/batch",
            "method": "GET",
            "request": batch_request or None,
            "reason": "refresh_batch_after_refill_job",
        },
        "expected_new_job": {
            "kind": "ptcli.daily_candidates",
            "source_tracker": source_tracker,
            "target": target,
            "exclude_source_ids": _string_list(request.get("exclude_source_ids")),
            "covered_source_ids_before_refill": _string_list(refill_plan.get("covered_source_ids")),
            "ready_shortfall_before_refill": ready_shortfall,
        },
        "read_after_create": ["job_id", "status_endpoint", "summary_endpoint", "candidate_digest", "candidate_batch_handoff", "daily_candidate_completion_gate"],
        "continue_when": "batch_status_call shows candidate_job_count increased or daily_candidate_completion_gate.ready_count increases",
        "repeat_when": "daily_candidate_completion_gate.action=refill_shortfall and refill_handoff.ready=true",
        "stop_when": [
            "batch_status_call.daily_candidate_completion_gate.blockers is non-empty",
            "ready_shortfall_count does not decrease after refill",
            "new candidate source_id is already in expected_new_job.exclude_source_ids",
        ],
    }


def _daily_candidate_completion_refill_next_actions(ready: bool, ready_shortfall_count: int) -> list[str]:
    if ready:
        return [f"Call refill_handoff.recommended_call to create a refill daily candidate job for {ready_shortfall_count} missing ready candidate(s)."]
    return ["Follow daily_candidate_completion_gate.action before creating a refill job."]


def _daily_candidate_completion_gate_action(
    complete: bool,
    blockers: list[str],
    running_count: int,
    remaining_submit_count: int,
    ready_shortfall_count: int,
    safe_to_submit_count: int,
    reportable: bool,
) -> str:
    if complete:
        return "report_complete"
    if blockers:
        return "resolve_blockers"
    if running_count:
        return "poll_running"
    if remaining_submit_count or safe_to_submit_count:
        return "submit_next"
    if ready_shortfall_count:
        return "refill_shortfall"
    if reportable:
        return "report_partial"
    return "inspect"


def _daily_candidate_completion_gate_next_step(
    tracking_report: dict[str, Any],
    refill_plan: dict[str, Any],
    execution_summary: dict[str, Any],
    batch_sequence: dict[str, Any],
) -> dict[str, Any]:
    tracking_call = tracking_report.get("recommended_call") if isinstance(tracking_report.get("recommended_call"), dict) else {}
    next_step = batch_sequence.get("next_step") if isinstance(batch_sequence.get("next_step"), dict) else {}
    refill_contract = refill_plan.get("refill_request_contract") if isinstance(refill_plan.get("refill_request_contract"), dict) else {}
    if tracking_call.get("tool"):
        return {
            "tool": tracking_call.get("tool"),
            "endpoint": tracking_call.get("endpoint"),
            "method": tracking_call.get("method"),
            "request": tracking_call.get("request"),
            "reason": tracking_call.get("reason") or "daily_candidate_tracking_report",
        }
    if refill_contract.get("recommended_tool"):
        return {
            "tool": refill_contract.get("recommended_tool"),
            "endpoint": refill_contract.get("recommended_endpoint"),
            "method": refill_contract.get("recommended_method"),
            "request": refill_contract.get("recommended_request"),
            "reason": "daily_candidate_refill_request_contract",
        }
    return {
        "tool": next_step.get("tool") or execution_summary.get("recommended_tool") or "daily_candidate_batch_status",
        "endpoint": next_step.get("endpoint") or execution_summary.get("recommended_endpoint") or "/v1/jobs/candidates/daily/batch",
        "method": next_step.get("method") or execution_summary.get("recommended_method") or "GET",
        "request": next_step.get("request") if next_step.get("request") is not None else execution_summary.get("recommended_request"),
        "reason": next_step.get("reason") or "inspect_daily_candidate_completion",
    }


def _daily_candidate_completion_gate_next_actions(action: str, target_count: int, complete_count: int, running_count: int, ready_shortfall_count: int, blockers: list[str]) -> list[str]:
    if action == "report_complete":
        return [f"Report daily_candidate_completion_gate progress {complete_count}/{target_count} with completion_report evidence."]
    if blockers:
        return ["Resolve daily_candidate_completion_gate.blockers before continuing the daily candidate loop."]
    if action == "poll_running":
        return [f"Poll {running_count} running submitted retorrent job(s), then refresh daily_candidate_completion_gate."]
    if action == "submit_next":
        return ["Ask the user to approve the next candidate, then call daily_candidate_completion_gate.recommended_call."]
    if action == "refill_shortfall":
        return [f"Run refill discovery for {ready_shortfall_count} missing ready candidate(s), then refresh daily_candidate_completion_gate."]
    if action == "report_partial":
        return ["Report the partial daily candidate result and explain remaining shortfall or stopped jobs."]
    return ["Inspect daily_candidate_completion_gate.read_order before choosing the next daily candidate action."]


def _daily_candidate_batch_target_report(
    summary: dict[str, Any],
    submission_plan: dict[str, Any],
    execution_summary: dict[str, Any],
    refill_plan: dict[str, Any],
    batch_sequence: dict[str, Any],
    tracking_report: dict[str, Any],
    completion_gate: dict[str, Any],
) -> dict[str, Any]:
    target_count = int(submission_plan.get("target_count") or tracking_report.get("target_count") or completion_gate.get("target_count") or DEFAULT_CANDIDATE_LIMIT)
    ready_count = int(submission_plan.get("ready_count") or tracking_report.get("ready_count") or completion_gate.get("ready_count") or 0)
    safe_count = int(submission_plan.get("safe_to_submit_count") or tracking_report.get("safe_to_submit_count") or completion_gate.get("safe_to_submit_count") or 0)
    submitted_count = int(summary.get("submitted_retorrent_job_count") or tracking_report.get("submitted_retorrent_job_count") or completion_gate.get("submitted_retorrent_job_count") or 0)
    complete_count = int(execution_summary.get("complete_count") or tracking_report.get("complete_count") or completion_gate.get("complete_count") or 0)
    running_count = int(execution_summary.get("running_count") or tracking_report.get("running_count") or completion_gate.get("running_count") or 0)
    blocked_count = int(execution_summary.get("blocked_count") or tracking_report.get("blocked_count") or completion_gate.get("blocked_count") or 0)
    remaining_submit_count = int(execution_summary.get("remaining_submit_count") or tracking_report.get("remaining_submit_count") or completion_gate.get("remaining_submit_count") or 0)
    ready_shortfall_count = int(refill_plan.get("ready_shortfall_count") or tracking_report.get("ready_shortfall_count") or completion_gate.get("ready_shortfall_count") or max(0, target_count - ready_count))
    blockers = [
        blocker
        for blocker in list(dict.fromkeys(_string_list(summary.get("blockers")) + _string_list(tracking_report.get("blockers")) + _string_list(completion_gate.get("blockers"))))
        if "ready_target_shortfall" not in blocker and "selected_target_shortfall" not in blocker
    ]
    loop_control = batch_sequence.get("loop_control") if isinstance(batch_sequence.get("loop_control"), dict) else {}
    action = _daily_candidate_batch_target_action(
        complete=completion_gate.get("complete") is True,
        blockers=blockers,
        running_count=running_count,
        remaining_submit_count=remaining_submit_count,
        safe_count=safe_count,
        ready_shortfall_count=ready_shortfall_count,
        report_allowed=completion_gate.get("report_allowed") is True,
    )
    recommended_call = _daily_candidate_batch_target_recommended_call(action, tracking_report, completion_gate, refill_plan, loop_control)
    return {
        "kind": "ptcli.daily_candidate_batch_target_report",
        "ready": action in {"submit_next", "poll_running", "refill_shortfall", "report_complete", "report_partial"} and not (blockers and action not in {"report_partial"}),
        "status": "complete" if action == "report_complete" else "blocked" if blockers else "shortfall" if ready_shortfall_count else "ready",
        "action": action,
        "target": {
            "target_count": target_count,
            "ready_count": ready_count,
            "safe_to_submit_count": safe_count,
            "submitted_retorrent_job_count": submitted_count,
            "complete_count": complete_count,
            "running_count": running_count,
            "blocked_count": blocked_count,
            "remaining_submit_count": remaining_submit_count,
            "ready_shortfall_count": ready_shortfall_count,
            "ready_target_met": bool(target_count and ready_count >= target_count),
            "completion_target_met": bool(target_count and complete_count >= target_count and not running_count and not blocked_count),
        },
        "loop": {
            "should_submit": action == "submit_next" or loop_control.get("should_submit") is True,
            "should_poll": action == "poll_running" or loop_control.get("should_poll") is True,
            "should_refill": action == "refill_shortfall" or loop_control.get("should_refill") is True,
            "should_report": action in {"report_complete", "report_partial"} or loop_control.get("should_report") is True,
            "loop_control": loop_control or None,
            "after_step": loop_control.get("after_step") if isinstance(loop_control, dict) else None,
            "repeat_until": _string_list(loop_control.get("repeat_until")) if isinstance(loop_control, dict) else [],
        },
        "recommended_call": recommended_call,
        "recommended_tool": recommended_call.get("tool"),
        "recommended_endpoint": recommended_call.get("endpoint"),
        "recommended_method": recommended_call.get("method"),
        "recommended_request": recommended_call.get("request"),
        "refill_handoff": completion_gate.get("refill_handoff") if isinstance(completion_gate.get("refill_handoff"), dict) else refill_plan.get("refill_job_handoff") if isinstance(refill_plan.get("refill_job_handoff"), dict) else None,
        "submission": {
            "approval_required": action == "submit_next",
            "first_submit_request": submission_plan.get("first_submit_request") if isinstance(submission_plan.get("first_submit_request"), dict) else None,
            "submit_requests": submission_plan.get("submit_requests") if isinstance(submission_plan.get("submit_requests"), list) else [],
            "required_user_inputs": ["explicit candidate approval", "accept_rules=true", "confirm_upload=true", "save_path or path"],
        },
        "read_order": ["daily_candidate_batch_target_report", "daily_candidate_completion_gate", "daily_candidate_tracking_report", "daily_candidate_batch_loop_control", "daily_candidate_refill_plan", "daily_candidate_submission_plan"],
        "complete_when": [
            "target.completion_target_met=true",
            "target.ready_shortfall_count=0",
            "target.running_count=0",
            "target.blocked_count=0",
            "target.remaining_submit_count=0",
        ],
        "stop_when": [
            "blockers is non-empty",
            "action=submit_next until explicit user approval is available",
            "action=refill_shortfall and refill_handoff.ready=false",
            "refill returns no new safe candidates while ready_shortfall_count>0",
        ],
        "safety": {
            "report_does_not_submit_candidates": True,
            "report_does_not_upload_torrents": True,
            "submit_requires_human_approval": True,
            "live_upload_requires_confirm_upload": True,
            "does_not_bypass_site_rules": True,
        },
        "blockers": blockers,
        "next_actions": _daily_candidate_batch_target_next_actions(action, ready_shortfall_count, running_count, remaining_submit_count, blockers),
    }


def _daily_candidate_batch_target_action(
    *,
    complete: bool,
    blockers: list[str],
    running_count: int,
    remaining_submit_count: int,
    safe_count: int,
    ready_shortfall_count: int,
    report_allowed: bool,
) -> str:
    if complete:
        return "report_complete"
    if blockers:
        return "resolve_blockers"
    if running_count:
        return "poll_running"
    if remaining_submit_count or safe_count:
        return "submit_next"
    if ready_shortfall_count:
        return "refill_shortfall"
    if report_allowed:
        return "report_partial"
    return "inspect"


def _daily_candidate_batch_target_recommended_call(
    action: str,
    tracking_report: dict[str, Any],
    completion_gate: dict[str, Any],
    refill_plan: dict[str, Any],
    loop_control: dict[str, Any],
) -> dict[str, Any]:
    if action == "refill_shortfall":
        refill_handoff = completion_gate.get("refill_handoff") if isinstance(completion_gate.get("refill_handoff"), dict) else refill_plan.get("refill_job_handoff") if isinstance(refill_plan.get("refill_job_handoff"), dict) else {}
        call = refill_handoff.get("recommended_call") if isinstance(refill_handoff.get("recommended_call"), dict) else {}
        if call:
            return call
    if action in {"submit_next", "poll_running", "report_complete", "report_partial"}:
        call = completion_gate.get("recommended_call") if isinstance(completion_gate.get("recommended_call"), dict) else tracking_report.get("recommended_call") if isinstance(tracking_report.get("recommended_call"), dict) else {}
        if call:
            return call
    next_step = loop_control.get("next_step") if isinstance(loop_control.get("next_step"), dict) else {}
    return {
        "tool": next_step.get("tool") or "daily_candidate_batch_status",
        "endpoint": next_step.get("endpoint") or "/v1/jobs/candidates/daily/batch",
        "method": next_step.get("method") or "GET",
        "request": next_step.get("request"),
        "safe_to_call_now": action in {"poll_running", "refill_shortfall", "report_complete", "report_partial", "inspect"},
        "requires_user_review": action == "submit_next",
        "reason": next_step.get("reason") or f"daily_candidate_batch_target_report.{action}",
    }


def _daily_candidate_batch_target_next_actions(action: str, ready_shortfall_count: int, running_count: int, remaining_submit_count: int, blockers: list[str]) -> list[str]:
    if blockers:
        return ["Resolve daily_candidate_batch_target_report.blockers, then refresh daily_candidate_batch_status."]
    if action == "submit_next":
        return [f"Ask the user to approve one of {remaining_submit_count} remaining candidate(s), then call daily_candidate_batch_target_report.recommended_call."]
    if action == "poll_running":
        return [f"Poll {running_count} submitted retorrent job(s), then refresh daily_candidate_batch_target_report."]
    if action == "refill_shortfall":
        return [f"Run refill_handoff.recommended_call for {ready_shortfall_count} missing ready candidate(s), then refresh daily_candidate_batch_target_report."]
    if action == "report_complete":
        return ["Report the daily target as complete using completed job summaries and closure evidence."]
    if action == "report_partial":
        return ["Report the partial daily target and explain remaining unmet conditions."]
    return ["Inspect daily_candidate_batch_target_report.read_order before choosing the next action."]


def _daily_candidate_batch_publish_payload(
    summary: dict[str, Any],
    approval_sequence: dict[str, Any],
    final_report: dict[str, Any],
    tracking_report: dict[str, Any],
    completion_gate: dict[str, Any],
    target_report: dict[str, Any] | None = None,
) -> dict[str, Any]:
    counts = final_report.get("counts") if isinstance(final_report.get("counts"), dict) else {}
    completion_report = final_report.get("completion_report") if isinstance(final_report.get("completion_report"), dict) else {}
    approval_items = approval_sequence.get("approval_items") if isinstance(approval_sequence.get("approval_items"), list) else []
    completed_jobs = completion_report.get("completed_jobs") if isinstance(completion_report.get("completed_jobs"), list) else []
    blockers = [
        blocker
        for blocker in list(dict.fromkeys(_string_list(summary.get("blockers")) + _string_list(final_report.get("blockers")) + _string_list(tracking_report.get("blockers"))))
        if "ready_target_shortfall" not in blocker and "selected_target_shortfall" not in blocker
    ]
    status = _daily_candidate_batch_publish_status(tracking_report, final_report, blockers)
    publish_cards = [_daily_candidate_publish_approval_card(item) for item in approval_items if isinstance(item, dict)]
    completion_cards = [_daily_candidate_publish_completion_card(job) for job in completed_jobs if isinstance(job, dict)]
    candidate_field_completeness = _daily_candidate_publish_field_completeness(publish_cards)
    candidate_executability_matrix = _daily_candidate_publish_executability_matrix(publish_cards, blockers)
    ready = status in {"ready_for_approval", "ready_to_report", "shortfall", "empty"} and not blockers
    title = _daily_candidate_batch_publish_title(status, counts)
    message = _daily_candidate_batch_publish_message(status, counts, publish_cards, completion_cards, blockers)
    return {
        "kind": "ptcli.daily_candidate_batch_publish_payload",
        "ready": ready,
        "status": status,
        "format": "application/json",
        "title": title,
        "summary": message,
        "message": message,
        "counts": {
            "target_candidates": int(counts.get("target_count") or 0),
            "selected_candidates": int(counts.get("selected_count") or summary.get("candidate_job_count") or 0),
            "ready_candidates": int(counts.get("ready_count") or 0),
            "safe_candidates": int(counts.get("safe_to_submit_count") or 0),
            "shortfall_candidates": int(counts.get("shortfall_count") or tracking_report.get("ready_shortfall_count") or 0),
            "submitted_jobs": int(tracking_report.get("submitted_retorrent_job_count") or 0),
            "completed_jobs": int(completion_report.get("complete_count") or tracking_report.get("complete_count") or 0),
            "running_jobs": int(completion_report.get("running_count") or tracking_report.get("running_count") or 0),
            "blocked_jobs": int(completion_report.get("blocked_count") or tracking_report.get("blocked_count") or 0),
            "target_met": bool(counts.get("target_met") or tracking_report.get("target_met")),
        },
        "items": publish_cards,
        "top_item": publish_cards[0] if publish_cards else None,
        "candidate_field_completeness": candidate_field_completeness,
        "candidate_executability_matrix": candidate_executability_matrix,
        "completion_items": completion_cards,
        "top_completion": completion_cards[0] if completion_cards else None,
        "approval_queue": {
            "ready": bool(approval_sequence.get("ready")),
            "approval_count": int(approval_sequence.get("approval_count") or len(approval_items)),
            "items": approval_items,
            "first_prompt": approval_sequence.get("human_prompt"),
            "required_user_inputs": _string_list(approval_sequence.get("required_user_inputs")),
        },
        "tracking": {
            "action": tracking_report.get("action"),
            "recommended_tool": tracking_report.get("recommended_tool"),
            "recommended_endpoint": tracking_report.get("recommended_endpoint"),
            "recommended_method": tracking_report.get("recommended_method"),
            "recommended_request": tracking_report.get("recommended_request"),
            "can_submit_now": tracking_report.get("can_submit_now"),
            "should_refill": tracking_report.get("should_refill"),
            "should_poll": tracking_report.get("should_poll"),
            "should_report": tracking_report.get("should_report"),
            "loop_control": tracking_report.get("loop_control") if isinstance(tracking_report.get("loop_control"), dict) else None,
        },
        "completion_gate": completion_gate,
        "target_report": target_report,
        "completion_report": completion_report,
        "daily_candidate_final_report": final_report,
        "daily_candidate_tracking_report": tracking_report,
        "daily_candidate_completion_gate": completion_gate,
        "daily_candidate_batch_target_report": target_report,
        "publish_contract": {
            "payload_field": "daily_candidate_batch_publish_payload",
            "does_not_upload": True,
            "submit_requires_user_approval": True,
            "live_upload_requires_confirm_upload": True,
            "safe_to_publish_without_tracker_mutation": True,
        },
        "read_order": ["daily_candidate_batch_publish_payload", "daily_candidate_completion_gate", "daily_candidate_tracking_report", "daily_candidate_final_report", "daily_candidate_approval_sequence", "daily_candidate_batch_summary"],
        "blockers": blockers,
        "next_actions": _daily_candidate_batch_publish_next_actions(status, tracking_report, blockers),
    }


def _daily_candidate_batch_publish_status(tracking_report: dict[str, Any], final_report: dict[str, Any], blockers: list[str]) -> str:
    if blockers:
        return "blocked"
    if tracking_report.get("should_report"):
        return "ready_to_report"
    if tracking_report.get("can_submit_now"):
        return "ready_for_approval"
    if tracking_report.get("should_poll"):
        return "polling"
    if tracking_report.get("should_refill"):
        return "shortfall"
    verdict = str(final_report.get("verdict") or "")
    if verdict == "empty":
        return "empty"
    return verdict or "inspect"


def _daily_candidate_publish_approval_card(item: dict[str, Any]) -> dict[str, Any]:
    request = item.get("submit_request") if isinstance(item.get("submit_request"), dict) else {}
    source_card = item.get("publish_card") if isinstance(item.get("publish_card"), dict) else {}
    site_policy_profile_handoff = _candidate_item_site_policy_profile_handoff(item)
    site_policy_summary = _candidate_item_site_policy_summary(item, site_policy_profile_handoff)
    action = source_card.get("action") if isinstance(source_card.get("action"), dict) else {}
    action_handoff = item.get("action_handoff") if isinstance(item.get("action_handoff"), dict) else _daily_candidate_submit_action_handoff(
        candidate_job_id=str(item.get("candidate_job_id") or "") or None,
        rank=item.get("rank") or item.get("index"),
        source_id=source_card.get("source_id") or item.get("source_id"),
        endpoint=item.get("endpoint"),
        request_template=request,
    )
    return {
        "kind": "ptcli.daily_candidate_publish_card",
        "type": "approval",
        "rank": item.get("rank") or item.get("index"),
        "source_tracker": source_card.get("source_tracker") or item.get("source_tracker"),
        "target": source_card.get("target") or item.get("target") or request.get("target"),
        "source_id": source_card.get("source_id") or item.get("source_id"),
        "source_url": source_card.get("source_url") or item.get("source_url") or request.get("source_url") or request.get("source"),
        "title": source_card.get("title") or item.get("title"),
        "size": source_card.get("size") or item.get("size"),
        "published_at": source_card.get("published_at") or item.get("published_at"),
        "promotion": source_card.get("promotion") or item.get("promotion"),
        "freeleech_like": source_card.get("freeleech_like"),
        "metadata": source_card.get("metadata") if isinstance(source_card.get("metadata"), dict) else item.get("metadata") if isinstance(item.get("metadata"), dict) else {},
        "duplicate_check": source_card.get("duplicate_check") if isinstance(source_card.get("duplicate_check"), dict) else {"clear": item.get("duplicate_clear")},
        "downloadability": source_card.get("downloadability") if isinstance(source_card.get("downloadability"), dict) else {},
        "recommendation": source_card.get("recommendation") if isinstance(source_card.get("recommendation"), dict) else {},
        "risk": source_card.get("risk") if isinstance(source_card.get("risk"), dict) else {"level": item.get("risk_level"), "policy_level": item.get("policy_risk_level"), "blockers": _string_list(item.get("blockers"))},
        "summary_text": item.get("approval_text"),
        "endpoint": item.get("endpoint"),
        "method": item.get("method") or "POST",
        "request": request,
        "action_handoff": action_handoff,
        "submit_call": action_handoff["submit_call"],
        "tracking_call": action_handoff["tracking_call"],
        "after_submit_calls": action_handoff["after_submit_calls"],
        "candidate_executability": item.get("candidate_executability") if isinstance(item.get("candidate_executability"), dict) else None,
        "action": {
            "decision": action.get("decision") or "submit_when_confirmed",
            "can_submit": action.get("can_submit") if isinstance(action.get("can_submit"), bool) else bool(request),
            "can_submit_after_approval": item.get("can_submit_after_approval"),
            "tool": action.get("tool") or item.get("submit_tool"),
            "endpoint": action.get("endpoint") or item.get("submit_endpoint"),
            "request": action.get("request") if isinstance(action.get("request"), dict) else request,
            "approval_prompt": action.get("approval_prompt") if isinstance(action.get("approval_prompt"), dict) else item.get("approval_prompt"),
            "required_user_inputs": _string_list(action.get("required_user_inputs")) or _string_list(item.get("required_overrides")) or ["confirm_upload=true", "save_path or path"],
        },
        "requires_user_approval": True,
        "required_overrides": item.get("required_overrides") if isinstance(item.get("required_overrides"), list) else ["confirm_upload=true", "save_path or path"],
        "site_policy_profile_handoff": site_policy_profile_handoff,
        "site_policy_summary": site_policy_summary,
    }


def _daily_candidate_publish_field_completeness(cards: list[dict[str, Any]]) -> dict[str, Any]:
    required_fields = [
        "source_tracker",
        "target",
        "source_id",
        "source_url",
        "title",
        "size",
        "published_at",
        "promotion",
        "metadata",
        "duplicate_check",
        "downloadability",
        "recommendation",
        "risk",
        "action",
    ]
    reports = [_daily_candidate_publish_field_item(card, required_fields) for card in cards]
    missing_by_source_id = {str(report["source_id"] or report["rank"]): report["missing_fields"] for report in reports if report["missing_fields"]}
    return {
        "kind": "ptcli.daily_candidate_field_completeness",
        "ready": not missing_by_source_id,
        "required_fields": required_fields,
        "item_count": len(reports),
        "ready_count": sum(1 for report in reports if report["ready"]),
        "missing_count": len(missing_by_source_id),
        "missing_by_source_id": missing_by_source_id,
        "items": reports,
        "continue_when": "candidate_field_completeness.ready=true before publishing the daily candidate digest as complete.",
        "stop_when": ["candidate_field_completeness.missing_by_source_id is non-empty"],
    }


def _daily_candidate_publish_executability_matrix(cards: list[dict[str, Any]], blockers: list[str]) -> dict[str, Any]:
    items = [_daily_candidate_publish_executability_item(card) for card in cards]
    safe_items = [item for item in items if item.get("can_submit_after_approval")]
    blocked_items = [item for item in items if not item.get("ready")]
    next_item = blocked_items[0] if blocked_items else safe_items[0] if safe_items else None
    return {
        "kind": "ptcli.daily_candidate_executability_matrix",
        "ready": bool(safe_items) and not blockers,
        "status": "ready_for_approval" if safe_items and not blockers else "blocked" if blockers or blocked_items else "empty",
        "item_count": len(items),
        "safe_to_submit_count": len(safe_items),
        "blocked_count": len(blocked_items),
        "ready_count": sum(1 for item in items if item.get("ready")),
        "next_source_id": next_item.get("source_id") if isinstance(next_item, dict) else None,
        "next_phase": next_item.get("first_blocked_phase") if isinstance(next_item, dict) else None,
        "next_evidence": next_item.get("first_blocked_check") if isinstance(next_item, dict) else None,
        "items": items,
        "phase_summary": _daily_candidate_publish_executability_phase_summary(items),
        "blockers": blockers,
        "continue_when": "candidate_executability_matrix.safe_to_submit_count>0 and user explicitly approves one candidate with confirm_upload=true",
        "stop_when": ["candidate_executability_matrix.blockers is non-empty", "candidate_executability_matrix.safe_to_submit_count=0"],
        "next_actions": _daily_candidate_publish_executability_next_actions(safe_items, next_item, blockers),
    }


def _daily_candidate_publish_executability_item(card: dict[str, Any]) -> dict[str, Any]:
    report = card.get("candidate_executability") if isinstance(card.get("candidate_executability"), dict) else {}
    if report:
        return {
            "rank": report.get("rank") or card.get("rank"),
            "source_tracker": report.get("source_tracker") or card.get("source_tracker"),
            "source_id": report.get("source_id") or card.get("source_id"),
            "source_url": report.get("source_url") or card.get("source_url"),
            "target": report.get("target") or card.get("target"),
            "title": report.get("title") or card.get("title"),
            "ready": report.get("ready") is True,
            "can_submit_after_approval": report.get("can_submit_after_approval") is True,
            "requires_human_approval": report.get("requires_human_approval") is not False,
            "status": report.get("status") or "ready_for_approval" if report.get("can_submit_after_approval") is True else "blocked",
            "first_blocked_phase": report.get("first_blocked_phase"),
            "first_blocked_check": report.get("first_blocked_check"),
            "checks": report.get("checks") if isinstance(report.get("checks"), list) else [],
            "missing_checks": _string_list(report.get("missing_checks")),
            "submit_tool": report.get("submit_tool") or "submit_daily_candidate_job",
            "submit_endpoint": report.get("submit_endpoint") or card.get("endpoint"),
            "submit_request": report.get("submit_request") if isinstance(report.get("submit_request"), dict) else card.get("request") if isinstance(card.get("request"), dict) else None,
            "required_user_inputs": _string_list(report.get("required_user_inputs")) or _string_list((card.get("action") or {}).get("required_user_inputs") if isinstance(card.get("action"), dict) else []),
            "blockers": _string_list(report.get("blockers")),
        }
    action = card.get("action") if isinstance(card.get("action"), dict) else {}
    ready = action.get("can_submit") is True and bool(action.get("request") or card.get("request"))
    return {
        "rank": card.get("rank"),
        "source_tracker": card.get("source_tracker"),
        "source_id": card.get("source_id"),
        "source_url": card.get("source_url"),
        "target": card.get("target"),
        "title": card.get("title"),
        "ready": ready,
        "can_submit_after_approval": ready,
        "requires_human_approval": True,
        "status": "ready_for_approval" if ready else "blocked",
        "first_blocked_phase": None if ready else "submit",
        "first_blocked_check": None if ready else "submit_request",
        "checks": [],
        "missing_checks": [] if ready else ["submit_request"],
        "submit_tool": action.get("tool") or "submit_daily_candidate_job",
        "submit_endpoint": action.get("endpoint") or card.get("endpoint"),
        "submit_request": action.get("request") if isinstance(action.get("request"), dict) else card.get("request") if isinstance(card.get("request"), dict) else None,
        "required_user_inputs": _string_list(action.get("required_user_inputs")) or ["confirm_upload=true", "save_path or path"],
        "blockers": _string_list(card.get("blockers")),
    }


def _daily_candidate_publish_executability_phase_summary(items: list[dict[str, Any]]) -> dict[str, dict[str, Any]]:
    phases = ["source", "metadata", "duplicate", "source_pull", "policy", "risk", "submit"]
    summary: dict[str, dict[str, Any]] = {}
    for phase in phases:
        phase_items = [
            item
            for item in items
            if item.get("first_blocked_phase") == phase
            or any(isinstance(check, dict) and check.get("phase") == phase for check in item.get("checks", []) if isinstance(check, dict))
        ]
        blocked = [item for item in phase_items if item.get("first_blocked_phase") == phase or any(isinstance(check, dict) and check.get("phase") == phase and check.get("ready") is False for check in item.get("checks", []))]
        summary[phase] = {
            "ready": not blocked,
            "item_count": len(phase_items),
            "blocked_count": len(blocked),
            "blocked_source_ids": [item.get("source_id") for item in blocked if item.get("source_id")],
        }
    return summary


def _daily_candidate_publish_executability_next_actions(safe_items: list[dict[str, Any]], next_item: dict[str, Any] | None, blockers: list[str]) -> list[str]:
    if blockers:
        return ["Resolve daily_candidate_batch_publish_payload.candidate_executability_matrix.blockers before submitting candidates."]
    if safe_items:
        return ["Ask the user to approve candidate_executability_matrix.items[0].submit_request with confirm_upload=true, then call submit_daily_candidate_job."]
    if next_item:
        return [f"Resolve {next_item.get('first_blocked_phase') or 'candidate'} evidence for source_id={next_item.get('source_id')} before approval."]
    return ["Run daily_candidates_job before expecting candidate_executability_matrix.items."]


def _daily_candidate_executability_by_source_id(digest: dict[str, Any]) -> dict[str, dict[str, Any]]:
    matrix = digest.get("candidate_executability_matrix") if isinstance(digest.get("candidate_executability_matrix"), dict) else {}
    reports = matrix.get("items") if isinstance(matrix.get("items"), list) else []
    return {str(item.get("source_id")): item for item in reports if isinstance(item, dict) and item.get("source_id") is not None}


def _daily_candidate_publish_field_item(card: dict[str, Any], required_fields: list[str]) -> dict[str, Any]:
    values = {
        "source_tracker": card.get("source_tracker"),
        "target": card.get("target"),
        "source_id": card.get("source_id"),
        "source_url": card.get("source_url"),
        "title": card.get("title"),
        "size": card.get("size"),
        "published_at": card.get("published_at"),
        "promotion": card.get("promotion"),
        "metadata": _daily_candidate_publish_metadata_ready(card.get("metadata")),
        "duplicate_check": _nested_bool(card, "duplicate_check", "clear") is True,
        "downloadability": _nested_bool(card, "downloadability", "ready") is True,
        "recommendation": bool(_nested_value(card.get("recommendation"), "reason")),
        "risk": isinstance(card.get("risk"), dict) and bool(card["risk"]),
        "action": isinstance(card.get("action"), dict) and bool(card["action"].get("request") or card["action"].get("endpoint")),
    }
    missing = [field for field in required_fields if not values.get(field)]
    return {
        "rank": card.get("rank"),
        "source_tracker": card.get("source_tracker"),
        "target": card.get("target"),
        "source_id": card.get("source_id"),
        "title": card.get("title"),
        "ready": not missing,
        "missing_fields": missing,
        "can_submit": _nested_bool(card, "action", "can_submit") is True,
    }


def _daily_candidate_publish_metadata_ready(value: Any) -> bool:
    metadata = value if isinstance(value, dict) else {}
    return bool(metadata.get("ready") or metadata.get("imdb_id") or metadata.get("tmdb_id") or metadata.get("douban_id") or metadata.get("douban_url") or metadata.get("name"))


def _daily_candidate_publish_completion_card(job: dict[str, Any]) -> dict[str, Any]:
    qbit_enforcement_summary = job.get("qbit_enforcement_summary") if isinstance(job.get("qbit_enforcement_summary"), dict) else None
    qbit_execution_gate = job.get("qbit_execution_gate") if isinstance(job.get("qbit_execution_gate"), dict) else None
    uploaded_seeding_evidence = job.get("uploaded_seeding_evidence") if isinstance(job.get("uploaded_seeding_evidence"), dict) else None
    return {
        "kind": "ptcli.daily_candidate_publish_card",
        "type": "completion",
        "retorrent_job_id": job.get("retorrent_job_id"),
        "source_id": job.get("source_id"),
        "title": job.get("title"),
        "summary_endpoint": job.get("summary_endpoint"),
        "status_endpoint": job.get("status_endpoint"),
        "job_final_verdict": job.get("job_final_verdict"),
        "manual_retorrent_verdict": job.get("manual_retorrent_verdict"),
        "report_allowed": job.get("report_allowed"),
        "duplicate_exists": job.get("duplicate_exists"),
        "closure_complete": job.get("closure_complete"),
        "qbit_enforcement_ready": qbit_enforcement_summary.get("ready") if isinstance(qbit_enforcement_summary, dict) else job.get("qbit_enforcement_ready"),
        "qbit_execution_ready": qbit_execution_gate.get("ready") if isinstance(qbit_execution_gate, dict) else job.get("qbit_execution_ready"),
        "uploaded_seeding_ready": uploaded_seeding_evidence.get("ready") if isinstance(uploaded_seeding_evidence, dict) else job.get("uploaded_seeding_ready"),
        "evidence_refs": [
            "summary_endpoint.policy_application_handoff",
            "summary_endpoint.qbit_enforcement_summary",
            "summary_endpoint.qbit_execution_gate",
            "summary_endpoint.target_upload_handoff.uploaded_seeding_evidence",
            "summary_endpoint.live_completion_gate",
            "summary_endpoint.closure_summary",
            "summary_endpoint.seedbox_live_validation_completion_report",
        ],
    }


def _daily_candidate_batch_publish_title(status: str, counts: dict[str, Any]) -> str:
    target = int(counts.get("target_count") or 0)
    ready = int(counts.get("ready_count") or 0)
    if status == "ready_to_report":
        return "Daily PT retorrent batch complete"
    if status == "ready_for_approval":
        return f"Daily PT candidates ready for approval ({ready}/{target})"
    if status == "shortfall":
        return f"Daily PT candidates need refill ({ready}/{target})"
    if status == "blocked":
        return "Daily PT candidate batch blocked"
    return "Daily PT candidate batch status"


def _daily_candidate_batch_publish_message(status: str, counts: dict[str, Any], publish_cards: list[dict[str, Any]], completion_cards: list[dict[str, Any]], blockers: list[str]) -> str:
    target = int(counts.get("target_count") or 0)
    ready = int(counts.get("ready_count") or 0)
    shortfall = int(counts.get("shortfall_count") or 0)
    if blockers:
        return f"Daily candidate batch is blocked: {blockers[0]}"
    if status == "ready_to_report":
        return f"{len(completion_cards)} daily retorrent job(s) are complete and ready to report."
    if status == "ready_for_approval":
        return f"{len(publish_cards)} candidate(s) are ready for approval; daily target progress is {ready}/{target}."
    if status == "shortfall":
        return f"Daily target is short by {shortfall}; refill discovery is recommended before reporting completion."
    return f"Daily candidate progress is {ready}/{target}."


def _daily_candidate_batch_publish_next_actions(status: str, tracking_report: dict[str, Any], blockers: list[str]) -> list[str]:
    if blockers:
        return ["Report daily_candidate_batch_publish_payload.blockers and do not submit or upload."]
    if status == "ready_for_approval":
        return ["Publish daily_candidate_batch_publish_payload.items to the user and wait for explicit approval before submit_daily_candidate_job."]
    if status == "ready_to_report":
        return ["Publish daily_candidate_batch_publish_payload.completion_items with completion_report evidence."]
    if status == "shortfall":
        return ["Run daily_candidate_tracking_report.refill_request_contract.recommended_request, then refresh daily_candidate_batch_publish_payload."]
    if status == "polling":
        return ["Poll submitted jobs, then refresh daily_candidate_batch_publish_payload."]
    return _string_list(tracking_report.get("next_actions")) or ["Refresh daily_candidate_batch_publish_payload after the next batch action."]


def _daily_candidate_approval_sequence(
    summary: dict[str, Any],
    submission_plan: dict[str, Any],
    execution_summary: dict[str, Any],
    refill_plan: dict[str, Any],
    batch_sequence: dict[str, Any],
) -> dict[str, Any]:
    approval_items = _daily_candidate_approval_items(submission_plan)
    blockers = list(dict.fromkeys(_string_list(submission_plan.get("hard_blockers")) + _string_list(execution_summary.get("blockers")) + _string_list(refill_plan.get("blockers"))))
    submitted_count = int(summary.get("submitted_retorrent_job_count") or 0)
    running_count = int(execution_summary.get("running_count") or 0)
    complete_count = int(execution_summary.get("complete_count") or 0)
    ready_shortfall_count = int(refill_plan.get("ready_shortfall_count") or execution_summary.get("ready_shortfall_count") or 0)
    if blockers:
        action = "resolve_blockers"
    elif approval_items:
        action = "ask_user_approval"
    elif running_count:
        action = "poll_approved_jobs"
    elif str(execution_summary.get("action") or "") == "complete":
        action = "report_complete"
    elif ready_shortfall_count and refill_plan.get("recommended_tool"):
        action = "refill_candidates"
    elif int(summary.get("candidate_job_count") or 0) == 0:
        action = "create_daily_candidates"
    else:
        action = str(batch_sequence.get("action") or "inspect_batch")
    steps = _daily_candidate_approval_sequence_steps(action, approval_items, execution_summary, refill_plan, batch_sequence)
    return {
        "kind": "ptcli.daily_candidate_approval_sequence",
        "ready": action in {"ask_user_approval", "poll_approved_jobs", "refill_candidates", "report_complete"} and not blockers,
        "action": action,
        "target_count": int(submission_plan.get("target_count") or 0),
        "ready_count": int(submission_plan.get("ready_count") or 0),
        "approval_count": len(approval_items),
        "submitted_retorrent_job_count": submitted_count,
        "complete_count": complete_count,
        "running_count": running_count,
        "ready_shortfall_count": ready_shortfall_count,
        "approval_items": approval_items,
        "approved_submit_requests": [item.get("submit_request") for item in approval_items if isinstance(item.get("submit_request"), dict)],
        "steps": steps,
        "next_step": steps[0] if steps else None,
        "human_prompt": _daily_candidate_approval_human_prompt(action, approval_items, ready_shortfall_count),
        "required_user_inputs": ["approved approval_items[].source_id or rank", "confirm_upload=true", "save_path or path"],
        "read_order": ["daily_candidate_approval_sequence", "daily_candidate_batch_summary.items[].publish_cards", "daily_candidate_submission_plan.submit_requests", "daily_candidate_execution_summary", "daily_candidate_refill_plan"],
        "continue_when": [
            "the user approves one or more daily_candidate_approval_sequence.approval_items",
            "each approved submit request returns retorrent_job_id",
            "approved jobs reach complete or an explicit stop action",
            "ready_shortfall_count=0 or refill_candidates has no new safe candidates",
        ],
        "stop_when": [
            "daily_candidate_approval_sequence.blockers is not empty",
            "the user rejects all approval_items",
            "a submitted retorrent job reports duplicate_check.exists=true",
            "a submitted retorrent job requires unresolved policy/material confirmation",
        ],
        "blockers": blockers,
        "next_actions": _daily_candidate_approval_sequence_next_actions(action, len(approval_items), running_count, ready_shortfall_count, blockers),
    }


def _daily_candidate_approval_items(submission_plan: dict[str, Any]) -> list[dict[str, Any]]:
    items: list[dict[str, Any]] = []
    for index, submit_request in enumerate(submission_plan.get("submit_requests", []) if isinstance(submission_plan.get("submit_requests"), list) else [], start=1):
        if not isinstance(submit_request, dict):
            continue
        request = submit_request.get("request") if isinstance(submit_request.get("request"), dict) else {}
        source_request = submit_request.get("source_url_retorrent_request") if isinstance(submit_request.get("source_url_retorrent_request"), dict) else request
        source_reference = _approval_source_reference(source_request)
        site_policy_profile_handoff = _candidate_item_site_policy_profile_handoff(submit_request)
        site_policy_summary = _candidate_item_site_policy_summary(submit_request, site_policy_profile_handoff)
        action_handoff = submit_request.get("action_handoff") if isinstance(submit_request.get("action_handoff"), dict) else _daily_candidate_submit_action_handoff(
            candidate_job_id=str(submit_request.get("candidate_job_id") or "") or None,
            rank=submit_request.get("rank"),
            source_id=submit_request.get("source_id") or source_request.get("source_id") or source_reference.get("source_id"),
            endpoint=submit_request.get("endpoint"),
            request_template=request,
        )
        items.append(
            {
                "index": index,
                "rank": submit_request.get("rank"),
                "candidate_job_id": submit_request.get("candidate_job_id"),
                "source_tracker": source_request.get("source_tracker") or submit_request.get("source_tracker") or source_reference.get("tracker"),
                "target": source_request.get("target") or source_request.get("target_trackers") or submit_request.get("target_trackers"),
                "source_id": submit_request.get("source_id") or source_request.get("source_id") or source_reference.get("source_id"),
                "title": submit_request.get("title"),
                "endpoint": submit_request.get("endpoint"),
                "method": submit_request.get("method") or "POST",
                "submit_request": request,
                "action_handoff": action_handoff,
                "submit_call": action_handoff["submit_call"],
                "tracking_call": action_handoff["tracking_call"],
                "after_submit_calls": action_handoff["after_submit_calls"],
                "candidate_execution_context": submit_request.get("candidate_execution_context") if isinstance(submit_request.get("candidate_execution_context"), dict) else None,
                "candidate_executability": submit_request.get("candidate_executability") if isinstance(submit_request.get("candidate_executability"), dict) else None,
                "can_submit_after_approval": submit_request.get("can_submit_after_approval"),
                "first_blocked_phase": submit_request.get("first_blocked_phase"),
                "first_blocked_check": submit_request.get("first_blocked_check"),
                "missing_checks": _string_list(submit_request.get("missing_checks")),
                "site_policy_profile_handoff": site_policy_profile_handoff,
                "site_policy_summary": site_policy_summary,
                "required_overrides": submit_request.get("required_overrides") or ["confirm_upload=true", "save_path or path"],
                "approval_text": _daily_candidate_approval_item_text(index, submit_request, request),
                "after_submit": submit_request.get("after_submit"),
            }
        )
    return items


def _approval_source_reference(request: dict[str, Any]) -> dict[str, Any]:
    source = str(request.get("source_url") or request.get("source") or "").strip()
    if not source:
        return {}
    try:
        return resolve_source_reference(source, request.get("source_tracker"))
    except (ValueError, TypeError):
        return {}


def _daily_candidate_approval_item_text(index: int, submit_request: dict[str, Any], request: dict[str, Any]) -> str:
    source_tracker = str(request.get("source_tracker") or "?")
    target = request.get("target") or request.get("target_trackers") or "?"
    source_id = str(submit_request.get("source_id") or "?")
    title = str(submit_request.get("title") or "untitled")
    return f"Approve #{index}: {source_tracker}-{source_id} -> {target} {title}"


def _daily_candidate_approval_sequence_steps(
    action: str,
    approval_items: list[dict[str, Any]],
    execution_summary: dict[str, Any],
    refill_plan: dict[str, Any],
    batch_sequence: dict[str, Any],
) -> list[dict[str, Any]]:
    if action == "ask_user_approval":
        first = approval_items[0] if approval_items else {}
        return [
            _daily_candidate_batch_sequence_step(1, "present_approval_queue", "daily_candidate_batch_status", "/v1/jobs/candidates/daily/batch", "GET", None, ["daily_candidate_approval_sequence.approval_items", "approval_items[].approval_text", "approval_items[].submit_request"], "the user approves one or more rank/source_id values", "the user rejects every approval item", "ask_user"),
            _daily_candidate_batch_sequence_step(2, "submit_approved_candidate", "submit_daily_candidate_job", first.get("endpoint"), first.get("method") or "POST", first.get("submit_request"), ["retorrent_job_id", "status_endpoint", "summary_endpoint", "policy_application_handoff", "manual_retorrent_final_report", "candidate_submit_sequence", "material_gap_summary"], "retorrent_job_id is returned for every approved item and policy_application_handoff has no missing request fields", "duplicate_check.exists=true or policy_application_handoff.ready=false or policy_execution.ready=false", "call_tool", repeat_when="more approved approval_items remain"),
            _daily_candidate_batch_sequence_step(3, "poll_approved_jobs", "get_job_status", "/v1/jobs/{retorrent_job_id}", "GET", {"job_id": "<retorrent_job_id from submit_approved_candidate>"}, ["status", "policy_application_handoff", "manual_retorrent_final_report", "candidate_submit_sequence", "material_gap_summary", "live_action_sequence"], "all approved jobs are terminal or need a resume action", "status=failed or status=cancelled or policy_application_handoff.missing_request_fields is non-empty", "poll", repeat_when="status in queued,running"),
            _daily_candidate_batch_sequence_step(4, "continue_material_or_live_steps", "resume_job or get_job_summary", "/v1/jobs/{retorrent_job_id}/resume or /v1/jobs/{retorrent_job_id}/summary", "POST or GET", "candidate_submit_sequence.next_step.request or material_gap_summary.items[].execute_request", ["policy_application_handoff", "manual_retorrent_final_report", "material_gap_summary", "live_completion_gate", "closure_summary"], "the submitted job completes or returns an explicit stop action", "live_completion_gate.action=stop_duplicate or policy_application_handoff.missing_request_fields is non-empty", "branch_on_candidate_submit_sequence"),
        ]
    if action == "poll_approved_jobs":
        next_step = execution_summary.get("next_step") if isinstance(execution_summary.get("next_step"), dict) else {}
        return [_daily_candidate_batch_sequence_step(1, "poll_approved_jobs", next_step.get("tool") or "get_job_status", next_step.get("endpoint"), next_step.get("method") or "GET", next_step.get("request"), ["status", "policy_application_handoff", "manual_retorrent_final_report", "candidate_submit_sequence", "live_action_sequence", "material_gap_summary"], "submitted jobs are terminal or need a resume action", "status=failed or status=cancelled or policy_application_handoff.missing_request_fields is non-empty", "poll", repeat_when="submitted jobs are queued/running")]
    if action == "refill_candidates":
        return [
            _daily_candidate_batch_sequence_step(1, "refill_daily_candidates", refill_plan.get("recommended_tool") or "daily_candidates_job", refill_plan.get("recommended_endpoint") or "/v1/jobs/candidates/daily", refill_plan.get("recommended_method") or "POST", refill_plan.get("recommended_request"), ["job_id", "status_endpoint", "summary_endpoint"], "a new daily candidate job is created", "site/rule blockers remain", "call_tool"),
            _daily_candidate_batch_sequence_step(2, "refresh_approval_queue", "daily_candidate_batch_status", "/v1/jobs/candidates/daily/batch", "GET", None, ["daily_candidate_approval_sequence", "daily_candidate_submission_plan"], "approval_count increases or ready_shortfall_count=0", "ready_shortfall_count remains and no new candidates appear", "read"),
        ]
    if action == "report_complete":
        return [_daily_candidate_batch_sequence_step(1, "read_completed_summaries", "get_job_summary", "/v1/jobs/{completed_retorrent_job_id}/summary", "GET", None, ["policy_application_handoff", "manual_retorrent_final_report", "closure_summary", "live_completion_gate", "candidate_submission_summary"], "completed daily candidate outcomes are reported", "policy_application_handoff.ready=false", "read")]
    if action == "resolve_blockers":
        next_step = batch_sequence.get("next_step") if isinstance(batch_sequence.get("next_step"), dict) else {}
        return [_daily_candidate_batch_sequence_step(1, "inspect_approval_blockers", next_step.get("tool") or "daily_candidate_batch_status", next_step.get("endpoint") or "/v1/jobs/candidates/daily/batch", next_step.get("method") or "GET", next_step.get("request"), ["manual_retorrent_final_report", "daily_candidate_approval_sequence.blockers", "daily_candidate_submission_plan.hard_blockers", "daily_candidate_execution_summary.blockers"], "blockers are resolved and approval sequence is regenerated", "blockers remain", "read")]
    if action == "create_daily_candidates":
        return [_daily_candidate_batch_sequence_step(1, "create_daily_candidates", "daily_candidates_job", "/v1/jobs/candidates/daily", "POST", refill_plan.get("recommended_request"), ["job_id", "status_endpoint", "summary_endpoint"], "daily candidate job is created", "schedule/config blockers remain", "call_tool")]
    next_step = batch_sequence.get("next_step") if isinstance(batch_sequence.get("next_step"), dict) else {}
    return [_daily_candidate_batch_sequence_step(1, "inspect_batch", next_step.get("tool") or "daily_candidate_batch_status", next_step.get("endpoint") or "/v1/jobs/candidates/daily/batch", next_step.get("method") or "GET", next_step.get("request"), ["daily_candidate_approval_sequence", "daily_candidate_batch_sequence"], "next approval action is known", None, "read")]


def _daily_candidate_approval_human_prompt(action: str, approval_items: list[dict[str, Any]], ready_shortfall_count: int) -> str | None:
    if action == "ask_user_approval":
        sample = "; ".join(str(item.get("approval_text")) for item in approval_items[:3])
        return f"Ask the user which daily candidates to submit. {len(approval_items)} safe candidate(s) are available: {sample}"
    if action == "refill_candidates":
        return f"No safe approval item is left; refill discovery is recommended for {ready_shortfall_count} missing ready candidate(s)."
    if action == "poll_approved_jobs":
        return "Approved retorrent jobs are already submitted; poll them before asking for more approvals."
    if action == "report_complete":
        return "Daily candidate submissions are complete; summarize closure evidence for the user."
    return None


def _daily_candidate_approval_sequence_next_actions(action: str, approval_count: int, running_count: int, ready_shortfall_count: int, blockers: list[str]) -> list[str]:
    if blockers:
        return ["Resolve daily_candidate_approval_sequence.blockers before asking for approval or submitting candidates."]
    if action == "ask_user_approval":
        return [f"Present {approval_count} safe approval item(s) to the user and submit only explicitly approved items."]
    if action == "poll_approved_jobs":
        return [f"Poll {running_count} approved retorrent job(s), then refresh daily_candidate_approval_sequence."]
    if action == "refill_candidates":
        return [f"Run refill discovery for {ready_shortfall_count} missing ready candidate(s), then refresh the approval queue."]
    if action == "report_complete":
        return ["Read completed job summaries and report daily candidate transfer evidence."]
    return ["Inspect daily_candidate_approval_sequence.read_order before continuing."]


def _daily_candidate_jobs_batch_item(candidate_job: dict[str, Any], submitted_jobs: list[dict[str, Any]]) -> dict[str, Any]:
    job_id = str(candidate_job.get("job_id") or "")
    candidate_payload = _candidate_payload(candidate_job.get("result")) or {}
    digest = _candidate_digest_from_payload(candidate_job.get("result")) or {}
    request = candidate_job.get("request") if isinstance(candidate_job.get("request"), dict) else {}
    nested_payload = candidate_payload.get("result") if isinstance(candidate_payload.get("result"), dict) else {}
    pagination_plan = candidate_payload.get("pagination_plan") if isinstance(candidate_payload.get("pagination_plan"), dict) else nested_payload.get("pagination_plan") if isinstance(nested_payload.get("pagination_plan"), dict) else None
    scan_limit = _bounded_int(candidate_payload.get("scan_limit") or nested_payload.get("scan_limit") or request.get("scan_limit"), default=MAX_CANDIDATE_SCAN, minimum=1, maximum=HARD_MAX_CANDIDATE_SCAN)
    max_scan_limit = _bounded_int(candidate_payload.get("max_scan_limit") or nested_payload.get("max_scan_limit"), default=HARD_MAX_CANDIDATE_SCAN, minimum=1, maximum=HARD_MAX_CANDIDATE_SCAN)
    candidate_executability_matrix = digest.get("candidate_executability_matrix") if isinstance(digest.get("candidate_executability_matrix"), dict) else None
    batch_handoff = _job_candidate_batch_handoff(candidate_job) or {}
    control = _candidate_control_summary_from_payload(candidate_job.get("result")) or {}
    safe_ids = batch_handoff.get("items") if isinstance(batch_handoff.get("items"), list) else []
    submitted_items = [_daily_candidate_submitted_item(job) for job in submitted_jobs]
    return {
        "candidate_job_id": job_id or None,
        "status": candidate_job.get("status"),
        "status_endpoint": f"/v1/jobs/{job_id}" if job_id else None,
        "summary_endpoint": f"/v1/jobs/{job_id}/summary" if job_id else None,
        "source_tracker": request.get("source_tracker"),
        "target_trackers": request.get("target_trackers") or request.get("target"),
        "candidate_request": request,
        "candidate_counts": {
            "target": int(digest.get("target_count") or control.get("target_count") or candidate_payload.get("target_count") or candidate_payload.get("count") or control.get("selected_count") or 0),
            "scan": int(digest.get("scan_count") or candidate_payload.get("scan_count") or 0),
            "scan_limit": scan_limit,
            "max_scan_limit": max_scan_limit,
            "selected": int(digest.get("selected_count") or control.get("selected_count") or candidate_payload.get("selected_count") or candidate_payload.get("count") or 0),
            "ready": int(digest.get("ready_count") or control.get("ready_count") or candidate_payload.get("ready_count") or 0),
            "safe_to_submit": int(batch_handoff.get("submit_count") or control.get("safe_to_submit_count") or 0),
            "submitted": len(submitted_jobs),
            "shortfall": int(digest.get("shortfall_count") or control.get("ready_shortfall_count") or 0),
        },
        "pagination_plan": pagination_plan,
        "candidate_control_summary": control or None,
        "candidate_executability_matrix": candidate_executability_matrix,
        "candidate_batch_handoff_ready": batch_handoff.get("ready"),
        "submit_endpoint": batch_handoff.get("submit_endpoint"),
        "recommended_request": batch_handoff.get("recommended_request"),
        "safe_source_ids": [
            (item.get("selector") or {}).get("source_id")
            for item in safe_ids
            if isinstance(item, dict) and isinstance(item.get("selector"), dict) and (item.get("selector") or {}).get("source_id")
        ],
        "submit_requests": [_daily_candidate_batch_item_submit_request(job_id, item) for item in safe_ids if isinstance(item, dict)],
        "submitted_jobs": submitted_items,
        "blockers": list(dict.fromkeys(_string_list(candidate_job.get("blockers")) + _string_list(batch_handoff.get("blockers")) + _string_list(control.get("blockers")))),
    }


def _daily_candidate_batch_item_submit_request(candidate_job_id: str, item: dict[str, Any]) -> dict[str, Any]:
    selector = item.get("selector") if isinstance(item.get("selector"), dict) else {}
    request = item.get("request_template") if isinstance(item.get("request_template"), dict) else {}
    site_policy_profile_handoff = _candidate_item_site_policy_profile_handoff(item)
    site_policy_summary = _candidate_item_site_policy_summary(item, site_policy_profile_handoff)
    action_handoff = item.get("action_handoff") if isinstance(item.get("action_handoff"), dict) else _daily_candidate_submit_action_handoff(
        candidate_job_id=candidate_job_id or None,
        rank=selector.get("rank"),
        source_id=selector.get("source_id"),
        endpoint=item.get("submit_endpoint") or (f"/v1/jobs/candidates/{candidate_job_id}/submit" if candidate_job_id else None),
        request_template=request,
    )
    return {
        "candidate_job_id": candidate_job_id or None,
        "rank": selector.get("rank"),
        "source_id": selector.get("source_id"),
        "title": item.get("title"),
        "endpoint": item.get("submit_endpoint") or (f"/v1/jobs/candidates/{candidate_job_id}/submit" if candidate_job_id else None),
        "method": "POST",
        "request": request,
        "action_handoff": action_handoff,
        "submit_call": action_handoff["submit_call"],
        "tracking_call": action_handoff["tracking_call"],
        "after_submit_calls": action_handoff["after_submit_calls"],
        "source_url_retorrent_request": item.get("source_url_retorrent_request") if isinstance(item.get("source_url_retorrent_request"), dict) else None,
        "candidate_execution_context": item.get("candidate_execution_context") if isinstance(item.get("candidate_execution_context"), dict) else None,
        "candidate_executability": item.get("candidate_executability") if isinstance(item.get("candidate_executability"), dict) else None,
        "can_submit_after_approval": item.get("can_submit_after_approval"),
        "first_blocked_phase": item.get("first_blocked_phase"),
        "first_blocked_check": item.get("first_blocked_check"),
        "missing_checks": _string_list(item.get("missing_checks")),
        "site_policy_profile_handoff": site_policy_profile_handoff,
        "site_policy_summary": site_policy_summary,
        "required_overrides": item.get("required_overrides") if isinstance(item.get("required_overrides"), list) else ["confirm_upload=true", "save_path or path"],
        "after_submit": item.get("after_submit") if isinstance(item.get("after_submit"), dict) else None,
    }


def _daily_candidate_batch_targets(value: Any) -> list[str]:
    if value is None:
        return []
    if isinstance(value, list):
        return [str(item).strip().upper() for item in value if str(item).strip()]
    return [item.strip().upper() for item in str(value).split(",") if item.strip()]


def _daily_candidate_job_matches_batch_filter(job: dict[str, Any], *, source_tracker: str, target_trackers: list[str]) -> bool:
    request = job.get("request") if isinstance(job.get("request"), dict) else {}
    if source_tracker and str(request.get("source_tracker") or "").strip().upper() != source_tracker:
        return False
    if target_trackers:
        job_targets = _daily_candidate_batch_targets(request.get("target_trackers") or request.get("target"))
        if not set(target_trackers).intersection(job_targets):
            return False
    return True


def _daily_candidate_submitted_item(job: dict[str, Any]) -> dict[str, Any]:
    followup = _job_candidate_submit_followup(job) or {}
    submission = _job_candidate_submission(job) or {}
    manual_final_report = followup.get("manual_retorrent_final_report") if isinstance(followup.get("manual_retorrent_final_report"), dict) else _job_cached_manual_retorrent_final_report(job)
    job_final_report = _job_final_report(job)
    summary = followup.get("candidate_submission_summary") if isinstance(followup.get("candidate_submission_summary"), dict) else {}
    execution = summary.get("execution_handoff") if isinstance(summary.get("execution_handoff"), dict) else {}
    policy_application_handoff = _job_policy_application_handoff(job)
    qbit_enforcement_summary = _job_qbit_enforcement_summary(job)
    qbit_execution_gate = _job_qbit_execution_gate(job)
    target_upload_handoff = _job_target_upload_handoff(job)
    uploaded_seeding_evidence = target_upload_handoff.get("uploaded_seeding_evidence") if isinstance(target_upload_handoff, dict) and isinstance(target_upload_handoff.get("uploaded_seeding_evidence"), dict) else None
    return {
        "retorrent_job_id": job.get("job_id"),
        "status": job.get("status"),
        "candidate_rank": submission.get("candidate_rank"),
        "candidate_source_id": submission.get("candidate_source_id"),
        "candidate_title": submission.get("candidate_title"),
        "action": followup.get("action"),
        "status_endpoint": followup.get("status_endpoint"),
        "summary_endpoint": followup.get("summary_endpoint"),
        "resume_endpoint": followup.get("resume_endpoint"),
        "recommended_tool": followup.get("recommended_tool"),
        "recommended_endpoint": followup.get("recommended_endpoint"),
        "recommended_method": followup.get("recommended_method"),
        "recommended_request": followup.get("recommended_request"),
        "job_final_verdict": job_final_report.get("verdict"),
        "job_report_allowed": job_final_report.get("report_allowed"),
        "job_final_report": job_final_report,
        "manual_retorrent_verdict": manual_final_report.get("verdict") if isinstance(manual_final_report, dict) else None,
        "manual_report_allowed": manual_final_report.get("report_allowed") if isinstance(manual_final_report, dict) else None,
        "manual_retorrent_final_report": manual_final_report,
        "closure_complete": summary.get("closure_complete") is True,
        "policy_execution_ready": summary.get("policy_execution_ready"),
        "policy_application_ready": policy_application_handoff.get("ready") if isinstance(policy_application_handoff, dict) else None,
        "policy_application_handoff": policy_application_handoff,
        "qbit_enforcement_ready": qbit_enforcement_summary.get("ready") if isinstance(qbit_enforcement_summary, dict) else None,
        "qbit_enforcement_summary": qbit_enforcement_summary,
        "qbit_execution_ready": qbit_execution_gate.get("ready") if isinstance(qbit_execution_gate, dict) else None,
        "qbit_execution_gate": qbit_execution_gate,
        "uploaded_seeding_ready": uploaded_seeding_evidence.get("ready") if isinstance(uploaded_seeding_evidence, dict) else None,
        "uploaded_seeding_evidence": uploaded_seeding_evidence,
        "execution_state": execution.get("state") or summary.get("execution_state"),
        "blockers": _string_list(followup.get("blockers")),
        "next_actions": _string_list(followup.get("next_actions")),
    }


def _daily_candidate_jobs_batch_blockers(items: list[dict[str, Any]], submitted_jobs: list[dict[str, Any]]) -> list[str]:
    blockers: list[str] = []
    if not items:
        return []
    for item in items:
        if item.get("status") in {"queued", "running"}:
            blockers.append(f"candidate_job.{item.get('candidate_job_id')}.pending")
        blockers.extend(f"candidate_job.{item.get('candidate_job_id')}.{blocker}" for blocker in _string_list(item.get("blockers")))
    for job in submitted_jobs:
        followup = _job_candidate_submit_followup(job) or {}
        action = followup.get("action")
        if action in {"stop_duplicate", "collect_confirmations", "configure_policy", "blocked", "failed", "cancelled"}:
            blockers.append(f"submitted_job.{job.get('job_id')}.{action}")
    return list(dict.fromkeys(str(item) for item in blockers if item))


def _daily_candidate_jobs_batch_next_actions(candidate_jobs: list[dict[str, Any]], submitted_jobs: list[dict[str, Any]], unsubmitted_safe_count: int, blockers: list[str]) -> list[str]:
    if not candidate_jobs:
        return ["Create daily candidate jobs with daily_candidates_schedule_job or daily_candidates_job before reading batch execution status."]
    if unsubmitted_safe_count:
        return ["Submit approved daily_candidate_batch_summary.items[].recommended_request through submit_daily_candidate_job after explicit user confirmation."]
    if any(job.get("status") in {"queued", "running"} for job in submitted_jobs):
        return ["Poll submitted retorrent jobs through daily_candidate_batch_summary.items[].submitted_jobs[].status_endpoint."]
    if blockers:
        return ["Resolve daily_candidate_batch_summary.blockers before treating the daily candidate batch as complete."]
    return ["Read submitted job summaries and report completed/blocked daily candidate outcomes."]


