def _job_seedbox_live_evidence_diagnostics(checks: dict[str, Any], missing_evidence: list[str], blockers: list[str]) -> dict[str, Any]:
    matrix = _seedbox_live_evidence_matrix()
    check_map = {
        "source_torrent_downloaded": ["source_torrent_hash_present"],
        "source_qbit_complete": ["source_content_path_present", "qbit_enforcement_ready"],
        "metadata_and_description_ready": ["materials_ready"],
        "media_assets_ready": ["materials_ready"],
        "target_duplicate_clear": ["duplicate_clear"],
        "target_upload_created": ["target_uploaded_torrent_hash_present", "uploaded_torrent_path_present"],
        "target_qbit_seeding": ["target_injected_torrent_hash_present", "uploaded_seeding_ready", "qbit_enforcement_ready"],
        "final_user_report_allowed": ["job_complete", "closure_complete", "closure_blockers_clear"],
    }
    items: list[dict[str, Any]] = []
    for item in matrix:
        name = str(item.get("name") or "")
        related_checks = check_map.get(name, [])
        missing_checks = [check for check in related_checks if checks.get(check) is False]
        unknown_checks = [check for check in related_checks if checks.get(check) is None]
        phase_blockers = list(missing_checks)
        if name == "final_user_report_allowed":
            phase_blockers.extend(blockers)
            if missing_evidence:
                phase_blockers.append("missing_evidence_clear")
        ready = not missing_checks and (name != "final_user_report_allowed" or (not blockers and not missing_evidence))
        status = "ready" if ready else "blocked"
        if unknown_checks and ready:
            status = "unknown"
        items.append(
            {
                "name": name,
                "phase": item.get("phase"),
                "ready": ready,
                "status": status,
                "produced_by": item.get("produced_by"),
                "required_fields": item.get("required_fields") if isinstance(item.get("required_fields"), list) else [],
                "related_checks": related_checks,
                "missing_checks": missing_checks,
                "unknown_checks": unknown_checks,
                "blockers": list(dict.fromkeys(str(blocker) for blocker in phase_blockers if str(blocker).strip())),
                "read_from": item.get("read_from") if isinstance(item.get("read_from"), list) else [],
            }
        )
    phase_summary = _job_seedbox_live_evidence_phase_summary(items)
    blocked_items = [item for item in items if item.get("ready") is not True]
    next_item = blocked_items[0] if blocked_items else None
    return {
        "kind": "ptcli.seedbox_live_evidence_diagnostics",
        "ready": not blocked_items and not blockers and not missing_evidence,
        "status": "ready" if not blocked_items and not blockers and not missing_evidence else "blocked",
        "next_phase": next_item.get("phase") if isinstance(next_item, dict) else None,
        "next_evidence": next_item.get("name") if isinstance(next_item, dict) else None,
        "blocked_count": len(blocked_items),
        "ready_count": len(items) - len(blocked_items),
        "total_count": len(items),
        "items": items,
        "phase_summary": phase_summary,
        "missing_evidence": missing_evidence,
        "blockers": blockers,
        "next_actions": _job_seedbox_live_evidence_diagnostics_next_actions(next_item, missing_evidence, blockers),
    }


def _job_seedbox_live_evidence_phase_summary(items: list[dict[str, Any]]) -> dict[str, dict[str, Any]]:
    summary: dict[str, dict[str, Any]] = {}
    for item in items:
        phase = str(item.get("phase") or "unknown")
        phase_summary = summary.setdefault(phase, {"ready": True, "ready_count": 0, "blocked_count": 0, "items": [], "missing_checks": [], "blockers": []})
        phase_summary["items"].append(item.get("name"))
        if item.get("ready") is True:
            phase_summary["ready_count"] += 1
        else:
            phase_summary["ready"] = False
            phase_summary["blocked_count"] += 1
            phase_summary["missing_checks"].extend(_string_list(item.get("missing_checks")))
            phase_summary["blockers"].extend(_string_list(item.get("blockers")))
        phase_summary["missing_checks"] = list(dict.fromkeys(phase_summary["missing_checks"]))
        phase_summary["blockers"] = list(dict.fromkeys(phase_summary["blockers"]))
    return summary


def _job_seedbox_live_evidence_diagnostics_next_actions(next_item: dict[str, Any] | None, missing_evidence: list[str], blockers: list[str]) -> list[str]:
    if not next_item and not missing_evidence and not blockers:
        return ["Evidence diagnostics are ready; read live_validation_completion_audit before reporting completion."]
    if isinstance(next_item, dict) and next_item.get("name"):
        return [f"Repair evidence phase {next_item.get('phase')} / {next_item.get('name')}; missing checks: {', '.join(_string_list(next_item.get('missing_checks')) or _string_list(next_item.get('blockers')))}."]
    if missing_evidence:
        return [f"Collect missing live evidence: {', '.join(missing_evidence)}."]
    if blockers:
        return ["Resolve live evidence blockers before reporting completion."]
    return ["Reread seedbox_live_validation_completion_report before deciding the next action."]


def _job_live_completion_gate(job: dict[str, Any], summary_payload: dict[str, Any] | None = None) -> dict[str, Any]:
    completion_report = _job_seedbox_live_validation_completion_report(job, summary_payload)
    closure_summary = _job_closure_summary(job, summary_payload)
    qbit_enforcement_summary = _job_qbit_enforcement_summary(job, summary_payload)
    policy_execution_report = _job_policy_execution_report(job, summary_payload)
    material_evidence_summary = _job_material_evidence_summary(job, summary_payload)
    ready_for_user_report = completion_report.get("ready_for_user_report") is True and not _string_list(completion_report.get("missing_evidence")) and not _string_list(completion_report.get("blockers"))
    blockers = list(dict.fromkeys(_string_list(completion_report.get("blockers")) + _string_list(closure_summary.get("blockers"))))
    status = str(completion_report.get("status") or "unknown")
    action = _live_completion_gate_action(job, status, ready_for_user_report, blockers, completion_report)
    recommended_call = completion_report.get("recommended_call") if isinstance(completion_report.get("recommended_call"), dict) else None
    recommended = completion_report.get("next_step") if isinstance(completion_report.get("next_step"), dict) else {}
    return {
        "kind": "ptcli.live_completion_gate",
        "ready": ready_for_user_report,
        "ready_for_user_report": ready_for_user_report,
        "status": status,
        "action": action,
        "job_id": job.get("job_id"),
        "job_status": job.get("status"),
        "summary_file": completion_report.get("summary_file") or job.get("summary_file") or _job_summary_file(job),
        "duplicate_check": completion_report.get("duplicate_check") if isinstance(completion_report.get("duplicate_check"), dict) else None,
        "evidence_status": {
            "closure_complete": closure_summary.get("complete") is True,
            "source_torrent_hash_present": (completion_report.get("checks") or {}).get("source_torrent_hash_present") if isinstance(completion_report.get("checks"), dict) else None,
            "target_uploaded_torrent_hash_present": (completion_report.get("checks") or {}).get("target_uploaded_torrent_hash_present") if isinstance(completion_report.get("checks"), dict) else None,
            "target_injected_torrent_hash_present": (completion_report.get("checks") or {}).get("target_injected_torrent_hash_present") if isinstance(completion_report.get("checks"), dict) else None,
            "uploaded_seeding_ready": (completion_report.get("checks") or {}).get("uploaded_seeding_ready") if isinstance(completion_report.get("checks"), dict) else None,
            "materials_ready": material_evidence_summary.get("ready") if isinstance(material_evidence_summary, dict) else None,
            "policy_execution_ready": policy_execution_report.get("ready") if isinstance(policy_execution_report, dict) else None,
            "qbit_enforcement_ready": qbit_enforcement_summary.get("ready") if isinstance(qbit_enforcement_summary, dict) else None,
        },
        "missing_evidence": _string_list(completion_report.get("missing_evidence")),
        "evidence_diagnostics": completion_report.get("evidence_diagnostics") if isinstance(completion_report.get("evidence_diagnostics"), dict) else None,
        "evidence_refs": [
            "seedbox_live_validation_completion_report",
            "closure_summary",
            "closure_handoff",
            "target_upload_handoff",
            "qbit_enforcement_summary",
            "policy_execution_report",
            "material_evidence_summary",
        ],
        "recommended_tool": recommended.get("tool"),
        "recommended_endpoint": recommended.get("endpoint"),
        "recommended_method": recommended.get("method"),
        "recommended_request": recommended.get("request"),
        "recommended_call": recommended_call,
        "dry_run_request": completion_report.get("dry_run_request"),
        "execute_request": completion_report.get("execute_request"),
        "read_order": [
            "live_completion_gate",
            "seedbox_live_validation_completion_report",
            "closure_summary",
            "closure_handoff",
            "qbit_enforcement_summary",
            "policy_execution_report",
            "summary",
        ],
        "complete_when": [
            "live_completion_gate.ready_for_user_report=true",
            "live_completion_gate.missing_evidence=[]",
            "live_completion_gate.blockers=[]",
            "seedbox_live_validation_completion_report.ready_for_user_report=true",
        ],
        "stop_when": _string_list(completion_report.get("stop_when")),
        "blockers": blockers,
        "next_actions": _live_completion_gate_next_actions(action, recommended, completion_report, blockers),
    }


def _job_live_user_report(job: dict[str, Any], summary_payload: dict[str, Any] | None = None) -> dict[str, Any]:
    gate = _job_live_completion_gate(job, summary_payload)
    validation = _job_seedbox_live_validation_completion_report(job, summary_payload)
    closure = _job_closure_summary(job, summary_payload)
    qbit = _job_qbit_enforcement_summary(job, summary_payload)
    target_upload_handoff = _job_target_upload_handoff(job, summary_payload)
    uploaded_seeding_evidence = target_upload_handoff.get("uploaded_seeding_evidence") if isinstance(target_upload_handoff, dict) and isinstance(target_upload_handoff.get("uploaded_seeding_evidence"), dict) else {}
    duplicate_check = validation.get("duplicate_check") if isinstance(validation.get("duplicate_check"), dict) else {}
    source = validation.get("source") if isinstance(validation.get("source"), dict) else {}
    target = validation.get("target") if isinstance(validation.get("target"), dict) else {}
    evidence = validation.get("evidence") if isinstance(validation.get("evidence"), dict) else {}
    blockers = list(dict.fromkeys(_string_list(gate.get("blockers")) + _string_list(validation.get("blockers")) + _string_list(closure.get("blockers"))))
    missing_evidence = list(dict.fromkeys(_string_list(gate.get("missing_evidence")) + _string_list(validation.get("missing_evidence"))))
    ready = gate.get("ready_for_user_report") is True and validation.get("ready_for_user_report") is True and closure.get("complete") is True and not blockers and not missing_evidence
    next_step = gate.get("recommended_call") if isinstance(gate.get("recommended_call"), dict) else validation.get("recommended_call") if isinstance(validation.get("recommended_call"), dict) else {}
    return {
        "kind": "ptcli.live_user_report",
        "ready": ready,
        "ready_for_user_report": ready,
        "verdict": "complete" if ready else str(gate.get("action") or validation.get("status") or "blocked"),
        "job_id": job.get("job_id"),
        "job_status": job.get("status"),
        "summary_file": gate.get("summary_file") or validation.get("summary_file") or job.get("summary_file") or _job_summary_file(job),
        "report_allowed": ready,
        "report_blocked_reason": None if ready else _live_user_report_blocked_reason(gate, validation, closure, blockers, missing_evidence),
        "source": {
            "torrent_hash": source.get("torrent_hash"),
            "content_path": source.get("content_path"),
            "wait_complete": source.get("wait_complete"),
        },
        "target": {
            "uploaded_torrent_hash": target.get("uploaded_torrent_hash"),
            "injected_torrent_hash": target.get("injected_torrent_hash"),
            "uploaded_seeding_ready": target.get("uploaded_seeding_ready"),
            "uploaded_wait_evidence": target.get("uploaded_wait_evidence"),
        },
        "duplicate_check": {
            "searched": duplicate_check.get("searched"),
            "exists": duplicate_check.get("exists"),
            "clear": duplicate_check.get("clear"),
            "count": duplicate_check.get("count"),
        },
        "qbit": {
            "ready": qbit.get("ready") if isinstance(qbit, dict) else None,
            "applied_roles": qbit.get("applied_roles") if isinstance(qbit, dict) else None,
            "pending_roles": qbit.get("pending_roles") if isinstance(qbit, dict) else None,
            "mismatch_roles": qbit.get("mismatch_roles") if isinstance(qbit, dict) else None,
            "uploaded_seeding_evidence": uploaded_seeding_evidence or None,
        },
        "evidence": {
            "source_torrent_path": evidence.get("source_torrent_path"),
            "target_torrent_file": evidence.get("target_torrent_file"),
            "uploaded_torrent_path": evidence.get("uploaded_torrent_path"),
            "required_fields": _live_user_report_required_fields(),
            "missing_evidence": missing_evidence,
            "diagnostics": validation.get("evidence_diagnostics") if isinstance(validation.get("evidence_diagnostics"), dict) else None,
        },
        "report_outline": _live_user_report_outline(ready),
        "read_order": ["live_user_report", "live_completion_gate", "seedbox_live_validation_completion_report", "closure_summary", "qbit_enforcement_summary"],
        "complete_when": [
            "live_user_report.ready_for_user_report=true",
            "live_user_report.evidence.missing_evidence=[]",
            "live_user_report.blockers=[]",
        ],
        "stop_when": [
            "live_user_report.report_allowed=false",
            "seedbox_live_validation_completion_report.status=duplicate_stopped",
            "live_completion_gate.action=stop_duplicate",
        ],
        "recommended_tool": next_step.get("tool"),
        "recommended_endpoint": next_step.get("endpoint"),
        "recommended_method": next_step.get("method"),
        "recommended_request": next_step.get("request"),
        "recommended_call": next_step,
        "blockers": blockers,
        "next_actions": _live_user_report_next_actions(ready, gate, validation, blockers, missing_evidence),
    }


def _live_user_report_required_fields() -> list[str]:
    return [
        "source.torrent_hash",
        "source.content_path",
        "target.uploaded_torrent_hash",
        "target.injected_torrent_hash",
        "target.uploaded_seeding_ready",
        "duplicate_check.clear",
        "evidence.uploaded_torrent_path",
        "qbit.ready",
    ]


def _live_user_report_outline(ready: bool) -> list[str]:
    fields = [
        "state whether the target duplicate check was clear",
        "include source torrent hash and content path",
        "include uploaded target torrent hash and injected qBittorrent hash",
        "include uploaded torrent file path and qBittorrent seeding/rate-limit evidence",
        "state that accept_rules and confirm_upload were required before live upload",
    ]
    if not ready:
        fields.append("do not claim completion; report blockers and the recommended next tool instead")
    return fields


def _live_user_report_blocked_reason(gate: dict[str, Any], validation: dict[str, Any], closure: dict[str, Any], blockers: list[str], missing_evidence: list[str]) -> str:
    if validation.get("status") == "duplicate_stopped" or gate.get("action") == "stop_duplicate":
        return "target_duplicate_exists"
    if blockers:
        return "blockers_present"
    if missing_evidence:
        return "missing_evidence"
    if closure.get("complete") is not True:
        return "closure_incomplete"
    return "not_ready"


def _live_user_report_next_actions(ready: bool, gate: dict[str, Any], validation: dict[str, Any], blockers: list[str], missing_evidence: list[str]) -> list[str]:
    if ready:
        return ["Report live_user_report.source, target, duplicate_check, qbit, and evidence to the user."]
    if validation.get("status") == "duplicate_stopped" or gate.get("action") == "stop_duplicate":
        return ["Report duplicate evidence and do not upload this target."]
    if gate.get("recommended_tool"):
        return ["Follow live_user_report.recommended_call, then reread live_user_report before reporting completion."]
    if missing_evidence:
        return [f"Collect missing final report evidence: {', '.join(missing_evidence)}."]
    if blockers:
        return ["Resolve live_user_report.blockers before reporting completion."]
    return ["Read live_completion_gate and seedbox_live_validation_completion_report before deciding the next action."]


def _job_live_validation_final_report(job: dict[str, Any], summary_payload: dict[str, Any] | None = None) -> dict[str, Any]:
    live_user_report = _job_live_user_report(job, summary_payload)
    completion_report = _job_seedbox_live_validation_completion_report(job, summary_payload)
    gate = _job_live_completion_gate(job, summary_payload)
    closure = _job_closure_summary(job, summary_payload)
    followup = _job_live_validation_followup(job, summary_payload)
    missing_evidence = _string_list((live_user_report.get("evidence") or {}).get("missing_evidence")) if isinstance(live_user_report.get("evidence"), dict) else []
    blockers = list(
        dict.fromkeys(
            _string_list(live_user_report.get("blockers"))
            + _string_list(completion_report.get("blockers"))
            + _string_list(gate.get("blockers"))
            + _string_list(closure.get("blockers"))
        )
    )
    report_allowed = (
        live_user_report.get("report_allowed") is True
        and completion_report.get("ready_for_user_report") is True
        and closure.get("complete") is True
        and not missing_evidence
        and not blockers
    )
    next_call = live_user_report.get("recommended_call") if isinstance(live_user_report.get("recommended_call"), dict) else {}
    if not next_call and isinstance(followup, dict):
        next_call = {
            "tool": followup.get("recommended_tool"),
            "endpoint": followup.get("recommended_endpoint"),
            "method": followup.get("recommended_method"),
            "request": followup.get("recommended_request"),
            "action": followup.get("action"),
        }
    return {
        "kind": "ptcli.live_validation_final_report",
        "ready": report_allowed,
        "report_allowed": report_allowed,
        "verdict": "complete" if report_allowed else str(live_user_report.get("verdict") or completion_report.get("status") or "blocked"),
        "job_id": job.get("job_id"),
        "job_status": job.get("status"),
        "summary_file": live_user_report.get("summary_file") or completion_report.get("summary_file") or _job_summary_file(job),
        "source": live_user_report.get("source") if isinstance(live_user_report.get("source"), dict) else {},
        "target": live_user_report.get("target") if isinstance(live_user_report.get("target"), dict) else {},
        "duplicate_check": live_user_report.get("duplicate_check") if isinstance(live_user_report.get("duplicate_check"), dict) else {},
        "qbit": live_user_report.get("qbit") if isinstance(live_user_report.get("qbit"), dict) else {},
        "evidence": live_user_report.get("evidence") if isinstance(live_user_report.get("evidence"), dict) else {},
        "report_outline": live_user_report.get("report_outline") if isinstance(live_user_report.get("report_outline"), list) else _live_user_report_outline(report_allowed),
        "audit": {
            "final_report_field": "live_validation_final_report",
            "source_report_field": "live_user_report",
            "audit_report_fields": ["seedbox_live_validation_completion_report", "live_completion_gate", "closure_summary", "qbit_enforcement_summary", "qbit_rate_limit_repair_plan", "policy_execution_report"],
            "completion_report_status": completion_report.get("status"),
            "closure_complete": closure.get("complete") is True,
            "live_user_report_allowed": live_user_report.get("report_allowed") is True,
            "missing_evidence": missing_evidence,
        },
        "read_order": ["live_validation_final_report", "live_user_report", "seedbox_live_validation_completion_report", "live_completion_gate", "closure_summary", "qbit_enforcement_summary"],
        "complete_when": [
            "live_validation_final_report.report_allowed=true",
            "live_validation_final_report.evidence.missing_evidence=[]",
            "live_validation_final_report.blockers=[]",
        ],
        "stop_when": [
            "live_validation_final_report.report_allowed=false",
            "seedbox_live_validation_completion_report.status=duplicate_stopped",
            "live_completion_gate.action=stop_duplicate",
        ],
        "recommended_tool": next_call.get("tool"),
        "recommended_endpoint": next_call.get("endpoint"),
        "recommended_method": next_call.get("method"),
        "recommended_request": next_call.get("request"),
        "recommended_call": next_call,
        "blockers": blockers,
        "next_actions": _live_validation_final_report_next_actions(report_allowed, next_call, blockers, missing_evidence),
    }


def _live_validation_final_report_next_actions(report_allowed: bool, next_call: dict[str, Any], blockers: list[str], missing_evidence: list[str]) -> list[str]:
    if report_allowed:
        return ["Report live_validation_final_report.source, target, duplicate_check, qbit, and evidence to the user."]
    if next_call.get("tool"):
        return ["Follow live_validation_final_report.recommended_call, then reread live_validation_final_report before reporting completion."]
    if missing_evidence:
        return [f"Collect missing final report evidence: {', '.join(missing_evidence)}."]
    if blockers:
        return ["Resolve live_validation_final_report.blockers before reporting completion."]
    return ["Read live_validation_final_report.read_order before choosing the next action."]


def _job_live_validation_completion_audit(job: dict[str, Any], summary_payload: dict[str, Any] | None = None) -> dict[str, Any]:
    live_user_report = _job_live_user_report(job, summary_payload)
    final_report = _job_live_validation_final_report(job, summary_payload)
    completion_report = _job_seedbox_live_validation_completion_report(job, summary_payload)
    closure_summary = _job_closure_summary(job, summary_payload)
    qbit = _job_qbit_enforcement_summary(job, summary_payload)
    policy = _job_policy_execution_report(job, summary_payload)
    materials = _job_material_evidence_summary(job, summary_payload)
    live_missing = _string_list((live_user_report.get("evidence") or {}).get("missing_evidence")) if isinstance(live_user_report.get("evidence"), dict) else []
    completion_missing = _string_list(completion_report.get("missing_evidence"))
    blockers = list(
        dict.fromkeys(
            _string_list(live_user_report.get("blockers"))
            + _string_list(final_report.get("blockers"))
            + _string_list(completion_report.get("blockers"))
            + _string_list(closure_summary.get("blockers"))
        )
    )
    checks = {
        "live_user_report_allowed": live_user_report.get("report_allowed") is True,
        "live_user_ready_for_user_report": live_user_report.get("ready_for_user_report") is True,
        "final_report_allowed": final_report.get("report_allowed") is True,
        "completion_report_ready": completion_report.get("ready_for_user_report") is True,
        "closure_complete": closure_summary.get("complete") is True,
        "qbit_enforcement_ready": qbit.get("ready") is True if isinstance(qbit, dict) else None,
        "policy_execution_ready": policy.get("ready") is not False if isinstance(policy, dict) else None,
        "materials_ready": materials.get("ready") is True if isinstance(materials, dict) else None,
        "missing_evidence_clear": not live_missing and not completion_missing,
        "blockers_clear": not blockers,
    }
    failed_checks = [key for key, value in checks.items() if value is False]
    report_allowed = not failed_checks and not blockers
    next_call = final_report.get("recommended_call") if isinstance(final_report.get("recommended_call"), dict) else live_user_report.get("recommended_call") if isinstance(live_user_report.get("recommended_call"), dict) else completion_report.get("recommended_call") if isinstance(completion_report.get("recommended_call"), dict) else {}
    return {
        "kind": "ptcli.live_validation_completion_audit",
        "ready": report_allowed,
        "report_allowed": report_allowed,
        "verdict": "report_complete" if report_allowed else str(final_report.get("verdict") or live_user_report.get("verdict") or completion_report.get("status") or "blocked"),
        "job_id": job.get("job_id"),
        "job_status": job.get("status"),
        "summary_file": live_user_report.get("summary_file") or final_report.get("summary_file") or completion_report.get("summary_file") or _job_summary_file(job),
        "checks": checks,
        "failed_checks": failed_checks,
        "missing_evidence": list(dict.fromkeys(live_missing + completion_missing)),
        "source": live_user_report.get("source") if isinstance(live_user_report.get("source"), dict) else {},
        "target": live_user_report.get("target") if isinstance(live_user_report.get("target"), dict) else {},
        "duplicate_check": live_user_report.get("duplicate_check") if isinstance(live_user_report.get("duplicate_check"), dict) else {},
        "qbit": live_user_report.get("qbit") if isinstance(live_user_report.get("qbit"), dict) else {},
        "report_refs": {
            "live_user_report": "live_user_report",
            "live_validation_final_report": "live_validation_final_report",
            "seedbox_live_validation_completion_report": "seedbox_live_validation_completion_report",
            "closure_summary": "closure_summary",
            "qbit_enforcement_summary": "qbit_enforcement_summary",
            "policy_execution_report": "policy_execution_report",
            "material_evidence_summary": "material_evidence_summary",
        },
        "recommended_call": next_call,
        "recommended_tool": next_call.get("tool"),
        "recommended_endpoint": next_call.get("endpoint"),
        "recommended_method": next_call.get("method"),
        "recommended_request": next_call.get("request"),
        "read_order": ["live_validation_completion_audit", "live_validation_final_report", "live_user_report", "seedbox_live_validation_completion_report", "closure_summary", "qbit_enforcement_summary", "policy_execution_report", "material_evidence_summary"],
        "complete_when": ["live_validation_completion_audit.report_allowed=true", "live_validation_completion_audit.failed_checks=[]", "live_validation_completion_audit.missing_evidence=[]", "live_validation_completion_audit.blockers=[]"],
        "stop_when": ["live_validation_completion_audit.report_allowed=false", "seedbox_live_validation_completion_report.status=duplicate_stopped", "closure_summary.action=stop_duplicate"],
        "safety": {
            "read_only": True,
            "does_not_submit": True,
            "does_not_upload": True,
            "requires_final_evidence_before_user_report": True,
        },
        "blockers": blockers,
        "next_actions": _live_validation_completion_audit_next_actions(report_allowed, next_call, failed_checks, blockers, list(dict.fromkeys(live_missing + completion_missing))),
    }


def _live_validation_completion_audit_next_actions(report_allowed: bool, next_call: dict[str, Any], failed_checks: list[str], blockers: list[str], missing_evidence: list[str]) -> list[str]:
    if report_allowed:
        return ["Report live_validation_completion_audit.source, target, duplicate_check, qbit, and summary_file to the user."]
    if next_call.get("tool"):
        return ["Follow live_validation_completion_audit.recommended_call, then reread live_validation_completion_audit before reporting completion."]
    if missing_evidence:
        return [f"Collect missing live validation evidence: {', '.join(missing_evidence)}."]
    if failed_checks:
        return [f"Resolve failed live validation checks: {', '.join(failed_checks)}."]
    if blockers:
        return ["Resolve live_validation_completion_audit.blockers before reporting completion."]
    return ["Read live_validation_completion_audit.read_order before choosing the next action."]


def _live_completion_gate_action(job: dict[str, Any], status: str, ready_for_user_report: bool, blockers: list[str], completion_report: dict[str, Any]) -> str:
    if ready_for_user_report:
        return "report_complete"
    if status == "duplicate_stopped":
        return "stop_duplicate"
    if str(job.get("status") or "") in {"queued", "running"} or status == "running":
        return "poll_job"
    if completion_report.get("recommended_tool") == "resume_job":
        return "resume_job"
    if blockers:
        return "resolve_blockers"
    if status in {"failed", "cancelled"}:
        return "stop"
    return "inspect_summary"


def _live_completion_gate_next_actions(action: str, recommended: dict[str, Any], completion_report: dict[str, Any], blockers: list[str]) -> list[str]:
    if action == "report_complete":
        return ["Report live_completion_gate plus seedbox_live_validation_completion_report evidence to the user."]
    if action == "poll_job":
        return ["Poll live_completion_gate.job_id until the job is terminal, then read live_completion_gate again."]
    if action == "resume_job" and recommended.get("tool"):
        return [f"Call {recommended['tool']} from live_completion_gate.recommended_request, then read live_completion_gate again."]
    if action == "stop_duplicate":
        return ["Stop this target and report live_completion_gate.duplicate_check."]
    if blockers:
        return ["Resolve live_completion_gate.blockers before reporting the live retorrent complete."]
    missing = _string_list(completion_report.get("missing_evidence"))
    if missing:
        return [f"Collect missing live completion evidence: {', '.join(missing)}."]
    return ["Inspect live_completion_gate.read_order before taking the next job action."]


def _job_live_action_sequence(job: dict[str, Any], summary_payload: dict[str, Any] | None = None) -> dict[str, Any]:
    gate = _job_live_completion_gate(job, summary_payload)
    recovery = _job_recovery_handoff(job, summary_payload)
    action = str(gate.get("action") or "inspect_summary")
    blockers = _string_list(gate.get("blockers")) or _string_list(recovery.get("blockers"))
    steps = _job_live_action_sequence_steps(action, gate, recovery)
    return {
        "kind": "ptcli.job_live_action_sequence",
        "ready": action in {"report_complete", "poll_job", "resume_job", "stop_duplicate"} and not (blockers and action != "stop_duplicate"),
        "status": gate.get("status"),
        "action": action,
        "job_id": gate.get("job_id") or job.get("job_id"),
        "summary_file": gate.get("summary_file") or job.get("summary_file") or _job_summary_file(job),
        "steps": steps,
        "next_step": steps[0] if steps else None,
        "final_report_field": "live_completion_gate",
        "audit_report_field": "seedbox_live_validation_completion_report",
        "complete_when": _string_list(gate.get("complete_when")),
        "stop_when": _string_list(gate.get("stop_when")),
        "blockers": blockers,
        "next_actions": _job_live_action_sequence_next_actions(action, steps, blockers),
    }


def _job_live_action_sequence_steps(action: str, gate: dict[str, Any], recovery: dict[str, Any]) -> list[dict[str, Any]]:
    job_id = gate.get("job_id")
    if action == "report_complete":
        return [
            _job_live_action_sequence_step(1, "read_final_summary", "get_job_summary", gate.get("summary_file"), "GET", None, ["live_completion_gate", "seedbox_live_validation_completion_report", "closure_summary"], "live_completion_gate.ready_for_user_report=true", None, "read"),
        ]
    if action == "poll_job":
        return [
            _job_live_action_sequence_step(1, "poll_job", "get_job_status", f"/v1/jobs/{job_id}" if job_id else None, "GET", {"job_id": job_id}, ["status", "live_completion_gate", "job_control_summary"], "live_completion_gate.action!=poll_job", "status=failed or status=cancelled", "poll", repeat_when="status in queued,running"),
        ]
    if action == "resume_job":
        dry_run_request = gate.get("dry_run_request") if isinstance(gate.get("dry_run_request"), dict) else recovery.get("dry_run_request")
        execute_request = gate.get("execute_request") if isinstance(gate.get("execute_request"), dict) else recovery.get("execute_request")
        endpoint = gate.get("recommended_endpoint") or recovery.get("recommended_endpoint") or (f"/v1/jobs/{job_id}/resume" if job_id else None)
        return [
            _job_live_action_sequence_step(1, "resume_preview", "resume_job", endpoint, "POST", dry_run_request, ["command_argv", "ignored_overrides", "material_resolution", "live_completion_gate"], "dry_run returns ok=true and command_argv is reviewed", "dry_run_request is missing or blockers remain", "call_tool"),
            _job_live_action_sequence_step(2, "resume_execute", "resume_job", endpoint, "POST", execute_request, ["job_id", "status_endpoint", "summary_endpoint"], "child job_id is returned", "execute_request is missing or user has not approved live execution", "call_tool"),
            _job_live_action_sequence_step(3, "poll_after_resume", "get_job_status", "/v1/jobs/{child_job_id}", "GET", {"job_id": "<child job_id from resume_execute>"}, ["status", "live_completion_gate", "job_control_summary"], "child status is terminal", "status=failed or status=cancelled", "poll", repeat_when="status in queued,running"),
            _job_live_action_sequence_step(4, "read_gate_after_resume", "get_job_summary", "/v1/jobs/{child_job_id}/summary", "GET", {"job_id": "<child job_id from resume_execute>"}, ["live_completion_gate", "seedbox_live_validation_completion_report", "closure_summary"], "live_completion_gate.ready_for_user_report=true or live_completion_gate.action changes", "live_completion_gate.action=stop_duplicate", "read"),
        ]
    if action == "stop_duplicate":
        return [
            _job_live_action_sequence_step(1, "report_duplicate", "get_job_summary", gate.get("summary_file"), "GET", None, ["live_completion_gate.duplicate_check", "closure_summary.duplicate_check"], "duplicate details are reported; do not upload", None, "read"),
        ]
    if action == "resolve_blockers":
        return [
            _job_live_action_sequence_step(1, "inspect_blockers", "get_job_summary", gate.get("summary_file"), "GET", None, ["live_completion_gate.blockers", "recovery_handoff", "job_control_summary"], "blockers are resolved and live_action_sequence is regenerated", "blockers remain", "read"),
        ]
    return [
        _job_live_action_sequence_step(1, "inspect_summary", "get_job_summary", gate.get("summary_file"), "GET", None, ["live_completion_gate", "job_control_summary", "recovery_handoff"], "next action is known", None, "read"),
    ]


def _job_live_action_sequence_step(
    index: int,
    name: str,
    tool: Any,
    endpoint: Any,
    method: Any,
    request: Any,
    read: list[str],
    continue_when: Any,
    stop_when: Any,
    action: str,
    *,
    repeat_when: Any = None,
) -> dict[str, Any]:
    return {
        "index": index,
        "name": name,
        "action": action,
        "tool": tool,
        "endpoint": endpoint,
        "method": method,
        "request": request,
        "read": read,
        "continue_when": continue_when,
        "repeat_when": repeat_when,
        "stop_when": stop_when,
    }


def _job_live_action_sequence_next_actions(action: str, steps: list[dict[str, Any]], blockers: list[str]) -> list[str]:
    if blockers and action not in {"stop_duplicate"}:
        return ["Resolve live_action_sequence.blockers, then read live_action_sequence again before live tracker action."]
    if steps:
        return [f"Execute live_action_sequence.steps[0].name={steps[0].get('name')} and reread live_completion_gate after the state changes."]
    return ["Inspect live_completion_gate and job_control_summary before choosing the next job call."]


def _seedbox_live_validation_completion_status(
    job_status: str,
    ready_for_user_report: bool,
    duplicate_exists: bool,
    blockers: list[str],
    missing_evidence: list[str],
    recovery_handoff: dict[str, Any],
    job_handoff: dict[str, Any],
) -> str:
    if ready_for_user_report:
        return "complete"
    if duplicate_exists:
        return "duplicate_stopped"
    if job_status in {"queued", "running"}:
        return "running"
    if job_status in {"failed", "cancelled"}:
        return job_status
    if recovery_handoff.get("should_resume") is True or job_handoff.get("action") == "resume":
        return "needs_resume"
    if blockers or missing_evidence:
        return "blocked"
    return "unknown"


def _seedbox_live_validation_completion_recommended_step(
    status: str,
    job_id: Any,
    recovery_handoff: dict[str, Any],
    job_handoff: dict[str, Any],
    closure_summary: dict[str, Any],
) -> dict[str, Any]:
    if status == "complete":
        return {"tool": "get_job_summary", "endpoint": f"/v1/jobs/{job_id}/summary" if job_id else None, "method": "GET", "request": None, "reason": "live_validation_complete"}
    if status == "running":
        return {"tool": "get_job_status", "endpoint": f"/v1/jobs/{job_id}" if job_id else None, "method": "GET", "request": None, "reason": "job_still_running"}
    if status == "duplicate_stopped":
        return {"tool": None, "endpoint": None, "method": None, "request": None, "reason": "target_duplicate_exists"}
    for handoff in (recovery_handoff, job_handoff, closure_summary):
        if isinstance(handoff, dict) and handoff.get("recommended_tool"):
            return {
                "tool": handoff.get("recommended_tool"),
                "endpoint": handoff.get("recommended_endpoint"),
                "method": handoff.get("recommended_method") or "POST",
                "request": handoff.get("recommended_request"),
                "reason": f"continue_from_{handoff.get('kind') or handoff.get('action') or 'handoff'}",
            }
    return {"tool": None, "endpoint": None, "method": None, "request": None, "reason": "manual_review_required"}


def _seedbox_live_validation_completion_request(key: str, recovery_handoff: dict[str, Any], job_handoff: dict[str, Any]) -> dict[str, Any] | None:
    for handoff in (recovery_handoff, job_handoff):
        value = handoff.get(key) if isinstance(handoff, dict) else None
        if isinstance(value, dict) and value:
            return value
    return None


def _seedbox_live_validation_completion_call_action(status: str, next_step: dict[str, Any]) -> str:
    if status == "running":
        return "wait"
    if status == "complete":
        return "done"
    if status in {"duplicate_stopped", "failed", "cancelled"}:
        return "stop"
    if next_step.get("tool") == "resume_job":
        return "resume"
    return status


def _seedbox_live_validation_completion_next_actions(status: str, next_step: dict[str, Any], missing_evidence: list[str], blockers: list[str]) -> list[str]:
    if status == "complete":
        return ["Report seedbox_live_validation_completion_report evidence to the user."]
    if next_step.get("tool"):
        return [f"Call {next_step['tool']} from seedbox_live_validation_completion_report.next_step, then read the completion report again."]
    if status == "duplicate_stopped":
        return ["Stop live validation for this target and report duplicate_check.dupes."]
    if missing_evidence:
        return [f"Collect or repair missing live validation evidence: {', '.join(missing_evidence)}."]
    if blockers:
        return ["Resolve seedbox_live_validation_completion_report.blockers before reporting the live validation as complete."]
    return ["Inspect closure_summary and recovery_handoff before taking the next action."]


def _closure_checklist(
    source_ready: Any,
    target_ready: Any,
    complete: bool,
    duplicate_check: dict[str, Any],
    manual_retorrent_handoff: dict[str, Any] | None,
    target_upload_handoff: dict[str, Any] | None,
    qbit_handoff: dict[str, Any] | None,
) -> dict[str, Any]:
    manual_checklist = manual_retorrent_handoff.get("live_checklist") if isinstance(manual_retorrent_handoff, dict) and isinstance(manual_retorrent_handoff.get("live_checklist"), dict) else None
    items = [
        _checklist_item("source_download_or_match", source_ready is True, required=True, blocker="source.not_ready"),
        _checklist_item("target_uploaded_and_seeding", target_ready is True, required=True, blocker="target.uploaded_seeding_not_ready"),
        _checklist_item("target_duplicate_clear", duplicate_check.get("searched") is True and duplicate_check.get("exists") is False, required=True, blocker="duplicate_check.not_clear"),
        _checklist_item("manual_live_gates", manual_checklist.get("ready") is True if isinstance(manual_checklist, dict) else None, required=True, blocker="manual_retorrent_handoff.live_checklist_not_ready"),
        _checklist_item("target_upload_handoff", target_upload_handoff.get("uploaded_seeding_ready") is True if isinstance(target_upload_handoff, dict) else None, required=True, blocker="target_upload_handoff.not_ready"),
        _checklist_item("qbit_handoff", qbit_handoff.get("ready") is True if isinstance(qbit_handoff, dict) else None, required=False, blocker="qbit_handoff.not_ready"),
    ]
    blockers = _checklist_blockers(items)
    return {
        "kind": "ptcli.closure_checklist",
        "ready": complete and not blockers,
        "items": items,
        "blockers": blockers,
        "next_actions": [] if complete and not blockers else ["Follow closure_handoff.next_step after reviewing closure_checklist.blockers."],
    }


def _closure_handoff_nested_blockers(*handoffs: dict[str, Any] | None) -> list[str]:
    blockers: list[str] = []
    for handoff in handoffs:
        if isinstance(handoff, dict):
            blockers.extend(_string_list(handoff.get("blockers")))
    return blockers


def _closure_handoff_complete(status: str, result: dict[str, Any], closure: dict[str, Any], target_upload_handoff: dict[str, Any] | None) -> bool:
    if closure.get("complete") is True:
        return True
    if result.get("status") == "complete" or result.get("ok") is True:
        if isinstance(target_upload_handoff, dict):
            return bool(target_upload_handoff.get("uploaded_seeding_ready") or target_upload_handoff.get("ready"))
        return status == "complete"
    return status == "complete" and (not isinstance(target_upload_handoff, dict) or bool(target_upload_handoff.get("uploaded_seeding_ready") or target_upload_handoff.get("ready")))


def _closure_handoff_action(
    status: str,
    complete: bool,
    duplicate_check: dict[str, Any],
    target_upload_handoff: dict[str, Any] | None,
    manual_retorrent_handoff: dict[str, Any] | None,
    qbit_handoff: dict[str, Any] | None,
    blockers: list[str],
) -> str:
    if complete:
        return "done"
    if status in {"queued", "running"}:
        return "wait"
    if duplicate_check.get("exists") is True:
        return "stop_duplicate"
    if isinstance(target_upload_handoff, dict) and target_upload_handoff.get("action") not in {None, "inspect", "done"}:
        return str(target_upload_handoff.get("action"))
    if isinstance(manual_retorrent_handoff, dict) and manual_retorrent_handoff.get("action") not in {None, "inspect", "done"}:
        return str(manual_retorrent_handoff.get("action"))
    if isinstance(qbit_handoff, dict) and qbit_handoff.get("ready") is False:
        return "repair_qbit"
    if blockers:
        return "resolve_blockers"
    return "inspect"


def _closure_handoff_next_step(
    job: dict[str, Any],
    action: str,
    target_upload_handoff: dict[str, Any] | None,
    manual_retorrent_handoff: dict[str, Any] | None,
) -> dict[str, Any]:
    job_id = job.get("job_id")
    if action == "done":
        return {"tool": "get_job_summary", "endpoint": f"/v1/jobs/{job_id}/summary" if job_id else None, "method": "GET", "request": None, "reason": "retorrent_closure_complete"}
    if action == "wait":
        return {"tool": "get_job_status", "endpoint": f"/v1/jobs/{job_id}" if job_id else None, "method": "GET", "request": None, "reason": "job_still_running"}
    if action == "stop_duplicate":
        return {"tool": None, "endpoint": None, "method": None, "request": None, "reason": "target_duplicate_exists"}
    if isinstance(target_upload_handoff, dict) and isinstance(target_upload_handoff.get("next_step"), dict) and action == target_upload_handoff.get("action"):
        return target_upload_handoff["next_step"]
    if isinstance(manual_retorrent_handoff, dict) and action == manual_retorrent_handoff.get("action") and manual_retorrent_handoff.get("resume_endpoint"):
        return {
            "tool": "resume_job",
            "endpoint": manual_retorrent_handoff.get("resume_endpoint"),
            "method": "POST",
            "request": {},
            "reason": manual_retorrent_handoff.get("reason") or "manual_retorrent_resume_recommended",
        }
    if action == "repair_qbit":
        return {"tool": "resume_job", "endpoint": f"/v1/jobs/{job_id}/resume" if job_id else None, "method": "POST", "request": {}, "reason": "qbit_evidence_or_limits_not_ready"}
    return {"tool": "get_job_summary", "endpoint": f"/v1/jobs/{job_id}/summary" if job_id else None, "method": "GET", "request": None, "reason": "inspect_closure_state"}


def _closure_handoff_next_actions(action: str, blockers: list[str], next_step: dict[str, Any]) -> list[str]:
    if action == "done":
        return []
    if action == "stop_duplicate":
        return ["Do not upload. Inspect closure_handoff.duplicate_check.dupes or choose another target tracker."]
    if next_step.get("tool"):
        return [f"Call {next_step['tool']} via closure_handoff.next_step after reviewing blockers and site rules."]
    if blockers:
        return ["Resolve closure_handoff.blockers before attempting live retorrent closure."]
    return ["Inspect closure_handoff.source, closure_handoff.target, and closure_handoff.evidence before taking live action."]


def _first_bool(*values: Any) -> bool | None:
    for value in values:
        if isinstance(value, bool):
            return value
    return None


def _qbit_limit_source_result(payloads: list[dict[str, Any]]) -> dict[str, Any] | None:
    for payload in payloads:
        stage = _stage_from_payload(payload, "inject-source")
        result = stage.get("result") if isinstance(stage, dict) else None
        if isinstance(result, dict):
            return result
    return None


def _qbit_limit_uploaded_result(payloads: list[dict[str, Any]]) -> dict[str, Any] | None:
    for payload in payloads:
        stage = _stage_from_payload(payload, "target-upload")
        result = stage.get("result") if isinstance(stage, dict) else None
        if isinstance(result, dict) and isinstance(result.get("injected_torrent"), dict):
            return result["injected_torrent"]
        direct = _nested_value(payload, "injected_torrent")
        if isinstance(direct, dict):
            return direct
    return None


def _stage_from_payload(payload: dict[str, Any], name: str) -> dict[str, Any] | None:
    stages = payload.get("stages")
    if not isinstance(stages, list):
        pipeline = payload.get("pipeline")
        stages = pipeline.get("stages") if isinstance(pipeline, dict) else None
    if not isinstance(stages, list):
        return None
    for stage in stages:
        if isinstance(stage, dict) and stage.get("stage") == name:
            return stage
    return None


def _qbit_limit_role_audit(role: str, plan: Any, result: dict[str, Any] | None) -> dict[str, Any]:
    plan = plan if isinstance(plan, dict) else {}
    expected = {
        key: value
        for key, value in {
            "upload_limit": plan.get("upload_limit"),
            "download_limit": plan.get("download_limit"),
        }.items()
        if value is not None
    }
    if not expected:
        return {
            "role": role,
            "status": "no_limits_requested",
            "ready": True,
            "expected": {},
            "observed": None,
            "evidence_present": isinstance(result, dict),
            "blockers": [],
        }
    if not isinstance(result, dict):
        blockers = [f"{role}.qbit_limit_evidence_missing"]
        return {
            "role": role,
            "status": "pending",
            "ready": False,
            "expected": expected,
            "observed": None,
            "evidence_present": False,
            "blockers": blockers,
        }

    rate_limits = result.get("rate_limits") if isinstance(result.get("rate_limits"), dict) else {}
    requested = rate_limits.get("requested") if isinstance(rate_limits.get("requested"), dict) else {}
    observed = {
        "upload_limit": result.get("upload_limit", requested.get("upload_limit")),
        "download_limit": result.get("download_limit", requested.get("download_limit")),
        "rate_limits": rate_limits or None,
    }
    mismatches = [key for key, value in expected.items() if observed.get(key) != value]
    missing_calls = _qbit_limit_missing_calls(expected, rate_limits)
    blockers = [f"{role}.{key}_mismatch" for key in mismatches] + [f"{role}.{item}" for item in missing_calls]
    applied = bool(rate_limits.get("applied")) and not blockers
    return {
        "role": role,
        "status": "applied" if applied else "mismatch",
        "ready": applied,
        "expected": expected,
        "observed": observed,
        "evidence_present": True,
        "blockers": blockers,
    }


def _qbit_limit_missing_calls(expected: dict[str, Any], rate_limits: dict[str, Any]) -> list[str]:
    calls = rate_limits.get("calls") if isinstance(rate_limits.get("calls"), list) else []
    methods = {str(call.get("method")) for call in calls if isinstance(call, dict)}
    missing: list[str] = []
    if "upload_limit" in expected and "torrents_set_upload_limit" not in methods:
        missing.append("upload_limit_call_missing")
    if "download_limit" in expected and "torrents_set_download_limit" not in methods:
        missing.append("download_limit_call_missing")
    return missing


def _qbit_limit_audit_next_actions(blockers: list[str]) -> list[str]:
    if not blockers:
        return []
    return ["Resume or rerun the qBittorrent injection step so configured per-site rate limits are applied and captured in job evidence."]


def _qbit_plan_value_source(key: str, sources: dict[str, Any], overrides: dict[str, Any]) -> str | None:
    if key in overrides:
        return "request"
    if key in sources:
        return str(sources[key])
    return None


def _job_resume_context(job: dict[str, Any]) -> dict[str, Any] | None:
    request = job.get("request")
    if isinstance(request, dict) and isinstance(request.get("resume_context"), dict):
        return request["resume_context"]
    return None


def _job_material_resolution(job: dict[str, Any]) -> dict[str, Any] | None:
    request = job.get("request")
    if isinstance(request, dict) and isinstance(request.get("material_resolution"), dict):
        return request["material_resolution"]
    resume_context = _job_resume_context(job)
    if isinstance(resume_context, dict) and isinstance(resume_context.get("material_resolution"), dict):
        return resume_context["material_resolution"]
    return None


def _job_resume_lineage(job: dict[str, Any]) -> dict[str, Any] | None:
    request = job.get("request")
    if isinstance(request, dict) and isinstance(request.get("resume_lineage"), dict):
        return request["resume_lineage"]
    return None


def _job_resume_audit(job: dict[str, Any]) -> dict[str, Any]:
    job_id = str(job.get("job_id") or "")
    request = job.get("request") if isinstance(job.get("request"), dict) else {}
    lineage = _job_resume_lineage(job)
    context = _job_resume_context(job)
    material_resolution = _job_material_resolution(job)
    plan = _job_resume_plan(job)
    requirements = _job_resume_requirements(job)
    applied_overrides = _resume_audit_override_list(request, context, "applied_overrides")
    ignored_overrides = _resume_audit_override_list(request, context, "ignored_overrides")
    is_resume_job = bool(lineage or context or str(job.get("kind") or "") == "ptcli.resume")
    parent_job_id = request.get("parent_job_id") or (lineage or {}).get("parent_job_id") or (context or {}).get("parent_job_id")
    dry_run_request = requirements.get("dry_run_request") if isinstance(requirements.get("dry_run_request"), dict) else None
    execute_request = requirements.get("execute_request") if isinstance(requirements.get("execute_request"), dict) else None
    return {
        "kind": "ptcli.resume_audit",
        "job_id": job_id or None,
        "is_resume_job": is_resume_job,
        "parent_job_id": parent_job_id,
        "parent_status": request.get("parent_status") or (lineage or {}).get("parent_status") or (context or {}).get("parent_status"),
        "parent_kind": request.get("parent_kind") or (lineage or {}).get("parent_kind") or (context or {}).get("parent_kind"),
        "child_status": job.get("status"),
        "resume_available": bool(plan.get("available")),
        "resume_allowed": bool(plan.get("allowed")),
        "resume_recommended": bool(plan.get("recommended")),
        "resume_endpoint": plan.get("endpoint"),
        "summary_endpoint": f"/v1/jobs/{job_id}/summary" if job_id else None,
        "next_subcommand": plan.get("subcommand") or (lineage or {}).get("next_subcommand"),
        "next_command_argv": plan.get("next_command_argv") or request.get("next_command_argv"),
        "original_next_command_argv": request.get("original_next_command_argv"),
        "applied_override_keys": [item["key"] for item in applied_overrides],
        "ignored_override_keys": [item["key"] for item in ignored_overrides],
        "applied_overrides": applied_overrides,
        "ignored_overrides": ignored_overrides,
        "material_resolution": material_resolution,
        "covered_recommended_inputs": _string_list((material_resolution or {}).get("covered_recommended_inputs")) if isinstance(material_resolution, dict) else [],
        "unresolved_recommended_inputs": (material_resolution or {}).get("unresolved_recommended_inputs") if isinstance(material_resolution, dict) else [],
        "dry_run_request": dry_run_request,
        "execute_request": execute_request,
        "next_step": _resume_audit_next_step(job, plan, dry_run_request, execute_request),
        "next_actions": _resume_audit_next_actions(job, plan, material_resolution),
    }


def _string_keyed_overrides(value: Any) -> list[dict[str, Any]]:
    if not isinstance(value, list):
        return []
    return [item for item in value if isinstance(item, dict) and item.get("key")]


def _resume_audit_override_list(request: dict[str, Any], context: dict[str, Any] | None, key: str) -> list[dict[str, Any]]:
    if isinstance(request.get(key), list):
        return _string_keyed_overrides(request.get(key))
    if isinstance(context, dict) and isinstance(context.get(key), list):
        return _string_keyed_overrides(context.get(key))
    return []


def _resume_audit_next_step(job: dict[str, Any], plan: dict[str, Any], dry_run_request: dict[str, Any] | None, execute_request: dict[str, Any] | None) -> dict[str, Any]:
    if plan.get("recommended") and plan.get("allowed"):
        return {
            "tool": "resume_job",
            "endpoint": plan.get("endpoint"),
            "method": "POST",
            "request": dry_run_request or execute_request or {"job_id": job.get("job_id")},
            "reason": "resume_recommended",
        }
    if job.get("status") in {"queued", "running"}:
        return {"tool": "get_job_status", "endpoint": f"/v1/jobs/{job.get('job_id')}", "method": "GET", "request": None, "reason": "job_running"}
    return {"tool": "get_job_summary", "endpoint": f"/v1/jobs/{job.get('job_id')}/summary", "method": "GET", "request": None, "reason": "inspect_resume_audit"}


def _resume_audit_next_actions(job: dict[str, Any], plan: dict[str, Any], material_resolution: dict[str, Any] | None) -> list[str]:
    if plan.get("recommended") and plan.get("allowed"):
        return ["Preview resume with resume_audit.dry_run_request, then execute resume_audit.execute_request after reviewing command_argv and blockers."]
    if isinstance(material_resolution, dict) and material_resolution.get("unresolved_recommended_inputs"):
        return ["Provide unresolved material inputs before executing resume."]
    if job.get("status") in {"queued", "running"}:
        return ["Poll status_endpoint before attempting resume."]
    return ["Inspect resume_audit and closure_handoff before taking the next action."]


def _job_resume_summary(job: dict[str, Any]) -> dict[str, Any]:
    plan = _job_resume_plan(job)
    requirements = _job_resume_requirements(job)
    material_resolution = _job_material_resolution(job)
    dry_run_request = requirements.get("dry_run_request") if isinstance(requirements.get("dry_run_request"), dict) else None
    execute_request = requirements.get("execute_request") if isinstance(requirements.get("execute_request"), dict) else None
    recommended_inputs = requirements.get("recommended_inputs") if isinstance(requirements.get("recommended_inputs"), list) else []
    unresolved_inputs = material_resolution.get("unresolved_recommended_inputs") if isinstance(material_resolution, dict) and isinstance(material_resolution.get("unresolved_recommended_inputs"), list) else []
    next_step = _resume_summary_next_step(job, plan, dry_run_request, execute_request, unresolved_inputs)
    blockers = _resume_summary_blockers(job, plan, requirements, unresolved_inputs)
    return {
        "kind": "ptcli.resume_summary",
        "available": bool(plan.get("available")),
        "allowed": bool(plan.get("allowed")),
        "recommended": bool(plan.get("recommended")),
        "status": plan.get("status"),
        "subcommand": plan.get("subcommand"),
        "endpoint": plan.get("endpoint"),
        "method": plan.get("method"),
        "next_command_argv": plan.get("next_command_argv"),
        "blocker": plan.get("blocker"),
        "missing_confirmations": _string_list(requirements.get("missing_confirmations")),
        "required_overrides": _string_list(requirements.get("required_overrides")),
        "suggested_overrides": requirements.get("suggested_overrides") if isinstance(requirements.get("suggested_overrides"), dict) else {},
        "recommended_input_keys": [item.get("key") for item in recommended_inputs if isinstance(item, dict) and item.get("key")],
        "unresolved_recommended_inputs": unresolved_inputs,
        "covered_recommended_inputs": _string_list(material_resolution.get("covered_recommended_inputs")) if isinstance(material_resolution, dict) else [],
        "dry_run_request": dry_run_request,
        "execute_request": execute_request,
        "next_step": next_step,
        "recommended_tool": next_step.get("tool"),
        "recommended_endpoint": next_step.get("endpoint"),
        "recommended_request": next_step.get("request"),
        "blockers": blockers,
        "next_actions": _resume_summary_next_actions(plan, next_step, blockers, unresolved_inputs),
    }


def _job_resume_followup_handoff(job: dict[str, Any], job_lineage: dict[str, Any] | None = None) -> dict[str, Any]:
    job_id = str(job.get("job_id") or "")
    status = str(job.get("status") or "unknown")
    runtime = _job_runtime(job)
    lineage = job_lineage if isinstance(job_lineage, dict) else _job_lineage_summary(job)
    parent_job_id = lineage.get("parent_job_id") or _job_parent_job_id(job)
    is_resume_job = bool(parent_job_id or str(job.get("kind") or "") == "ptcli.resume")
    steps = _job_resume_followup_steps(job_id, runtime, parent_job_id)
    return {
        "kind": "ptcli.resume_followup_handoff",
        "ready": is_resume_job and bool(job_id),
        "is_resume_job": is_resume_job,
        "action": _job_resume_followup_action(status, runtime, is_resume_job),
        "job_id": job_id or None,
        "parent_job_id": parent_job_id,
        "child_status": status,
        "parent_status": lineage.get("parent_status"),
        "status_endpoint": runtime.get("status_endpoint"),
        "summary_endpoint": runtime.get("summary_endpoint"),
        "parent_status_endpoint": f"/v1/jobs/{parent_job_id}" if parent_job_id else None,
        "parent_summary_endpoint": f"/v1/jobs/{parent_job_id}/summary" if parent_job_id else None,
        "primary_next_step": steps[0] if steps else None,
        "steps": steps,
        "read_order": ["resume_followup_handoff", "job_control_summary", "job_final_report", "live_user_report", "closure_summary", "job_lineage"],
        "complete_when": ["child status is terminal", "child summary has job_final_report or live_user_report", "parent job_lineage.latest_child points at this child"],
        "stop_when": ["child status=failed", "child status=cancelled", "child job_final_report.verdict=blocked", "duplicate_check.exists=true"],
        "blockers": [] if is_resume_job else ["Job is not a resume child job."],
        "next_actions": _job_resume_followup_next_actions(is_resume_job, status, job_id, parent_job_id),
    }


def _job_resume_followup_steps(job_id: str, runtime: dict[str, Any], parent_job_id: Any) -> list[dict[str, Any]]:
    status_endpoint = runtime.get("status_endpoint") or f"/v1/jobs/{job_id}"
    summary_endpoint = runtime.get("summary_endpoint") or f"/v1/jobs/{job_id}/summary"
    if runtime.get("should_poll"):
        return [
            {
                "index": 1,
                "name": "poll_child_status",
                "tool": "get_job_status",
                "endpoint": status_endpoint,
                "method": "GET",
                "request": {"job_id": job_id},
                "repeat_when": "status in queued,running",
                "continue_when": "status in blocked,failed,cancelled,complete",
            },
            {
                "index": 2,
                "name": "read_child_summary",
                "tool": "get_job_summary",
                "endpoint": summary_endpoint,
                "method": "GET",
                "request": {"job_id": job_id},
                "continue_when": "job_final_report or live_user_report is readable",
            },
        ]
    steps = [
        {
            "index": 1,
            "name": "read_child_summary",
            "tool": "get_job_summary",
            "endpoint": summary_endpoint,
            "method": "GET",
            "request": {"job_id": job_id},
            "continue_when": "job_final_report or live_user_report is readable",
        }
    ]
    if parent_job_id:
        steps.append(
            {
                "index": 2,
                "name": "refresh_parent_lineage",
                "tool": "get_job_status",
                "endpoint": f"/v1/jobs/{parent_job_id}",
                "method": "GET",
                "request": {"job_id": str(parent_job_id)},
                "continue_when": "job_lineage.latest_child.job_id equals child job_id",
            }
        )
    return steps


def _job_resume_followup_action(status: str, runtime: dict[str, Any], is_resume_job: bool) -> str:
    if not is_resume_job:
        return "not_applicable"
    if runtime.get("should_poll"):
        return "poll_child"
    if status == "complete":
        return "read_child_summary"
    if status == "blocked":
        return "read_child_summary_or_resume_again"
    if status in {"failed", "cancelled"}:
        return "report_child_terminal_failure"
    return "inspect_child"


def _job_resume_followup_next_actions(is_resume_job: bool, status: str, job_id: str, parent_job_id: Any) -> list[str]:
    if not is_resume_job:
        return ["Use job_control_summary for non-resume jobs."]
    if status in {"queued", "running"}:
        return [f"Poll resume child job {job_id}, then read its summary when terminal."]
    if status == "complete":
        actions = [f"Read resume child summary {job_id}, then report job_final_report/live_user_report evidence."]
        if parent_job_id:
            actions.append(f"Refresh parent job {parent_job_id} lineage if needed.")
        return actions
    if status == "blocked":
        return [f"Read resume child summary {job_id}; if job_control_summary recommends another safe resume, preview it before execute."]
    if status in {"failed", "cancelled"}:
        return [f"Read resume child summary {job_id} and report terminal failure before retrying."]
    return [f"Follow resume_followup_handoff.primary_next_step for child job {job_id}."]


def _job_resume_execution_handoff(job: dict[str, Any], payload: dict[str, Any] | None = None) -> dict[str, Any]:
    requirements = _job_resume_requirements(job, payload if isinstance(payload, dict) else None)
    summary = _job_resume_summary(job)
    plan = _job_resume_plan(job)
    dry_run_request = requirements.get("dry_run_request") if isinstance(requirements.get("dry_run_request"), dict) else None
    execute_request = requirements.get("execute_request") if isinstance(requirements.get("execute_request"), dict) else None
    unresolved_inputs = summary.get("unresolved_recommended_inputs") if isinstance(summary.get("unresolved_recommended_inputs"), list) else []
    blockers = _resume_execution_handoff_blockers(plan, requirements, summary, unresolved_inputs)
    ready = bool(plan.get("recommended")) and bool(plan.get("allowed")) and not blockers
    return {
        "kind": "ptcli.resume_execution_handoff",
        "ready": ready,
        "status": plan.get("status"),
        "subcommand": plan.get("subcommand"),
        "endpoint": plan.get("endpoint"),
        "method": "POST",
        "preview_required": True,
        "dry_run_request": dry_run_request,
        "execute_request": execute_request,
        "recommended_request": dry_run_request or execute_request,
        "allowed_overrides": requirements.get("allowed_overrides") if isinstance(requirements.get("allowed_overrides"), dict) else {},
        "required_overrides": _string_list(requirements.get("required_overrides")),
        "suggested_overrides": requirements.get("suggested_overrides") if isinstance(requirements.get("suggested_overrides"), dict) else {},
        "recommended_inputs": requirements.get("recommended_inputs") if isinstance(requirements.get("recommended_inputs"), list) else [],
        "unresolved_recommended_inputs": unresolved_inputs,
        "safety_gates": {
            "resume_available": bool(plan.get("available")),
            "resume_allowed": bool(plan.get("allowed")),
            "resume_recommended": bool(plan.get("recommended")),
            "next_command_allowlisted": bool(plan.get("allowed")),
            "missing_confirmations": _string_list(requirements.get("missing_confirmations")),
            "unknown_overrides_ignored": True,
            "live_upload": _resume_current_flags(plan.get("next_command_argv") if isinstance(plan.get("next_command_argv"), list) else None).get("has_confirm_upload"),
        },
        "continue_when": "dry_run_request returns resume_preview.ok=true and user has reviewed command_argv, applied_overrides, ignored_overrides, and site-rule confirmations",
        "execute_when": "preview_required satisfied and execute_request has only allowlisted overrides required for this resume",
        "stop_when": [
            "resume_plan.allowed=false",
            "resume_preview.ok=false",
            "resume_preview.ignored_overrides is non-empty and user has not approved continuing",
            "resume_execution_handoff.blockers is non-empty",
        ],
        "blockers": blockers,
        "next_actions": _resume_execution_handoff_next_actions(ready, dry_run_request, execute_request, blockers),
    }


def _resume_execution_handoff_blockers(plan: dict[str, Any], requirements: dict[str, Any], summary: dict[str, Any], unresolved_inputs: list[Any]) -> list[str]:
    blockers: list[str] = []
    if plan.get("available") is not True:
        blockers.append(plan.get("blocker") or "resume.next_command_unavailable")
    elif plan.get("allowed") is not True:
        blockers.append(plan.get("blocker") or "resume.next_command_not_allowlisted")
    if plan.get("recommended") is not True:
        blockers.append("resume.not_recommended_for_current_status")
    blockers.extend(_string_list(requirements.get("missing_confirmations")))
    blockers.extend([f"resume.unresolved_input.{item.get('key')}" for item in unresolved_inputs if isinstance(item, dict) and item.get("key")])
    blockers.extend(_string_list(summary.get("blockers")))
    return list(dict.fromkeys(str(item) for item in blockers if item))


def _resume_execution_handoff_next_actions(ready: bool, dry_run_request: dict[str, Any] | None, execute_request: dict[str, Any] | None, blockers: list[str]) -> list[str]:
    if ready and dry_run_request and execute_request:
        return ["Call resume_execution_handoff.dry_run_request first, review the preview, then call execute_request only after user approval."]
    if ready and execute_request:
        return ["Call resume_execution_handoff.execute_request after reviewing site rules and blockers."]
    if blockers:
        return ["Resolve resume_execution_handoff.blockers before attempting resume."]
    return ["Inspect resume_execution_handoff before taking the next resume action."]


def _resume_summary_next_step(
    job: dict[str, Any],
    plan: dict[str, Any],
    dry_run_request: dict[str, Any] | None,
    execute_request: dict[str, Any] | None,
    unresolved_inputs: list[Any],
) -> dict[str, Any]:
    if job.get("status") in {"queued", "running"}:
        return {"tool": "get_job_status", "endpoint": f"/v1/jobs/{job.get('job_id')}", "method": "GET", "request": None, "reason": "job_running"}
    if plan.get("recommended") and plan.get("allowed"):
        return {
            "tool": "resume_job",
            "endpoint": plan.get("endpoint"),
            "method": "POST",
            "request": dry_run_request or execute_request or {"job_id": job.get("job_id")},
            "reason": "preview_resume_before_execute" if dry_run_request else "execute_resume",
        }
    if unresolved_inputs:
        return {"tool": "get_job_summary", "endpoint": f"/v1/jobs/{job.get('job_id')}/summary", "method": "GET", "request": None, "reason": "provide_recommended_inputs"}
    return {"tool": "get_job_summary", "endpoint": f"/v1/jobs/{job.get('job_id')}/summary", "method": "GET", "request": None, "reason": "inspect_resume_summary"}


def _resume_summary_blockers(job: dict[str, Any], plan: dict[str, Any], requirements: dict[str, Any], unresolved_inputs: list[Any]) -> list[str]:
    blockers: list[str] = []
    if plan.get("available") is not True:
        blockers.append(plan.get("blocker") or "resume.next_command_unavailable")
    elif plan.get("allowed") is not True:
        blockers.append(plan.get("blocker") or "resume.next_command_not_allowlisted")
    if job.get("status") in {"queued", "running"}:
        blockers.append(f"resume.job_still_{job.get('status')}")
    blockers.extend(_string_list(requirements.get("missing_confirmations")))
    blockers.extend([f"resume.unresolved_input.{item.get('key')}" for item in unresolved_inputs if isinstance(item, dict) and item.get("key")])
    return list(dict.fromkeys(str(item) for item in blockers if item))


def _resume_summary_next_actions(plan: dict[str, Any], next_step: dict[str, Any], blockers: list[str], unresolved_inputs: list[Any]) -> list[str]:
    request = next_step.get("request") if isinstance(next_step.get("request"), dict) else {}
    if plan.get("recommended") and plan.get("allowed") and not unresolved_inputs and request.get("dry_run") is True:
        return ["Call resume_summary.next_step to dry-run the patched command, review command_argv, then call resume_summary.execute_request without dry_run when ready."]
    if plan.get("recommended") and plan.get("allowed"):
        return ["Call resume_summary.next_step after reviewing blockers, confirmations, and site rules."]
    if unresolved_inputs:
        return ["Provide resume_summary.unresolved_recommended_inputs before executing resume."]
    if blockers:
        return ["Resolve resume_summary.blockers before attempting resume."]
    return ["Inspect resume_summary and closure_summary before taking the next action."]


def _job_candidate_submission(job: dict[str, Any]) -> dict[str, Any] | None:
    request = job.get("request")
    if isinstance(request, dict) and isinstance(request.get("candidate_submission"), dict):
        return request["candidate_submission"]
    return None


def _job_check_submission(job: dict[str, Any]) -> dict[str, Any] | None:
    request = job.get("request")
    if isinstance(request, dict) and isinstance(request.get("check_submission"), dict):
        return request["check_submission"]
    return None


def _job_live_validation_submission(job: dict[str, Any]) -> dict[str, Any] | None:
    request = job.get("request")
    if isinstance(request, dict) and isinstance(request.get("live_validation_submission"), dict):
        return request["live_validation_submission"]
    return None


def _job_live_validation_followup(job: dict[str, Any], summary_payload: dict[str, Any] | None = None) -> dict[str, Any] | None:
    submission = _job_live_validation_submission(job)
    if not submission:
        return None
    job_id = str(job.get("job_id") or "")
    status = str(job.get("status") or "")
    control = _job_control_summary(job, summary_payload)
    completion_report = _job_seedbox_live_validation_completion_report(job, summary_payload)
    live_report = _job_live_user_report(job, summary_payload)
    live_report_blockers = _string_list(live_report.get("blockers") if isinstance(live_report, dict) else [])
    control_blockers = _string_list(control.get("blockers") if isinstance(control, dict) else [])
    completion_blockers = _string_list(completion_report.get("blockers") if isinstance(completion_report, dict) else [])
    blockers = list(dict.fromkeys(control_blockers + completion_blockers + live_report_blockers + _string_list(job.get("blockers"))))

    status_endpoint = f"/v1/jobs/{job_id}" if job_id else None
    summary_endpoint = f"/v1/jobs/{job_id}/summary" if job_id else None
    resume_endpoint = f"/v1/jobs/{job_id}/resume" if job_id else None
    action = "inspect"
    recommended_tool = None
    recommended_endpoint = None
    recommended_method = None
    recommended_request = None

    if isinstance(live_report, dict) and live_report.get("report_allowed") is True:
        action = "report_complete"
        recommended_tool = "get_job_summary"
        recommended_endpoint = summary_endpoint
        recommended_method = "GET"
        recommended_request = {"job_id": job_id} if job_id else None
    elif status in {"queued", "running"} or (isinstance(control, dict) and control.get("should_poll") is True):
        action = "poll"
        recommended_tool = "get_job_status"
        recommended_endpoint = status_endpoint
        recommended_method = "GET"
        recommended_request = {"job_id": job_id} if job_id else None
    elif isinstance(control, dict) and control.get("should_resume") is True:
        action = "resume_preview" if control.get("resume_preview_required") else "resume_execute"
        recommended_tool = "resume_job"
        recommended_endpoint = resume_endpoint
        recommended_method = "POST"
        recommended_request = control.get("dry_run_request") or control.get("recommended_request") or control.get("execute_request")
    elif isinstance(completion_report, dict) and completion_report.get("ready_for_user_report") is True:
        action = "report_complete"
        recommended_tool = "get_job_summary"
        recommended_endpoint = summary_endpoint
        recommended_method = "GET"
        recommended_request = {"job_id": job_id} if job_id else None
    elif isinstance(control, dict):
        action = str(control.get("action") or status or "inspect")
        recommended_tool = control.get("recommended_tool")
        recommended_endpoint = control.get("recommended_endpoint")
        recommended_method = control.get("recommended_method")
        recommended_request = control.get("recommended_request")

    ready = action in {"poll", "resume_preview", "resume_execute", "report_complete"} and (action == "poll" or not blockers)
    return {
        "kind": "ptcli.live_validation_followup",
        "ready": ready,
        "action": action,
        "job_id": job_id or None,
        "job_status": status or None,
        "source": submission.get("source"),
        "source_summary_file": submission.get("summary_file"),
        "source_summary_kind": submission.get("summary_kind"),
        "live_safe_to_attempt": submission.get("live_safe_to_attempt"),
        "doctor_result_ready": submission.get("doctor_result_ready"),
        "status_endpoint": status_endpoint,
        "summary_endpoint": summary_endpoint,
        "resume_endpoint": resume_endpoint,
        "recommended_tool": recommended_tool,
        "recommended_endpoint": recommended_endpoint,
        "recommended_method": recommended_method,
        "recommended_request": recommended_request,
        "job_control_summary": control,
        "seedbox_live_validation_completion_report": completion_report,
        "live_user_report": live_report,
        "read_order": ["live_validation_followup", "job_control_summary", "live_validation_completion_audit", "seedbox_live_validation_completion_report", "live_user_report", "live_completion_gate", "closure_summary", "recovery_handoff"],
        "continue_when": _live_validation_followup_continue_when(action),
        "stop_when": _live_validation_followup_stop_when(action, submission),
        "complete_when": _string_list(submission.get("complete_when")) or [*LIVE_VALIDATION_COMPLETE_WHEN, "seedbox_live_validation_completion_report.ready_for_user_report=true"],
        "blockers": blockers,
        "next_actions": _live_validation_followup_next_actions(action, recommended_tool, blockers),
    }


def _live_validation_followup_continue_when(action: str) -> str | None:
    if action == "poll":
        return "job_status leaves queued/running"
    if action in {"resume_preview", "resume_execute"}:
        return "resume_job returns a terminal summary or a new resumable blocker"
    if action == "report_complete":
        return "live_validation_completion_audit.report_allowed=true and live_validation_completion_audit.failed_checks=[] and live_validation_completion_audit.missing_evidence=[] and live_validation_completion_audit.blockers=[]"
    return None


def _live_validation_followup_stop_when(action: str, submission: dict[str, Any]) -> list[str]:
    stop_when = _string_list(submission.get("stop_when"))
    if action in {"failed", "cancelled"}:
        stop_when.append(f"job_status={action}")
    stop_when.append("live_validation_followup.blockers is not empty and recommended_tool is null")
    return list(dict.fromkeys(stop_when))


def _live_validation_followup_next_actions(action: str, recommended_tool: Any, blockers: list[str]) -> list[str]:
    if action == "poll":
        return ["Poll live_validation_followup.status_endpoint until the submitted live validation job is terminal or resumable."]
    if action in {"resume_preview", "resume_execute"} and recommended_tool:
        return ["Call live_validation_followup.recommended_request after reviewing job_control_summary, site rules, and blockers."]
    if action == "report_complete":
        return ["Read live_validation_followup.summary_endpoint and report live_user_report with seedbox_live_validation_completion_report evidence."]
    if blockers:
        return ["Resolve live_validation_followup.blockers before reporting the live validation as complete."]
    return ["Inspect live_validation_followup.job_control_summary and live_user_report before taking the next action."]


def _job_candidate_submission_handoff(job: dict[str, Any], summary_payload: dict[str, Any] | None = None) -> dict[str, Any] | None:
    submission = _job_candidate_submission(job)
    if not submission:
        return None
    job_id = job.get("job_id")
    request = job.get("request") if isinstance(job.get("request"), dict) else {}
    manual_handoff = _job_manual_retorrent_handoff(job, summary_payload)
    manual_final_report = _job_cached_manual_retorrent_final_report(job, summary_payload)
    policy_execution_handoff = submission.get("policy_execution_handoff") if isinstance(submission.get("policy_execution_handoff"), dict) else {}
    candidate_execution_context = submission.get("candidate_execution_context") if isinstance(submission.get("candidate_execution_context"), dict) else {}
    policy_execution_plan = _job_policy_execution_plan(job)
    policy_enforcement_bundle = _job_policy_enforcement_bundle(job)
    policy_runtime_contract = _job_policy_runtime_contract(job)
    policy_application_handoff = _job_policy_application_handoff(job, summary_payload)
    closure_summary = _job_closure_summary(job, summary_payload)
    execution_handoff = _candidate_submission_execution_handoff(job, manual_handoff if isinstance(manual_handoff, dict) else {}, closure_summary, policy_execution_handoff)
    return {
        "kind": "ptcli.candidate_submission_handoff",
        "candidate_job_id": submission.get("candidate_job_id"),
        "candidate_rank": submission.get("candidate_rank"),
        "candidate_source_id": submission.get("candidate_source_id"),
        "candidate_title": submission.get("candidate_title"),
        "candidate_summary_text": submission.get("candidate_summary_text"),
        "candidate_digest_kind": submission.get("candidate_digest_kind"),
        "inherited_request": submission.get("inherited_request") if isinstance(submission.get("inherited_request"), dict) else {},
        "submitted_overrides": submission.get("submitted_overrides") if isinstance(submission.get("submitted_overrides"), dict) else {},
        "material_options": submission.get("material_options") if isinstance(submission.get("material_options"), dict) else {},
        "qbit_overrides": submission.get("qbit_overrides") if isinstance(submission.get("qbit_overrides"), dict) else {},
        "policy_execution_handoff": policy_execution_handoff,
        "candidate_execution_context": candidate_execution_context,
        "policy_execution_plan": policy_execution_plan,
        "policy_enforcement_bundle": policy_enforcement_bundle,
        "policy_runtime_contract": policy_runtime_contract,
        "policy_application_handoff": policy_application_handoff,
        "retorrent_job_id": job_id,
        "retorrent_status": job.get("status"),
        "source_reference": _job_source_reference(job),
        "target_trackers": request.get("target_trackers"),
        "manual_retorrent_handoff": manual_handoff,
        "manual_retorrent_final_report": manual_final_report,
        "action": manual_handoff.get("action") if isinstance(manual_handoff, dict) else None,
        "execution_state": execution_handoff.get("state"),
        "execution_handoff": execution_handoff,
        "status_endpoint": f"/v1/jobs/{job_id}" if job_id else None,
        "summary_endpoint": f"/v1/jobs/{job_id}/summary" if job_id else None,
        "parent_status_endpoint": f"/v1/jobs/{submission.get('candidate_job_id')}" if submission.get("candidate_job_id") else None,
        "parent_summary_endpoint": f"/v1/jobs/{submission.get('candidate_job_id')}/summary" if submission.get("candidate_job_id") else None,
        "next_actions": _candidate_submission_handoff_next_actions(manual_handoff),
    }


def _job_cached_manual_retorrent_final_report(job: dict[str, Any], summary_payload: dict[str, Any] | None = None) -> dict[str, Any] | None:
    candidates = [
        summary_payload,
        job.get("manual_retorrent_final_report"),
        job.get("agent_decision"),
        job.get("workflow_context"),
    ]
    for candidate in candidates:
        if isinstance(candidate, dict) and isinstance(candidate.get("manual_retorrent_final_report"), dict):
            return candidate["manual_retorrent_final_report"]
        if isinstance(candidate, dict) and candidate.get("kind") == "ptcli.manual_retorrent_final_report":
            return candidate
    return None


def _job_candidate_submission_summary(job: dict[str, Any], summary_payload: dict[str, Any] | None = None) -> dict[str, Any] | None:
    submission = _job_candidate_submission(job)
    if not submission:
        return None
    handoff = _job_candidate_submission_handoff(job, summary_payload)
    manual_handoff = handoff.get("manual_retorrent_handoff") if isinstance(handoff, dict) and isinstance(handoff.get("manual_retorrent_handoff"), dict) else {}
    manual_final_report = handoff.get("manual_retorrent_final_report") if isinstance(handoff, dict) and isinstance(handoff.get("manual_retorrent_final_report"), dict) else _job_cached_manual_retorrent_final_report(job, summary_payload)
    closure_summary = _job_closure_summary(job, summary_payload)
    request = job.get("request") if isinstance(job.get("request"), dict) else {}
    submitted_overrides = submission.get("submitted_overrides") if isinstance(submission.get("submitted_overrides"), dict) else {}
    material_options = submission.get("material_options") if isinstance(submission.get("material_options"), dict) else {}
    qbit_overrides = submission.get("qbit_overrides") if isinstance(submission.get("qbit_overrides"), dict) else {}
    policy_execution_handoff = submission.get("policy_execution_handoff") if isinstance(submission.get("policy_execution_handoff"), dict) else {}
    candidate_execution_context = submission.get("candidate_execution_context") if isinstance(submission.get("candidate_execution_context"), dict) else {}
    policy_execution_plan = _job_policy_execution_plan(job)
    policy_enforcement_bundle = _job_policy_enforcement_bundle(job)
    policy_runtime_contract = _job_policy_runtime_contract(job)
    policy_application_handoff = _job_policy_application_handoff(job, summary_payload)
    next_step = closure_summary.get("next_step") if isinstance(closure_summary.get("next_step"), dict) else {}
    execution_handoff = handoff.get("execution_handoff") if isinstance(handoff, dict) and isinstance(handoff.get("execution_handoff"), dict) else {}
    blockers = list(
        dict.fromkeys(
            _string_list(closure_summary.get("blockers"))
            + _string_list(manual_handoff.get("blockers"))
            + _string_list(job.get("blockers"))
        )
    )
    return {
        "kind": "ptcli.candidate_submission_summary",
        "candidate_job_id": submission.get("candidate_job_id"),
        "retorrent_job_id": job.get("job_id"),
        "retorrent_status": job.get("status"),
        "candidate_rank": submission.get("candidate_rank"),
        "candidate_source_id": submission.get("candidate_source_id"),
        "candidate_title": submission.get("candidate_title"),
        "source_reference": _job_source_reference(job),
        "target_trackers": request.get("target_trackers"),
        "inherited_request": submission.get("inherited_request") if isinstance(submission.get("inherited_request"), dict) else {},
        "submitted_override_keys": sorted(submitted_overrides),
        "material_option_keys": sorted(material_options),
        "qbit_override_keys": sorted(qbit_overrides),
        "policy_execution_handoff": policy_execution_handoff,
        "candidate_execution_context": candidate_execution_context,
        "policy_execution_plan": policy_execution_plan,
        "policy_enforcement_bundle": policy_enforcement_bundle,
        "policy_runtime_contract": policy_runtime_contract,
        "policy_application_handoff": policy_application_handoff,
        "policy_enforcement_ready": policy_enforcement_bundle.get("ready") if isinstance(policy_enforcement_bundle, dict) else None,
        "policy_runtime_ready": policy_runtime_contract.get("ready") if isinstance(policy_runtime_contract, dict) else None,
        "policy_execution_ready": policy_execution_handoff.get("ready") if policy_execution_handoff else None,
        "manual_action": manual_handoff.get("action"),
        "manual_retorrent_verdict": manual_final_report.get("verdict") if isinstance(manual_final_report, dict) else None,
        "manual_report_allowed": manual_final_report.get("report_allowed") if isinstance(manual_final_report, dict) else None,
        "manual_retorrent_final_report": manual_final_report,
        "closure_action": closure_summary.get("action"),
        "closure_complete": closure_summary.get("complete") is True,
        "execution_state": execution_handoff.get("state"),
        "execution_handoff": execution_handoff,
        "can_attempt_live": manual_handoff.get("can_attempt_live"),
        "next_step": next_step,
        "recommended_tool": next_step.get("tool"),
        "recommended_endpoint": next_step.get("endpoint"),
        "recommended_request": next_step.get("request"),
        "status_endpoint": f"/v1/jobs/{job.get('job_id')}" if job.get("job_id") else None,
        "summary_endpoint": f"/v1/jobs/{job.get('job_id')}/summary" if job.get("job_id") else None,
        "parent_summary_endpoint": f"/v1/jobs/{submission.get('candidate_job_id')}/summary" if submission.get("candidate_job_id") else None,
        "blockers": blockers,
        "next_actions": _candidate_submission_summary_next_actions(closure_summary, manual_handoff, next_step, blockers),
    }


def _job_candidate_submit_followup(job: dict[str, Any], summary_payload: dict[str, Any] | None = None) -> dict[str, Any] | None:
    submission = _job_candidate_submission(job)
    if not submission:
        return None
    job_id = str(job.get("job_id") or "")
    parent_job_id = str(submission.get("candidate_job_id") or "")
    summary = _job_candidate_submission_summary(job, summary_payload) or {}
    handoff = _job_candidate_submission_handoff(job, summary_payload) or {}
    manual_final_report = summary.get("manual_retorrent_final_report") if isinstance(summary.get("manual_retorrent_final_report"), dict) else _job_cached_manual_retorrent_final_report(job, summary_payload)
    execution = summary.get("execution_handoff") if isinstance(summary.get("execution_handoff"), dict) else handoff.get("execution_handoff") if isinstance(handoff.get("execution_handoff"), dict) else {}
    action = execution.get("state") or summary.get("execution_state") or summary.get("manual_action") or summary.get("closure_action")
    recommended_tool = execution.get("recommended_tool") or summary.get("recommended_tool")
    recommended_endpoint = execution.get("recommended_endpoint") or summary.get("recommended_endpoint")
    recommended_method = execution.get("recommended_method")
    recommended_request = execution.get("recommended_request") if execution.get("recommended_request") is not None else summary.get("recommended_request")
    return {
        "kind": "ptcli.candidate_submit_followup",
        "ready": action in {"wait", "resume", "prepare_materials", "repair_target_payload", "repair_qbit", "ready_for_live_upload", "complete", "read_summary"} and not _string_list(execution.get("blockers")),
        "action": action,
        "candidate_job_id": parent_job_id or None,
        "candidate_rank": submission.get("candidate_rank"),
        "candidate_source_id": submission.get("candidate_source_id"),
        "candidate_title": submission.get("candidate_title"),
        "retorrent_job_id": job_id or None,
        "retorrent_status": job.get("status"),
        "source_reference": _job_source_reference(job),
        "target_trackers": (job.get("request") or {}).get("target_trackers") if isinstance(job.get("request"), dict) else None,
        "status_endpoint": f"/v1/jobs/{job_id}" if job_id else None,
        "summary_endpoint": f"/v1/jobs/{job_id}/summary" if job_id else None,
        "resume_endpoint": f"/v1/jobs/{job_id}/resume" if job_id else None,
        "parent_status_endpoint": f"/v1/jobs/{parent_job_id}" if parent_job_id else None,
        "parent_summary_endpoint": f"/v1/jobs/{parent_job_id}/summary" if parent_job_id else None,
        "recommended_tool": recommended_tool,
        "recommended_endpoint": recommended_endpoint,
        "recommended_method": recommended_method,
        "recommended_request": recommended_request,
        "job_control_summary_ref": "job_control_summary",
        "job_handoff_ref": "job_handoff",
        "candidate_submission_summary": summary,
        "candidate_submission_handoff": handoff,
        "manual_retorrent_final_report": manual_final_report,
        "manual_retorrent_verdict": manual_final_report.get("verdict") if isinstance(manual_final_report, dict) else None,
        "manual_report_allowed": manual_final_report.get("report_allowed") if isinstance(manual_final_report, dict) else None,
        "read_order": ["candidate_submit_followup", "manual_retorrent_final_report", "job_control_summary", "candidate_submission_summary.execution_handoff", "job_handoff", "closure_summary", "seedbox_live_validation_completion_report"],
        "continue_when": _candidate_submit_followup_continue_when(str(action or "")),
        "stop_when": _candidate_submit_followup_stop_when(str(action or "")),
        "blockers": list(dict.fromkeys(_string_list(execution.get("blockers")) + _string_list(summary.get("blockers")) + _string_list(job.get("blockers")))),
        "next_actions": _candidate_submit_followup_next_actions(str(action or ""), recommended_tool),
    }


def _candidate_submit_followup_continue_when(action: str) -> str | None:
    if action == "wait":
        return "retorrent_status leaves queued/running"
    if action in {"resume", "prepare_materials", "repair_target_payload", "repair_qbit"}:
        return "recommended_request has been dry-run reviewed and user approved resume execution"
    if action == "ready_for_live_upload":
        return "target upload preflight, duplicate check, rule gate, and uploaded-seeding plan are ready"
    if action in {"complete", "read_summary"}:
        return "seedbox_live_validation_completion_report.ready_for_user_report=true"
    return None


def _candidate_submit_followup_stop_when(action: str) -> list[str]:
    if action == "stop_duplicate":
        return ["duplicate_check.exists=true"]
    if action == "collect_confirmations":
        return ["accept_rules or confirm_upload is missing"]
    if action == "configure_policy":
        return ["policy_execution_handoff.ready=false", "site policy or rule obligations are incomplete"]
    if action in {"blocked", "failed", "cancelled"}:
        return [f"candidate_submit_followup.action={action}"]
    return ["candidate_submit_followup.blockers is not empty and recommended_tool is null"]


def _candidate_submit_followup_next_actions(action: str, recommended_tool: Any) -> list[str]:
    if action == "wait":
        return ["Poll candidate_submit_followup.status_endpoint until the submitted retorrent job is terminal."]
    if action in {"resume", "prepare_materials", "repair_target_payload", "repair_qbit"} and recommended_tool:
        return ["Call candidate_submit_followup.recommended_request after reviewing job_control_summary, blockers, site rules, and any dry-run preview."]
    if action == "ready_for_live_upload":
        return ["Review target_upload_handoff and candidate_submit_followup.recommended_request before live upload."]
    if action in {"complete", "read_summary"}:
        return ["Read candidate_submit_followup.summary_endpoint and report closure evidence."]
    if action == "stop_duplicate":
        return ["Stop. Do not upload; report duplicate_check.dupes or choose another candidate."]
    if action == "collect_confirmations":
        return ["Ask the user for explicit accept_rules/confirm_upload before resuming."]
    if action == "configure_policy":
        return ["Call site_policies or update PTCLI.SITE_POLICIES, then rerun or resume after policy coverage is ready."]
    return ["Inspect candidate_submit_followup.blockers, job_control_summary, and candidate_submission_summary before taking the next action."]


def _job_candidate_submit_sequence(job: dict[str, Any], summary_payload: dict[str, Any] | None = None) -> dict[str, Any] | None:
    followup = _job_candidate_submit_followup(job, summary_payload)
    if not isinstance(followup, dict):
        return None
    action = str(followup.get("action") or "inspect")
    blockers = _string_list(followup.get("blockers"))
    steps = _candidate_submit_sequence_steps(action, followup)
    manual_final_report = followup.get("manual_retorrent_final_report") if isinstance(followup.get("manual_retorrent_final_report"), dict) else None
    return {
        "kind": "ptcli.candidate_submit_sequence",
        "ready": bool(followup.get("ready")) and not blockers,
        "status": "ready" if bool(followup.get("ready")) and not blockers else "blocked" if blockers else "inspect",
        "action": action,
        "candidate_job_id": followup.get("candidate_job_id"),
        "candidate_rank": followup.get("candidate_rank"),
        "candidate_source_id": followup.get("candidate_source_id"),
        "retorrent_job_id": followup.get("retorrent_job_id"),
        "retorrent_status": followup.get("retorrent_status"),
        "source_reference": followup.get("source_reference") if isinstance(followup.get("source_reference"), dict) else {},
        "target_trackers": followup.get("target_trackers"),
        "manual_retorrent_final_report": manual_final_report,
        "manual_retorrent_verdict": manual_final_report.get("verdict") if isinstance(manual_final_report, dict) else None,
        "manual_report_allowed": manual_final_report.get("report_allowed") if isinstance(manual_final_report, dict) else None,
        "steps": steps,
        "next_step": steps[0] if steps else None,
        "read_order": ["candidate_submit_sequence", "manual_retorrent_final_report", "candidate_submit_followup", "candidate_submission_summary.execution_handoff", "live_action_sequence", "live_completion_gate", "job_handoff"],
        "complete_when": [
            "manual_retorrent_final_report.report_allowed=true",
            "live_completion_gate.ready=true",
            "closure_summary.complete=true",
            "candidate_submit_followup.action in complete,read_summary",
        ],
        "stop_when": _candidate_submit_sequence_stop_when(action),
        "blockers": blockers,
        "next_actions": _candidate_submit_sequence_next_actions(action, steps, blockers),
        "safety": {
            "mutates_state": False,
            "live_upload": action == "ready_for_live_upload",
            "requires_explicit_confirmations": ["accept_rules=true", "confirm_upload=true"],
            "does_not_bypass_duplicate_check": True,
            "does_not_bypass_site_rules": True,
        },
    }


def _candidate_submit_sequence_steps(action: str, followup: dict[str, Any]) -> list[dict[str, Any]]:
    job_id = followup.get("retorrent_job_id")
    status_endpoint = followup.get("status_endpoint")
    summary_endpoint = followup.get("summary_endpoint")
    resume_endpoint = followup.get("resume_endpoint")
    recommended_request = followup.get("recommended_request")
    if action == "wait":
        return [
            {
                "name": "poll_submitted_retorrent_job",
                "tool": "get_job_status",
                "endpoint": status_endpoint,
                "method": "GET",
                "request": {"job_id": job_id} if job_id else None,
                "read": ["status", "candidate_submit_sequence", "manual_retorrent_final_report", "live_action_sequence", "live_completion_gate", "job_handoff"],
                "continue_when": "retorrent_status is not queued/running",
                "repeat_when": "retorrent_status in queued,running",
                "stop_when": ["status=failed", "status=cancelled"],
            }
        ]
    if action in {"resume", "prepare_materials", "repair_target_payload", "repair_qbit"}:
        return [
            {
                "name": "review_resume_request",
                "tool": "get_job_summary",
                "endpoint": summary_endpoint,
                "method": "GET",
                "request": {"job_id": job_id} if job_id else None,
                "read": ["manual_retorrent_final_report", "resume_execution_handoff", "candidate_submission_summary.execution_handoff", "material_input_template", "job_control_summary"],
                "continue_when": "resume_execution_handoff.dry_run_request or execute_request is ready and required material inputs are available",
                "stop_when": ["resume_execution_handoff.blockers is not empty"],
            },
            {
                "name": "resume_submitted_retorrent_job",
                "tool": "resume_job",
                "endpoint": resume_endpoint,
                "method": "POST",
                "request": recommended_request,
                "read": ["resume_preview", "status", "candidate_submit_followup"],
                "continue_when": "resume call returns ok=true or a new resumable blocker",
                "stop_when": ["resume_preview.ok=false", "ignored_overrides require user review"],
            },
            {
                "name": "poll_after_resume",
                "tool": "get_job_status",
                "endpoint": status_endpoint,
                "method": "GET",
                "request": {"job_id": job_id} if job_id else None,
                "read": ["candidate_submit_sequence", "manual_retorrent_final_report", "live_completion_gate", "job_handoff"],
                "continue_when": "live_completion_gate.ready=true or candidate_submit_sequence.action changes",
                "repeat_when": "retorrent_status in queued,running",
                "stop_when": ["status=failed", "status=cancelled"],
            },
        ]
    if action == "ready_for_live_upload":
        return [
            {
                "name": "review_live_upload_request",
                "tool": "get_job_summary",
                "endpoint": summary_endpoint,
                "method": "GET",
                "request": {"job_id": job_id} if job_id else None,
                "read": ["manual_retorrent_final_report", "target_upload_handoff", "duplicate_check", "policy_execution_report", "qbit_execution_gate", "live_action_sequence"],
                "continue_when": "confirm_upload=true, duplicate_check.exists=false, and target_upload_handoff.ready=true",
                "stop_when": ["duplicate_check.exists=true", "policy_execution_report.ready=false", "target_upload_handoff.ready=false"],
            },
            {
                "name": "execute_live_upload_resume",
                "tool": "resume_job",
                "endpoint": resume_endpoint,
                "method": "POST",
                "request": recommended_request,
                "read": ["manual_retorrent_final_report", "target_upload_handoff", "uploaded_torrent", "qbit_enforcement_summary", "live_completion_gate"],
                "continue_when": "uploaded target torrent is downloaded, injected, and qbit_enforcement_summary.ready=true",
                "stop_when": ["confirm_upload is not true", "target upload returns duplicate or rule blocker"],
            },
        ]
    if action in {"complete", "read_summary"}:
        return [
            {
                "name": "read_completion_summary",
                "tool": "get_job_summary",
                "endpoint": summary_endpoint,
                "method": "GET",
                "request": {"job_id": job_id} if job_id else None,
                "read": ["manual_retorrent_final_report", "live_completion_gate", "closure_summary", "evidence", "candidate_submission_summary"],
                "continue_when": "final user report includes source, target, duplicate result, uploaded torrent hash, and qB seeding evidence",
                "stop_when": ["live_completion_gate.ready=false"],
            }
        ]
    if action == "stop_duplicate":
        return [
            {
                "name": "report_duplicate_and_stop",
                "tool": "get_job_summary",
                "endpoint": summary_endpoint,
                "method": "GET",
                "request": {"job_id": job_id} if job_id else None,
                "read": ["manual_retorrent_final_report", "duplicate_check", "closure_summary", "candidate_submission_summary"],
                "continue_when": "duplicate evidence has been reported and no upload is attempted",
                "stop_when": ["always_stop_duplicate"],
            }
        ]
    if action == "configure_policy":
        return [
            {
                "name": "repair_site_policy_before_resume",
                "tool": "site_policies",
                "endpoint": "/v1/site-policies",
                "method": "POST",
                "request": None,
                "read": ["manual_retorrent_final_report", "policy_execution_sequence", "policy_execution_handoff", "rule_obligations"],
                "continue_when": "policy_execution_sequence.ready=true, then refresh this retorrent job summary",
                "stop_when": ["rule_obligations.*.ready=false", "policy_execution_handoff.ready=false"],
            }
        ]
    if action == "collect_confirmations":
        return [
            {
                "name": "collect_live_confirmations",
                "tool": "resume_job",
                "endpoint": resume_endpoint,
                "method": "POST",
                "request": recommended_request,
                "read": ["manual_retorrent_final_report", "resume_requirements", "candidate_submission_summary", "job_handoff"],
                "continue_when": "accept_rules=true and confirm_upload=true are explicitly present",
                "stop_when": ["user does not confirm site rules or live upload"],
            }
        ]
    return [
        {
            "name": "inspect_candidate_submission",
            "tool": followup.get("recommended_tool") or "get_job_summary",
            "endpoint": followup.get("recommended_endpoint") or summary_endpoint,
            "method": followup.get("recommended_method") or "GET",
            "request": recommended_request if recommended_request is not None else {"job_id": job_id} if job_id else None,
            "read": ["candidate_submit_followup", "manual_retorrent_final_report", "candidate_submission_summary", "job_control_summary", "job_handoff"],
            "continue_when": "candidate_submit_sequence.action becomes a known action",
            "stop_when": ["candidate_submit_sequence.blockers is not empty and no recommended_tool is present"],
        }
    ]


def _candidate_submit_sequence_stop_when(action: str) -> list[str]:
    if action == "stop_duplicate":
        return ["duplicate_check.exists=true", "do_not_upload"]
    if action == "configure_policy":
        return ["policy_execution_handoff.ready=false", "rule_obligations.*.ready=false"]
    if action == "collect_confirmations":
        return ["accept_rules or confirm_upload is missing"]
    return ["candidate_submit_sequence.blockers is not empty and candidate_submit_sequence.next_step is null", "status=failed", "status=cancelled"]


def _candidate_submit_sequence_next_actions(action: str, steps: list[dict[str, Any]], blockers: list[str]) -> list[str]:
    if blockers and action not in {"configure_policy", "stop_duplicate", "collect_confirmations"}:
        return ["Resolve candidate_submit_sequence.blockers before continuing the submitted candidate job."]
    if action == "wait":
        return ["Poll candidate_submit_sequence.next_step until the submitted retorrent job leaves queued/running."]
    if action in {"resume", "prepare_materials", "repair_target_payload", "repair_qbit"}:
        return ["Follow candidate_submit_sequence.steps in order: read summary, review resume request/material inputs, resume, then poll again."]
    if action == "ready_for_live_upload":
        return ["Review live upload gates, then resume only with explicit accept_rules and confirm_upload still present."]
    if action in {"complete", "read_summary"}:
        return ["Read candidate_submit_sequence.next_step and report the final closure evidence."]
    if action == "stop_duplicate":
        return ["Stop this candidate. Report duplicate evidence and do not upload."]
    if action == "configure_policy":
        return ["Repair site policy/rule obligations, rerun site_policies, then refresh the submitted retorrent job summary."]
    if action == "collect_confirmations":
        return ["Ask for explicit accept_rules and confirm_upload before resuming."]
    if steps:
        return ["Inspect candidate_submit_sequence.next_step before taking action."]
    return ["Inspect candidate_submit_followup and job_handoff before continuing."]


def _candidate_submission_execution_handoff(job: dict[str, Any], manual_handoff: dict[str, Any], closure_summary: dict[str, Any], policy_execution_handoff: dict[str, Any]) -> dict[str, Any]:
    status = str(job.get("status") or "unknown")
    blockers = list(dict.fromkeys(_string_list(closure_summary.get("blockers")) + _string_list(manual_handoff.get("blockers")) + _string_list(job.get("blockers"))))
    closure_action = str(closure_summary.get("action") or "")
    manual_action = str(manual_handoff.get("action") or "")
    next_step = closure_summary.get("next_step") if isinstance(closure_summary.get("next_step"), dict) else {}
    materials_handoff = manual_handoff.get("materials_handoff") if isinstance(manual_handoff.get("materials_handoff"), dict) else None
    material_input_template = _candidate_submission_material_input_template(materials_handoff)
    policy_ready = policy_execution_handoff.get("ready") if isinstance(policy_execution_handoff.get("ready"), bool) else None
    state, reason = _candidate_submission_execution_state(status, closure_summary, manual_handoff, policy_ready, blockers)
    recommended_tool = next_step.get("tool")
    recommended_endpoint = next_step.get("endpoint")
    recommended_request = next_step.get("request")
    return {
        "kind": "ptcli.candidate_submission_execution_handoff",
        "state": state,
        "reason": reason,
        "status": status,
        "ready_for_live": state in {"ready_for_live_upload", "resume"} and not blockers,
        "should_poll": state == "wait",
        "should_resume": state in {"resume", "prepare_materials", "repair_target_payload", "repair_qbit"} and recommended_tool == "resume_job",
        "should_stop": state in {"stop_duplicate", "collect_confirmations", "configure_policy", "cancelled"},
        "manual_action": manual_action or None,
        "closure_action": closure_action or None,
        "policy_execution_ready": policy_ready,
        "recommended_tool": recommended_tool,
        "recommended_endpoint": recommended_endpoint,
        "recommended_method": next_step.get("method"),
        "recommended_request": recommended_request,
        "material_input_template": material_input_template,
        "continue_when": _candidate_submission_execution_continue_when(state),
        "stop_when": _candidate_submission_execution_stop_when(state),
        "blockers": blockers,
        "next_actions": _candidate_submission_execution_next_actions(state, next_step, blockers, material_input_template),
    }


def _candidate_submission_material_input_template(materials_handoff: dict[str, Any] | None) -> dict[str, Any] | None:
    if not isinstance(materials_handoff, dict):
        return None
    recommended_inputs = materials_handoff.get("recommended_inputs") if isinstance(materials_handoff.get("recommended_inputs"), list) else []
    material_plan = materials_handoff.get("material_plan") if isinstance(materials_handoff.get("material_plan"), dict) else {}
    resume_handoff = materials_handoff.get("resume_handoff") if isinstance(materials_handoff.get("resume_handoff"), dict) else {}
    next_item = material_plan.get("next_item") if isinstance(material_plan.get("next_item"), dict) else None
    return {
        "kind": "ptcli.candidate_submission_material_input_template",
        "ready": materials_handoff.get("ready") is True,
        "recommended_input_keys": [item.get("key") for item in recommended_inputs if isinstance(item, dict) and item.get("key")],
        "recommended_inputs": recommended_inputs,
        "missing": _string_list(material_plan.get("missing")),
        "next_item": next_item,
        "accepted_override_keys": _string_list(resume_handoff.get("accepted_override_keys")),
        "resume_request_template": materials_handoff.get("resume_request_template") if isinstance(materials_handoff.get("resume_request_template"), dict) else {},
        "dry_run_request": resume_handoff.get("dry_run_request") if isinstance(resume_handoff.get("dry_run_request"), dict) else None,
        "execute_request": resume_handoff.get("execute_request") if isinstance(resume_handoff.get("execute_request"), dict) else None,
        "staged_requests": resume_handoff.get("staged_requests") if isinstance(resume_handoff.get("staged_requests"), list) else [],
        "examples_by_key": {
            str(item.get("key")): item.get("examples")
            for item in recommended_inputs
            if isinstance(item, dict) and item.get("key") and isinstance(item.get("examples"), dict)
        },
        "continue_when": resume_handoff.get("continue_when"),
        "stop_when": resume_handoff.get("stop_when"),
    }


def _candidate_submission_execution_state(status: str, closure_summary: dict[str, Any], manual_handoff: dict[str, Any], policy_ready: bool | None, blockers: list[str]) -> tuple[str, str]:
    closure_action = str(closure_summary.get("action") or "")
    manual_action = str(manual_handoff.get("action") or "")
    if status in {"queued", "running"} or closure_action == "wait" or manual_action == "poll":
        return "wait", "submitted_retorrent_job_still_running"
    if closure_summary.get("complete") is True and not blockers:
        return "complete", "retorrent_closure_complete"
    if closure_action == "stop_duplicate" or manual_action == "stop_duplicate":
        return "stop_duplicate", "target_duplicate_exists"
    if manual_action == "collect_confirmations" or closure_action == "collect_confirmations":
        return "collect_confirmations", "missing_required_confirmation"
    if policy_ready is False or manual_action == "configure_policy" or closure_action == "configure_policy":
        return "configure_policy", "policy_coverage_or_execution_incomplete"
    if closure_action in {"prepare_materials", "repair_target_payload", "repair_qbit", "ready_for_upload"}:
        return "ready_for_live_upload" if closure_action == "ready_for_upload" else closure_action, closure_action
    if manual_action == "resume" or closure_summary.get("recommended_tool") == "resume_job":
        return "resume", "resume_submitted_retorrent_job"
    if status == "cancelled":
        return "cancelled", "job_cancelled"
    if blockers:
        return "blocked", "blocked_by_runtime_or_gate"
    if status == "complete":
        return "complete", "retorrent_job_complete"
    return "inspect", "unknown_candidate_submission_state"


def _candidate_submission_execution_continue_when(state: str) -> str | None:
    if state == "wait":
        return "job status is no longer queued/running"
    if state in {"resume", "prepare_materials", "repair_target_payload", "repair_qbit"}:
        return "recommended_request reviewed, site rules accepted, and resume dry-run is acceptable"
    if state == "ready_for_live_upload":
        return "accept_rules=true, confirm_upload=true, duplicate_check clear, policy_execution_ready=true, and target payload ready"
    if state == "complete":
        return "closure_summary.complete=true and blockers=[]"
    return None


def _candidate_submission_execution_stop_when(state: str) -> list[str]:
    if state == "stop_duplicate":
        return ["duplicate_check.exists=true"]
    if state == "collect_confirmations":
        return ["accept_rules or confirm_upload is missing"]
    if state == "configure_policy":
        return ["policy_execution_handoff.ready=false", "rule obligations or site policy coverage incomplete"]
    if state == "cancelled":
        return ["job.status=cancelled"]
    if state == "blocked":
        return ["candidate_submission_summary.blockers is not empty and recommended_tool is null"]
    return []


def _candidate_submission_execution_next_actions(state: str, next_step: dict[str, Any], blockers: list[str], material_input_template: dict[str, Any] | None) -> list[str]:
    if state == "complete":
        return []
    if state == "wait":
        return ["Poll candidate_submission_handoff.status_endpoint until the submitted retorrent job is terminal."]
    if state == "stop_duplicate":
        return ["Stop. Do not upload; report duplicate_check.dupes or choose another target."]
    if state == "collect_confirmations":
        return ["Ask the user for explicit accept_rules/confirm_upload confirmation before resuming."]
    if state == "configure_policy":
        return ["Call site_policies or update PTCLI.SITE_POLICIES before attempting live work."]
    if state == "prepare_materials" and isinstance(material_input_template, dict):
        keys = ", ".join(_string_list(material_input_template.get("recommended_input_keys")))
        return [f"Use candidate_submission_summary.execution_handoff.material_input_template to provide material overrides: {keys}."]
    if next_step.get("tool"):
        return [f"Use candidate_submission_summary.execution_handoff.recommended_request with {next_step['tool']} after reviewing blockers and site rules."]
    if blockers:
        return ["Resolve candidate_submission_summary.execution_handoff.blockers before resuming the submitted retorrent job."]
    return ["Inspect candidate_submission_summary.execution_handoff and closure_summary before taking live action."]


def _candidate_submission_summary_next_actions(closure_summary: dict[str, Any], manual_handoff: dict[str, Any], next_step: dict[str, Any], blockers: list[str]) -> list[str]:
    if closure_summary.get("complete") is True and not blockers:
        return []
    if next_step.get("tool"):
        return [f"Use candidate_submission_summary.next_step with {next_step['tool']} after reviewing blockers and confirmations."]
    actions = _string_list(manual_handoff.get("next_actions")) or _string_list(closure_summary.get("next_actions"))
    if actions:
        return actions
    if blockers:
        return ["Resolve candidate_submission_summary.blockers before resuming the submitted retorrent job."]
    return ["Poll candidate_submission_summary.status_endpoint, then read candidate_submission_summary.summary_endpoint."]


def _candidate_submission_handoff_next_actions(manual_handoff: dict[str, Any] | None) -> list[str]:
    if not isinstance(manual_handoff, dict):
        return ["Poll the retorrent job status endpoint, then inspect manual_retorrent_handoff."]
    action = manual_handoff.get("action")
    if action == "poll":
        return ["Poll status_endpoint until manual_retorrent_handoff.action changes."]
    if action == "resume":
        return _string_list(manual_handoff.get("next_actions")) or ["Resume the retorrent job through manual_retorrent_handoff.resume_endpoint."]
    return _string_list(manual_handoff.get("next_actions"))


def _job_source_reference(job: dict[str, Any]) -> dict[str, Any] | None:
    request = job.get("request")
    if not isinstance(request, dict):
        return None
    if isinstance(request.get("source_reference"), dict):
        return request["source_reference"]
    if isinstance(request.get("parent_source_reference"), dict):
        return request["parent_source_reference"]
    if isinstance(request.get("source"), dict):
        return request["source"]
    return None


def _job_manual_retorrent_handoff(job: dict[str, Any], summary_payload: dict[str, Any] | None = None) -> dict[str, Any] | None:
    request = job.get("request") if isinstance(job.get("request"), dict) else {}
    if not _is_manual_retorrent_job(job, request):
        return None
    status = str(job.get("status") or "unknown")
    duplicate_check = _job_duplicate_check(job)
    duplicate_searched = duplicate_check.get("searched") is True
    duplicate_exists = duplicate_check.get("exists") is True
    duplicate_clear = duplicate_searched and duplicate_exists is False
    missing_confirmations = _missing_live_confirmations(request)
    policy_coverage = _job_policy_coverage(job)
    policy_ready = policy_coverage.get("ready") if isinstance(policy_coverage, dict) and isinstance(policy_coverage.get("ready"), bool) else None
    qbit_limit_audit = _job_qbit_limit_audit(job, summary_payload)
    qbit_limit_ready = qbit_limit_audit.get("ready") if isinstance(qbit_limit_audit, dict) and isinstance(qbit_limit_audit.get("ready"), bool) else None
    policy_enforcement_bundle = _job_policy_enforcement_bundle(job)
    policy_enforcement_ready = policy_enforcement_bundle.get("ready") if isinstance(policy_enforcement_bundle, dict) and isinstance(policy_enforcement_bundle.get("ready"), bool) else None
    policy_runtime_contract = _job_policy_runtime_contract(job)
    policy_runtime_ready = policy_runtime_contract.get("ready") if isinstance(policy_runtime_contract, dict) and isinstance(policy_runtime_contract.get("ready"), bool) else None
    policy_application_handoff = _job_policy_application_handoff(job, summary_payload)
    materials_handoff = _job_materials_handoff(job, summary_payload)
    target_upload_handoff = _job_target_upload_handoff(job, summary_payload)
    resume_plan = _job_resume_plan(job)
    runtime = _job_runtime(job)
    blockers = _string_list(job.get("blockers"))
    next_actions = _string_list(job.get("next_actions"))
    action, reason = _manual_retorrent_handoff_action(
        status=status,
        duplicate_exists=duplicate_exists,
        missing_confirmations=missing_confirmations,
        policy_ready=policy_ready,
        resume_plan=resume_plan,
        blockers=blockers,
    )
    can_attempt_live = bool(duplicate_clear and not missing_confirmations and policy_ready is not False and policy_enforcement_ready is not False and policy_runtime_ready is not False and status not in {"queued", "running", "cancelled"})
    can_resume = bool(resume_plan.get("recommended")) and not duplicate_exists and not missing_confirmations and policy_ready is not False and policy_enforcement_ready is not False and policy_runtime_ready is not False
    live_checklist = _manual_retorrent_live_checklist(
        job,
        duplicate_clear=duplicate_clear,
        missing_confirmations=missing_confirmations,
        policy_ready=policy_ready,
        policy_enforcement_ready=policy_enforcement_ready,
        policy_runtime_ready=policy_runtime_ready,
        qbit_limit_ready=qbit_limit_ready,
        materials_handoff=materials_handoff,
        target_upload_handoff=target_upload_handoff,
    )
    return {
        "kind": "ptcli.manual_retorrent_handoff",
        "ready": status == "complete",
        "action": action,
        "reason": reason,
        "live_ready": live_checklist["ready"],
        "live_checklist": live_checklist,
        "status": status,
        "source_reference": _job_source_reference(job),
        "target_trackers": request.get("target_trackers"),
        "duplicate_check": duplicate_check,
        "duplicate_clear": duplicate_clear,
        "missing_confirmations": missing_confirmations,
        "policy_coverage_ready": policy_ready,
        "policy_enforcement_ready": policy_enforcement_ready,
        "policy_enforcement_bundle": policy_enforcement_bundle,
        "policy_runtime_ready": policy_runtime_ready,
        "policy_runtime_contract": policy_runtime_contract,
        "policy_application_handoff": policy_application_handoff,
        "qbit_limit_audit_ready": qbit_limit_ready,
        "materials_handoff": materials_handoff,
        "target_upload_handoff": target_upload_handoff,
        "can_attempt_live": can_attempt_live,
        "can_resume": can_resume,
        "should_poll": bool(runtime.get("should_poll")),
        "status_endpoint": runtime.get("status_endpoint"),
        "summary_endpoint": runtime.get("summary_endpoint"),
        "resume_endpoint": runtime.get("resume_endpoint") if can_resume else None,
        "resume_plan": resume_plan,
        "summary_file": job.get("summary_file") or _job_summary_file(job),
        "blockers": blockers,
        "next_actions": _manual_retorrent_handoff_next_actions(action, next_actions, missing_confirmations, resume_plan),
    }


def _job_manual_retorrent_final_report(job: dict[str, Any], summary_payload: dict[str, Any] | None = None) -> dict[str, Any] | None:
    request = job.get("request") if isinstance(job.get("request"), dict) else {}
    if not _is_manual_retorrent_job(job, request):
        return None
    manual_handoff = _job_manual_retorrent_handoff(job, summary_payload)
    policy_report = _job_policy_execution_final_report(job, summary_payload)
    material_report = _job_material_preparation_final_report(job, summary_payload)
    target_upload = _job_target_upload_handoff(job, summary_payload)
    closure = _job_closure_summary(job, summary_payload)
    live_gate = _job_live_completion_gate(job, summary_payload)
    live_report = _job_live_user_report(job, summary_payload)
    duplicate_check = _job_duplicate_check(job)
    blockers = _manual_retorrent_final_blockers(manual_handoff, policy_report, material_report, target_upload, closure, live_gate, live_report)
    missing_confirmations = _missing_live_confirmations(request)
    report_allowed = isinstance(live_report, dict) and live_report.get("report_allowed") is True and not blockers
    verdict = _manual_retorrent_final_verdict(
        job_status=str(job.get("status") or "unknown"),
        duplicate_check=duplicate_check,
        missing_confirmations=missing_confirmations,
        policy_report=policy_report,
        material_report=material_report,
        target_upload=target_upload,
        live_gate=live_gate,
        live_report=live_report,
        blockers=blockers,
    )
    next_step = _manual_retorrent_final_next_step(live_report, live_gate, manual_handoff, material_report, policy_report)
    return {
        "kind": "ptcli.manual_retorrent_final_report",
        "ready": report_allowed,
        "report_allowed": report_allowed,
        "verdict": verdict,
        "status": job.get("status"),
        "job_id": job.get("job_id"),
        "job_kind": job.get("kind"),
        "summary_file": job.get("summary_file") or _job_summary_file(job),
        "source_reference": _job_source_reference(job),
        "target_trackers": request.get("target_trackers"),
        "duplicate_check": {
            "searched": duplicate_check.get("searched"),
            "exists": duplicate_check.get("exists"),
            "clear": duplicate_check.get("searched") is True and duplicate_check.get("exists") is False,
            "count": duplicate_check.get("count"),
            "dupes": duplicate_check.get("dupes") if isinstance(duplicate_check.get("dupes"), list) else [],
        },
        "policy": {
            "ready_for_live": policy_report.get("ready_for_live") if isinstance(policy_report, dict) else None,
            "verdict": policy_report.get("verdict") if isinstance(policy_report, dict) else None,
            "blockers": _string_list(policy_report.get("blockers")) if isinstance(policy_report, dict) else [],
        },
        "materials": {
            "ready_for_target_upload": material_report.get("ready_for_target_upload") if isinstance(material_report, dict) else None,
            "verdict": material_report.get("verdict") if isinstance(material_report, dict) else None,
            "missing_domains": _string_list(material_report.get("missing_domains")) if isinstance(material_report, dict) else [],
            "blockers": _string_list(material_report.get("blockers")) if isinstance(material_report, dict) else [],
        },
        "target_upload": {
            "ready_for_live_upload": target_upload.get("ready_for_live_upload") if isinstance(target_upload, dict) else None,
            "uploaded_seeding_ready": target_upload.get("uploaded_seeding_ready") if isinstance(target_upload, dict) else None,
            "action": target_upload.get("action") if isinstance(target_upload, dict) else None,
            "blockers": _string_list(target_upload.get("blockers")) if isinstance(target_upload, dict) else [],
        },
        "closure": {
            "complete": closure.get("complete") if isinstance(closure, dict) else None,
            "action": closure.get("action") if isinstance(closure, dict) else None,
            "source": closure.get("source") if isinstance(closure, dict) else None,
            "target": closure.get("target") if isinstance(closure, dict) else None,
            "blockers": _string_list(closure.get("blockers")) if isinstance(closure, dict) else [],
        },
        "live": {
            "gate_ready": live_gate.get("ready") if isinstance(live_gate, dict) else None,
            "gate_action": live_gate.get("action") if isinstance(live_gate, dict) else None,
            "user_report_allowed": live_report.get("report_allowed") if isinstance(live_report, dict) else None,
            "validation_report_allowed": None,
            "missing_evidence": _string_list((live_report.get("evidence") or {}).get("missing_evidence")) if isinstance(live_report, dict) and isinstance(live_report.get("evidence"), dict) else [],
        },
        "control": {
            "action": None,
            "state": None,
            "safe_to_call_now": None,
        },
        "recommended_tool": next_step.get("tool"),
        "recommended_endpoint": next_step.get("endpoint"),
        "recommended_method": next_step.get("method"),
        "recommended_request": next_step.get("request"),
        "recommended_call": {
            "tool": next_step.get("tool"),
            "endpoint": next_step.get("endpoint"),
            "method": next_step.get("method"),
            "request": next_step.get("request"),
            "safe_to_call_now": bool(next_step.get("safe_to_call_now")),
            "requires_user_review": next_step.get("requires_user_review") is not False,
        },
        "read_order": ["manual_retorrent_final_report", "job_control_summary", "policy_execution_final_report", "material_preparation_final_report", "target_upload_handoff", "live_completion_gate", "live_validation_final_report", "closure_summary"],
        "complete_when": "manual_retorrent_final_report.report_allowed=true and live_validation_final_report.report_allowed=true before reporting manual retorrent completion.",
        "stop_when": "manual_retorrent_final_report.verdict in duplicate_stopped, policy_blocked, confirmations_required, blocked, failed, or cancelled without a recommended_call.",
        "blockers": blockers,
        "next_actions": _manual_retorrent_final_next_actions(verdict, blockers, next_step, missing_confirmations),
    }


def _manual_retorrent_final_blockers(*reports: dict[str, Any] | None) -> list[str]:
    blockers: list[str] = []
    for report in reports:
        if isinstance(report, dict):
            blockers.extend(_string_list(report.get("blockers")))
    return list(dict.fromkeys(blockers))


def _manual_retorrent_final_verdict(
    *,
    job_status: str,
    duplicate_check: dict[str, Any],
    missing_confirmations: list[str],
    policy_report: dict[str, Any] | None,
    material_report: dict[str, Any] | None,
    target_upload: dict[str, Any] | None,
    live_gate: dict[str, Any] | None,
    live_report: dict[str, Any] | None,
    blockers: list[str],
) -> str:
    if isinstance(live_report, dict) and live_report.get("report_allowed") is True and not blockers:
        return "complete"
    if duplicate_check.get("exists") is True:
        return "duplicate_stopped"
    if job_status in {"queued", "running"}:
        return "running"
    if job_status in {"failed", "cancelled"}:
        return job_status
    if missing_confirmations:
        return "confirmations_required"
    if isinstance(policy_report, dict) and policy_report.get("ready_for_live") is False:
        return "policy_blocked"
    if isinstance(material_report, dict) and material_report.get("ready_for_target_upload") is False:
        return "materials_blocked"
    if isinstance(target_upload, dict) and target_upload.get("uploaded_seeding_ready") is False:
        return "target_upload_pending"
    if isinstance(live_gate, dict) and live_gate.get("action") == "resume_job":
        return "resume_required"
    if blockers:
        return "blocked"
    return "inspect"


def _manual_retorrent_final_next_step(
    live_report: dict[str, Any] | None,
    live_gate: dict[str, Any] | None,
    manual_handoff: dict[str, Any] | None,
    material_report: dict[str, Any] | None,
    policy_report: dict[str, Any] | None,
) -> dict[str, Any]:
    for source in (live_report, live_gate, manual_handoff, material_report, policy_report):
        if not isinstance(source, dict):
            continue
        tool = source.get("recommended_tool")
        endpoint = source.get("recommended_endpoint")
        request = source.get("recommended_request")
        method = source.get("recommended_method") or source.get("method") or ("POST" if tool and request is not None else "GET" if tool else None)
        if tool or endpoint or request:
            return {
                "tool": tool,
                "endpoint": endpoint,
                "method": method,
                "request": request,
                "safe_to_call_now": source.get("safe_to_call_now") is True or (source.get("recommended_call") or {}).get("safe_to_call_now") is True,
                "requires_user_review": (source.get("recommended_call") or {}).get("requires_user_review") if isinstance(source.get("recommended_call"), dict) else True,
            }
    return {"tool": "get_job_summary", "endpoint": None, "method": "GET", "request": None, "safe_to_call_now": False, "requires_user_review": True}


def _manual_retorrent_final_next_actions(verdict: str, blockers: list[str], next_step: dict[str, Any], missing_confirmations: list[str]) -> list[str]:
    if verdict == "complete":
        return ["Report manual_retorrent_final_report plus live_validation_final_report evidence to the user."]
    if verdict == "duplicate_stopped":
        return ["Stop. Do not upload; report duplicate_check.dupes or choose another target."]
    if verdict == "running":
        return ["Poll job status, then read manual_retorrent_final_report again."]
    if verdict == "confirmations_required":
        return [f"Collect explicit confirmation for: {', '.join(missing_confirmations)}."]
    if verdict == "policy_blocked":
        return ["Resolve policy_execution_final_report before live automation."]
    if verdict == "materials_blocked":
        return ["Resolve material_preparation_final_report before target package or live upload."]
    if verdict in {"target_upload_pending", "resume_required"} and next_step.get("tool"):
        return [f"Use manual_retorrent_final_report.recommended_call with {next_step['tool']} after reviewing blockers and dry-run evidence."]
    if blockers:
        return ["Resolve manual_retorrent_final_report.blockers before continuing."]
    return ["Inspect manual_retorrent_final_report.read_order before choosing the next action."]


def _manual_retorrent_live_checklist(
    job: dict[str, Any],
    *,
    duplicate_clear: bool,
    missing_confirmations: list[str],
    policy_ready: bool | None,
    policy_enforcement_ready: bool | None,
    policy_runtime_ready: bool | None,
    qbit_limit_ready: bool | None,
    materials_handoff: dict[str, Any] | None,
    target_upload_handoff: dict[str, Any] | None,
) -> dict[str, Any]:
    source_reference = _job_source_reference(job)
    source_resolved = bool(source_reference.get("tracker") and (source_reference.get("source_id") or source_reference.get("source_url")))
    materials_ready = materials_handoff.get("ready") if isinstance(materials_handoff, dict) else None
    target_payload_ready = target_upload_handoff.get("ready_for_live_upload") if isinstance(target_upload_handoff, dict) else None
    uploaded_seeding_ready = target_upload_handoff.get("uploaded_seeding_ready") if isinstance(target_upload_handoff, dict) else None
    items = [
        _checklist_item("source_reference", source_resolved, required=True, blocker="source_reference.unresolved", evidence=source_reference),
        _checklist_item("target_duplicate_clear", duplicate_clear, required=True, blocker="duplicate_check.not_clear"),
        _checklist_item("confirmations", not missing_confirmations, required=True, blocker="confirmations.missing", missing=missing_confirmations),
        _checklist_item("site_policy", policy_ready is True, required=True, blocker="policy_coverage.not_ready", state="unknown" if policy_ready is None else "ready" if policy_ready else "blocked"),
        _checklist_item("policy_enforcement_bundle", policy_enforcement_ready is True, required=True, blocker="policy_enforcement_bundle.not_ready", state="unknown" if policy_enforcement_ready is None else "ready" if policy_enforcement_ready else "blocked"),
        _checklist_item("policy_runtime_contract", policy_runtime_ready is True, required=True, blocker="policy_runtime_contract.not_ready", state="unknown" if policy_runtime_ready is None else "ready" if policy_runtime_ready else "blocked"),
        _checklist_item("materials", materials_ready is True if materials_ready is not None else None, required=False, blocker="materials_handoff.not_ready"),
        _checklist_item("target_upload_payload", target_payload_ready is True if target_payload_ready is not None else None, required=False, blocker="target_upload_handoff.not_ready"),
        _checklist_item("uploaded_seeding", uploaded_seeding_ready is True if uploaded_seeding_ready is not None else None, required=False, blocker="target_upload_handoff.uploaded_seeding_not_ready"),
        _checklist_item("qbit_limit_audit", qbit_limit_ready is True if qbit_limit_ready is not None else None, required=False, blocker="qbit_limit_audit.not_ready"),
    ]
    blockers = _checklist_blockers(items)
    return {
        "kind": "ptcli.manual_retorrent_live_checklist",
        "ready": not blockers,
        "items": items,
        "blockers": blockers,
        "next_actions": [] if not blockers else ["Resolve manual_retorrent_handoff.live_checklist.blockers before attempting live upload."],
    }


def _checklist_item(key: str, ready: bool | None, *, required: bool, blocker: str, **extra: Any) -> dict[str, Any]:
    item = {
        "key": key,
        "ready": ready,
        "required": required,
        "blocker": blocker if ready is not True else None,
    }
    item.update({name: value for name, value in extra.items() if value not in (None, [], {})})
    return item


def _checklist_blockers(items: list[dict[str, Any]]) -> list[str]:
    return [str(item["blocker"]) for item in items if item.get("required") is True and item.get("ready") is not True and item.get("blocker")]


def _is_manual_retorrent_job(job: dict[str, Any], request: dict[str, Any]) -> bool:
    kind = str(job.get("kind") or "")
    mode = str(request.get("mode") or "")
    return kind in {"ptcli.manual_retorrent", "ptcli.source_url_retorrent", "ptcli.candidate_retorrent"} or mode in {"manual_retorrent", "source_url_retorrent", "candidate_retorrent"}


def _manual_retorrent_handoff_action(
    *,
    status: str,
    duplicate_exists: bool,
    missing_confirmations: list[str],
    policy_ready: bool | None,
    resume_plan: dict[str, Any],
    blockers: list[str],
) -> tuple[str, str | None]:
    if status in {"queued", "running"}:
        return "poll", "job_running"
    if duplicate_exists:
        return "stop_duplicate", "target_duplicate_exists"
    if missing_confirmations:
        return "collect_confirmations", "missing_required_confirmation"
    if policy_ready is False:
        return "configure_policy", "policy_coverage_incomplete"
    if status == "complete":
        return "done", None
    if status == "cancelled":
        return "stop", "job_cancelled"
    if resume_plan.get("recommended"):
        return "resume", None
    if blockers:
        return "resolve_blockers", "blocked_by_runtime_or_gate"
    return "inspect", "unknown_state"


def _manual_retorrent_handoff_next_actions(action: str, next_actions: list[str], missing_confirmations: list[str], resume_plan: dict[str, Any]) -> list[str]:
    if action == "poll":
        return ["Poll status_endpoint until status is no longer queued or running."]
    if action == "stop_duplicate":
        return ["Do not upload. Inspect duplicate_check.dupes or choose another target tracker."]
    if action == "collect_confirmations":
        return [f"Collect explicit confirmation for: {', '.join(missing_confirmations)}."]
    if action == "resume" and resume_plan.get("endpoint"):
        return [f"Call resume_endpoint {resume_plan['endpoint']} after reviewing blockers and site rules."]
    if next_actions:
        return next_actions
    return []


def _job_workflow_context(job: dict[str, Any], payload: dict[str, Any] | None = None) -> dict[str, Any]:
    request = job.get("request") if isinstance(job.get("request"), dict) else {}
    result = payload if isinstance(payload, dict) else job.get("result") if isinstance(job.get("result"), dict) else {}
    agent_summary = _agent_summary(result) or (job.get("agent_summary") if isinstance(job.get("agent_summary"), dict) else {}) or {}
    metadata = agent_summary.get("metadata") if isinstance(agent_summary.get("metadata"), dict) else {}
    materials = agent_summary.get("materials") if isinstance(agent_summary.get("materials"), dict) else {}
    target_preflight = agent_summary.get("target_preflight") if isinstance(agent_summary.get("target_preflight"), dict) else {}
    qbit = agent_summary.get("qbit") if isinstance(agent_summary.get("qbit"), dict) else {}
    qbit_source = qbit.get("source") if isinstance(qbit.get("source"), dict) else {}
    qbit_target = qbit.get("target") if isinstance(qbit.get("target"), dict) else {}
    duplicate_check = _job_duplicate_check(job)
    policy_coverage = _job_policy_coverage(job)
    resume_state = job.get("resume_state") if isinstance(job.get("resume_state"), dict) else _result_resume_state(result)
    next_command_argv = _result_next_command_argv(result)
    missing_confirmations = _missing_live_confirmations(request)
    duplicate_exists = duplicate_check.get("exists") is True
    duplicate_searched = duplicate_check.get("searched") is True
    policy_ready = policy_coverage.get("ready") if isinstance(policy_coverage, dict) else None
    resume_plan = _job_resume_plan(job)
    return {
        "workflow": job.get("kind"),
        "mode": request.get("mode"),
        "status": job.get("status"),
        "source_reference": _job_source_reference(job),
        "candidate_submission": _job_candidate_submission(job),
        "policy_config_apply_handoff": _job_policy_config_apply_handoff(job),
        "target_trackers": request.get("target_trackers"),
        "resume_lineage": _job_resume_lineage(job),
        "summary_file": job.get("summary_file"),
        "blockers": _string_list(job.get("blockers")),
        "next_actions": _string_list(job.get("next_actions")),
        "next_command_argv": next_command_argv,
        "gates": {
            "source_resolved": _job_source_reference(job) is not None,
            "duplicate_check": {
                "searched": duplicate_searched,
                "exists": duplicate_check.get("exists"),
                "status": duplicate_check.get("status"),
                "count": duplicate_check.get("count"),
                "clear": duplicate_searched and not duplicate_exists,
            },
            "policy_coverage_ready": policy_ready,
            "confirmations_ready": not missing_confirmations,
            "resume_available": bool(resume_plan.get("available")),
            "resume_allowed": bool(resume_plan.get("allowed")),
            "resume_recommended": bool(resume_plan.get("recommended")),
            "materials_ready": materials.get("ready_for_mteam_upload"),
            "target_preflight_ready": target_preflight.get("ready"),
            "qbit_source_ready": qbit_source.get("ready"),
            "qbit_target_ready": qbit_target.get("ready"),
            "uploaded_seeding_evidence": qbit_target.get("uploaded_wait_evidence"),
        },
        "metadata": {
            "ready": metadata.get("ready"),
            "imdb_ready": metadata.get("imdb_ready"),
            "tmdb_ready": metadata.get("tmdb_ready"),
            "douban_ready": metadata.get("douban_ready"),
            "ptgen_description_ready": metadata.get("ptgen_description_ready"),
            "missing": _string_list(metadata.get("missing")),
        },
        "materials": {
            "ready_for_mteam_upload": materials.get("ready_for_mteam_upload"),
            "critical_ready": materials.get("critical_ready"),
            "critical_missing": _string_list(materials.get("critical_missing")),
            "next_step": (materials.get("critical_path") or {}).get("next_step") if isinstance(materials.get("critical_path"), dict) else None,
            "mediainfo_or_bdinfo_ready": materials.get("mediainfo_or_bdinfo_ready"),
            "screenshots_ready": materials.get("screenshots_ready"),
            "screenshot_count": materials.get("screenshot_count"),
            "description_ready": materials.get("description_ready"),
            "upload_material_blockers": _string_list(materials.get("upload_material_blockers")),
        },
        "target_preflight": {
            "ready": target_preflight.get("ready"),
            "materials_ready": target_preflight.get("materials_ready"),
            "metadata_ready": target_preflight.get("metadata_ready"),
            "assets_ready": target_preflight.get("assets_ready"),
            "description_ready": target_preflight.get("description_ready"),
            "payload_ready": target_preflight.get("payload_ready"),
            "missing": _string_list(target_preflight.get("missing")),
            "description_missing": _string_list(target_preflight.get("description_missing")),
            "blockers": _string_list(target_preflight.get("blockers")),
        },
        "qbit": {
            "source": qbit_source,
            "target": qbit_target,
            "wait_diagnostics": qbit.get("wait_diagnostics") if isinstance(qbit.get("wait_diagnostics"), dict) else {},
        },
        "required_confirmations_missing": missing_confirmations,
        "policy_coverage": policy_coverage,
        "policy_handoff": _job_policy_handoff(job),
        "policy_qbit_defaults": _job_policy_qbit_defaults(job),
        "policy_execution_plan": _job_policy_execution_plan(job),
        "policy_enforcement_bundle": _job_policy_enforcement_bundle(job),
        "policy_runtime_contract": _job_policy_runtime_contract(job),
        "policy_application_handoff": _job_policy_application_handoff(job, payload if isinstance(payload, dict) else None),
        "policy_enforcement_gate": _job_policy_enforcement_gate(job),
        "qbit_plan": _job_qbit_plan(job),
        "qbit_limit_audit": _job_qbit_limit_audit(job, payload if isinstance(payload, dict) else None),
        "qbit_handoff": _job_qbit_handoff(job, payload if isinstance(payload, dict) else None),
        "qbit_enforcement_summary": _job_qbit_enforcement_summary(job, payload if isinstance(payload, dict) else None),
        "qbit_rate_limit_repair_plan": _job_qbit_rate_limit_repair_plan(job, payload if isinstance(payload, dict) else None),
        "policy_execution_report": _job_policy_execution_report(job, payload if isinstance(payload, dict) else None),
        "policy_execution_final_report": _job_policy_execution_final_report(job, payload if isinstance(payload, dict) else None),
        "qbit_execution_gate": _job_qbit_execution_gate(job, payload if isinstance(payload, dict) else None),
        "materials_handoff": _job_materials_handoff(job, payload if isinstance(payload, dict) else None),
        "material_gap_summary": _job_material_gap_summary(job, payload if isinstance(payload, dict) else None),
        "material_preparation_final_report": _job_material_preparation_final_report(job, payload if isinstance(payload, dict) else None),
        "target_upload_service_gate": _job_target_upload_service_gate(job, payload if isinstance(payload, dict) else None),
        "target_upload_handoff": _job_target_upload_handoff(job, payload if isinstance(payload, dict) else None),
        "live_completion_gate": _job_live_completion_gate(job, payload if isinstance(payload, dict) else None),
        "live_action_sequence": _job_live_action_sequence(job, payload if isinstance(payload, dict) else None),
        "manual_retorrent_handoff": _job_manual_retorrent_handoff(job, payload if isinstance(payload, dict) else None),
        "manual_retorrent_final_report": _job_manual_retorrent_final_report(job, payload if isinstance(payload, dict) else None),
        "candidate_submission_handoff": _job_candidate_submission_handoff(job, payload if isinstance(payload, dict) else None),
        "candidate_submission_summary": _job_candidate_submission_summary(job, payload if isinstance(payload, dict) else None),
        "candidate_submit_followup": _job_candidate_submit_followup(job, payload if isinstance(payload, dict) else None),
        "candidate_submit_sequence": _job_candidate_submit_sequence(job, payload if isinstance(payload, dict) else None),
        "resume_plan": resume_plan,
        "resume_requirements": _job_resume_requirements(job, payload if isinstance(payload, dict) else None),
        "resume_execution_handoff": _job_resume_execution_handoff(job, payload if isinstance(payload, dict) else None),
        "job_resume_handoff": _job_resume_handoff(job, payload if isinstance(payload, dict) else None),
        "resume_final_report": _job_resume_final_report(job, payload if isinstance(payload, dict) else None),
        "recovery_handoff": _job_recovery_handoff(job, payload if isinstance(payload, dict) else None),
        "resume_state": resume_state,
        "resume_context": _job_resume_context(job),
        "resume_summary": _job_resume_summary(job),
        "material_resolution": _job_material_resolution(job),
    }


def _job_resume_requirements(job: dict[str, Any], payload: dict[str, Any] | None = None) -> dict[str, Any]:
    request = job.get("request") if isinstance(job.get("request"), dict) else {}
    result = payload if isinstance(payload, dict) else job.get("result") if isinstance(job.get("result"), dict) else {}
    plan = _job_resume_plan(job)
    argv = plan.get("next_command_argv") if isinstance(plan.get("next_command_argv"), list) else None
    agent_summary = _agent_summary(result) or (job.get("agent_summary") if isinstance(job.get("agent_summary"), dict) else {}) or {}
    metadata = agent_summary.get("metadata") if isinstance(agent_summary.get("metadata"), dict) else {}
    materials = agent_summary.get("materials") if isinstance(agent_summary.get("materials"), dict) else {}
    target_preflight = agent_summary.get("target_preflight") if isinstance(agent_summary.get("target_preflight"), dict) else {}
    missing_confirmations = _missing_live_confirmations(request)
    suggested_overrides: dict[str, Any] = {}
    required_overrides: list[str] = []
    if "accept_rules=true" in missing_confirmations:
        suggested_overrides["accept_rules"] = True
        required_overrides.append("accept_rules")
    if "confirm_upload=true" in missing_confirmations:
        suggested_overrides["confirm_upload"] = True
        required_overrides.append("confirm_upload")

    recommended_inputs = _resume_recommended_inputs(request, metadata, materials, target_preflight)
    request_template = _resume_request_template(plan, suggested_overrides)
    return {
        "kind": "ptcli.resume_requirements",
        "can_call_resume": bool(plan.get("allowed")),
        "resume_recommended": bool(plan.get("recommended")),
        "subcommand": plan.get("subcommand"),
        "endpoint": plan.get("endpoint"),
        "method": "POST",
        "missing_confirmations": missing_confirmations,
        "required_overrides": required_overrides,
        "suggested_overrides": suggested_overrides,
        "request_template": request_template,
        "dry_run_request": {**request_template, "dry_run": True},
        "execute_request": request_template,
        "recommended_inputs": recommended_inputs,
        "allowed_overrides": {
            "boolean": sorted(RESUME_BOOLEAN_FLAG_OVERRIDES),
            "value": sorted(RESUME_VALUE_FLAG_OVERRIDES),
            "repeatable": sorted(RESUME_REPEATABLE_FLAG_OVERRIDES),
        },
        "current_flags": _resume_current_flags(argv),
        "ignored_override_policy": "Unknown override keys are ignored and reported in resume_context.ignored_overrides.",
        "blocker": plan.get("blocker"),
    }


def _resume_request_template(plan: dict[str, Any], suggested_overrides: dict[str, Any]) -> dict[str, Any]:
    template: dict[str, Any] = {}
    if plan.get("parent_job_id"):
        template["job_id"] = plan.get("parent_job_id")
    template.update(suggested_overrides)
    return template


def _resume_recommended_inputs(
    request: dict[str, Any],
    metadata: dict[str, Any],
    materials: dict[str, Any],
    target_preflight: dict[str, Any],
) -> list[dict[str, Any]]:
    inputs: list[dict[str, Any]] = []
    critical_missing = _string_list(materials.get("critical_missing"))
    upload_material_blockers = _string_list(materials.get("upload_material_blockers"))
    target_missing = _string_list(target_preflight.get("missing"))
    target_description_missing = _string_list(target_preflight.get("description_missing"))
    target_blockers = _string_list(target_preflight.get("blockers"))
    all_missing = set(_string_list(metadata.get("missing")) + critical_missing + upload_material_blockers + target_missing + target_description_missing + target_blockers)
    if not request.get("path") and not request.get("save_path"):
        inputs.append(
            _recommended_input(
                "path_or_save_path",
                ["path", "content_path", "save_path"],
                "content path helps resume without rediscovering qBittorrent state",
                stage="source-content",
                examples={"path": "/downloads/Example.Movie.2024", "save_path": "/downloads"},
            )
        )
    metadata_missing_keys = {"metadata.imdb", "metadata.tmdb", "metadata.douban", "materials.metadata.imdb", "materials.metadata.tmdb", "materials.metadata.douban"}
    if metadata.get("imdb_ready") is False or metadata.get("tmdb_ready") is False or metadata.get("douban_ready") is False or any(key in all_missing for key in metadata_missing_keys):
        inputs.append(
            _recommended_input(
                "metadata_file",
                ["metadata_file", "imdb_id", "tmdb_id", "tmdb_type", "douban_id", "douban_url", "enrich_metadata", "fetch_ptgen"],
                "IMDb/TMDb/豆瓣 metadata is incomplete; provide IDs/file or let ptcli enrich it before target package preparation",
                stage="materials-metadata",
                blocking_keys=sorted(key for key in metadata_missing_keys if key in all_missing),
                examples={"metadata_file": "/tmp/materials/metadata.json", "imdb_id": "tt1234567", "tmdb_id": "999", "tmdb_type": "movie", "douban_id": "1291546", "fetch_ptgen": True},
            )
        )
    description_missing_keys = {"description.content", "materials.description.ptgen_description", "materials.description.external_ids.tmdb", "materials.description.external_ids.imdb", "materials.description.external_ids.douban"}
    if metadata.get("ptgen_description_ready") is False or target_preflight.get("description_ready") is False or any(key in all_missing for key in description_missing_keys):
        inputs.append(
            _recommended_input(
                "ptgen_description_file",
                ["ptgen_description_file", "metadata_file", "fetch_ptgen", "enrich_metadata", "douban_id", "douban_url"],
                "target description/PTGen content is incomplete",
                stage="materials-description",
                blocking_keys=sorted(key for key in description_missing_keys if key in all_missing),
                examples={"ptgen_description_file": "/tmp/materials/ptgen-description.txt", "fetch_ptgen": True, "douban_url": "https://movie.douban.com/subject/1291546/"},
            )
        )
    if materials.get("mediainfo_or_bdinfo_ready") is False:
        inputs.append(
            _recommended_input(
                "mediainfo_or_bdinfo",
                ["mediainfo_file", "bdinfo_file", "generate_mediainfo", "generate_bdinfo"],
                "MediaInfo or BDInfo evidence is missing",
                stage="materials-media-info",
                blocking_keys=["materials.description.mediainfo_or_bdinfo"],
                examples={"mediainfo_file": "/tmp/materials/MI_FULL_00.txt", "bdinfo_file": "/tmp/materials/BDINFO.txt", "generate_mediainfo": True},
            )
        )
    if materials.get("screenshots_ready") is False:
        inputs.append(
            _recommended_input(
                "screenshot_files",
                ["screenshot_files", "screenshot_file", "generate_screenshots", "screenshot_count"],
                "screenshots are missing or insufficient",
                stage="materials-screenshots",
                blocking_keys=["materials.description.screenshot_bbcode"],
                examples={"screenshot_files": ["/tmp/materials/screen-01.png", "/tmp/materials/screen-02.png"], "generate_screenshots": True, "screenshot_count": "4"},
            )
        )
    image_host_missing_keys = {"assets.image_host_uploads", "materials.assets.image_host_uploads", "description.screenshot_coverage", "materials.description.screenshot_coverage"}
    if any(key in all_missing for key in image_host_missing_keys):
        inputs.append(
            _recommended_input(
                "image_host_file",
                ["image_host_file", "upload_screenshots", "image_host"],
                "hosted screenshot URLs are missing, partial, or stale",
                stage="materials-image-host",
                blocking_keys=sorted(key for key in image_host_missing_keys if key in all_missing),
                examples={"image_host_file": "/tmp/materials/image-host-uploads.json", "upload_screenshots": True, "image_host": "ptpimg"},
            )
        )
    if target_preflight.get("payload_ready") is False and request.get("package_dir"):
        inputs.append(
            _recommended_input(
                "package_dir",
                ["package_dir"],
                "reuse or replace the target upload package directory",
                stage="target-package",
                examples={"package_dir": "/tmp/target/U2-60635-to-MTEAM"},
            )
        )
    return inputs


def _resume_current_flags(argv: list[Any] | None) -> dict[str, Any]:
    argv = [str(item) for item in argv or []]
    return {
        "has_accept_rules": "--accept-rules" in argv,
        "has_confirm_upload": "--confirm-upload" in argv,
        "has_path": "--path" in argv,
        "has_save_path": "--save-path" in argv,
        "has_package_dir": "--package-dir" in argv,
        "has_screenshot_files": "--screenshot-file" in argv,
        "has_uploaded_torrent_file": "--uploaded-torrent-file" in argv,
    }


def _job_resume_plan(job: dict[str, Any]) -> dict[str, Any]:
    job_id = job.get("job_id")
    status = str(job.get("status") or "unknown")
    argv = _resume_argv_from_job(job)
    allowed, reason = _resume_command_allowed(argv)
    available = bool(argv)
    recommended = status in {"blocked", "failed"} and allowed
    endpoint = f"/v1/jobs/{job_id}/resume" if job_id else None
    if status in {"queued", "running"}:
        recommended = False
        if available:
            reason = f"Job is still {status}; wait before resuming."
    return {
        "available": available,
        "allowed": bool(allowed),
        "recommended": recommended,
        "endpoint": endpoint,
        "method": "POST",
        "status": status,
        "subcommand": _ptcli_subcommand(argv or []),
        "next_command_argv": argv,
        "blocker": reason,
        "parent_job_id": job_id,
    }


def _resume_preview(parent: dict[str, Any], request: dict[str, Any], argv: list[str] | None, *, allowed: bool, reason: str | None) -> dict[str, Any]:
    parent_job_id = str(parent.get("job_id") or "")
    blockers = [] if allowed else [reason or "No executable resume command is available."]
    payload = {
        "kind": "ptcli.resume_preview",
        "status": "ok" if allowed else "blocked",
        "ok": bool(allowed),
        "dry_run": True,
        "mutates_state": False,
        "live_upload": "--confirm-upload" in (argv or []),
        "parent_job_id": parent_job_id,
        "parent_status": parent.get("status"),
        "parent_kind": parent.get("kind"),
        "command_argv": argv or [],
        "original_next_command_argv": request.get("original_next_command_argv"),
        "resume_allowed": bool(allowed),
        "resume_blocker": reason,
        "resume_overrides": request.get("resume_overrides"),
        "applied_overrides": request.get("applied_overrides"),
        "ignored_overrides": request.get("ignored_overrides"),
        "material_resolution": request.get("material_resolution"),
        "resume_context": request.get("resume_context"),
        "resume_lineage": request.get("resume_lineage"),
        "resume_audit": _resume_audit_from_request(parent, request, argv, allowed=allowed, reason=reason),
        "resume_plan": _job_resume_plan(parent),
        "resume_requirements": _job_resume_requirements(parent),
        "source_reference": _job_source_reference(parent),
        "workflow_context": _job_workflow_context(parent),
        "blockers": blockers,
        "next_actions": _resume_preview_next_actions(allowed, blockers, parent_job_id),
    }
    payload["agent_decision"] = {
        "decision": "resume_preview" if allowed else "blocked",
        "should_resume": bool(allowed),
        "dry_run": True,
        "mutates_state": False,
        "resume_allowed": bool(allowed),
        "resume_blocker": reason,
        "command_argv": argv or [],
        "blockers": blockers,
        "next_actions": payload["next_actions"],
    }
    return payload


def _resume_audit_from_request(parent: dict[str, Any], request: dict[str, Any], argv: list[str] | None, *, allowed: bool, reason: str | None) -> dict[str, Any]:
    preview_job = {
        "job_id": parent.get("job_id"),
        "kind": parent.get("kind"),
        "status": parent.get("status"),
        "request": {
            **request,
            "resume_lineage": request.get("resume_lineage"),
            "resume_context": request.get("resume_context"),
        },
        "result": {"next_command_argv": argv},
    }
    audit = _job_resume_audit(preview_job)
    audit.update(
        {
            "kind": "ptcli.resume_preview_audit",
            "dry_run": True,
            "resume_allowed": bool(allowed),
            "resume_blocker": reason,
            "next_command_argv": argv or [],
        }
    )
    return audit


def _resume_preview_next_actions(allowed: bool, blockers: list[str], parent_job_id: str) -> list[str]:
    if allowed:
        return [f"Review command_argv, then call /v1/jobs/{parent_job_id}/resume without dry_run when ready."]
    if blockers:
        return ["Resolve resume_preview.blockers before executing resume."]
    return ["Inspect resume_preview before executing resume."]


def _resume_lineage(parent: dict[str, Any], *, parent_job_id: str, argv: list[str] | None, allowed: bool, reason: str | None) -> dict[str, Any]:
    parent_workflow_context = _job_workflow_context(parent)
    parent_duplicate_check = _job_duplicate_check(parent)
    return {
        "parent_job_id": parent_job_id,
        "parent_kind": parent.get("kind"),
        "parent_status": parent.get("status"),
        "parent_summary_file": _job_summary_file(parent),
        "parent_source_reference": _job_source_reference(parent),
        "parent_target_trackers": (parent.get("request") or {}).get("target_trackers") if isinstance(parent.get("request"), dict) else None,
        "parent_duplicate_check": parent_duplicate_check,
        "parent_workflow_context": {
            "workflow": parent_workflow_context.get("workflow"),
            "mode": parent_workflow_context.get("mode"),
            "status": parent_workflow_context.get("status"),
            "source_reference": parent_workflow_context.get("source_reference"),
            "target_trackers": parent_workflow_context.get("target_trackers"),
            "summary_file": parent_workflow_context.get("summary_file"),
            "gates": parent_workflow_context.get("gates"),
        },
        "parent_materials_handoff": _job_materials_handoff(parent),
        "inherited_policy": {
            "policy_coverage": _job_policy_coverage(parent),
            "policy_qbit_defaults": _job_policy_qbit_defaults(parent),
            "policy_enforcement_bundle": _job_policy_enforcement_bundle(parent),
            "policy_enforcement_gate": _job_policy_enforcement_gate(parent),
        },
        "resume_allowed": allowed,
        "resume_blocker": reason,
        "next_command_argv": argv,
        "next_subcommand": _ptcli_subcommand(argv or []),
    }


def _resume_context(parent: dict[str, Any], *, parent_job_id: str, argv: list[str] | None, allowed: bool, reason: str | None) -> dict[str, Any]:
    lineage = _resume_lineage(parent, parent_job_id=parent_job_id, argv=argv, allowed=allowed, reason=reason)
    return {
        "parent_job_id": parent_job_id,
        "parent_kind": parent.get("kind"),
        "parent_status": parent.get("status"),
        "resume_allowed": allowed,
        "resume_blocker": reason,
        "next_command_argv": argv,
        "parent_summary_file": _job_summary_file(parent),
        "parent_source_reference": lineage.get("parent_source_reference"),
        "parent_workflow_context": lineage.get("parent_workflow_context"),
        "parent_materials_handoff": lineage.get("parent_materials_handoff"),
        "parent_next_actions": _string_list(parent.get("next_actions")),
        "inherited_policy": lineage.get("inherited_policy"),
    }


def _resume_material_resolution(parent: dict[str, Any], override_result: dict[str, Any]) -> dict[str, Any] | None:
    materials_handoff = _job_materials_handoff(parent)
    if not isinstance(materials_handoff, dict):
        return None
    recommended_inputs = materials_handoff.get("recommended_inputs") if isinstance(materials_handoff.get("recommended_inputs"), list) else []
    applied_keys = [
        str(item.get("key"))
        for item in override_result.get("applied", [])
        if isinstance(item, dict) and item.get("key")
    ]
    ignored_keys = [
        str(item.get("key"))
        for item in override_result.get("ignored", [])
        if isinstance(item, dict) and item.get("key")
    ]
    covered: list[str] = []
    unresolved: list[dict[str, Any]] = []
    for item in recommended_inputs:
        if not isinstance(item, dict):
            continue
        key = str(item.get("key") or "")
        accepted_keys = [str(value) for value in _string_list(item.get("accepted_keys"))]
        if key in applied_keys or any(accepted_key in applied_keys for accepted_key in accepted_keys):
            covered.append(key)
        else:
            unresolved.append(item)
    return {
        "kind": "ptcli.resume_material_resolution",
        "ready_before_resume": materials_handoff.get("ready"),
        "parent_materials_handoff": materials_handoff,
        "recommended_inputs": recommended_inputs,
        "applied_override_keys": applied_keys,
        "ignored_override_keys": ignored_keys,
        "covered_recommended_inputs": covered,
        "unresolved_recommended_inputs": unresolved,
        "blockers_before_resume": _string_list(materials_handoff.get("blockers")),
        "next_actions": _resume_material_resolution_next_actions(unresolved, applied_keys, ignored_keys),
    }


def _resume_material_resolution_next_actions(unresolved: list[dict[str, Any]], applied_keys: list[str], ignored_keys: list[str]) -> list[str]:
    if unresolved:
        keys = ", ".join(str(item.get("key")) for item in unresolved if isinstance(item, dict) and item.get("key"))
        return [f"Resume was accepted, but these recommended material inputs were not provided yet: {keys}."]
    if applied_keys:
        return ["Resume command includes material overrides; poll the resumed job and inspect materials_handoff/target_preflight for validation."]
    if ignored_keys:
        return ["Resume ignored some provided material overrides; inspect ignored_override_keys and retry with allowed override names."]
    return []


def _agent_candidate_decision(
    job: dict[str, Any],
    result: dict[str, Any],
    request: dict[str, Any],
    status: str,
    blockers: list[str],
    next_actions: list[str],
) -> dict[str, Any] | None:
    if str(job.get("kind") or "") != "ptcli.daily_candidates" and not _candidate_payload(result):
        return None
    digest = _candidate_digest_from_payload(result) or {}
    top_submit_request = digest.get("top_submit_request") if isinstance(digest.get("top_submit_request"), dict) else None
    top_candidate = digest.get("top_candidate") if isinstance(digest.get("top_candidate"), dict) else {}
    top_policy_summary = top_candidate.get("policy_summary") if isinstance(top_candidate.get("policy_summary"), dict) else {}
    policy_coverage = top_policy_summary.get("policy_coverage") if isinstance(top_policy_summary.get("policy_coverage"), dict) else {}
    policy_coverage_ready = policy_coverage.get("ready") if isinstance(policy_coverage.get("ready"), bool) else None
    ready_count = int(digest.get("ready_count") or 0)
    if status in {"queued", "running"}:
        decision = "wait"
        stop_reason = None
        recommended_action = "Poll get_job_status until the daily candidate job is complete."
    elif top_submit_request and ready_count > 0 and policy_coverage_ready is False:
        decision = "configure_policy"
        stop_reason = "policy_coverage_incomplete"
        recommendations = _string_list(policy_coverage.get("recommendations"))
        recommended_action = recommendations[0] if recommendations else "Complete policy_coverage missing fields before submitting the top candidate."
    elif top_submit_request and ready_count > 0:
        decision = "submit_candidate_when_confirmed"
        stop_reason = None
        recommended_action = "Review digest.top_candidate and site rules, add confirm_upload=true plus a save_path or path, then submit digest.top_submit_request to source_url_retorrent_job."
    elif blockers or digest.get("recommendation") == "resolve_blockers":
        decision = "blocked"
        stop_reason = "candidate_blockers"
        recommended_action = next_actions[0] if next_actions else "Resolve digest.blockers before submitting any candidate."
    else:
        decision = "inspect"
        stop_reason = "no_ready_candidate"
        recommended_action = "Inspect digest.push_items and rerun later or adjust source/target filters."
    return {
        "workflow": job.get("kind"),
        "status": status,
        "decision": decision,
        "recommended_action": recommended_action,
        "stop_reason": stop_reason,
        "candidate_digest": digest,
        "top_submit_request": top_submit_request,
        "top_submit_job_endpoint": digest.get("top_submit_job_endpoint"),
        "top_submit_tool": digest.get("top_submit_tool"),
        "ready_count": ready_count,
        "policy_coverage": policy_coverage or None,
        "policy_coverage_ready": policy_coverage_ready,
        "runtime": _job_runtime(job),
        "missing_confirmations": _missing_live_confirmations(top_submit_request or request),
        "can_submit_job": bool(top_submit_request and ready_count > 0 and policy_coverage_ready is not False),
        "should_poll": status in {"queued", "running"},
        "should_resume": False,
        "resume_available": False,
        "summary_file": job.get("summary_file"),
        "blocker_count": len(blockers),
    }


def _agent_decision(job: dict[str, Any]) -> dict[str, Any]:
    result = job.get("result") if isinstance(job.get("result"), dict) else {}
    request = job.get("request") if isinstance(job.get("request"), dict) else {}
    status = str(job.get("status") or "unknown")
    blockers = _string_list(job.get("blockers"))
    next_actions = _string_list(job.get("next_actions"))
    candidate_decision = _agent_candidate_decision(job, result, request, status, blockers, next_actions)
    if candidate_decision:
        return candidate_decision
    duplicate_check = _job_duplicate_check(job)
    next_command_argv = _result_next_command_argv(result)
    resume_context = _job_resume_context(job)
    resume_lineage = _job_resume_lineage(job)
    material_resolution = _job_material_resolution(job)
    source_reference = _job_source_reference(job)
    manual_retorrent_handoff = _job_manual_retorrent_handoff(job)
    manual_retorrent_final_report = _job_manual_retorrent_final_report(job)
    report_job = dict(job)
    if isinstance(manual_retorrent_final_report, dict):
        report_job["manual_retorrent_final_report"] = manual_retorrent_final_report
    workflow_context = _job_workflow_context(report_job)
    materials_handoff = _job_materials_handoff(job)
    metadata_prepare_handoff = _job_metadata_prepare_handoff(job)
    materials_prepare_handoff = _job_materials_prepare_handoff(job)
    retorrent_stage_handoff = _job_retorrent_stage_handoff(job)
    target_package_handoff = _job_target_package_handoff(job)
    target_upload_handoff = _job_target_upload_handoff(job)
    material_preparation_final_report = _job_material_preparation_final_report(job)
    closure_handoff = _job_closure_handoff(job)
    candidate_submission_handoff = _job_candidate_submission_handoff(report_job)
    candidate_submission_summary = _job_candidate_submission_summary(report_job)
    candidate_submit_followup = _job_candidate_submit_followup(report_job)
    candidate_submit_sequence = _job_candidate_submit_sequence(report_job)
    candidate_execution_context = candidate_submission_summary.get("candidate_execution_context") if isinstance(candidate_submission_summary, dict) and isinstance(candidate_submission_summary.get("candidate_execution_context"), dict) else None
    candidate_submission_execution = candidate_submission_summary.get("execution_handoff") if isinstance(candidate_submission_summary, dict) and isinstance(candidate_submission_summary.get("execution_handoff"), dict) else None
    resume_plan = _job_resume_plan(job)
    resume_summary = _job_resume_summary(job)
    submit_if_clear_handoff = _job_submit_if_clear_handoff(job)
    missing_confirmations = _missing_live_confirmations(request)
    policy_coverage = _job_policy_coverage(job) if request.get("execute") is True or request.get("execute_if_no_duplicate") is True or request.get("mode") == "manual_retorrent" else None
    policy_handoff = _job_policy_handoff(job) if policy_coverage is not None else None
    policy_qbit_defaults = _job_policy_qbit_defaults(job) if request.get("execute") is True or request.get("execute_if_no_duplicate") is True or request.get("mode") == "manual_retorrent" else None
    policy_execution_plan = _job_policy_execution_plan(job) if request.get("execute") is True or request.get("execute_if_no_duplicate") is True or request.get("mode") == "manual_retorrent" else None
    policy_enforcement_bundle = _job_policy_enforcement_bundle(job) if policy_execution_plan is not None else None
    policy_runtime_contract = _job_policy_runtime_contract(job) if policy_execution_plan is not None else None
    policy_application_handoff = _job_policy_application_handoff(job) if policy_execution_plan is not None else None
    policy_enforcement_gate = _job_policy_enforcement_gate(job) if policy_enforcement_bundle is not None else None
    qbit_plan = _job_qbit_plan(job) if policy_qbit_defaults is not None else None
    qbit_limit_audit = _job_qbit_limit_audit(job) if qbit_plan is not None else None
    qbit_handoff = _job_qbit_handoff(job) if qbit_plan is not None else None
    qbit_enforcement_summary = _job_qbit_enforcement_summary(job) if qbit_plan is not None else None
    qbit_rate_limit_repair_plan = _job_qbit_rate_limit_repair_plan(job) if qbit_plan is not None else None
    policy_execution_report = _job_policy_execution_report(job) if qbit_plan is not None or policy_handoff is not None else None
    policy_execution_final_report = _job_policy_execution_final_report(job) if policy_execution_report is not None else None
    qbit_execution_gate = _job_qbit_execution_gate(job) if qbit_plan is not None else None
    live_completion_gate = _job_live_completion_gate(job)
    live_user_report = _job_live_user_report(job)
    live_action_sequence = _job_live_action_sequence(job)
    policy_coverage_ready = policy_coverage.get("ready") if isinstance(policy_coverage, dict) and isinstance(policy_coverage.get("ready"), bool) else None
    policy_coverage_incomplete = policy_coverage_ready is False
    policy_enforcement_blocked = isinstance(policy_enforcement_gate, dict) and policy_enforcement_gate.get("ready") is False
    policy_runtime_blocked = isinstance(policy_runtime_contract, dict) and policy_runtime_contract.get("ready") is False
    policy_application_blocked = isinstance(policy_application_handoff, dict) and policy_application_handoff.get("ready") is False and (
        bool(policy_application_handoff.get("missing_request_fields"))
        or bool(policy_application_handoff.get("missing_protected_fields"))
        or bool(policy_application_handoff.get("missing_confirmations"))
    )
    duplicate_exists = duplicate_check.get("exists") is True
    resume_available = bool(resume_plan.get("available"))
    resume_requirements = _job_resume_requirements(job)
    should_poll = status in {"queued", "running"}
    should_resume = bool(resume_plan.get("recommended")) and not duplicate_exists and not missing_confirmations and not policy_coverage_incomplete and not policy_enforcement_blocked and not policy_runtime_blocked and not policy_application_blocked
    can_attempt_live = not duplicate_exists and not missing_confirmations and not policy_coverage_incomplete and not policy_enforcement_blocked and not policy_runtime_blocked and not policy_application_blocked and status not in {"queued", "running", "cancelled"}

    if should_poll:
        decision = "wait"
        stop_reason = None
        recommended_action = "Poll get_job_status until the job is no longer queued or running."
    elif job.get("kind") == "ptcli.materials_prepare" and status == "complete":
        decision = "materials_ready"
        stop_reason = None
        recommended_action = "Use materials_prepare_handoff.material_options as job creation fields or resume_job overrides after duplicate/rule/confirmation gates are ready."
    elif job.get("kind") == "ptcli.metadata_prepare" and status == "complete":
        decision = "metadata_ready"
        stop_reason = None
        recommended_action = "Use metadata_prepare_handoff.material_options as metadata/material fields for materials_prepare, source_url_check_and_submit, or resume_job after duplicate/rule/confirmation gates are ready."
    elif job.get("kind") == "ptcli.target_package_prepare" and status == "complete":
        decision = "target_package_ready"
        stop_reason = None
        recommended_action = "Use target_package_handoff.target_upload_request for target upload preflight with an MTEAM-safe torrent file; live upload still requires confirm_upload and seeding closure."
    elif job.get("kind") == "ptcli.target_upload" and status == "complete":
        if isinstance(target_upload_handoff, dict) and target_upload_handoff.get("uploaded_seeding_ready"):
            decision = "target_upload_complete"
            stop_reason = None
            recommended_action = "Target upload and uploaded torrent seeding closure are complete; report summary_file and qBittorrent evidence."
        else:
            decision = "target_upload_followup_required"
            stop_reason = None
            recommended_action = "Follow target_upload_handoff.next_step until uploaded target torrent download, qBittorrent injection, and wait evidence are complete."
    elif isinstance(retorrent_stage_handoff, dict) and retorrent_stage_handoff.get("ready") is True and retorrent_stage_handoff.get("action") in {"prepare_target_package", "target_upload_closure"}:
        decision = str(retorrent_stage_handoff["action"])
        stop_reason = None
        recommended_action = f"Use retorrent_stage_handoff.recommended_request with {retorrent_stage_handoff.get('recommended_tool')} after reviewing blockers and site rules."
    elif duplicate_exists:
        decision = "stop"
        stop_reason = "target_duplicate_exists"
        recommended_action = "Do not upload. Inspect duplicate_check.dupes or choose a different target."
    elif missing_confirmations:
        decision = "ask_confirmation"
        stop_reason = "missing_required_confirmation"
        recommended_action = f"Collect explicit confirmation for: {', '.join(missing_confirmations)}."
    elif _is_retorrent_check_job(job) and isinstance(submit_if_clear_handoff, dict) and submit_if_clear_handoff.get("ready"):
        decision = "submit_if_clear"
        stop_reason = None
        recommended_action = "Target duplicate check is clear; submit submit_if_clear_handoff.request to source_url_retorrent_job after reviewing site rules."
    elif status == "complete":
        decision = "done"
        stop_reason = None
        recommended_action = "Retorrent workflow is complete; inspect summary_file and seeding evidence."
    elif status == "cancelled":
        decision = "stop"
        stop_reason = "job_cancelled"
        recommended_action = "Submit a new job if the work is still needed; cancelled jobs are terminal."
    elif policy_coverage_incomplete:
        decision = "configure_policy"
        stop_reason = "policy_coverage_incomplete"
        recommendations = _string_list(policy_coverage.get("recommendations")) if isinstance(policy_coverage, dict) else []
        recommended_action = recommendations[0] if recommendations else "Complete policy_coverage missing fields before attempting live retorrent automation."
    elif policy_enforcement_blocked:
        decision = "configure_policy_enforcement"
        stop_reason = "policy_enforcement_gate_blocked"
        gate_actions = _string_list(policy_enforcement_gate.get("next_actions")) if isinstance(policy_enforcement_gate, dict) else []
        recommended_action = gate_actions[0] if gate_actions else "Resolve policy_enforcement_gate.blockers before attempting live retorrent automation."
    elif policy_runtime_blocked:
        decision = "configure_policy_runtime"
        stop_reason = "policy_runtime_contract_blocked"
        runtime_actions = _string_list(policy_runtime_contract.get("next_actions")) if isinstance(policy_runtime_contract, dict) else []
        recommended_action = runtime_actions[0] if runtime_actions else "Resolve policy_runtime_contract.blockers before attempting live retorrent automation."
    elif policy_application_blocked:
        decision = "apply_policy_defaults"
        stop_reason = "policy_application_handoff_blocked"
        application_actions = _string_list(policy_application_handoff.get("next_actions")) if isinstance(policy_application_handoff, dict) else []
        recommended_action = application_actions[0] if application_actions else "Apply policy_application_handoff.request_patch before attempting live retorrent automation."
    elif should_resume:
        decision = "resume"
        stop_reason = None
        recommended_action = "Call resume_job or run the allowlisted next_command_argv."
    elif blockers:
        decision = "blocked"
        stop_reason = "blocked_by_runtime_or_gate"
        recommended_action = next_actions[0] if next_actions else "Inspect blockers and resolve the missing runtime, credential, rule, metadata, or qBittorrent evidence."
    else:
        decision = "inspect"
        stop_reason = "unknown_state"
        recommended_action = "Inspect result, summary_file, and logs before taking live action."

    return {
        "workflow": job.get("kind"),
        "status": status,
        "decision": decision,
        "recommended_action": recommended_action,
        "stop_reason": stop_reason,
        "duplicate_check": duplicate_check,
        "submit_if_clear_handoff": submit_if_clear_handoff,
        "missing_confirmations": missing_confirmations,
        "policy_coverage": policy_coverage,
        "policy_handoff": policy_handoff,
        "policy_qbit_defaults": policy_qbit_defaults,
        "policy_execution_plan": policy_execution_plan,
        "policy_enforcement_bundle": policy_enforcement_bundle,
        "policy_runtime_contract": policy_runtime_contract,
        "policy_application_handoff": policy_application_handoff,
        "policy_enforcement_gate": policy_enforcement_gate,
        "qbit_plan": qbit_plan,
        "qbit_limit_audit": qbit_limit_audit,
        "qbit_handoff": qbit_handoff,
        "qbit_enforcement_summary": qbit_enforcement_summary,
        "qbit_rate_limit_repair_plan": qbit_rate_limit_repair_plan,
        "policy_execution_report": policy_execution_report,
        "policy_execution_final_report": policy_execution_final_report,
        "qbit_execution_gate": qbit_execution_gate,
        "live_completion_gate": live_completion_gate,
        "live_user_report": live_user_report,
        "live_action_sequence": live_action_sequence,
        "materials_handoff": materials_handoff,
        "metadata_prepare_handoff": metadata_prepare_handoff,
        "materials_prepare_handoff": materials_prepare_handoff,
        "retorrent_stage_handoff": retorrent_stage_handoff,
        "target_package_handoff": target_package_handoff,
        "target_upload_handoff": target_upload_handoff,
        "material_preparation_final_report": material_preparation_final_report,
        "closure_handoff": closure_handoff,
        "policy_coverage_ready": policy_coverage_ready,
        "runtime": _job_runtime(job),
        "cancellation": job.get("cancellation") if isinstance(job.get("cancellation"), dict) else None,
        "can_attempt_live": can_attempt_live,
        "should_poll": should_poll,
        "should_resume": should_resume,
        "resume_available": resume_available,
        "resume_plan": resume_plan,
        "resume_requirements": resume_requirements,
        "resume_summary": resume_summary,
        "resume_lineage": resume_lineage,
        "resume_context": resume_context,
        "material_resolution": material_resolution,
        "candidate_execution_context": candidate_execution_context,
        "candidate_submission_execution": candidate_submission_execution,
        "material_input_template": candidate_submission_execution.get("material_input_template") if isinstance(candidate_submission_execution, dict) else None,
        "candidate_submission": _job_candidate_submission(job),
        "check_submission": _job_check_submission(job),
        "candidate_submission_summary": candidate_submission_summary,
        "candidate_submit_followup": candidate_submit_followup,
        "candidate_submit_sequence": candidate_submit_sequence,
        "source_reference": source_reference,
        "workflow_context": workflow_context,
        "manual_retorrent_handoff": manual_retorrent_handoff,
        "manual_retorrent_final_report": manual_retorrent_final_report,
        "candidate_submission_handoff": candidate_submission_handoff,
        "next_command_argv": next_command_argv,
        "summary_file": job.get("summary_file"),
        "blocker_count": len(blockers),
    }


def _job_duplicate_check(job: dict[str, Any]) -> dict[str, Any]:
    duplicate_check = job.get("duplicate_check")
    if isinstance(duplicate_check, dict):
        return duplicate_check
    result = job.get("result")
    if isinstance(result, dict):
        nested_duplicate_check = result.get("duplicate_check")
        if isinstance(nested_duplicate_check, dict):
            return nested_duplicate_check
        return _duplicate_check(result)
    return {"searched": False, "status": "unknown", "exists": None, "count": None, "dupes": []}


def _is_retorrent_check_job(job: dict[str, Any]) -> bool:
    kind = str(job.get("kind") or "")
    request = job.get("request") if isinstance(job.get("request"), dict) else {}
    return kind in {"ptcli.retorrent_check"} or (kind == "ptcli.retorrent" and request.get("execute") is not True)


def _missing_live_confirmations(request: dict[str, Any]) -> list[str]:
    if request.get("execute") is not True and request.get("execute_if_no_duplicate") is not True and request.get("mode") != "manual_retorrent":
        return []
    missing: list[str] = []
    if request.get("accept_rules") is not True:
        missing.append("accept_rules=true")
    if request.get("confirm_upload") is not True:
        missing.append("confirm_upload=true")
    return missing


def _job_status_from_result(result: dict[str, Any]) -> str:
    status = str(result.get("status") or "")
    if status == "error":
        return "failed"
    if status == "blocked":
        return "blocked"
    if result.get("ok") is False and _result_blockers(result):
        return "blocked"
    return "complete"


def _result_summary_file(result: Any) -> str | None:
    if not isinstance(result, dict):
        return None
    summary_file = result.get("summary_file")
    if summary_file:
        return str(summary_file)
    nested = result.get("result")
    if isinstance(nested, dict) and nested.get("summary_file"):
        return str(nested["summary_file"])
    pipeline = result.get("pipeline")
    if isinstance(pipeline, dict) and pipeline.get("summary_file"):
        return str(pipeline["summary_file"])
    return None


def _job_summary_file(job: dict[str, Any]) -> str | None:
    summary_file = job.get("summary_file")
    if summary_file:
        return str(summary_file)
    return _result_summary_file(job.get("result"))


def _result_resume_state(result: Any) -> dict[str, Any] | None:
    if not isinstance(result, dict):
        return None
    resume_state = result.get("resume_state")
    if isinstance(resume_state, dict):
        return resume_state
    nested = result.get("result")
    if isinstance(nested, dict) and isinstance(nested.get("resume_state"), dict):
        return nested["resume_state"]
    pipeline = result.get("pipeline")
    if isinstance(pipeline, dict) and isinstance(pipeline.get("resume_state"), dict):
        return pipeline["resume_state"]
    return None


def _result_next_command_argv(result: Any) -> list[str] | None:
    if not isinstance(result, dict):
        return None
    for candidate in (
        result.get("next_command_argv"),
        (result.get("resume_state") or {}).get("next_command_argv") if isinstance(result.get("resume_state"), dict) else None,
    ):
        argv = _argv_list(candidate)
        if argv:
            return argv
    nested = result.get("result")
    if isinstance(nested, dict):
        argv = _result_next_command_argv(nested)
        if argv:
            return argv
    pipeline = result.get("pipeline")
    if isinstance(pipeline, dict):
        argv = _result_next_command_argv(pipeline)
        if argv:
            return argv
    return None


def _resume_argv_from_job(job: dict[str, Any]) -> list[str] | None:
    result = job.get("result")
    argv = _result_next_command_argv(result)
    if argv:
        return argv
    resume_state = job.get("resume_state")
    if isinstance(resume_state, dict):
        return _argv_list(resume_state.get("next_command_argv"))
    return None


def _apply_resume_overrides(argv: list[str] | None, overrides: dict[str, Any]) -> dict[str, Any]:
    provided = {key: value for key, value in overrides.items() if key not in {"job_id", "dry_run"}} if isinstance(overrides, dict) else {}
    patched = list(argv or [])
    applied: list[dict[str, Any]] = []
    ignored: list[dict[str, Any]] = []
    if not patched:
        return {"argv": None, "provided": provided, "applied": applied, "ignored": [{"key": key, "reason": "no_resume_command"} for key in provided]}

    for key, value in provided.items():
        if key in RESUME_BOOLEAN_FLAG_OVERRIDES:
            flag = RESUME_BOOLEAN_FLAG_OVERRIDES[key]
            if _truthy(value):
                patched = _argv_ensure_boolean_flag(patched, flag)
                applied.append({"key": key, "flag": flag, "value": True})
            else:
                ignored.append({"key": key, "flag": flag, "reason": "boolean override must be true to add a live-action flag"})
        elif key in RESUME_VALUE_FLAG_OVERRIDES:
            flag = RESUME_VALUE_FLAG_OVERRIDES[key]
            if value in (None, ""):
                ignored.append({"key": key, "flag": flag, "reason": "empty value"})
            else:
                patched = _argv_set_value_flag(patched, flag, str(value))
                applied.append({"key": key, "flag": flag, "value": str(value)})
        elif key in RESUME_REPEATABLE_FLAG_OVERRIDES:
            flag = RESUME_REPEATABLE_FLAG_OVERRIDES[key]
            values = _list_value(value)
            if not values:
                ignored.append({"key": key, "flag": flag, "reason": "empty repeatable value"})
            else:
                patched = _argv_set_repeatable_flag(patched, flag, [str(item) for item in values])
                applied.append({"key": key, "flag": flag, "value": [str(item) for item in values]})
        else:
            ignored.append({"key": key, "reason": "override is not allowlisted for resume commands"})
    return {"argv": patched, "provided": provided, "applied": applied, "ignored": ignored}


def _argv_ensure_boolean_flag(argv: list[str], flag: str) -> list[str]:
    return argv if flag in argv else [*argv, flag]


def _argv_set_value_flag(argv: list[str], flag: str, value: str) -> list[str]:
    cleaned = _argv_without_flag(argv, flag, has_value=True)
    return [*cleaned, flag, value]


def _argv_set_repeatable_flag(argv: list[str], flag: str, values: list[str]) -> list[str]:
    cleaned = _argv_without_flag(argv, flag, has_value=True)
    for value in values:
        cleaned.extend([flag, value])
    return cleaned


def _argv_without_flag(argv: list[str], flag: str, *, has_value: bool) -> list[str]:
    result: list[str] = []
    index = 0
    while index < len(argv):
        item = argv[index]
        if item == flag:
            index += 2 if has_value and index + 1 < len(argv) else 1
            continue
        result.append(item)
        index += 1
    return result


def _argv_list(value: Any) -> list[str] | None:
    if not isinstance(value, list):
        return None
    argv = [str(item) for item in value if str(item)]
    return argv or None


def _resume_command_allowed(argv: list[str] | None) -> tuple[bool, str | None]:
    if not argv:
        return False, "No executable resume command is available for this job."
    if any("\x00" in item for item in argv):
        return False, "Resume command contains invalid null bytes."
    subcommand = _ptcli_subcommand(argv)
    if not subcommand:
        return False, "Resume command is not a recognized ptcli invocation."
    if subcommand not in RESUME_COMMAND_ALLOWLIST:
        return False, f"Resume command subcommand is not allowlisted: {subcommand}"
    return True, None


def _ptcli_subcommand(argv: list[str]) -> str | None:
    if len(argv) >= 2 and Path(argv[0]).name == "ptcli":
        return argv[1]
    if len(argv) >= 3 and Path(argv[1]).name == "ptcli.py":
        return argv[2]
    return None


def _run_resume_command(argv: list[str], *, parent_job_id: str) -> dict[str, Any]:
    started_at = time.time()
    completed = subprocess.run(argv, cwd=os.getcwd(), capture_output=True, text=True)
    parsed_stdout = _parse_json_stdout(completed.stdout)
    status = "ok" if completed.returncode == 0 else "blocked"
    blockers = [] if completed.returncode == 0 else [f"Resume command exited with code {completed.returncode}."]
    if isinstance(parsed_stdout, dict):
        blockers.extend(_result_blockers(parsed_stdout))
    if completed.stderr.strip():
        blockers.append(completed.stderr.strip())
    return {
        "kind": "ptcli.service.resume",
        "status": status,
        "ok": completed.returncode == 0,
        "parent_job_id": parent_job_id,
        "command_argv": argv,
        "returncode": completed.returncode,
        "stdout_json": parsed_stdout,
        "stdout": completed.stdout if parsed_stdout is None else None,
        "stderr": completed.stderr,
        "blockers": blockers,
        "next_actions": _string_list(parsed_stdout.get("next_actions")) if isinstance(parsed_stdout, dict) else [],
        "summary_file": _result_summary_file(parsed_stdout) if isinstance(parsed_stdout, dict) else None,
        "resume_state": _result_resume_state(parsed_stdout) if isinstance(parsed_stdout, dict) else None,
        "next_command_argv": _result_next_command_argv(parsed_stdout) if isinstance(parsed_stdout, dict) else None,
        "elapsed_seconds": round(time.time() - started_at, 3),
        "result": parsed_stdout,
    }


def _parse_json_stdout(stdout: str) -> dict[str, Any] | None:
    text = stdout.strip()
    if not text:
        return None
    try:
        payload = json.loads(text)
    except json.JSONDecodeError:
        return None
    return payload if isinstance(payload, dict) else None


def _nested_value(payload: Any, key: str) -> Any:
    if not isinstance(payload, dict):
        return None
    if key in payload:
        return payload[key]
    nested = payload.get("result")
    if isinstance(nested, dict) and key in nested:
        return nested[key]
    pipeline = payload.get("pipeline")
    if isinstance(pipeline, dict) and key in pipeline:
        return pipeline[key]
    return None


def _string_list(value: Any) -> list[str]:
    if isinstance(value, list):
        return [str(item) for item in value]
    if value is None:
        return []
    return [str(value)]


def health_payload() -> dict[str, Any]:
    return {
        "status": "ok",
        "service": "ptcli",
        "api": "v1",
        "time": int(time.time()),
    }


def deployment_check_payload(request: dict[str, Any] | None = None) -> dict[str, Any]:
    """Return a local deployment readiness report without touching trackers or qBittorrent."""
    request = request or {}
    base_dir = Path(str(request.get("base_dir") or os.environ.get("PTCLI_BASE_DIR") or os.getcwd())).expanduser()
    config_path = _deployment_path(request.get("config") or os.environ.get("PTCLI_CONFIG") or "data/config.py", base_dir)
    cookies_dir = _deployment_path(request.get("cookies_dir") or "data/cookies", base_dir)
    tmp_dir = Path(os.environ.get("TMPDIR") or str(base_dir / "tmp")).expanduser()
    job_dir = _resolve_job_dir(request.get("job_dir") or os.environ.get("PTCLI_JOB_DIR"))
    max_concurrent_jobs = _resolve_max_concurrent_jobs(request.get("max_concurrent_jobs"))
    downloads_path = Path(str(request.get("downloads_path") or os.environ.get("PTCLI_DOWNLOADS_PATH") or "/downloads")).expanduser()
    client = str(request.get("client") or "default")
    compose_path = _deployment_path(request.get("compose_file") or os.environ.get("PTCLI_COMPOSE_FILE") or "docker-compose.yml", base_dir)
    env_template = _deployment_env_template_summary(_deployment_path(request.get("env_template") or ".env.ptcli.example", base_dir), _deployment_path(request.get("env_file") or ".env", base_dir))

    runtime_check = build_runtime_dependency_check()
    runtime_tools = _deployment_runtime_tools()
    checks: list[dict[str, Any]] = [
        {
            "name": "runtime.ptcli_dependencies",
            "ok": bool(runtime_check.get("ok")),
            "message": runtime_check.get("message"),
            "details": runtime_check,
        },
        {
            "name": "runtime.material_tools",
            "ok": bool(runtime_tools.get("ready")),
            "blocking": False,
            "message": runtime_tools.get("message"),
            "details": runtime_tools,
        },
        _deployment_file_check("config", config_path, required=True),
        _deployment_dir_check("cookies_dir", cookies_dir, required=True),
        _deployment_dir_check("tmp_dir", tmp_dir, required=True, writable=True),
        _deployment_dir_check("job_dir", job_dir, required=True, writable=True),
        _deployment_dir_check("downloads_path", downloads_path, required=True),
        _deployment_api_token_check(),
    ]

    config: dict[str, Any] | None = None
    qbit: dict[str, Any] = {"configured": False, "client": client, "connectivity_checked": False}
    if checks[2]["ok"]:
        try:
            config = load_config(str(config_path))
            checks.append({"name": "config.load", "ok": True, "message": f"Config loaded: {config_path}"})
        except Exception as exc:
            checks.append({"name": "config.load", "ok": False, "message": f"Config could not be loaded: {exc}"})
    if config is not None:
        try:
            resolved_client, qbit_config = resolve_client_config(config, client)
            qbit = {
                "configured": True,
                "client": resolved_client,
                "torrent_client": qbit_config.get("torrent_client"),
                "qbit_url": qbit_config.get("qbit_url"),
                "qbit_port": qbit_config.get("qbit_port"),
                "qui_proxy_configured": bool(qbit_config.get("qui_proxy_url")),
                "connectivity_checked": False,
            }
            checks.append({"name": "qbit.config", "ok": True, "message": f"qBittorrent client config is present: {resolved_client}", "details": qbit})
        except Exception as exc:
            checks.append({"name": "qbit.config", "ok": False, "message": f"qBittorrent client config is not ready: {exc}", "details": qbit})

    daily_candidate_plan = _deployment_daily_candidate_plan(request)
    docker_compose = _deployment_docker_compose_summary(compose_path)
    checks.append(_deployment_api_exposure_check(docker_compose))
    checks.append(
        {
            "name": "automation.daily_candidates",
            "ok": bool(daily_candidate_plan.get("configured")) and not bool(daily_candidate_plan.get("blockers")),
            "blocking": False,
            "message": _deployment_daily_candidate_message(daily_candidate_plan),
            "details": daily_candidate_plan,
        }
    )
    checks.append(
        {
            "name": "docker.compose_daily_schedule",
            "ok": bool(docker_compose.get("daily_scheduler_service_ready") or docker_compose.get("daily_schedule_service_ready")),
            "blocking": False,
            "message": _deployment_docker_compose_message(docker_compose),
            "path": str(compose_path),
            "details": docker_compose,
        }
    )
    checks.append(
        {
            "name": "docker.compose_ptcli_api",
            "ok": bool(docker_compose.get("ptcli_api_service_ready")),
            "blocking": False,
            "message": _deployment_docker_compose_api_message(docker_compose),
            "path": str(compose_path),
            "details": docker_compose,
        }
    )

    blockers = [str(check.get("message")) for check in checks if check.get("ok") is False and check.get("blocking", True) is not False]
    warnings = [str(check.get("message")) for check in checks if check.get("ok") is False and check.get("blocking") is False]
    next_actions = _deployment_next_actions(checks)
    ready = not blockers
    paths = {
        "base_dir": str(base_dir),
        "config": str(config_path),
        "cookies_dir": str(cookies_dir),
        "tmp_dir": str(tmp_dir),
        "job_dir": str(job_dir),
        "downloads_path": str(downloads_path),
        "compose_file": str(compose_path),
        "env_template": str(env_template.get("template_path")),
        "env_file": str(env_template.get("env_path")),
    }
    mounts = _deployment_mount_summary(checks)
    agent_summary = _deployment_agent_summary(ready, checks, paths, mounts, qbit, daily_candidate_plan, docker_compose, env_template)
    deployment_handoff = _deployment_runtime_handoff(agent_summary, paths, qbit, daily_candidate_plan, docker_compose, env_template, blockers, warnings)
    deployment_runbook = _deployment_runbook(agent_summary, paths, qbit, daily_candidate_plan, docker_compose, env_template, blockers, warnings)
    daily_candidate_trigger_handoff = _deployment_daily_candidate_trigger_handoff(agent_summary, paths, daily_candidate_plan, docker_compose, blockers, warnings)
    daily_candidate_delivery_handoff = _deployment_daily_candidate_delivery_handoff(daily_candidate_plan, docker_compose, daily_candidate_trigger_handoff, blockers, warnings)
    seedbox_bootstrap_handoff = _deployment_seedbox_bootstrap_handoff(agent_summary, paths, mounts, qbit, daily_candidate_plan, docker_compose, env_template, blockers, warnings)
    agent_handoff = _deployment_agent_handoff(agent_summary, paths, qbit, daily_candidate_plan, docker_compose, env_template, blockers, warnings)
    deployment_final_report = _deployment_final_report(
        ready=ready,
        paths=paths,
        mounts=mounts,
        runtime_tools=runtime_tools,
        qbit=qbit,
        daily_candidate_plan=daily_candidate_plan,
        docker_compose=docker_compose,
        env_template=env_template,
        deployment_handoff=deployment_handoff,
        seedbox_bootstrap_handoff=seedbox_bootstrap_handoff,
        agent_summary=agent_summary,
        blockers=blockers,
        warnings=warnings,
    )
    seedbox_live_trial_handoff = _deployment_seedbox_live_trial_handoff(
        ready=ready,
        paths=paths,
        qbit=qbit,
        docker_compose=docker_compose,
        deployment_handoff=deployment_handoff,
        seedbox_bootstrap_handoff=seedbox_bootstrap_handoff,
        deployment_final_report=deployment_final_report,
        agent_summary=agent_summary,
        blockers=blockers,
        warnings=warnings,
    )
    deployment_runbook["daily_candidate_trigger_handoff"] = daily_candidate_trigger_handoff
    deployment_runbook["daily_candidate_delivery_handoff"] = daily_candidate_delivery_handoff
    deployment_handoff["daily_candidate_trigger_handoff"] = daily_candidate_trigger_handoff
    deployment_handoff["daily_candidate_delivery_handoff"] = daily_candidate_delivery_handoff
    agent_handoff["daily_candidate_trigger_handoff"] = daily_candidate_trigger_handoff
    agent_handoff["daily_candidate_delivery_handoff"] = daily_candidate_delivery_handoff
    deployment_handoff["seedbox_live_trial"] = seedbox_live_trial_handoff
    agent_handoff["seedbox_live_trial"] = seedbox_live_trial_handoff
    return {
        "kind": "ptcli.deployment_check",
        "status": "ok" if ready else "blocked",
        "ok": ready,
        "ready": ready,
        "checks": checks,
        "blockers": blockers,
        "warnings": warnings,
        "next_actions": next_actions,
        "paths": paths,
        "mounts": mounts,
        "runtime_tools": runtime_tools,
        "queue": {"max_concurrent_jobs": max_concurrent_jobs},
        "qbit": qbit,
        "daily_candidates": daily_candidate_plan,
        "deployment_env": env_template,
        "docker_compose": docker_compose,
        "deployment_runbook": deployment_runbook,
        "deployment_handoff": deployment_handoff,
        "daily_candidate_trigger_handoff": daily_candidate_trigger_handoff,
        "daily_candidate_delivery_handoff": daily_candidate_delivery_handoff,
        "seedbox_bootstrap_handoff": seedbox_bootstrap_handoff,
        "seedbox_live_trial_handoff": seedbox_live_trial_handoff,
        "deployment_final_report": deployment_final_report,
        "agent_summary": agent_summary,
        "agent_handoff": agent_handoff,
        "connectivity_checked": False,
    }


def _deployment_path(path: Any, base_dir: Path) -> Path:
    candidate = Path(str(path)).expanduser()
    return candidate if candidate.is_absolute() else base_dir / candidate


def _deployment_file_check(name: str, path: Path, *, required: bool) -> dict[str, Any]:
    exists = path.is_file()
    ok = exists or not required
    return {
        "name": f"path.{name}",
        "ok": ok,
        "blocking": required,
        "path": str(path),
        "message": f"{name} file is present: {path}" if exists else f"{name} file is missing: {path}",
    }


def _deployment_dir_check(name: str, path: Path, *, required: bool, writable: bool = False) -> dict[str, Any]:
    exists = path.is_dir()
    is_writable = os.access(path, os.W_OK) if exists else False
    ok = (exists or not required) and (not writable or is_writable)
    if not exists:
        message = f"{name} directory is missing: {path}"
    elif writable and not is_writable:
        message = f"{name} directory is not writable: {path}"
    else:
        message = f"{name} directory is ready: {path}"
    return {
        "name": f"path.{name}",
        "ok": ok,
        "blocking": required,
        "path": str(path),
        "exists": exists,
        "writable": is_writable,
        "message": message,
    }


def _deployment_api_token_check() -> dict[str, Any]:
    configured = bool(os.environ.get("PTCLI_API_TOKEN"))
    return {
        "name": "security.api_token",
        "ok": configured,
        "blocking": False,
        "configured": configured,
        "message": "PTCLI_API_TOKEN is configured." if configured else "PTCLI_API_TOKEN is not configured; keep the API bound to localhost or set a token before exposing it.",
    }


def _deployment_api_exposure_check(docker_compose: dict[str, Any]) -> dict[str, Any]:
    token_configured = bool(os.environ.get("PTCLI_API_TOKEN"))
    publicly_exposed = bool(docker_compose.get("ptcli_api_public_port"))
    local_only = bool(docker_compose.get("ptcli_api_localhost_port"))
    ready = not publicly_exposed or token_configured
    if ready and publicly_exposed:
        message = "ptcli-api is exposed beyond localhost and PTCLI_API_TOKEN is configured."
    elif ready:
        message = "ptcli-api is bound to localhost or has no public port mapping."
    else:
        message = "ptcli-api is exposed beyond localhost without PTCLI_API_TOKEN; set a token or bind ports to 127.0.0.1."
    return {
        "name": "security.api_exposure",
        "ok": ready,
        "blocking": True,
        "local_only": local_only,
        "publicly_exposed": publicly_exposed,
        "token_configured": token_configured,
        "message": message,
    }


def _deployment_runtime_tools() -> dict[str, Any]:
    required = [_runtime_binary_status("ffmpeg"), _runtime_binary_status("mediainfo")]
    optional = [_runtime_binary_status("ffprobe"), _runtime_binary_status("bdinfo"), _runtime_binary_status("BDInfo")]
    missing_required = [str(item["name"]) for item in required if not item.get("available")]
    ready = not missing_required
    return {
        "kind": "ptcli.runtime_material_tools",
        "ready": ready,
        "required": required,
        "optional": optional,
        "missing_required": missing_required,
        "message": "Material runtime tools are available for MediaInfo and screenshots." if ready else f"Material runtime tools are missing: {', '.join(missing_required)}.",
    }


def _runtime_binary_status(name: str) -> dict[str, Any]:
    path = shutil.which(name)
    return {"name": name, "available": bool(path), "path": path}


def _deployment_env_template_summary(template_path: Path, env_path: Path) -> dict[str, Any]:
    required_keys = [
        "TZ",
        "PTCLI_API_TOKEN",
        "PTCLI_PUBLIC_BASE_URL",
        "PTCLI_MAX_CONCURRENT_JOBS",
        "PTCLI_JOB_DIR",
        "PTCLI_DOWNLOADS_PATH",
        "PTCLI_DOWNLOADS_HOST_PATH",
        "PTCLI_CONFIG_HOST_PATH",
        "PTCLI_COOKIES_HOST_PATH",
        "PTCLI_TMP_HOST_PATH",
    ]
    daily_keys = ["PTCLI_DAILY_CANDIDATE_SCHEDULES", "PTCLI_DAILY_CANDIDATE_OUTPUT_DIR", "PTCLI_DAILY_CANDIDATE_WEBHOOK_URL"]
    optional_keys = ["PTCLI_DOCKER_NETWORK"]
    present = template_path.is_file()
    text = ""
    if present:
        try:
            text = template_path.read_text(encoding="utf-8")
        except OSError as exc:
            return {
                "kind": "ptcli.deployment_env_template",
                "ready": False,
                "template_present": True,
                "template_readable": False,
                "template_path": str(template_path),
                "env_path": str(env_path),
                "error": str(exc),
                "required_keys": required_keys,
                "daily_keys": daily_keys,
                "optional_keys": optional_keys,
                "missing_keys": required_keys + daily_keys,
                "copy_command": f"cp {template_path.name} {env_path.name}",
                "next_actions": [f"Fix permissions on {template_path} so deployment_check can read the env template."],
            }
    missing_keys = [key for key in [*required_keys, *daily_keys] if f"{key}=" not in text]
    ready = present and not missing_keys
    return {
        "kind": "ptcli.deployment_env_template",
        "ready": ready,
        "template_present": present,
        "template_readable": present,
        "template_path": str(template_path),
        "env_path": str(env_path),
        "env_present": env_path.is_file(),
        "required_keys": required_keys,
        "daily_keys": daily_keys,
        "optional_keys": optional_keys,
        "missing_keys": missing_keys,
        "copy_command": f"cp {template_path.name} {env_path.name}",
        "edit_after_copy": [
            "Set PTCLI_API_TOKEN before exposing the API.",
            "Adjust PTCLI_PUBLIC_BASE_URL if OpenClaw/Hermes reaches ptcli through a reverse proxy.",
            "Set PTCLI_DOWNLOADS_HOST_PATH, PTCLI_CONFIG_HOST_PATH, PTCLI_COOKIES_HOST_PATH, and PTCLI_TMP_HOST_PATH to real seedbox paths.",
            "Set PTCLI_DAILY_CANDIDATE_SCHEDULES when daily candidate jobs are needed.",
            "Keep PTCLI_DAILY_CANDIDATE_OUTPUT_DIR mounted under PTCLI_TMP_HOST_PATH so AI/IM consumers can read local digest files.",
        ],
        "security": {
            "api_token_default": "change-me",
            "api_token_required_when_exposed": True,
            "keep_localhost_binding": True,
        },
        "next_actions": _deployment_env_template_next_actions(ready, present, missing_keys),
    }


def _deployment_env_template_next_actions(ready: bool, present: bool, missing_keys: list[str]) -> list[str]:
    if ready:
        return ["Copy .env.ptcli.example to .env, set real local values, then start ptcli-api with docker compose."]
    if not present:
        return ["Add .env.ptcli.example or pass env_template to deployment_check so AI agents can discover the Docker Compose environment contract."]
    return [f"Add missing keys to .env.ptcli.example: {', '.join(missing_keys)}."]


def _deployment_daily_candidate_plan(request: dict[str, Any]) -> dict[str, Any]:
    schedule_request: dict[str, Any] = {}
    if "schedules" in request:
        schedule_request["schedules"] = request.get("schedules")
    elif "daily_candidate_schedules" in request:
        schedule_request["schedules"] = request.get("daily_candidate_schedules")
    summary_evidence = _deployment_daily_candidate_summary_evidence(request)
    try:
        plan = daily_candidate_schedule_payload(schedule_request)
    except ServiceError as exc:
        return {
            "configured": False,
            "status": "blocked",
            "ok": False,
            "source": "request" if schedule_request else "env",
            "env": DAILY_CANDIDATE_SCHEDULE_ENV,
            "count": 0,
            "schedules": [],
            "blockers": [str(exc)],
            "next_actions": [f"Fix {DAILY_CANDIDATE_SCHEDULE_ENV} JSON or POST valid schedules to /v1/candidates/daily/schedule."],
        }
    daily_plan = {
        "configured": bool(plan.get("count")),
        "status": plan.get("status"),
        "ok": bool(plan.get("ok")),
        "source": plan.get("source"),
        "env": plan.get("env"),
        "count": plan.get("count", 0),
        "schedules": plan.get("schedules", []),
        "schedule_handoff": plan.get("schedule_handoff") if isinstance(plan.get("schedule_handoff"), dict) else {},
        "schedule_digest": plan.get("schedule_digest") if isinstance(plan.get("schedule_digest"), dict) else {},
        "candidate_control_summary": plan.get("candidate_control_summary") if isinstance(plan.get("candidate_control_summary"), dict) else {},
        "notification_payload": plan.get("notification_payload") if isinstance(plan.get("notification_payload"), dict) else {},
        "delivery_handoff": plan.get("delivery_handoff") if isinstance(plan.get("delivery_handoff"), dict) else {},
        "daily_schedule_gate": plan.get("daily_schedule_gate") if isinstance(plan.get("daily_schedule_gate"), dict) else {},
        "daily_candidate_delivery_plan": plan.get("daily_candidate_delivery_plan") if isinstance(plan.get("daily_candidate_delivery_plan"), dict) else {},
        "daily_candidate_schedule_execution_context": plan.get("daily_candidate_schedule_execution_context") if isinstance(plan.get("daily_candidate_schedule_execution_context"), dict) else {},
        "daily_candidate_final_report": plan.get("daily_candidate_final_report") if isinstance(plan.get("daily_candidate_final_report"), dict) else {},
        "daily_candidate_delivery_final_report": plan.get("daily_candidate_delivery_final_report") if isinstance(plan.get("daily_candidate_delivery_final_report"), dict) else {},
        "daily_candidate_operational_final_report": plan.get("daily_candidate_operational_final_report") if isinstance(plan.get("daily_candidate_operational_final_report"), dict) else {},
        "blockers": _string_list(plan.get("blockers")),
        "next_actions": _string_list(plan.get("next_actions")),
    }
    if summary_evidence:
        _merge_daily_candidate_summary_evidence(daily_plan, summary_evidence)
    return daily_plan


def _deployment_daily_candidate_summary_evidence(request: dict[str, Any]) -> dict[str, Any]:
    summary_file = request.get("daily_candidate_summary_file") or request.get("daily_schedule_summary_file")
    if not summary_file:
        summary_file = request.get("summary_file") or request.get("path")
    if not summary_file:
        return {}
    path = Path(str(summary_file)).expanduser()
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return {}
    if not isinstance(payload, dict) or payload.get("kind") not in {"ptcli.daily_schedule.summary", "ptcli.daily_candidate_refill_job_result"}:
        return {}
    payload["summary_file"] = str(path)
    return payload


def _merge_daily_candidate_summary_evidence(daily_plan: dict[str, Any], summary: dict[str, Any]) -> None:
    daily_plan["summary_file"] = summary.get("summary_file")
    daily_plan["summary_kind"] = summary.get("kind")
    if isinstance(summary.get("schedule_digest"), dict):
        daily_plan["schedule_digest"] = summary["schedule_digest"]
    if isinstance(summary.get("notification_payload"), dict):
        daily_plan["notification_payload"] = summary["notification_payload"]
    if isinstance(summary.get("delivery_handoff"), dict):
        daily_plan["delivery_handoff"] = summary["delivery_handoff"]
    if isinstance(summary.get("daily_candidate_target_fulfillment_report"), dict):
        daily_plan["daily_candidate_target_fulfillment_report"] = summary["daily_candidate_target_fulfillment_report"]
    if isinstance(summary.get("daily_candidate_operational_final_report"), dict):
        daily_plan["daily_candidate_operational_final_report"] = summary["daily_candidate_operational_final_report"]
    if isinstance(summary.get("daily_scheduler_final_report"), dict):
        daily_plan["daily_scheduler_final_report"] = summary["daily_scheduler_final_report"]
    if isinstance(summary.get("refill_loop_report"), dict):
        daily_plan["refill_loop_report"] = summary["refill_loop_report"]
    if isinstance(summary.get("after_batch"), dict):
        after_batch = summary["after_batch"]
        daily_plan["refill_after_batch"] = after_batch
        for key in (
            "daily_candidate_batch_summary",
            "daily_candidate_batch_gate",
            "daily_candidate_submission_plan",
            "daily_candidate_execution_summary",
            "daily_candidate_refill_plan",
            "daily_candidate_batch_publish_payload",
            "daily_candidate_tracking_report",
            "daily_candidate_completion_gate",
        ):
            if isinstance(after_batch.get(key), dict):
                daily_plan[key] = after_batch[key]
    if isinstance(summary.get("before_batch"), dict):
        daily_plan["refill_before_batch"] = summary["before_batch"]
    if isinstance(summary.get("delivery_result"), dict):
        daily_plan["delivery_result"] = summary["delivery_result"]
    if isinstance(summary.get("delivery_audit"), dict):
        daily_plan["delivery_audit"] = summary["delivery_audit"]
    if isinstance(summary.get("run_and_deliver_report"), dict):
        daily_plan["run_and_deliver_report"] = summary["run_and_deliver_report"]
    daily_plan["summary_evidence"] = {
        "summary_file": summary.get("summary_file"),
        "kind": summary.get("kind"),
        "status": summary.get("status"),
        "ok": bool(summary.get("ok")),
        "has_scheduler_final_report": isinstance(summary.get("daily_scheduler_final_report"), dict),
        "has_refill_loop_report": isinstance(summary.get("refill_loop_report"), dict),
    }


def _deployment_daily_candidate_message(plan: dict[str, Any]) -> str:
    if plan.get("configured") and not plan.get("blockers"):
        return f"Daily candidate schedules are configured: {plan.get('count', 0)}."
    if plan.get("configured"):
        return f"Daily candidate schedules need attention: {', '.join(_string_list(plan.get('blockers')))}"
    return f"No daily candidate schedules configured; set {DAILY_CANDIDATE_SCHEDULE_ENV} when daily push jobs are needed."


def _deployment_docker_compose_summary(compose_path: Path) -> dict[str, Any]:
    exists = compose_path.is_file()
    text = ""
    if exists:
        try:
            text = compose_path.read_text(encoding="utf-8")
        except OSError as exc:
            return {
                "present": True,
                "readable": False,
                "path": str(compose_path),
                "error": str(exc),
                "ptcli_api_service": False,
                "daily_schedule_service": False,
                "daily_scheduler_service": False,
                "daily_profile": False,
                "daily_schedule_command": False,
                "daily_scheduler_command": False,
                "daily_schedule_service_ready": False,
                "daily_scheduler_service_ready": False,
                "ptcli_api_service_ready": False,
            }
    scheduler_command = 'command: ["daily-scheduler", "--summary-output-dir", "/Upload-Assistant/tmp/daily-candidates", "--write-notification", "--json"]'
    schedule_command = 'command: ["daily-schedule", "--write-summary", "--summary-output-dir", "/Upload-Assistant/tmp/daily-candidates", "--write-notification", "--json"]'
    host_path_envs = all(key in text for key in ("PTCLI_DOWNLOADS_HOST_PATH", "PTCLI_CONFIG_HOST_PATH", "PTCLI_COOKIES_HOST_PATH", "PTCLI_TMP_HOST_PATH"))
    daily_output_env = "PTCLI_DAILY_CANDIDATE_OUTPUT_DIR=${PTCLI_DAILY_CANDIDATE_OUTPUT_DIR:-/Upload-Assistant/tmp/daily-candidates}" in text
    ptcli_api_localhost_port = '"127.0.0.1:8080:8080"' in text or "'127.0.0.1:8080:8080'" in text
    ptcli_api_public_port = any(pattern in text for pattern in ('"8080:8080"', "'8080:8080'", '"0.0.0.0:8080:8080"', "'0.0.0.0:8080:8080'"))
    return {
        "present": exists,
        "readable": exists,
        "path": str(compose_path),
        "ptcli_api_service": "ptcli-api:" in text,
        "ptcli_api_command": 'command: ["serve", "--host", "0.0.0.0", "--port", "8080"]' in text,
        "ptcli_api_healthcheck": "healthcheck:" in text and "http://127.0.0.1:8080/health" in text,
        "ptcli_api_localhost_port": ptcli_api_localhost_port,
        "ptcli_api_public_port": ptcli_api_public_port,
        "ptcli_api_token_env": "PTCLI_API_TOKEN=${PTCLI_API_TOKEN:-}" in text,
        "ptcli_public_base_url_env": "PTCLI_PUBLIC_BASE_URL=${PTCLI_PUBLIC_BASE_URL:-" in text,
        "ptcli_job_dir_env": "PTCLI_JOB_DIR=/Upload-Assistant/tmp/ptcli-jobs" in text,
        "daily_candidate_output_dir_env": daily_output_env,
        "host_gateway": "host.docker.internal:host-gateway" in text,
        "downloads_mount": ":/downloads/" in text or ":/downloads:" in text,
        "config_mount": ":/Upload-Assistant/data/config.py:" in text,
        "cookies_mount": ":/Upload-Assistant/data/cookies/" in text or ":/Upload-Assistant/data/cookies:" in text,
        "tmp_mount": ":/Upload-Assistant/tmp/" in text or ":/Upload-Assistant/tmp:" in text,
        "host_path_envs": host_path_envs,
        "daily_schedule_service": "ptcli-daily-schedule:" in text,
        "daily_scheduler_service": "ptcli-daily-scheduler:" in text,
        "daily_profile": "- daily" in text,
        "daily_schedule_command": schedule_command in text,
        "daily_scheduler_command": scheduler_command in text,
        "ptcli_api_service_ready": all(
            (
                exists,
                "ptcli-api:" in text,
                'command: ["serve", "--host", "0.0.0.0", "--port", "8080"]' in text,
                "healthcheck:" in text,
                "http://127.0.0.1:8080/health" in text,
                ptcli_api_localhost_port,
                "PTCLI_API_TOKEN=${PTCLI_API_TOKEN:-}" in text,
                "PTCLI_JOB_DIR=/Upload-Assistant/tmp/ptcli-jobs" in text,
                "host.docker.internal:host-gateway" in text,
                (":/downloads/" in text or ":/downloads:" in text),
                ":/Upload-Assistant/data/config.py:" in text,
                (":/Upload-Assistant/data/cookies/" in text or ":/Upload-Assistant/data/cookies:" in text),
                (":/Upload-Assistant/tmp/" in text or ":/Upload-Assistant/tmp:" in text),
                host_path_envs,
            )
        ),
        "daily_schedule_service_ready": all(
            (
                exists,
                "ptcli-api:" in text,
                "ptcli-daily-schedule:" in text,
                "- daily" in text,
                schedule_command in text,
                daily_output_env,
            )
        ),
        "daily_scheduler_service_ready": all(
            (
                exists,
                "ptcli-api:" in text,
                "ptcli-daily-scheduler:" in text,
                "- daily" in text,
                scheduler_command in text,
                daily_output_env,
            )
        ),
    }


def _deployment_docker_compose_api_message(summary: dict[str, Any]) -> str:
    path = summary.get("path")
    if summary.get("ptcli_api_service_ready"):
        return f"Docker Compose ptcli-api service is configured for local AI access: {path}"
    if not summary.get("present"):
        return f"docker-compose.yml is not present at {path}; skip this warning if not using Docker Compose."
    if not summary.get("readable"):
        return f"docker-compose.yml could not be read at {path}: {summary.get('error')}"
    missing = [
        name
        for name, ready in (
            ("ptcli-api service", summary.get("ptcli_api_service")),
            ("serve command", summary.get("ptcli_api_command")),
            ("healthcheck", summary.get("ptcli_api_healthcheck")),
            ("127.0.0.1 API port binding", summary.get("ptcli_api_localhost_port")),
            ("PTCLI_API_TOKEN env", summary.get("ptcli_api_token_env")),
            ("PTCLI_JOB_DIR env", summary.get("ptcli_job_dir_env")),
            ("host.docker.internal host-gateway", summary.get("host_gateway")),
            ("/downloads mount", summary.get("downloads_mount")),
            ("data/config.py mount", summary.get("config_mount")),
            ("data/cookies mount", summary.get("cookies_mount")),
            ("tmp mount", summary.get("tmp_mount")),
            ("host path env vars", summary.get("host_path_envs")),
        )
        if not ready
    ]
    return f"Docker Compose ptcli-api service is incomplete at {path}: {', '.join(missing)}."


def _deployment_docker_compose_message(summary: dict[str, Any]) -> str:
    path = summary.get("path")
    if summary.get("daily_scheduler_service_ready"):
        return f"Docker Compose daily scheduler service is configured: {path}"
    if summary.get("daily_schedule_service_ready"):
        return f"Docker Compose one-shot daily schedule service is configured: {path}"
    if not summary.get("present"):
        return f"docker-compose.yml is not present at {path}; skip this warning if not using Docker Compose."
    if not summary.get("readable"):
        return f"docker-compose.yml could not be read at {path}: {summary.get('error')}"
    missing = [
        name
        for name, ready in (
            ("ptcli-api service", summary.get("ptcli_api_service")),
            ("ptcli-daily-scheduler service", summary.get("daily_scheduler_service")),
            ("daily profile", summary.get("daily_profile")),
            ("daily-scheduler command", summary.get("daily_scheduler_command")),
        )
        if not ready
    ]
    return f"Docker Compose daily scheduler service is incomplete at {path}: {', '.join(missing)}."


def _deployment_mount_summary(checks: list[dict[str, Any]]) -> dict[str, Any]:
    mount_names = {"path.config", "path.cookies_dir", "path.tmp_dir", "path.job_dir", "path.downloads_path"}
    required: list[dict[str, Any]] = []
    missing: list[dict[str, Any]] = []
    for check in checks:
        if check.get("name") not in mount_names:
            continue
        item = {
            "name": str(check.get("name")).removeprefix("path."),
            "path": check.get("path"),
            "ok": bool(check.get("ok")),
            "exists": check.get("exists", bool(check.get("ok"))),
            "writable": check.get("writable"),
            "message": check.get("message"),
        }
        required.append(item)
        if not item["ok"]:
            missing.append(item)
    return {
        "required": required,
        "missing": missing,
        "ready": not missing,
    }


def _deployment_agent_summary(
    ready: bool,
    checks: list[dict[str, Any]],
    paths: dict[str, str],
    mounts: dict[str, Any],
    qbit: dict[str, Any],
    daily_candidate_plan: dict[str, Any],
    docker_compose: dict[str, Any],
    env_template: dict[str, Any],
) -> dict[str, Any]:
    check_by_name = {str(check.get("name")): check for check in checks}
    api_token_check = check_by_name.get("security.api_token", {})
    api_exposure_check = check_by_name.get("security.api_exposure", {})
    blocking_failures = [str(check.get("name")) for check in checks if check.get("ok") is False and check.get("blocking", True) is not False]
    warning_failures = [str(check.get("name")) for check in checks if check.get("ok") is False and check.get("blocking") is False]
    return {
        "ready_for_ai": ready,
        "ready_for_manual_retorrent": ready and bool(qbit.get("configured")),
        "ready_for_daily_candidates": ready and bool(daily_candidate_plan.get("configured")) and not bool(daily_candidate_plan.get("blockers")),
        "manual_workflow_ready": ready and bool(qbit.get("configured")),
        "daily_workflow_ready": ready and bool(daily_candidate_plan.get("configured")) and not bool(daily_candidate_plan.get("blockers")),
        "compose_deployable": bool(docker_compose.get("ptcli_api_service_ready")),
        "api_local_only": bool(docker_compose.get("ptcli_api_localhost_port")),
        "api_auth_recommended": not bool(api_token_check.get("configured")),
        "api_token_configured": bool(api_token_check.get("configured")),
        "api_publicly_exposed": bool(api_exposure_check.get("publicly_exposed")),
        "api_auth_ready": bool(api_exposure_check.get("ok")),
        "api_exposure_blocked": bool(api_exposure_check.get("publicly_exposed")) and not bool(api_exposure_check.get("token_configured")),
        "qbit_configured": bool(qbit.get("configured")),
        "daily_candidates_configured": bool(daily_candidate_plan.get("configured")),
        "docker_compose_api_ready": bool(docker_compose.get("ptcli_api_service_ready")),
        "docker_compose_daily_ready": bool(docker_compose.get("daily_scheduler_service_ready") or docker_compose.get("daily_schedule_service_ready")),
        "docker_compose_host_path_envs": bool(docker_compose.get("host_path_envs")),
        "env_template_ready": bool(env_template.get("ready")),
        "env_template_present": bool(env_template.get("template_present")),
        "missing_mounts": mounts.get("missing", []),
        "blocking_checks": blocking_failures,
        "warning_checks": warning_failures,
        "configured_paths": paths,
        "qbit_client": qbit.get("client"),
        "daily_candidate_schedule_count": daily_candidate_plan.get("count", 0),
    }


def _deployment_runtime_handoff(
    agent_summary: dict[str, Any],
    paths: dict[str, str],
    qbit: dict[str, Any],
    daily_candidate_plan: dict[str, Any],
    docker_compose: dict[str, Any],
    env_template: dict[str, Any],
    blockers: list[str],
    warnings: list[str],
) -> dict[str, Any]:
    api_base_url = os.environ.get("PTCLI_PUBLIC_BASE_URL") or "http://127.0.0.1:8080"
    manual_ready = bool(agent_summary.get("manual_workflow_ready"))
    daily_ready = bool(agent_summary.get("daily_workflow_ready"))
    compose_ready = bool(agent_summary.get("compose_deployable"))
    return {
        "kind": "ptcli.deployment_runtime_handoff",
        "ready": bool(agent_summary.get("ready_for_ai")),
        "compose_deployable": compose_ready,
        "api": {
            "base_url": api_base_url,
            "health": f"{api_base_url.rstrip('/')}/health",
            "openapi": f"{api_base_url.rstrip('/')}/openapi.json",
            "tools": f"{api_base_url.rstrip('/')}/v1/tools",
            "agent_manifest": f"{api_base_url.rstrip('/')}/.well-known/ptcli-agent.json",
            "localhost_bound": bool(docker_compose.get("ptcli_api_localhost_port")),
            "publicly_exposed": bool(agent_summary.get("api_publicly_exposed")),
            "token_configured": bool(agent_summary.get("api_token_configured")),
            "auth_header": "Authorization: Bearer <PTCLI_API_TOKEN>",
            "auth_recommended": bool(agent_summary.get("api_auth_recommended")),
            "auth_ready": bool(agent_summary.get("api_auth_ready")),
            "exposure_blocked": bool(agent_summary.get("api_exposure_blocked")),
        },
        "env": {
            "template_ready": bool(env_template.get("ready")),
            "template_path": env_template.get("template_path"),
            "env_path": env_template.get("env_path"),
            "copy_command": env_template.get("copy_command"),
            "required_keys": env_template.get("required_keys") if isinstance(env_template.get("required_keys"), list) else [],
            "daily_keys": env_template.get("daily_keys") if isinstance(env_template.get("daily_keys"), list) else [],
            "missing_keys": env_template.get("missing_keys") if isinstance(env_template.get("missing_keys"), list) else [],
        },
        "manual_retorrent": {
            "ready": manual_ready,
            "tool": "source_url_check_and_submit" if manual_ready else "readiness_bundle",
            "endpoint": "/v1/jobs/retorrent/from-url/check-and-submit" if manual_ready else "/v1/readiness/bundle",
            "minimum_request": {
                "source_url": "https://u2.dmhy.org/details.php?id=60635",
                "target": "MTEAM",
                "accept_rules": True,
                "confirm_upload": True,
                "save_path": paths.get("downloads_path") or "/downloads",
            },
            "blocked_by": [] if manual_ready else _deployment_handoff_blockers(agent_summary, blockers, require_daily=False),
        },
        "daily_candidates": {
            "ready": daily_ready,
            "tool": "daily_candidates_schedule_job" if daily_ready else "deployment_check",
            "endpoint": "/v1/jobs/candidates/daily/schedule" if daily_ready else "/v1/deployment/check",
            "schedule_count": daily_candidate_plan.get("count", 0),
            "blocked_by": [] if daily_ready else _deployment_handoff_blockers(agent_summary, blockers, require_daily=True),
        },
        "qbit": {
            "configured": bool(qbit.get("configured")),
            "client": qbit.get("client"),
            "url": qbit.get("qbit_url"),
            "connectivity_checked": bool(qbit.get("connectivity_checked")),
        },
        "next_step": _deployment_runtime_next_step(manual_ready, daily_ready, compose_ready, blockers, warnings),
        "deployment_runbook": _deployment_runbook(agent_summary, paths, qbit, daily_candidate_plan, docker_compose, env_template, blockers, warnings),
        "warnings": warnings,
    }


def _deployment_runtime_next_step(manual_ready: bool, daily_ready: bool, compose_ready: bool, blockers: list[str], warnings: list[str]) -> dict[str, Any]:
    if blockers:
        return {"action": "fix_deployment", "tool": "deployment_check", "endpoint": "/v1/deployment/check", "blockers": blockers}
    if not compose_ready:
        return {"action": "fix_compose", "tool": "deployment_check", "endpoint": "/v1/deployment/check", "warnings": warnings}
    if manual_ready:
        return {"action": "run_manual_preflight", "tool": "source_url_check_and_submit", "endpoint": "/v1/jobs/retorrent/from-url/check-and-submit"}
    if daily_ready:
        return {"action": "run_daily_candidates", "tool": "daily_candidates_schedule_job", "endpoint": "/v1/jobs/candidates/daily/schedule"}
    return {"action": "configure_workflows", "tool": "readiness_bundle", "endpoint": "/v1/readiness/bundle", "warnings": warnings}


def _deployment_daily_candidate_trigger_handoff(
    agent_summary: dict[str, Any],
    paths: dict[str, str],
    daily_candidate_plan: dict[str, Any],
    docker_compose: dict[str, Any],
    blockers: list[str],
    warnings: list[str],
) -> dict[str, Any]:
    api_base_url = os.environ.get("PTCLI_PUBLIC_BASE_URL") or "http://127.0.0.1:8080"
    compose_file = str(paths.get("compose_file") or docker_compose.get("path") or "docker-compose.yml")
    schedule_handoff = daily_candidate_plan.get("schedule_handoff") if isinstance(daily_candidate_plan.get("schedule_handoff"), dict) else {}
    schedule_api = schedule_handoff.get("api") if isinstance(schedule_handoff.get("api"), dict) else {}
    inspect_schedule = schedule_api.get("inspect_schedule") if isinstance(schedule_api.get("inspect_schedule"), dict) else {}
    create_jobs = schedule_api.get("create_jobs") if isinstance(schedule_api.get("create_jobs"), dict) else {}
    first_job_request = schedule_api.get("first_job_request") if isinstance(schedule_api.get("first_job_request"), dict) else {}
    first_source = str(first_job_request.get("source_tracker") or "U2").upper()
    first_target = _first_target_value(first_job_request.get("target") or first_job_request.get("target_trackers") or "MTEAM")
    batch_request = {"source_tracker": first_source, "target": first_target, "limit": int(first_job_request.get("limit") or DEFAULT_CANDIDATE_LIMIT)}
    configured = bool(daily_candidate_plan.get("configured"))
    schedule_ready = bool(configured and not daily_candidate_plan.get("blockers"))
    api_ready = bool(docker_compose.get("ptcli_api_service_ready"))
    compose_daily_ready = bool(docker_compose.get("daily_scheduler_service_ready") or docker_compose.get("daily_schedule_service_ready"))
    ready = bool(agent_summary.get("ready_for_ai") and schedule_ready and api_ready and compose_daily_ready and not blockers)
    status = "ready" if ready else "blocked" if blockers else "configure_schedule" if not schedule_ready else "repair_compose_or_api"
    blocked_by = list(blockers)
    if not schedule_ready:
        blocked_by.extend(_string_list(daily_candidate_plan.get("blockers")) or [f"Configure {DAILY_CANDIDATE_SCHEDULE_ENV} with at least one enabled schedule."])
    if not api_ready:
        blocked_by.append("ptcli-api compose service is not ready.")
    if not compose_daily_ready:
        blocked_by.append("ptcli daily compose profile is not ready.")
    blocked_by = list(dict.fromkeys(blocked_by))
    compose = {
        "profile": "daily",
        "one_shot_service": "ptcli-daily-schedule",
        "daemon_service": "ptcli-daily-scheduler",
        "one_shot_command": f"docker compose -f {compose_file} --profile daily run --rm ptcli-daily-schedule",
        "daemon_command": f"docker compose -f {compose_file} --profile daily up -d ptcli-daily-scheduler",
        "summary_output_dir": "/Upload-Assistant/tmp/daily-candidates",
        "summary_file": "/Upload-Assistant/tmp/daily-candidates/ptcli-daily-schedule-summary.json",
        "notification_files": [
            "/Upload-Assistant/tmp/daily-candidates/ptcli-daily-candidates-notification.json",
            "/Upload-Assistant/tmp/daily-candidates/ptcli-daily-candidates-notification.txt",
        ],
        "api_ready": api_ready,
        "daily_ready": compose_daily_ready,
    }
    return {
        "kind": "ptcli.daily_candidate_trigger_handoff",
        "ready": ready,
        "status": status,
        "action": "run_daily_scheduler_or_create_jobs" if ready else "repair_daily_candidate_trigger",
        "read_only": True,
        "configured": configured,
        "configured_schedule_count": daily_candidate_plan.get("count", 0),
        "target_count": int(first_job_request.get("limit") or DEFAULT_CANDIDATE_LIMIT),
        "publish_payload_field": "daily_candidate_batch_publish_payload",
        "compose": compose,
        "api": {
            "base_url": api_base_url,
            "inspect_schedule": inspect_schedule
            or {"tool": "daily_candidates_schedule", "endpoint": "/v1/candidates/daily/schedule", "method": "POST", "request": {"schedules": daily_candidate_plan.get("schedules") or _daily_candidate_schedule_env_example()}},
            "create_jobs": create_jobs
            or {"tool": "daily_candidates_schedule_job", "endpoint": "/v1/jobs/candidates/daily/schedule", "method": "POST", "request": {"schedules": daily_candidate_plan.get("schedules") or _daily_candidate_schedule_env_example()}},
            "batch_status": {"tool": "daily_candidate_batch_status", "endpoint": "/v1/jobs/candidates/daily/batch", "method": "GET", "request": batch_request},
            "publish_payload_field": "daily_candidate_batch_publish_payload",
            "deliver_digest": {
                "tool": "daily_candidate_delivery",
                "endpoint": "/v1/candidates/daily/deliver",
                "method": "POST",
                "request": {
                    "daily_candidate_batch_publish_payload": "<daily_candidate_batch_publish_payload>",
                    "delivery_handoff": "<daily_candidate_delivery_handoff>",
                    "write_files": True,
                    "use_env_webhook": True,
                },
            },
            "poll_jobs": {"tool": "get_job_status", "endpoint": "/v1/jobs/{job_id}", "method": "GET"},
            "submit_candidate": {"tool": "submit_daily_candidate_job", "endpoint": "/v1/jobs/candidates/{candidate_job_id}/submit", "method": "POST"},
        },
        "env": {
            "schedule_env": DAILY_CANDIDATE_SCHEDULE_ENV,
            "webhook_env": "PTCLI_DAILY_CANDIDATE_WEBHOOK_URL",
            "job_dir_env": "PTCLI_JOB_DIR",
            "example": schedule_handoff.get("env_example"),
        },
        "workflow": [
            {"index": 1, "name": "inspect_schedule", "tool": "daily_candidates_schedule", "endpoint": "/v1/candidates/daily/schedule", "method": "POST", "read": ["schedule_handoff", "daily_schedule_gate"], "continue_when": "schedule_handoff.ready=true", "stop_when": "schedule_handoff.blockers is non-empty"},
            {"index": 2, "name": "create_daily_candidate_jobs", "tool": "daily_candidates_schedule_job", "endpoint": "/v1/jobs/candidates/daily/schedule", "method": "POST", "read": ["schedule_digest", "notification_payload", "delivery_handoff"], "continue_when": "candidate jobs are queued or complete", "stop_when": "daily_schedule_gate.blockers is non-empty"},
            {"index": 3, "name": "read_batch_publish_payload", "tool": "daily_candidate_batch_status", "endpoint": "/v1/jobs/candidates/daily/batch", "method": "GET", "request": batch_request, "read": ["daily_candidate_batch_publish_payload", "daily_candidate_tracking_report", "daily_candidate_batch_sequence"], "continue_when": "daily_candidate_batch_publish_payload.ready=true or status=shortfall", "stop_when": "daily_candidate_batch_publish_payload.blockers is non-empty"},
            {"index": 4, "name": "deliver_candidate_digest", "tool": "daily_candidate_delivery", "endpoint": "/v1/candidates/daily/deliver", "method": "POST", "request": {"daily_candidate_batch_publish_payload": "<daily_candidate_batch_publish_payload>", "delivery_handoff": "<daily_candidate_delivery_handoff>", "write_files": True, "use_env_webhook": True}, "read": ["daily_candidate_delivery_result.file_delivery", "daily_candidate_delivery_result.webhook_delivery", "daily_candidate_delivery_result.payload_fingerprint"], "continue_when": "daily_candidate_delivery_result.ok=true and user receives candidate digest", "stop_when": "daily_candidate_delivery_result.blockers is non-empty"},
            {"index": 5, "name": "submit_only_after_approval", "tool": "submit_daily_candidate_job", "endpoint": "/v1/jobs/candidates/{candidate_job_id}/submit", "method": "POST", "read": ["daily_candidate_approval_sequence.approval_items[].submit_request"], "continue_when": "user explicitly approves selected candidates with confirm_upload=true", "stop_when": "approval is missing or duplicate/policy blocker appears"},
        ],
        "read_order": ["daily_candidate_trigger_handoff", "daily_candidates.schedule_handoff", "daily_candidates.daily_schedule_gate", "daily_candidate_batch_publish_payload", "daily_candidate_tracking_report"],
        "continue_when": "ready=true, then run compose daemon or api.create_jobs and publish api.batch_status.daily_candidate_batch_publish_payload",
        "stop_when": "blockers is non-empty, schedule_handoff.ready=false, or any submit action lacks explicit user approval",
        "safety": {
            "mutates_state": False,
            "uploads": False,
            "compose_scheduler_creates_candidate_jobs_only": True,
            "submit_requires_user_approval": True,
            "live_upload_requires_confirm_upload": True,
            "publish_payload_field": "daily_candidate_batch_publish_payload",
        },
        "blockers": blocked_by,
        "warnings": warnings,
        "next_actions": _deployment_daily_candidate_trigger_next_actions(ready, schedule_ready, api_ready, compose_daily_ready, blocked_by),
    }


def _first_target_value(value: Any) -> str:
    if isinstance(value, list) and value:
        return str(value[0]).upper()
    if isinstance(value, tuple) and value:
        return str(value[0]).upper()
    return str(value or "MTEAM").upper()


def _deployment_daily_candidate_trigger_next_actions(ready: bool, schedule_ready: bool, api_ready: bool, compose_daily_ready: bool, blockers: list[str]) -> list[str]:
    if ready:
        return ["Start ptcli-daily-scheduler or call daily_candidates_schedule_job, read daily_candidate_batch_publish_payload, then deliver it through daily_candidate_delivery."]
    if blockers:
        return ["Resolve daily_candidate_trigger_handoff.blockers, then rerun deployment_check."]
    if not schedule_ready:
        return [f"Configure {DAILY_CANDIDATE_SCHEDULE_ENV}, then rerun deployment_check."]
    if not api_ready or not compose_daily_ready:
        return ["Repair docker-compose.yml ptcli-api and daily profile services, then rerun deployment_check."]
    return ["Inspect daily_candidate_trigger_handoff before enabling daily delivery."]


def _deployment_daily_candidate_delivery_handoff(
    daily_candidate_plan: dict[str, Any],
    docker_compose: dict[str, Any],
    trigger_handoff: dict[str, Any],
    blockers: list[str],
    warnings: list[str],
) -> dict[str, Any]:
    api = trigger_handoff.get("api") if isinstance(trigger_handoff.get("api"), dict) else {}
    compose = trigger_handoff.get("compose") if isinstance(trigger_handoff.get("compose"), dict) else {}
    batch_status = api.get("batch_status") if isinstance(api.get("batch_status"), dict) else {}
    webhook_configured = bool(os.environ.get("PTCLI_DAILY_CANDIDATE_WEBHOOK_URL"))
    trigger_ready = bool(trigger_handoff.get("ready"))
    api_ready = bool(docker_compose.get("ptcli_api_service_ready"))
    file_ready = bool(docker_compose.get("daily_scheduler_service_ready") or docker_compose.get("daily_schedule_service_ready"))
    delivery_blockers = list(blockers)
    delivery_blockers.extend(_string_list(trigger_handoff.get("blockers")))
    delivery_blockers = list(dict.fromkeys(delivery_blockers))
    ready = bool((trigger_ready or api_ready or file_ready) and not delivery_blockers)
    status = "ready" if ready else "blocked" if delivery_blockers else "configure_delivery"
    publish_payload_sources = [
        "daily_candidate_batch_status.daily_candidate_batch_publish_payload",
        "daily_candidate_delivery.request.daily_candidate_batch_publish_payload",
        "daily_candidate_trigger_handoff.api.batch_status",
        "ptcli-daily-candidates-notification.json.notification_payload",
        "ptcli-daily-schedule-summary.json.notification_payload",
    ]
    digest_evidence_refs = [
        "daily_candidate_batch_publish_payload.items",
        "daily_candidate_batch_publish_payload.top_item",
        "daily_candidate_batch_publish_payload.approval_queue",
        "daily_candidate_batch_publish_payload.tracking",
        "daily_candidate_batch_publish_payload.completion_report",
    ]
    completion_evidence_refs = [
        "daily_candidate_batch_publish_payload.completion_items[].qbit_enforcement_ready",
        "daily_candidate_batch_publish_payload.completion_items[].qbit_execution_ready",
        "daily_candidate_batch_publish_payload.completion_items[].uploaded_seeding_ready",
        "daily_candidate_batch_publish_payload.completion_report.completed_jobs[].qbit_enforcement_summary",
        "daily_candidate_batch_publish_payload.completion_report.completed_jobs[].qbit_execution_gate",
        "daily_candidate_batch_publish_payload.completion_report.completed_jobs[].uploaded_seeding_evidence",
    ]
    return {
        "kind": "ptcli.daily_candidate_deployment_delivery_handoff",
        "ready": ready,
        "status": status,
        "action": "publish_daily_candidate_digest" if ready else "repair_daily_candidate_delivery",
        "read_only": True,
        "publish_payload_field": "daily_candidate_batch_publish_payload",
        "notification_payload_field": "notification_payload",
        "publish_payload_sources": publish_payload_sources,
        "digest_evidence_refs": digest_evidence_refs,
        "completion_evidence_refs": completion_evidence_refs,
        "evidence_contract": {
            "candidate_digest_ready_when": "daily_candidate_batch_publish_payload.ready=true and items or approval_queue are present",
            "completion_ready_when": "daily_candidate_batch_publish_payload.status=ready_to_report and completion_items[].uploaded_seeding_ready=true",
            "must_read_before_reporting_completion": completion_evidence_refs,
            "must_read_before_submitting_candidate": [
                "daily_candidate_batch_publish_payload.approval_queue.items[].candidate_execution_context",
                "daily_candidate_batch_publish_payload.approval_queue.items[].submit_request",
                "daily_candidate_batch_publish_payload.approval_queue.items[].required_overrides",
            ],
            "stop_when": [
                "daily_candidate_batch_publish_payload.blockers is non-empty",
                "completion_items[].qbit_enforcement_ready=false",
                "completion_items[].uploaded_seeding_ready=false",
                "user approval is missing before submit_daily_candidate_job",
            ],
        },
        "channels": {
            "ai_pull": {
                "ready": api_ready,
                "tool": batch_status.get("tool") or "daily_candidate_batch_status",
                "endpoint": batch_status.get("endpoint") or "/v1/jobs/candidates/daily/batch",
                "method": batch_status.get("method") or "GET",
                "request": batch_status.get("request"),
                "payload_field": "daily_candidate_batch_publish_payload",
                "safe_to_retry": True,
            },
            "delivery_api": {
                "ready": api_ready,
                "tool": "daily_candidate_delivery",
                "endpoint": "/v1/candidates/daily/deliver",
                "method": "POST",
                "request": {
                    "daily_candidate_batch_publish_payload": "<daily_candidate_batch_publish_payload>",
                    "delivery_handoff": "<daily_candidate_delivery_handoff>",
                    "write_files": True,
                    "use_env_webhook": True,
                },
                "result_fields": ["file_delivery", "webhook_delivery", "payload_fingerprint", "evidence_contract"],
                "safe_to_retry": True,
            },
            "local_files": {
                "ready": file_ready,
                "enabled_by_compose": True,
                "write_notification": True,
                "summary_file": compose.get("summary_file") or "/Upload-Assistant/tmp/daily-candidates/ptcli-daily-schedule-summary.json",
                "notification_files": compose.get("notification_files")
                or [
                    "/Upload-Assistant/tmp/daily-candidates/ptcli-daily-candidates-notification.json",
                    "/Upload-Assistant/tmp/daily-candidates/ptcli-daily-candidates-notification.txt",
                ],
                "payload_field": "notification_payload",
                "safe_to_retry": True,
            },
            "webhook": {
                "ready": webhook_configured,
                "configured": webhook_configured,
                "env": "PTCLI_DAILY_CANDIDATE_WEBHOOK_URL",
                "url": "<configured>" if webhook_configured else None,
                "payload_field": "notification_payload",
                "safe_to_retry": True,
            },
        },
        "delivery_plan": daily_candidate_plan.get("daily_candidate_delivery_plan") if isinstance(daily_candidate_plan.get("daily_candidate_delivery_plan"), dict) else {},
        "delivery_final_report": daily_candidate_plan.get("daily_candidate_delivery_final_report") if isinstance(daily_candidate_plan.get("daily_candidate_delivery_final_report"), dict) else {},
        "workflow": [
            {"index": 1, "name": "trigger_daily_candidates", "tool": "daily_candidates_schedule_job", "endpoint": "/v1/jobs/candidates/daily/schedule", "method": "POST", "request": api.get("create_jobs", {}).get("request") if isinstance(api.get("create_jobs"), dict) else None, "continue_when": "candidate jobs are queued or complete", "stop_when": "daily_candidate_trigger_handoff.blockers is non-empty"},
            {"index": 2, "name": "read_publish_payload", "tool": "daily_candidate_batch_status", "endpoint": "/v1/jobs/candidates/daily/batch", "method": "GET", "request": batch_status.get("request"), "read": ["daily_candidate_batch_publish_payload", "daily_candidate_tracking_report", "daily_candidate_batch_publish_payload.completion_report", "daily_candidate_batch_publish_payload.completion_items"], "continue_when": "daily_candidate_batch_publish_payload is present", "stop_when": "daily_candidate_batch_publish_payload.blockers is non-empty"},
            {"index": 3, "name": "deliver_digest", "tool": "daily_candidate_delivery", "endpoint": "/v1/candidates/daily/deliver", "method": "POST", "request": {"daily_candidate_batch_publish_payload": "<daily_candidate_batch_publish_payload>", "delivery_handoff": "<daily_candidate_delivery_handoff>", "write_files": True, "use_env_webhook": True}, "read": publish_payload_sources + digest_evidence_refs + ["daily_candidate_delivery_result.file_delivery", "daily_candidate_delivery_result.webhook_delivery", "daily_candidate_delivery_result.payload_fingerprint"], "continue_when": "daily_candidate_delivery_result.ok=true and digest is visible to the AI/IM/webhook consumer", "stop_when": "daily_candidate_delivery_result.blockers is non-empty or no delivery channel can read notification_payload or daily_candidate_batch_publish_payload"},
            {"index": 4, "name": "wait_for_user_approval", "tool": "ask_user", "endpoint": None, "method": None, "read": ["approval_queue", "first_approval_prompt", "submit_request"], "continue_when": "user explicitly approves a candidate", "stop_when": "user does not approve or candidate blockers are present"},
            {"index": 5, "name": "report_completed_retorrents", "tool": "daily_candidate_batch_status", "endpoint": "/v1/jobs/candidates/daily/batch", "method": "GET", "request": batch_status.get("request"), "read": completion_evidence_refs, "continue_when": "all completed jobs have uploaded_seeding_ready=true or blockers explain why not", "stop_when": "completion evidence is missing"},
        ],
        "read_order": ["daily_candidate_delivery_handoff", "daily_candidate_trigger_handoff", "daily_candidate_batch_publish_payload", "daily_candidate_batch_publish_payload.completion_report", "daily_candidate_batch_publish_payload.completion_items", "notification_payload", "daily_candidate_delivery_final_report"],
        "continue_when": "daily_candidate_delivery_handoff.ready=true and one channel has delivered the digest; submit only after explicit user approval",
        "stop_when": "delivery_handoff.blockers is non-empty or any submit action lacks accept_rules=true and confirm_upload=true",
        "safety": {
            "publishing_mutates_tracker": False,
            "publishing_uploads": False,
            "contacts_trackers": False,
            "contacts_qbittorrent": False,
            "submit_requires_user_approval": True,
            "submit_requires": ["accept_rules=true", "confirm_upload=true", "duplicate_check.exists=false", "site policy gate ready"],
            "webhook_payload_contains_no_credentials": True,
        },
        "blockers": delivery_blockers,
        "warnings": warnings,
        "next_actions": _deployment_daily_candidate_delivery_next_actions(ready, api_ready, file_ready, webhook_configured, delivery_blockers),
    }


def _deployment_daily_candidate_delivery_next_actions(ready: bool, api_ready: bool, file_ready: bool, webhook_configured: bool, blockers: list[str]) -> list[str]:
    if blockers:
        return ["Resolve daily_candidate_delivery_handoff.blockers, then rerun deployment_check."]
    if ready:
        actions = ["Call daily_candidate_delivery with daily_candidate_batch_publish_payload, or consume local notification files/webhook output; this does not submit or upload torrents."]
        if not webhook_configured:
            actions.append("Optionally set PTCLI_DAILY_CANDIDATE_WEBHOOK_URL to push the digest to an external consumer.")
        return actions
    if not api_ready and not file_ready:
        return ["Start ptcli-api or the daily compose profile so a delivery channel can expose the daily candidate digest."]
    return ["Inspect daily_candidate_delivery_handoff.channels before publishing the daily candidate digest."]


def _deployment_final_report(
    *,
    ready: bool,
    paths: dict[str, str],
    mounts: dict[str, Any],
    runtime_tools: dict[str, Any],
    qbit: dict[str, Any],
    daily_candidate_plan: dict[str, Any],
    docker_compose: dict[str, Any],
    env_template: dict[str, Any],
    deployment_handoff: dict[str, Any],
    seedbox_bootstrap_handoff: dict[str, Any],
    agent_summary: dict[str, Any],
    blockers: list[str],
    warnings: list[str],
) -> dict[str, Any]:
    api = deployment_handoff.get("api") if isinstance(deployment_handoff.get("api"), dict) else {}
    compose_ready = bool(docker_compose.get("ptcli_api_service_ready"))
    final_ready = bool(ready and compose_ready and agent_summary.get("ready_for_ai"))
    if final_ready:
        verdict = "ready_for_readiness_bundle"
    elif blockers:
        verdict = "blocked"
    else:
        verdict = "compose_or_warning_incomplete"
    recommended_call = _deployment_final_report_recommended_call(final_ready, compose_ready, blockers, seedbox_bootstrap_handoff, deployment_handoff)
    return {
        "kind": "ptcli.deployment_final_report",
        "ready": final_ready,
        "report_allowed": final_ready,
        "verdict": verdict,
        "deployment_status": "ready" if final_ready else "blocked",
        "read_only": True,
        "docker": {
            "compose_file": paths.get("compose_file") or docker_compose.get("path"),
            "ptcli_api_service_ready": compose_ready,
            "daily_scheduler_ready": bool(docker_compose.get("daily_scheduler_service_ready")),
            "daily_schedule_ready": bool(docker_compose.get("daily_schedule_service_ready")),
            "localhost_port": bool(docker_compose.get("ptcli_api_localhost_port")),
            "host_gateway": bool(docker_compose.get("host_gateway")),
            "host_path_envs": bool(docker_compose.get("host_path_envs")),
            "start_api_command": (seedbox_bootstrap_handoff.get("compose") or {}).get("start_api") if isinstance(seedbox_bootstrap_handoff.get("compose"), dict) else None,
            "start_daily_scheduler_command": (seedbox_bootstrap_handoff.get("compose") or {}).get("start_daily_scheduler") if isinstance(seedbox_bootstrap_handoff.get("compose"), dict) else None,
        },
        "api": {
            "base_url": api.get("base_url"),
            "health": api.get("health"),
            "openapi": api.get("openapi"),
            "tools": api.get("tools"),
            "agent_manifest": api.get("agent_manifest"),
            "localhost_bound": bool(api.get("localhost_bound")),
            "publicly_exposed": bool(api.get("publicly_exposed")),
            "token_configured": bool(api.get("token_configured")),
            "auth_recommended": bool(api.get("auth_recommended")),
            "auth_ready": bool(api.get("auth_ready")),
            "exposure_blocked": bool(api.get("exposure_blocked")),
            "auth_header": "Authorization: Bearer <PTCLI_API_TOKEN>",
        },
        "mounts": {
            "ready": bool(mounts.get("ready")),
            "missing_count": len(mounts.get("missing") or []),
            "required": mounts.get("required") if isinstance(mounts.get("required"), list) else [],
            "missing": mounts.get("missing") if isinstance(mounts.get("missing"), list) else [],
        },
        "env": {
            "template_ready": bool(env_template.get("ready")),
            "env_present": bool(env_template.get("env_present")),
            "copy_command": env_template.get("copy_command"),
            "missing_keys": env_template.get("missing_keys") if isinstance(env_template.get("missing_keys"), list) else [],
        },
        "runtime": {
            "material_tools_ready": bool(runtime_tools.get("ready")),
            "missing_required": runtime_tools.get("missing_required") if isinstance(runtime_tools.get("missing_required"), list) else [],
            "job_dir": paths.get("job_dir"),
            "downloads_path": paths.get("downloads_path"),
        },
        "qbit": {
            "configured": bool(qbit.get("configured")),
            "client": qbit.get("client"),
            "url": qbit.get("qbit_url"),
            "connectivity_checked": bool(qbit.get("connectivity_checked")),
        },
        "workflows": {
            "manual_retorrent_ready": bool(agent_summary.get("manual_workflow_ready")),
            "daily_candidates_ready": bool(agent_summary.get("daily_workflow_ready")),
            "daily_schedule_count": daily_candidate_plan.get("count", 0),
        },
        "safety": {
            "mutates_state": False,
            "contacts_trackers": False,
            "contacts_qbittorrent": False,
            "live_upload_requires": ["accept_rules=true", "confirm_upload=true", "duplicate_check.exists=false", "site policy ready"],
            "do_not_expose_without_token": not bool(api.get("token_configured")),
            "api_exposure_gate": "blocked" if api.get("exposure_blocked") else "ready",
            "api_exposure_rule": "Public or 0.0.0.0 ptcli-api port mappings require PTCLI_API_TOKEN; localhost-only bindings may run without a token for local AI access.",
        },
        "recommended_call": recommended_call,
        "read_order": ["deployment_final_report", "deployment_handoff", "seedbox_bootstrap_handoff", "deployment_runbook", "agent_summary", "docker_compose", "mounts", "qbit"],
        "complete_when": ["deployment_final_report.ready=true", "docker.ptcli_api_service_ready=true", "mounts.ready=true", "qbit.configured=true", "api.health returns status=ok"],
        "stop_when": ["blockers is non-empty", "docker.ptcli_api_service_ready=false", "config/cookies/downloads/tmp/job paths are missing", "qBittorrent config is missing"],
        "blockers": blockers if blockers else ([] if compose_ready else ["Docker Compose ptcli-api service is incomplete."]),
        "warnings": warnings,
        "next_actions": ["Run readiness_bundle with source/target and explicit confirmations, then follow live_execution_package."] if final_ready else _deployment_final_report_next_actions(compose_ready, blockers, warnings),
    }


def _deployment_final_report_recommended_call(
    final_ready: bool,
    compose_ready: bool,
    blockers: list[str],
    seedbox_bootstrap_handoff: dict[str, Any],
    deployment_handoff: dict[str, Any],
) -> dict[str, Any]:
    if final_ready:
        return {
            "tool": "readiness_bundle",
            "endpoint": "/v1/readiness/bundle",
            "method": "POST",
            "request": {"source_tracker": "U2", "source_id": "60635", "target": "MTEAM", "accept_rules": True, "confirm_upload": True},
            "safe_to_call_now": True,
        }
    if blockers:
        return {"tool": "deployment_check", "endpoint": "/v1/deployment/check", "method": "GET", "request": None, "safe_to_call_now": True, "blockers": blockers}
    if not compose_ready:
        next_step = seedbox_bootstrap_handoff.get("next_step") if isinstance(seedbox_bootstrap_handoff.get("next_step"), dict) else {}
        return {
            "tool": next_step.get("tool") or "deployment_check",
            "endpoint": next_step.get("endpoint") or "/v1/deployment/check",
            "method": next_step.get("method") or "GET",
            "request": next_step.get("request"),
            "safe_to_call_now": next_step.get("tool") != "shell",
            "reason": "repair_docker_compose",
        }
    next_step = deployment_handoff.get("next_step") if isinstance(deployment_handoff.get("next_step"), dict) else {}
    return {
        "tool": next_step.get("tool") or "deployment_check",
        "endpoint": next_step.get("endpoint") or "/v1/deployment/check",
        "method": "GET" if next_step.get("tool") == "deployment_check" else "POST",
        "request": next_step.get("request"),
        "safe_to_call_now": True,
        "reason": "resolve_deployment_warnings",
    }


def _deployment_final_report_next_actions(compose_ready: bool, blockers: list[str], warnings: list[str]) -> list[str]:
    if blockers:
        return ["Resolve deployment_final_report.blockers, then rerun deployment_check."]
    if not compose_ready:
        return ["Repair docker-compose.yml ptcli-api service, then rerun deployment_check before exposing the API to OpenClaw/Hermes."]
    if warnings:
        return ["Review deployment_final_report.warnings, then run readiness_bundle before any live retorrent job."]
    return ["Rerun deployment_check and inspect deployment_final_report.recommended_call."]


def _deployment_seedbox_live_trial_handoff(
    *,
    ready: bool,
    paths: dict[str, str],
    qbit: dict[str, Any],
    docker_compose: dict[str, Any],
    deployment_handoff: dict[str, Any],
    seedbox_bootstrap_handoff: dict[str, Any],
    deployment_final_report: dict[str, Any],
    agent_summary: dict[str, Any],
    blockers: list[str],
    warnings: list[str],
) -> dict[str, Any]:
    api = deployment_handoff.get("api") if isinstance(deployment_handoff.get("api"), dict) else {}
    api_base_url = str(api.get("base_url") or os.environ.get("PTCLI_PUBLIC_BASE_URL") or "http://127.0.0.1:8080").rstrip("/")
    compose = seedbox_bootstrap_handoff.get("compose") if isinstance(seedbox_bootstrap_handoff.get("compose"), dict) else {}
    compose_file = str(paths.get("compose_file") or docker_compose.get("path") or "docker-compose.yml")
    final_ready = bool(ready and deployment_final_report.get("ready") and agent_summary.get("manual_workflow_ready") and docker_compose.get("ptcli_api_service_ready"))
    readiness_request = {
        "source_tracker": "U2",
        "source_id": "60635",
        "target": "MTEAM",
        "accept_rules": True,
        "confirm_upload": True,
        "save_path": paths.get("downloads_path") or "/downloads",
        "connect_qbit": True,
    }
    return {
        "kind": "ptcli.seedbox_live_trial_handoff",
        "ready": final_ready,
        "status": "ready" if final_ready else "blocked",
        "action": "run_readiness_bundle" if final_ready else "repair_deployment",
        "read_only": True,
        "compose": {
            "file": compose_file,
            "start_api": compose.get("start_api") or f"docker compose -f {compose_file} up -d --build ptcli-api",
            "check_health": f"curl -fsS {api_base_url}/health",
            "logs": f"docker compose -f {compose_file} logs -f ptcli-api",
            "start_daily_scheduler_after_trial": compose.get("start_daily_scheduler") or f"docker compose -f {compose_file} --profile daily up -d ptcli-daily-scheduler",
        },
        "api": {
            "base_url": api_base_url,
            "health": api.get("health") or f"{api_base_url}/health",
            "openapi": api.get("openapi") or f"{api_base_url}/openapi.json",
            "tools": api.get("tools") or f"{api_base_url}/v1/tools",
            "deployment_check": f"{api_base_url}/v1/deployment/check",
            "readiness_bundle": f"{api_base_url}/v1/readiness/bundle",
            "jobs": f"{api_base_url}/v1/jobs",
            "auth_header": "Authorization: Bearer <PTCLI_API_TOKEN>",
            "token_configured": bool(api.get("token_configured")),
            "auth_recommended": bool(api.get("auth_recommended")),
            "auth_ready": bool(api.get("auth_ready")),
            "publicly_exposed": bool(api.get("publicly_exposed")),
            "exposure_blocked": bool(api.get("exposure_blocked")),
        },
        "readiness": {
            "tool": "readiness_bundle",
            "endpoint": "/v1/readiness/bundle",
            "method": "POST",
            "request_template": readiness_request,
            "read": ["live_readiness", "seedbox_live_validation_handoff", "first_live_validation_handoff", "live_execution_package"],
            "continue_when": "seedbox_live_validation_handoff.validation_report.ready=true and first_live_validation_handoff.ready=true",
            "stop_when": "validation_report.first_blocker is present or duplicate_check.exists=true",
        },
        "live_order": [
            {
                "index": 1,
                "name": "deployment_check",
                "tool": "deployment_check",
                "endpoint": "/v1/deployment/check",
                "continue_when": "ready=true and seedbox_live_trial_handoff.ready=true",
            },
            {
                "index": 2,
                "name": "readiness_bundle",
                "tool": "readiness_bundle",
                "endpoint": "/v1/readiness/bundle",
                "request": readiness_request,
                "continue_when": "first_live_validation_handoff.ready=true",
            },
            {
                "index": 3,
                "name": "doctor",
                "tool": "retorrent_doctor",
                "source": "first_live_validation_handoff.doctor",
                "continue_when": "doctor_result_handoff.live_safe_to_attempt=true",
            },
            {
                "index": 4,
                "name": "check_and_submit",
                "tool": "source_url_check_and_submit",
                "endpoint": "/v1/jobs/retorrent/from-url/check-and-submit",
                "continue_when": "job_id is present and status in queued/running/blocked/complete",
            },
            {
                "index": 5,
                "name": "poll_or_resume",
                "tool": "get_job_status",
                "endpoint": "/v1/jobs/{job_id}",
                "continue_when": "job status complete or blocked with resume_state/next_actions",
            },
            {
                "index": 6,
                "name": "read_summary",
                "tool": "get_job_summary",
                "endpoint": "/v1/jobs/{job_id}/summary",
                "continue_when": "live_validation_completion_audit.report_allowed=true and uploaded torrent seeding evidence exists",
            },
        ],
        "report_contract": {
            "final_report_field": LIVE_VALIDATION_FINAL_REPORT_FIELD,
            "audit_report_fields": ["seedbox_live_validation_completion_report", "live_validation_final_report", "uploaded_seeding"],
            "complete_when": [
                "job.status=complete",
                "duplicate_check.exists=false",
                *LIVE_VALIDATION_COMPLETE_WHEN,
                "target_upload.uploaded_torrent_hash is present",
                "uploaded_seeding.injected_torrent_hash is present",
                "uploaded_seeding.injection_verified=true",
            ],
            "blocked_when": ["blockers is non-empty", "doctor_result_handoff.live_safe_to_attempt=false", "rules or confirmations missing"],
        },
        "safety": {
            "mutates_state": False,
            "contacts_trackers": False,
            "contacts_qbittorrent": False,
            "live_upload": False,
            "live_upload_requires": ["accept_rules=true", "confirm_upload=true", "duplicate_check.exists=false", "site policy ready", "doctor_result_handoff.live_safe_to_attempt=true"],
            "first_mutating_call": "source_url_check_and_submit only after readiness and doctor pass",
        },
        "required_confirmations": ["accept_rules=true", "confirm_upload=true", "source and target rules reviewed", "target duplicate check is clean"],
        "qbit": {
            "configured": bool(qbit.get("configured")),
            "client": qbit.get("client"),
            "url": qbit.get("qbit_url"),
            "connectivity_checked": bool(qbit.get("connectivity_checked")),
        },
        "next_step": {
            "tool": "readiness_bundle" if final_ready else "deployment_check",
            "endpoint": "/v1/readiness/bundle" if final_ready else "/v1/deployment/check",
            "method": "POST" if final_ready else "GET",
            "request": readiness_request if final_ready else None,
            "safe_to_call_now": True,
            "reason": "first_seedbox_live_trial" if final_ready else "repair_deployment_before_live_trial",
        },
        "blockers": [] if final_ready else blockers or ["Deployment is not ready for a seedbox live trial."],
        "warnings": warnings,
        "next_actions": ["Run seedbox_live_trial_handoff.readiness, then follow live_order in order."] if final_ready else ["Resolve seedbox_live_trial_handoff.blockers, then rerun deployment_check."],
    }


def _deployment_seedbox_bootstrap_handoff(
    agent_summary: dict[str, Any],
    paths: dict[str, str],
    mounts: dict[str, Any],
    qbit: dict[str, Any],
    daily_candidate_plan: dict[str, Any],
    docker_compose: dict[str, Any],
    env_template: dict[str, Any],
    blockers: list[str],
    warnings: list[str],
) -> dict[str, Any]:
    missing_mounts = mounts.get("missing") if isinstance(mounts.get("missing"), list) else []
    mkdir_paths = [str(item.get("path")) for item in missing_mounts if isinstance(item, dict) and item.get("path") and item.get("name") != "config"]
    config_path = str(paths.get("config") or "data/config.py")
    env_path = str(paths.get("env_file") or ".env")
    compose_file = str(paths.get("compose_file") or docker_compose.get("path") or "docker-compose.yml")
    ready = bool(agent_summary.get("ready_for_ai") and docker_compose.get("ptcli_api_service_ready"))
    next_step = _deployment_seedbox_bootstrap_next_step(ready, mkdir_paths, env_template, docker_compose, blockers)
    return {
        "kind": "ptcli.seedbox_bootstrap_handoff",
        "ready": ready,
        "action": "ready_for_readiness_bundle" if ready else "prepare_seedbox_paths_and_env",
        "read_only": True,
        "configured_paths": paths,
        "missing_mounts": missing_mounts,
        "mkdir_commands": [f"mkdir -p {path}" for path in mkdir_paths],
        "config_file": {
            "path": config_path,
            "required": True,
            "create_from": "data/example-config.py or an existing Upload-Assistant data/config.py",
            "manual_edit_required": ["TRACKERS credentials/cookies", "TORRENT_CLIENTS.qbittorrent", "PTCLI.SITE_POLICIES"],
        },
        "env_file": {
            "path": env_path,
            "template": env_template.get("template_path"),
            "copy_command": env_template.get("copy_command"),
            "missing_keys": env_template.get("missing_keys") if isinstance(env_template.get("missing_keys"), list) else [],
            "edit_after_copy": env_template.get("edit_after_copy") if isinstance(env_template.get("edit_after_copy"), list) else [],
        },
        "compose": {
            "file": compose_file,
            "api_ready": bool(docker_compose.get("ptcli_api_service_ready")),
            "daily_ready": bool(docker_compose.get("daily_scheduler_service_ready") or docker_compose.get("daily_schedule_service_ready")),
            "host_path_envs": bool(docker_compose.get("host_path_envs")),
            "start_api": f"docker compose -f {compose_file} up -d --build ptcli-api",
            "start_daily_scheduler": f"docker compose -f {compose_file} --profile daily up -d ptcli-daily-scheduler",
        },
        "qbit": {
            "configured": bool(qbit.get("configured")),
            "client": qbit.get("client"),
            "host_hint": qbit.get("qbit_url") or "http://host.docker.internal",
            "connectivity_checked": bool(qbit.get("connectivity_checked")),
        },
        "daily_candidates": {
            "configured": bool(daily_candidate_plan.get("configured")),
            "schedule_handoff": daily_candidate_plan.get("schedule_handoff") if isinstance(daily_candidate_plan.get("schedule_handoff"), dict) else {},
        },
        "verification_requests": [
            {"method": "GET", "endpoint": "/health", "continue_when": "status=ok"},
            {"method": "GET", "endpoint": "/openapi.json", "continue_when": "contains /v1/tools and job endpoints"},
            {"method": "GET", "endpoint": "/v1/deployment/check", "continue_when": "ready=true or only non-blocking warnings remain"},
            {"method": "POST", "endpoint": "/v1/readiness/bundle", "continue_when": "live_validation_repair_plan.ready=true before doctor/live jobs"},
        ],
        "next_step": next_step,
        "recommended_tool": next_step.get("tool"),
        "recommended_endpoint": next_step.get("endpoint"),
        "recommended_request": next_step.get("request"),
        "continue_when": "seedbox_bootstrap_handoff.ready=true and deployment_check.ready=true",
        "stop_when": ["missing config.py", "downloads/job/tmp paths are absent or not writable", "qBittorrent config missing", "ptcli-api compose service incomplete"],
        "blockers": blockers,
        "warnings": warnings,
        "next_actions": _deployment_seedbox_bootstrap_next_actions(ready, mkdir_paths, blockers, warnings),
    }


def _deployment_seedbox_bootstrap_next_step(
    ready: bool,
    mkdir_paths: list[str],
    env_template: dict[str, Any],
    docker_compose: dict[str, Any],
    blockers: list[str],
) -> dict[str, Any]:
    if ready:
        return {"tool": "readiness_bundle", "endpoint": "/v1/readiness/bundle", "method": "POST", "request": {"source_tracker": "U2", "source_id": "60635", "target": "MTEAM", "accept_rules": True, "confirm_upload": True}, "reason": "deployment_bootstrap_ready"}
    if mkdir_paths:
        return {"tool": "shell", "endpoint": None, "method": None, "request": {"commands": [f"mkdir -p {path}" for path in mkdir_paths]}, "reason": "create_missing_seedbox_directories"}
    if env_template.get("env_present") is not True:
        return {"tool": "shell", "endpoint": None, "method": None, "request": {"commands": [str(env_template.get("copy_command") or "cp .env.ptcli.example .env")]}, "reason": "copy_env_template"}
    if docker_compose.get("ptcli_api_service_ready") is not True:
        return {"tool": "deployment_check", "endpoint": "/v1/deployment/check", "method": "GET", "request": None, "reason": "repair_docker_compose"}
    return {"tool": "deployment_check", "endpoint": "/v1/deployment/check", "method": "GET", "request": None, "reason": "resolve_deployment_blockers", "blockers": blockers}


def _deployment_seedbox_bootstrap_next_actions(ready: bool, mkdir_paths: list[str], blockers: list[str], warnings: list[str]) -> list[str]:
    if ready:
        return ["Run readiness_bundle with source/target and explicit confirmations, then follow live_execution_package before any live upload."]
    if mkdir_paths:
        return ["Create missing seedbox directories from seedbox_bootstrap_handoff.mkdir_commands, then rerun deployment_check."]
    if blockers:
        return ["Resolve seedbox_bootstrap_handoff.blockers in order, then rerun deployment_check."]
    if warnings:
        return ["Review seedbox_bootstrap_handoff.warnings before exposing the API or enabling daily candidate delivery."]
    return ["Inspect seedbox_bootstrap_handoff.next_step and rerun deployment_check after repair."]


def _deployment_runbook(
    agent_summary: dict[str, Any],
    paths: dict[str, str],
    qbit: dict[str, Any],
    daily_candidate_plan: dict[str, Any],
    docker_compose: dict[str, Any],
    env_template: dict[str, Any],
    blockers: list[str],
    warnings: list[str],
) -> dict[str, Any]:
    api_base_url = os.environ.get("PTCLI_PUBLIC_BASE_URL") or "http://127.0.0.1:8080"
    compose_file = str(paths.get("compose_file") or docker_compose.get("path") or "docker-compose.yml")
    ready = bool(agent_summary.get("ready_for_ai") and docker_compose.get("ptcli_api_service_ready"))
    steps = [
        {
            "index": 1,
            "name": "prepare_env",
            "kind": "shell",
            "command": str(env_template.get("copy_command") or "cp .env.ptcli.example .env"),
            "read": [".env", "PTCLI_API_TOKEN", "PTCLI_PUBLIC_BASE_URL", "PTCLI_DAILY_CANDIDATE_SCHEDULES"],
            "continue_when": "deployment_env.ready=true, .env exists, and host paths in docker-compose.yml are adjusted for the seedbox",
            "stop_when": "config/cookies/downloads/tmp host paths are not mapped to the seedbox paths",
            "env_template": env_template,
        },
        {
            "index": 2,
            "name": "build_and_start_api",
            "kind": "shell",
            "command": f"docker compose -f {compose_file} up -d --build ptcli-api",
            "read": ["docker compose ps ptcli-api", "healthcheck"],
            "continue_when": "ptcli-api is running and healthcheck is healthy",
            "stop_when": "container exits, healthcheck fails, or port 127.0.0.1:8080 is unavailable",
        },
        {
            "index": 3,
            "name": "verify_api_contracts",
            "kind": "http",
            "requests": [
                {"method": "GET", "url": f"{api_base_url.rstrip('/')}/health"},
                {"method": "GET", "url": f"{api_base_url.rstrip('/')}/openapi.json"},
                {"method": "GET", "url": f"{api_base_url.rstrip('/')}/v1/tools"},
                {"method": "GET", "url": f"{api_base_url.rstrip('/')}/.well-known/ptcli-agent.json"},
            ],
            "continue_when": "all requests return 200 and JSON contains expected kind/schema fields",
            "stop_when": "API token/auth, reverse proxy, or localhost binding prevents AI access",
        },
        {
            "index": 4,
            "name": "check_deployment",
            "kind": "http",
            "request": {"method": "GET", "url": f"{api_base_url.rstrip('/')}/v1/deployment/check"},
            "read": ["ready", "deployment_runbook", "agent_summary", "docker_compose", "qbit", "blockers"],
            "continue_when": "ready=true and agent_summary.manual_workflow_ready=true",
            "stop_when": "blockers is non-empty",
        },
        {
            "index": 5,
            "name": "readiness_bundle",
            "kind": "http",
            "request": {
                "method": "POST",
                "url": f"{api_base_url.rstrip('/')}/v1/readiness/bundle",
                "json": {
                    "source_tracker": "U2",
                    "source_id": "60635",
                    "target": "MTEAM",
                    "accept_rules": True,
                    "confirm_upload": True,
                    "save_path": paths.get("downloads_path") or "/downloads",
                },
            },
            "read": ["live_readiness", "seedbox_live_validation_handoff.validation_report", "seedbox_live_validation_handoff.validation_plan"],
            "continue_when": "seedbox_live_validation_handoff.validation_report.ready=true",
            "stop_when": "validation_report.first_blocker is present",
        },
        {
            "index": 6,
            "name": "first_live_validation",
            "kind": "guided",
            "read": ["seedbox_live_validation_handoff.doctor", "seedbox_live_validation_handoff.manual_job", "seedbox_live_validation_handoff.post_submit_handoff"],
            "continue_when": "doctor_result_handoff.live_safe_to_attempt=true then source_url_check_and_submit returns job_id",
            "stop_when": "duplicate_check.exists=true, doctor_result_handoff.live_safe_to_attempt=false, or live upload confirmations are missing",
        },
    ]
    return {
        "kind": "ptcli.deployment_runbook",
        "ready": ready,
        "compose_file": compose_file,
        "api_base_url": api_base_url,
        "service": "ptcli-api",
        "steps": steps,
        "first_step": "build_and_start_api" if docker_compose.get("ptcli_api_service_ready") else "prepare_env",
        "daily_candidates": {
            "configured": bool(daily_candidate_plan.get("configured")),
            "schedule_count": daily_candidate_plan.get("count", 0),
            "optional_start_command": f"docker compose -f {compose_file} --profile daily up -d ptcli-daily-scheduler",
        },
        "env": {
            "template_ready": bool(env_template.get("ready")),
            "template_path": env_template.get("template_path"),
            "env_path": env_template.get("env_path"),
            "copy_command": env_template.get("copy_command"),
            "missing_keys": env_template.get("missing_keys") if isinstance(env_template.get("missing_keys"), list) else [],
        },
        "qbit": {
            "configured": bool(qbit.get("configured")),
            "host_hint": "Use http://host.docker.internal for host qBittorrent, or a Docker service name when qBittorrent shares the compose network.",
            "client": qbit.get("client"),
        },
        "safety": {
            "api_localhost_bound": bool(docker_compose.get("ptcli_api_localhost_port")),
            "api_token_configured": bool(agent_summary.get("api_token_configured")),
            "live_upload_requires": ["accept_rules=true", "confirm_upload=true", "duplicate_check.exists=false", "site policy ready"],
        },
        "blockers": blockers,
        "warnings": warnings,
    }


