def _deployment_handoff_blockers(agent_summary: dict[str, Any], blockers: list[str], *, require_daily: bool) -> list[str]:
    items = list(blockers)
    if agent_summary.get("qbit_configured") is not True:
        items.append("qBittorrent is not configured.")
    if require_daily and agent_summary.get("daily_candidates_configured") is not True:
        items.append(f"No daily candidate schedules configured. Set {DAILY_CANDIDATE_SCHEDULE_ENV}.")
    return list(dict.fromkeys(item for item in items if item))


def _deployment_next_actions(checks: list[dict[str, Any]]) -> list[str]:
    actions: list[str] = []
    for check in checks:
        if check.get("ok") is not False:
            continue
        name = str(check.get("name") or "")
        path = check.get("path")
        if name == "path.config":
            actions.append(f"Mount or create data/config.py at {path}.")
        elif name == "path.cookies_dir":
            actions.append(f"Mount data/cookies at {path} and add source tracker cookie files such as U2.txt or CHD.txt.")
        elif name in {"path.tmp_dir", "path.job_dir"}:
            actions.append(f"Create the writable directory {path} or fix its permissions.")
        elif name == "path.downloads_path":
            actions.append(f"Mount the qBittorrent download path at {path}, matching the paths used by qBittorrent.")
        elif name == "qbit.config":
            actions.append("Configure DEFAULT.default_torrent_client and TORRENT_CLIENTS.<client> for qBittorrent in data/config.py.")
        elif name == "runtime.ptcli_dependencies":
            actions.append("Install focused ptcli dependencies from requirements-ptcli.txt or rebuild the ptcli Docker image.")
        elif name == "runtime.material_tools":
            actions.append("Install ffmpeg and mediainfo, or rebuild the focused ptcli Docker image.")
        elif name == "security.api_token":
            actions.append("Set PTCLI_API_TOKEN before exposing ptcli-api outside localhost.")
        elif name == "security.api_exposure":
            actions.append("Set PTCLI_API_TOKEN or change the ptcli-api Docker Compose port mapping back to 127.0.0.1:8080:8080.")
        elif name == "automation.daily_candidates":
            actions.extend(_string_list((check.get("details") or {}).get("next_actions")))
        elif name == "docker.compose_daily_schedule":
            actions.append("Add or update the ptcli-daily-schedule service in docker-compose.yml, or run ptcli daily-schedule manually if not using Docker Compose.")
    return actions


def goal_progress_payload(request: dict[str, Any] | None = None) -> dict[str, Any]:
    """Return an AI-readable progress audit for the long-running ptcli product goal."""
    request = request if isinstance(request, dict) else {}
    deployment = deployment_check_payload(request)
    policy_request = _goal_progress_policy_request(request)
    try:
        site_policies = site_policies_payload(policy_request)
    except ServiceError as exc:
        site_policies = {"status": "blocked", "ok": False, "ready": False, "blockers": [str(exc)]}
    try:
        tracker_adapters = sites_payload(policy_request)
    except ServiceError as exc:
        tracker_adapters = {"status": "blocked", "ok": False, "ready": False, "blockers": [str(exc)]}
    tools = _agent_tool_schemas()
    tool_names = {str(tool.get("name")) for tool in tools}
    live_validation_evidence = _goal_progress_live_validation_evidence(request)
    live_validation_preflight = _goal_progress_live_validation_preflight(request, live_validation_evidence)
    progress_items = _goal_progress_items(deployment, site_policies, tracker_adapters, tool_names, live_validation_evidence)
    estimate = _goal_progress_estimate(progress_items)
    blockers = _goal_progress_blockers(progress_items, deployment, site_policies, live_validation_evidence)
    policy_repair_gate = site_policies.get("policy_repair_gate") if isinstance(site_policies.get("policy_repair_gate"), dict) else {}
    policy_config_handoff = site_policies.get("policy_config_handoff") if isinstance(site_policies.get("policy_config_handoff"), dict) else {}
    policy_execution_handoff = site_policies.get("policy_execution_handoff") if isinstance(site_policies.get("policy_execution_handoff"), dict) else {}
    policy_execution_summary = site_policies.get("policy_execution_summary") if isinstance(site_policies.get("policy_execution_summary"), dict) else {}
    policy_execution_plan = site_policies.get("policy_execution_plan") if isinstance(site_policies.get("policy_execution_plan"), dict) else {}
    policy_runtime_contract = site_policies.get("policy_runtime_contract") if isinstance(site_policies.get("policy_runtime_contract"), dict) else {}
    policy_enforcement_bundle = site_policies.get("policy_enforcement_bundle") if isinstance(site_policies.get("policy_enforcement_bundle"), dict) else {}
    config_update_plan = site_policies.get("config_update_plan") if isinstance(site_policies.get("config_update_plan"), dict) else {}
    daily_candidate_plan = deployment.get("daily_candidates") if isinstance(deployment.get("daily_candidates"), dict) else {}
    next_step = _goal_progress_next_step(progress_items, blockers, site_policies, live_validation_evidence, live_validation_preflight, daily_candidate_plan)
    return {
        "kind": "ptcli.goal_progress",
        "status": "ok" if estimate["critical_path_ready"] else "blocked",
        "ok": estimate["critical_path_ready"],
        "objective": "Chinese PT-focused Docker Compose deployed AI-callable retorrent/upload/upload-farming automation service.",
        "completion_estimate": estimate,
        "capabilities": progress_items,
        "critical_path_remaining": _goal_progress_remaining(progress_items),
        "blockers": blockers,
        "next_step": next_step,
        "recommended_tool": next_step.get("tool"),
        "recommended_endpoint": next_step.get("endpoint"),
        "source_context": {
            "source_tracker": policy_request.get("source_tracker"),
            "source_id": policy_request.get("source_id"),
            "source_url": policy_request.get("source_url"),
            "target": policy_request.get("target"),
            "accept_rules": _truthy(policy_request.get("accept_rules")),
            "confirm_upload": _truthy(policy_request.get("confirm_upload")),
        },
        "evidence": {
            "deployment": {
                "ready": deployment.get("ready"),
                "docker_compose_api_ready": (deployment.get("docker_compose") or {}).get("ptcli_api_service_ready"),
                "daily_schedule_ready": (deployment.get("docker_compose") or {}).get("daily_scheduler_service_ready")
                or (deployment.get("docker_compose") or {}).get("daily_schedule_service_ready"),
                "qbit_configured": (deployment.get("qbit") or {}).get("configured"),
                "connectivity_checked": deployment.get("connectivity_checked"),
            },
            "daily_candidates": _goal_progress_daily_candidate_evidence(daily_candidate_plan),
            "qbittorrent": _goal_progress_qbittorrent_evidence(deployment, live_validation_evidence, live_validation_preflight),
            "site_policies": {
                "ready": site_policies.get("ready"),
                "policy_repair_action": policy_repair_gate.get("action"),
                "policy_repair_ready": policy_repair_gate.get("ready"),
                "policy_repair_gate": policy_repair_gate or None,
                "rule_review_request": policy_repair_gate.get("rule_review_request") if isinstance(policy_repair_gate.get("rule_review_request"), dict) else None,
                "config_update_plan": {
                    "ready": config_update_plan.get("ready"),
                    "preferred_shape": config_update_plan.get("preferred_shape"),
                    "structured_patch": config_update_plan.get("structured_patch") if isinstance(config_update_plan.get("structured_patch"), dict) else None,
                    "flat_patch": config_update_plan.get("flat_patch") if isinstance(config_update_plan.get("flat_patch"), dict) else None,
                    "apply_order": config_update_plan.get("apply_order") if isinstance(config_update_plan.get("apply_order"), list) else [],
                    "blockers": _string_list(config_update_plan.get("blockers")),
                }
                if config_update_plan
                else None,
                "policy_config_handoff": policy_config_handoff or None,
                "policy_execution_ready": policy_execution_handoff.get("ready") if policy_execution_handoff else policy_execution_summary.get("ready"),
                "policy_execution_phase": policy_execution_handoff.get("phase"),
                "policy_execution_summary": policy_execution_summary or None,
                "policy_execution_handoff": policy_execution_handoff or None,
                "policy_execution_plan": {
                    "ready": policy_execution_plan.get("ready"),
                    "action": policy_execution_plan.get("action"),
                    "request_defaults": policy_execution_plan.get("request_defaults") if isinstance(policy_execution_plan.get("request_defaults"), dict) else {},
                    "request_default_sources": policy_execution_plan.get("request_default_sources") if isinstance(policy_execution_plan.get("request_default_sources"), dict) else {},
                    "required_confirmations": _string_list(policy_execution_plan.get("required_confirmations")),
                    "recommended_tool": policy_execution_plan.get("recommended_tool"),
                    "recommended_endpoint": policy_execution_plan.get("recommended_endpoint"),
                }
                if policy_execution_plan
                else None,
                "policy_enforcement_bundle": {
                    "ready": policy_enforcement_bundle.get("ready"),
                    "action": policy_enforcement_bundle.get("action"),
                    "request_defaults": policy_enforcement_bundle.get("request_defaults") if isinstance(policy_enforcement_bundle.get("request_defaults"), dict) else {},
                    "live_job_requirements": _string_list(policy_enforcement_bundle.get("live_job_requirements")),
                    "completion_evidence": _string_list(policy_enforcement_bundle.get("completion_evidence")),
                    "blockers": _string_list(policy_enforcement_bundle.get("blockers")),
                }
                if policy_enforcement_bundle
                else None,
                "policy_runtime_contract": {
                    "ready": policy_runtime_contract.get("ready"),
                    "required_request_fields": _string_list(policy_runtime_contract.get("required_request_fields")),
                    "request_defaults": policy_runtime_contract.get("request_defaults") if isinstance(policy_runtime_contract.get("request_defaults"), dict) else {},
                    "protected_fields": policy_runtime_contract.get("protected_fields") if isinstance(policy_runtime_contract.get("protected_fields"), list) else [],
                    "completion_contract": policy_runtime_contract.get("completion_contract") if isinstance(policy_runtime_contract.get("completion_contract"), dict) else None,
                }
                if policy_runtime_contract
                else None,
                "next_step": policy_repair_gate.get("next_step")
                if isinstance(policy_repair_gate.get("next_step"), dict)
                else policy_execution_handoff.get("next_step")
                if isinstance(policy_execution_handoff.get("next_step"), dict)
                else policy_config_handoff.get("next_step")
                if isinstance(policy_config_handoff.get("next_step"), dict)
                else None,
                "read_order": ["policy_repair_gate", "policy_execution_handoff", "policy_execution_plan", "policy_runtime_contract", "config_update_plan"],
                "blockers": _string_list(site_policies.get("blockers")),
            },
            "tracker_adapters": _goal_progress_tracker_adapter_evidence(tracker_adapters),
            "live_validation": live_validation_evidence,
            "live_validation_preflight": live_validation_preflight,
            "tool_count": len(tools),
        },
        "read_order": ["completion_estimate", "critical_path_remaining", "capabilities", "evidence.site_policies", "evidence.live_validation", "evidence.live_validation_preflight", "evidence.qbittorrent", "evidence", "next_step", "blockers"],
        "next_actions": _goal_progress_next_actions(progress_items, blockers, site_policies, live_validation_evidence, live_validation_preflight),
    }


def _goal_progress_policy_request(request: dict[str, Any]) -> dict[str, Any]:
    source_url = str(request.get("source_url") or request.get("source") or "").strip()
    source_tracker = str(request.get("source_tracker") or request.get("from") or "").strip().upper()
    if not source_tracker and source_url:
        try:
            source_reference = resolve_source_reference(source_url)
            source_tracker = str(source_reference.get("tracker") if isinstance(source_reference, dict) else source_reference.tracker).upper()
            if not request.get("source_id"):
                source_id = source_reference.get("torrent_id") if isinstance(source_reference, dict) else source_reference.torrent_id
                request = {**request, "source_id": source_id}
        except ServiceError:
            pass
    return {
        "source_url": source_url or None,
        "source_tracker": source_tracker or "U2",
        "source_id": request.get("source_id"),
        "target": request.get("target") or request.get("to") or "MTEAM",
        "accept_rules": request.get("accept_rules"),
        "confirm_upload": request.get("confirm_upload"),
        "config": request.get("config"),
        "base_dir": request.get("base_dir"),
    }


def _goal_progress_live_validation_preflight(request: dict[str, Any], live_validation_evidence: dict[str, Any]) -> dict[str, Any]:
    if live_validation_evidence.get("ready") is True:
        return {
            "kind": "ptcli.goal_live_validation_preflight",
            "ready": True,
            "status": "already_verified",
            "skipped": True,
            "reason": "live_validation_evidence_complete",
            "blockers": [],
            "next_actions": ["Live validation is already proven by evidence.live_validation.completion_evidence."],
        }
    try:
        readiness = readiness_bundle_payload(request)
    except Exception as exc:  # noqa: BLE001
        return {
            "kind": "ptcli.goal_live_validation_preflight",
            "ready": False,
            "status": "blocked",
            "skipped": False,
            "reason": "readiness_bundle_failed",
            "blockers": [str(exc)],
            "next_actions": ["Resolve goal_live_validation_preflight.blockers, then rerun goal_progress."],
        }
    live_execution_package = readiness.get("live_execution_package") if isinstance(readiness.get("live_execution_package"), dict) else {}
    repair_plan = readiness.get("live_validation_repair_plan") if isinstance(readiness.get("live_validation_repair_plan"), dict) else {}
    validation_report = readiness.get("seedbox_live_validation_report") if isinstance(readiness.get("seedbox_live_validation_report"), dict) else {}
    validation_summary = readiness.get("live_validation_summary") if isinstance(readiness.get("live_validation_summary"), dict) else {}
    validation_sequence = readiness.get("live_validation_sequence") if isinstance(readiness.get("live_validation_sequence"), dict) else {}
    runbook_final_report = readiness.get("seedbox_live_runbook_final_report") if isinstance(readiness.get("seedbox_live_runbook_final_report"), dict) else {}
    next_step = repair_plan.get("next_step") if isinstance(repair_plan.get("next_step"), dict) else validation_summary.get("next_step") if isinstance(validation_summary.get("next_step"), dict) else {}
    ready = bool(live_execution_package.get("ready") or repair_plan.get("ready") or validation_report.get("ready"))
    return {
        "kind": "ptcli.goal_live_validation_preflight",
        "ready": ready,
        "status": live_execution_package.get("status") or repair_plan.get("status") or readiness.get("status"),
        "skipped": False,
        "readiness_ready": readiness.get("ready"),
        "live_readiness_ready": (readiness.get("live_readiness") or {}).get("ready_for_ai") if isinstance(readiness.get("live_readiness"), dict) else None,
        "live_execution_package": live_execution_package,
        "live_validation_repair_plan": repair_plan,
        "seedbox_live_validation_report": validation_report,
        "live_validation_summary": validation_summary,
        "live_validation_sequence": validation_sequence,
        "seedbox_live_runbook_final_report": runbook_final_report,
        "next_step": next_step or None,
        "recommended_tool": next_step.get("tool") if isinstance(next_step, dict) else None,
        "recommended_endpoint": next_step.get("endpoint") if isinstance(next_step, dict) else None,
        "recommended_method": next_step.get("method") if isinstance(next_step, dict) else None,
        "recommended_request": next_step.get("request") if isinstance(next_step, dict) else None,
        "read_order": ["goal_live_validation_preflight", "seedbox_live_runbook_final_report", "live_execution_package", "live_validation_repair_plan", "seedbox_live_validation_report", "live_validation_sequence"],
        "blockers": _string_list(readiness.get("blockers")) + _string_list(repair_plan.get("blockers")) + _string_list(validation_report.get("blockers")),
        "next_actions": _goal_progress_live_validation_preflight_next_actions(ready, next_step, repair_plan, live_execution_package),
    }


def _goal_progress_live_validation_preflight_next_actions(ready: bool, next_step: dict[str, Any], repair_plan: dict[str, Any], live_execution_package: dict[str, Any]) -> list[str]:
    if ready and next_step:
        tool = next_step.get("tool") or "next tool"
        return [f"Run goal_live_validation_preflight.next_step with tool={tool}, then collect job_id or summary_file and rerun goal_progress."]
    blockers = _string_list(repair_plan.get("blockers")) + _string_list(live_execution_package.get("blockers"))
    if blockers:
        return ["Resolve live_validation_preflight blockers before running doctor or live check-and-submit."]
    return ["Inspect goal_live_validation_preflight.read_order, then rerun readiness_bundle with source/target details if no next_step is available."]


def _goal_progress_live_validation_evidence(request: dict[str, Any]) -> dict[str, Any]:
    explicit_job_id = str(request.get("job_id") or request.get("live_job_id") or "").strip()
    explicit_summary_file = str(request.get("summary_file") or request.get("live_summary_file") or "").strip()
    job_dir = _resolve_job_dir(request.get("job_dir"))
    candidates: list[dict[str, Any]] = []
    checked_jobs = 0
    if explicit_summary_file:
        candidates.append(_goal_progress_live_validation_from_summary_file(explicit_summary_file, source="request.summary_file"))
    if explicit_job_id:
        candidates.append(_goal_progress_live_validation_from_job_id(job_dir, explicit_job_id, source="request.job_id"))
    if not explicit_job_id:
        for path in sorted(job_dir.glob("*.json"), key=lambda item: item.stat().st_mtime, reverse=True)[:100]:
            checked_jobs += 1
            candidates.append(_goal_progress_live_validation_from_job_path(path, source="job_dir"))
    valid_candidates = [candidate for candidate in candidates if candidate.get("valid")]
    complete = next((candidate for candidate in valid_candidates if candidate.get("ready")), None)
    submitted = next((candidate for candidate in valid_candidates if str(candidate.get("status") or "").startswith("submitted_")), None)
    ready_to_submit = next((candidate for candidate in valid_candidates if candidate.get("status") == "ready_to_submit"), None)
    best = complete or submitted or ready_to_submit or (valid_candidates[0] if valid_candidates else None)
    blockers = [] if complete or submitted else ["No current-state job or summary evidence has live_validation_completion_audit.report_allowed=true."]
    if best and best.get("blockers"):
        blockers.extend(_string_list(best.get("blockers")))
    status = "complete" if complete else "missing" if not valid_candidates else str(best.get("status") or "incomplete") if best else "incomplete"
    return {
        "kind": "ptcli.goal_live_validation_evidence",
        "ready": bool(complete),
        "status": status,
        "submission_ready": bool(best and best.get("submission_ready")),
        "source": complete.get("source") if complete else best.get("source") if best else None,
        "job_dir": str(job_dir),
        "requested_job_id": explicit_job_id or None,
        "requested_summary_file": explicit_summary_file or None,
        "checked_jobs": checked_jobs,
        "candidate_count": len(valid_candidates),
        "best": best,
        "completion_evidence": complete,
        "live_validation_completion_audit": best.get("live_validation_completion_audit") if isinstance(best, dict) and isinstance(best.get("live_validation_completion_audit"), dict) else None,
        "live_submission_package": best.get("live_submission_package") if isinstance(best, dict) and isinstance(best.get("live_submission_package"), dict) else None,
        "live_submission_final_report": best.get("live_submission_final_report") if isinstance(best, dict) and isinstance(best.get("live_submission_final_report"), dict) else None,
        "live_validation_submission": best.get("live_validation_submission") if isinstance(best, dict) and isinstance(best.get("live_validation_submission"), dict) else None,
        "live_validation_followup": best.get("live_validation_followup") if isinstance(best, dict) and isinstance(best.get("live_validation_followup"), dict) else None,
        "resume_final_report": best.get("resume_final_report") if isinstance(best, dict) and isinstance(best.get("resume_final_report"), dict) else None,
        "job_lifecycle_final_report": best.get("job_lifecycle_final_report") if isinstance(best, dict) and isinstance(best.get("job_lifecycle_final_report"), dict) else None,
        "next_step": best.get("next_step") if isinstance(best, dict) and isinstance(best.get("next_step"), dict) else None,
        "recommended_tool": best.get("recommended_tool") if isinstance(best, dict) else None,
        "recommended_endpoint": best.get("recommended_endpoint") if isinstance(best, dict) else None,
        "recommended_method": best.get("recommended_method") if isinstance(best, dict) else None,
        "recommended_request": best.get("recommended_request") if isinstance(best, dict) else None,
        "required_condition": "live_validation_completion_audit.report_allowed=true and live_validation_completion_audit.failed_checks=[] and live_validation_completion_audit.missing_evidence=[] and live_validation_completion_audit.blockers=[]",
        "blockers": list(dict.fromkeys(blocker for blocker in blockers if blocker)),
        "next_actions": _goal_progress_live_validation_evidence_next_actions(str(status), bool(complete), bool(valid_candidates)),
    }


def _goal_progress_live_validation_from_job_id(job_dir: Path, job_id: str, *, source: str) -> dict[str, Any]:
    if not JOB_ID_PATTERN.fullmatch(job_id):
        return {"valid": False, "source": source, "job_id": job_id, "blockers": ["Invalid job id."]}
    return _goal_progress_live_validation_from_job_path(job_dir / f"{job_id}.json", source=source)


def _goal_progress_live_validation_from_job_path(path: Path, *, source: str) -> dict[str, Any]:
    try:
        job = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        return {"valid": False, "source": source, "job_file": str(path), "blockers": [f"Could not read job evidence: {exc}"]}
    if not isinstance(job, dict):
        return {"valid": False, "source": source, "job_file": str(path), "blockers": ["Job evidence is not an object."]}
    summary_payload = _goal_progress_summary_payload_for_job(job)
    evidence = _goal_progress_live_validation_from_job(job, summary_payload, source=source)
    evidence["job_file"] = str(path)
    return evidence


def _goal_progress_live_validation_from_summary_file(summary_file: str, *, source: str) -> dict[str, Any]:
    path = Path(summary_file).expanduser()
    try:
        summary_payload = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        return {"valid": False, "source": source, "summary_file": str(path), "blockers": [f"Could not read summary evidence: {exc}"]}
    if not isinstance(summary_payload, dict):
        return {"valid": False, "source": source, "summary_file": str(path), "blockers": ["Summary evidence is not an object."]}
    if summary_payload.get("kind") == "ptcli.daily_schedule.summary":
        return {"valid": False, "source": source, "summary_file": str(path), "summary_kind": summary_payload.get("kind"), "blockers": []}
    job = {"job_id": None, "kind": "summary_file", "status": summary_payload.get("status"), "summary_file": str(path), "result": summary_payload, "blockers": _string_list(summary_payload.get("blockers"))}
    evidence = _goal_progress_live_validation_from_job(job, summary_payload, source=source)
    submission_evidence = _goal_progress_live_submission_from_summary_file(str(path))
    if submission_evidence:
        evidence["live_submission_package"] = submission_evidence
        final_report = submission_evidence.get("final_report") if isinstance(submission_evidence.get("final_report"), dict) else {}
        if final_report:
            evidence["live_submission_final_report"] = final_report
        evidence["submission_ready"] = submission_evidence.get("ready") is True
        if evidence.get("ready") is not True and submission_evidence.get("ready") is True:
            evidence["status"] = "ready_to_submit"
            final_next_step = final_report.get("next_step") if final_report and isinstance(final_report.get("next_step"), dict) else {}
            evidence["next_step"] = final_report.get("next_step") if final_report else submission_evidence.get("next_step")
            evidence["recommended_tool"] = final_report.get("recommended_tool") if final_report else submission_evidence.get("recommended_tool")
            evidence["recommended_endpoint"] = final_report.get("recommended_endpoint") if final_report else submission_evidence.get("recommended_endpoint")
            evidence["recommended_method"] = final_next_step.get("method") if final_report else submission_evidence.get("recommended_method")
            evidence["recommended_request"] = final_report.get("recommended_request") if final_report else submission_evidence.get("recommended_request")
            evidence["blockers"] = _string_list(final_report.get("blockers")) if final_report else _string_list(submission_evidence.get("blockers"))
    return evidence


def _goal_progress_live_submission_from_summary_file(summary_file: str) -> dict[str, Any] | None:
    try:
        payload = summary_check_service_payload({"summary_file": summary_file})
    except ServiceError:
        return None
    package = payload.get("live_submission_package") if isinstance(payload.get("live_submission_package"), dict) else {}
    final_report = payload.get("live_submission_final_report") if isinstance(payload.get("live_submission_final_report"), dict) else {}
    submit = package.get("submit") if isinstance(package.get("submit"), dict) else {}
    if not package:
        return None
    final_next_step = final_report.get("next_step") if isinstance(final_report.get("next_step"), dict) else {}
    final_request = final_report.get("recommended_request") if isinstance(final_report.get("recommended_request"), dict) else None
    next_step_request = final_next_step.get("request") if isinstance(final_next_step.get("request"), dict) else None
    submit_request = submit.get("request") if isinstance(submit.get("request"), dict) else None
    return {
        "ready": package.get("ready") is True,
        "status": package.get("status"),
        "summary_file": package.get("summary_file"),
        "final_report": final_report or None,
        "submit": {
            "tool": submit.get("tool"),
            "endpoint": submit.get("endpoint"),
            "method": submit.get("method"),
            "request": submit.get("request") if isinstance(submit.get("request"), dict) else None,
        },
        "after_submit": package.get("after_submit") if isinstance(package.get("after_submit"), dict) else {},
        "report_contract": package.get("report_contract") if isinstance(package.get("report_contract"), dict) else {},
        "next_step": {
            "tool": final_next_step.get("tool") or submit.get("tool") or "source_url_check_and_submit",
            "endpoint": final_next_step.get("endpoint") or submit.get("endpoint") or "/v1/jobs/retorrent/from-url/check-and-submit",
            "method": final_next_step.get("method") or submit.get("method") or "POST",
            "request": next_step_request or submit_request,
            "reason": final_next_step.get("reason") or "doctor_summary_ready_to_submit",
        },
        "recommended_tool": final_report.get("recommended_tool") or submit.get("tool") or "source_url_check_and_submit",
        "recommended_endpoint": final_report.get("recommended_endpoint") or submit.get("endpoint") or "/v1/jobs/retorrent/from-url/check-and-submit",
        "recommended_method": final_next_step.get("method") or submit.get("method") or "POST",
        "recommended_request": final_request or submit_request,
        "blockers": _string_list(package.get("blockers")),
        "next_actions": _string_list(package.get("next_actions")),
    }


def _goal_progress_summary_payload_for_job(job: dict[str, Any]) -> dict[str, Any] | None:
    summary_file = _job_summary_file(job)
    if not summary_file:
        result = job.get("result")
        return result if isinstance(result, dict) else None
    path = Path(summary_file).expanduser()
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        result = job.get("result")
        return result if isinstance(result, dict) else None
    return payload if isinstance(payload, dict) else None


def _goal_progress_live_validation_from_job(job: dict[str, Any], summary_payload: dict[str, Any] | None, *, source: str) -> dict[str, Any]:
    live_user_report = _job_live_user_report(job, summary_payload)
    completion_audit = _job_live_validation_completion_audit(job, summary_payload)
    validation = _job_seedbox_live_validation_completion_report(job, summary_payload)
    closure = _job_closure_summary(job, summary_payload)
    qbit = _job_qbit_enforcement_summary(job, summary_payload)
    live_validation_submission = _job_live_validation_submission(job)
    live_validation_followup = _job_live_validation_followup(job, summary_payload)
    resume_final_report = _job_resume_final_report(job, summary_payload)
    job_lifecycle_final_report = _job_lifecycle_final_report(job, summary_payload)
    missing_evidence = _string_list(completion_audit.get("missing_evidence"))
    blockers = _string_list(completion_audit.get("blockers"))
    ready = completion_audit.get("report_allowed") is True and not _string_list(completion_audit.get("failed_checks")) and not missing_evidence and not blockers
    submitted_status = _goal_progress_submitted_live_validation_status(job, live_validation_followup)
    status = "complete" if ready else submitted_status or "incomplete"
    followup_next_step = _goal_progress_submitted_live_validation_next_step(live_validation_followup)
    resume_next_step = _goal_progress_resume_final_report_next_step(resume_final_report)
    lifecycle_next_step = _goal_progress_job_lifecycle_final_report_next_step(job_lifecycle_final_report)
    next_step = lifecycle_next_step or resume_next_step if status == "submitted_needs_resume" and resume_next_step else lifecycle_next_step or followup_next_step
    return {
        "valid": True,
        "ready": ready,
        "status": status,
        "source": source,
        "job_id": job.get("job_id"),
        "job_status": job.get("status"),
        "kind": job.get("kind"),
        "summary_file": live_user_report.get("summary_file") or _job_summary_file(job),
        "live_validation_submission": live_validation_submission,
        "live_validation_followup": live_validation_followup,
        "resume_final_report": resume_final_report,
        "job_lifecycle_final_report": job_lifecycle_final_report,
        "live_user_report": {
            "report_allowed": live_user_report.get("report_allowed"),
            "ready_for_user_report": live_user_report.get("ready_for_user_report"),
            "report_blocked_reason": live_user_report.get("report_blocked_reason"),
            "source": live_user_report.get("source"),
            "target": live_user_report.get("target"),
            "duplicate_check": live_user_report.get("duplicate_check"),
            "qbit": live_user_report.get("qbit"),
        },
        "live_validation_completion_audit": {
            "report_allowed": completion_audit.get("report_allowed"),
            "ready": completion_audit.get("ready"),
            "verdict": completion_audit.get("verdict"),
            "failed_checks": completion_audit.get("failed_checks"),
            "missing_evidence": completion_audit.get("missing_evidence"),
            "blockers": completion_audit.get("blockers"),
        },
        "seedbox_live_validation_completion_report": {
            "ready_for_user_report": validation.get("ready_for_user_report"),
            "status": validation.get("status"),
            "missing_evidence": validation.get("missing_evidence"),
        },
        "closure_summary": {
            "complete": closure.get("complete"),
            "action": closure.get("action"),
        },
        "qbit_enforcement_summary": {
            "ready": qbit.get("ready") if isinstance(qbit, dict) else None,
            "status": qbit.get("status") if isinstance(qbit, dict) else None,
        },
        "missing_evidence": missing_evidence,
        "blockers": blockers,
        "next_step": next_step,
        "recommended_tool": next_step.get("tool") if isinstance(next_step, dict) else None,
        "recommended_endpoint": next_step.get("endpoint") if isinstance(next_step, dict) else None,
        "recommended_method": next_step.get("method") if isinstance(next_step, dict) else None,
        "recommended_request": next_step.get("request") if isinstance(next_step, dict) else None,
    }


def _goal_progress_submitted_live_validation_status(job: dict[str, Any], followup: dict[str, Any] | None) -> str | None:
    if not isinstance(followup, dict):
        return None
    action = str(followup.get("action") or "")
    job_status = str(job.get("status") or "")
    if action == "poll" or job_status in {"queued", "running"}:
        return "submitted_running"
    if action in {"resume_preview", "resume_execute"}:
        return "submitted_needs_resume"
    if action == "report_complete":
        return "submitted_ready_to_report"
    if job_status in {"blocked", "failed", "cancelled"}:
        return f"submitted_{job_status}"
    if action and action != "inspect":
        return f"submitted_{action}"
    return "submitted_incomplete"


def _goal_progress_submitted_live_validation_next_step(followup: dict[str, Any] | None) -> dict[str, Any] | None:
    if not isinstance(followup, dict):
        return None
    tool = followup.get("recommended_tool")
    endpoint = followup.get("recommended_endpoint")
    method = followup.get("recommended_method")
    if not tool or not endpoint:
        return None
    return {
        "tool": tool,
        "endpoint": endpoint,
        "method": method or ("GET" if tool in {"get_job_status", "get_job_summary"} else "POST"),
        "request": followup.get("recommended_request"),
        "reason": f"live_validation_followup.{followup.get('action') or 'inspect'}",
    }


def _goal_progress_resume_final_report_next_step(report: dict[str, Any] | None) -> dict[str, Any] | None:
    if not isinstance(report, dict):
        return None
    call = report.get("recommended_call") if isinstance(report.get("recommended_call"), dict) else {}
    tool = call.get("tool") or report.get("recommended_tool")
    endpoint = call.get("endpoint") or report.get("recommended_endpoint")
    method = call.get("method") or report.get("recommended_method")
    request = call.get("request") if "request" in call else report.get("recommended_request")
    if not tool or not endpoint:
        return None
    return {
        "tool": tool,
        "endpoint": endpoint,
        "method": method or ("GET" if tool in {"get_job_status", "get_job_summary"} else "POST"),
        "request": request,
        "reason": f"resume_final_report.{report.get('verdict') or report.get('action') or 'inspect'}",
    }


def _goal_progress_job_lifecycle_final_report_next_step(report: dict[str, Any] | None) -> dict[str, Any] | None:
    if not isinstance(report, dict):
        return None
    call = report.get("recommended_call") if isinstance(report.get("recommended_call"), dict) else {}
    step = report.get("primary_next_step") if isinstance(report.get("primary_next_step"), dict) else {}
    tool = call.get("tool") or step.get("tool") or report.get("recommended_tool")
    endpoint = call.get("endpoint") or step.get("endpoint") or report.get("recommended_endpoint")
    method = call.get("method") or step.get("method") or report.get("recommended_method")
    request = call.get("request") if call.get("request") is not None else step.get("request") if "request" in step else report.get("recommended_request")
    if not tool or not endpoint:
        return None
    return {
        "tool": tool,
        "endpoint": endpoint,
        "method": method or ("GET" if tool in {"get_job_status", "get_job_summary"} else "POST"),
        "request": request,
        "reason": f"job_lifecycle_final_report.{report.get('verdict') or report.get('action') or 'inspect'}",
    }


def _goal_progress_live_validation_evidence_next_actions(status: str, ready: bool, has_candidates: bool) -> list[str]:
    if ready:
        return ["Treat seedbox_live_validation as proven for this goal audit and continue with the next incomplete capability."]
    if status == "submitted_needs_resume":
        return ["Read evidence.live_validation.job_lifecycle_final_report, dry-run or execute its recommended_call when safe, then rerun /v1/goal/progress with the same job_id."]
    if status.startswith("submitted_"):
        return ["Follow evidence.live_validation.job_lifecycle_final_report until live_validation_completion_audit.report_allowed=true, then rerun /v1/goal/progress with the same job_id."]
    if has_candidates:
        return ["Open evidence.live_validation.best, resolve its blockers or missing_evidence, then rerun /v1/goal/progress with the same job_dir/job_id."]
    return ["Run readiness_bundle.live_execution_package on a real U2/CHD -> MTEAM seedbox job, then rerun /v1/goal/progress with job_id or job_dir."]


def _goal_progress_daily_candidate_evidence(daily_candidate_plan: dict[str, Any]) -> dict[str, Any]:
    schedule_handoff = daily_candidate_plan.get("schedule_handoff") if isinstance(daily_candidate_plan.get("schedule_handoff"), dict) else {}
    schedule_digest = daily_candidate_plan.get("schedule_digest") if isinstance(daily_candidate_plan.get("schedule_digest"), dict) else {}
    control = daily_candidate_plan.get("candidate_control_summary") if isinstance(daily_candidate_plan.get("candidate_control_summary"), dict) else {}
    notification = daily_candidate_plan.get("notification_payload") if isinstance(daily_candidate_plan.get("notification_payload"), dict) else {}
    delivery = daily_candidate_plan.get("delivery_handoff") if isinstance(daily_candidate_plan.get("delivery_handoff"), dict) else {}
    gate = daily_candidate_plan.get("daily_schedule_gate") if isinstance(daily_candidate_plan.get("daily_schedule_gate"), dict) else {}
    delivery_plan = daily_candidate_plan.get("daily_candidate_delivery_plan") if isinstance(daily_candidate_plan.get("daily_candidate_delivery_plan"), dict) else {}
    execution = daily_candidate_plan.get("daily_candidate_schedule_execution_context") if isinstance(daily_candidate_plan.get("daily_candidate_schedule_execution_context"), dict) else {}
    final_report = daily_candidate_plan.get("daily_candidate_final_report") if isinstance(daily_candidate_plan.get("daily_candidate_final_report"), dict) else {}
    delivery_final = daily_candidate_plan.get("daily_candidate_delivery_final_report") if isinstance(daily_candidate_plan.get("daily_candidate_delivery_final_report"), dict) else {}
    operational_final = daily_candidate_plan.get("daily_candidate_operational_final_report") if isinstance(daily_candidate_plan.get("daily_candidate_operational_final_report"), dict) else {}
    target_fulfillment = daily_candidate_plan.get("daily_candidate_target_fulfillment_report") if isinstance(daily_candidate_plan.get("daily_candidate_target_fulfillment_report"), dict) else {}
    scheduler_final = daily_candidate_plan.get("daily_scheduler_final_report") if isinstance(daily_candidate_plan.get("daily_scheduler_final_report"), dict) else {}
    refill_loop_report = daily_candidate_plan.get("refill_loop_report") if isinstance(daily_candidate_plan.get("refill_loop_report"), dict) else {}
    delivery_result = daily_candidate_plan.get("delivery_result") if isinstance(daily_candidate_plan.get("delivery_result"), dict) else {}
    delivery_audit = daily_candidate_plan.get("delivery_audit") if isinstance(daily_candidate_plan.get("delivery_audit"), dict) else {}
    return {
        "configured": daily_candidate_plan.get("configured"),
        "status": daily_candidate_plan.get("status"),
        "source": daily_candidate_plan.get("source"),
        "env": daily_candidate_plan.get("env"),
        "count": daily_candidate_plan.get("count"),
        "summary_file": daily_candidate_plan.get("summary_file"),
        "summary_evidence": daily_candidate_plan.get("summary_evidence") if isinstance(daily_candidate_plan.get("summary_evidence"), dict) else None,
        "schedules": daily_candidate_plan.get("schedules") if isinstance(daily_candidate_plan.get("schedules"), list) else [],
        "schedule_handoff": schedule_handoff or None,
        "schedule_digest": {
            "target_count": schedule_digest.get("target_count"),
            "selected_count": schedule_digest.get("selected_count"),
            "ready_count": schedule_digest.get("ready_count"),
            "shortfall_count": schedule_digest.get("shortfall_count"),
            "target_met": schedule_digest.get("target_met"),
            "pending_job_count": schedule_digest.get("pending_job_count"),
        }
        if schedule_digest
        else None,
        "candidate_control_summary": control or None,
        "notification_payload": {
            "ready": notification.get("ready"),
            "status": notification.get("status"),
            "submission_ready": notification.get("submission_ready"),
            "counts": notification.get("counts") if isinstance(notification.get("counts"), dict) else {},
        }
        if notification
        else None,
        "delivery_handoff": delivery or None,
        "daily_schedule_gate": gate or None,
        "daily_candidate_delivery_plan": delivery_plan or None,
        "daily_candidate_schedule_execution_context": execution or None,
        "daily_candidate_final_report": final_report or None,
        "daily_candidate_delivery_final_report": delivery_final or None,
        "daily_candidate_operational_final_report": operational_final or None,
        "daily_candidate_target_fulfillment_report": target_fulfillment or None,
        "daily_scheduler_final_report": scheduler_final or None,
        "refill_loop_report": refill_loop_report or None,
        "delivery_result": {
            "status": delivery_result.get("status"),
            "ok": delivery_result.get("ok"),
            "channel_attempted": delivery_result.get("channel_attempted"),
            "payload_fingerprint": delivery_result.get("payload_fingerprint"),
        }
        if delivery_result
        else None,
        "delivery_audit": {
            "ready": delivery_audit.get("ready"),
            "status": delivery_audit.get("status"),
            "payload_fingerprint": delivery_audit.get("payload_fingerprint"),
            "channels": delivery_audit.get("channels") if isinstance(delivery_audit.get("channels"), dict) else {},
            "retry": delivery_audit.get("retry") if isinstance(delivery_audit.get("retry"), dict) else {},
            "blockers": _string_list(delivery_audit.get("blockers")),
        }
        if delivery_audit
        else None,
        "daily_candidate_schedule_final_report": _goal_progress_daily_candidate_schedule_final_report(daily_candidate_plan, schedule_handoff),
        "goal_handoff": _goal_progress_daily_candidate_goal_handoff(daily_candidate_plan, schedule_handoff, control, delivery, delivery_plan, final_report, delivery_final, refill_loop_report),
        "next_step": _goal_progress_daily_candidate_next_step(daily_candidate_plan),
        "blockers": _string_list(daily_candidate_plan.get("blockers")),
        "next_actions": _string_list(daily_candidate_plan.get("next_actions")),
    }


def _goal_progress_daily_candidate_schedule_final_report(daily_candidate_plan: dict[str, Any], schedule_handoff: dict[str, Any]) -> dict[str, Any]:
    next_step = _goal_progress_daily_candidate_next_step(daily_candidate_plan)
    configured = bool(daily_candidate_plan.get("configured"))
    blockers = _string_list(daily_candidate_plan.get("blockers")) or _string_list(schedule_handoff.get("blockers"))
    ready = configured and not blockers
    return {
        "kind": "ptcli.daily_candidate_schedule_final_report",
        "ready": ready,
        "report_allowed": ready,
        "verdict": "schedule_ready" if ready else "schedule_missing",
        "action": "create_schedule_jobs" if ready else "configure_schedule",
        "configured_count": int(daily_candidate_plan.get("count") or schedule_handoff.get("configured_count") or 0),
        "enabled_count": int(schedule_handoff.get("enabled_count") or 0),
        "target_count": int(schedule_handoff.get("target_count") or DEFAULT_CANDIDATE_LIMIT),
        "source": daily_candidate_plan.get("source"),
        "env": daily_candidate_plan.get("env"),
        "schedules": daily_candidate_plan.get("schedules") if isinstance(daily_candidate_plan.get("schedules"), list) else [],
        "schedule_handoff": schedule_handoff or None,
        "next_step": next_step,
        "recommended_tool": next_step.get("tool") if isinstance(next_step, dict) else None,
        "recommended_endpoint": next_step.get("endpoint") if isinstance(next_step, dict) else None,
        "recommended_request": next_step.get("request") if isinstance(next_step, dict) else None,
        "read_order": ["daily_candidate_schedule_final_report", "schedule_handoff", "daily_candidate_delivery_final_report", "candidate_control_summary", "blockers"],
        "complete_when": "daily_candidate_schedule_final_report.ready=true and schedule_handoff.api.create_jobs has been used to create daily candidate jobs.",
        "stop_when": [
            "daily_candidate_schedule_final_report.ready=false",
            "site policy gate is not ready",
            "candidate results are treated as submitted without explicit approval",
        ],
        "safety": {
            "mutates_state": False,
            "uploads": False,
            "creates_jobs_only_after_explicit_call": True,
            "submitting_candidates_requires": ["human approval", "confirm_upload=true", "accept_rules=true", "target duplicate clear"],
        },
        "blockers": blockers,
        "next_actions": _string_list(daily_candidate_plan.get("next_actions")) or _string_list(schedule_handoff.get("next_actions")),
    }


def _goal_progress_daily_candidate_goal_handoff(
    daily_candidate_plan: dict[str, Any],
    schedule_handoff: dict[str, Any],
    control: dict[str, Any],
    delivery: dict[str, Any],
    delivery_plan: dict[str, Any],
    final_report: dict[str, Any],
    delivery_final: dict[str, Any],
    refill_loop_report: dict[str, Any],
) -> dict[str, Any]:
    next_step = _goal_progress_daily_candidate_next_step(daily_candidate_plan)
    configured = bool(daily_candidate_plan.get("configured"))
    blockers = _string_list(daily_candidate_plan.get("blockers")) or _string_list(schedule_handoff.get("blockers"))
    create_jobs = _goal_progress_daily_candidate_api_call(schedule_handoff, "create_jobs")
    inspect_schedule = _goal_progress_daily_candidate_api_call(schedule_handoff, "inspect_schedule")
    publish_call = _goal_progress_daily_candidate_recommended_call(delivery_final, delivery_plan, delivery, action_hint="publish_notification")
    submit_call = _goal_progress_daily_candidate_recommended_call(final_report, control, delivery_plan, action_hint="submit_candidate")
    shortfall_call = _goal_progress_daily_candidate_shortfall_call(final_report, control, delivery_plan)
    refill_call = _goal_progress_daily_candidate_refill_call(refill_loop_report)
    action = "configure_schedule"
    if configured and final_report.get("ready"):
        action = str(final_report.get("action") or "inspect_candidates")
    elif configured:
        action = "create_or_poll_candidate_jobs"
    return {
        "kind": "ptcli.goal_daily_candidate_handoff",
        "ready": bool(configured and not blockers),
        "status": daily_candidate_plan.get("status"),
        "action": action,
        "target_count": int(schedule_handoff.get("target_count") or final_report.get("target_count") or DEFAULT_CANDIDATE_LIMIT),
        "configured": configured,
        "configured_count": int(daily_candidate_plan.get("count") or schedule_handoff.get("configured_count") or 0),
        "enabled_count": int(schedule_handoff.get("enabled_count") or 0),
        "schedule": {
            "source": daily_candidate_plan.get("source"),
            "env": daily_candidate_plan.get("env"),
            "schedules": daily_candidate_plan.get("schedules") if isinstance(daily_candidate_plan.get("schedules"), list) else [],
            "env_example": schedule_handoff.get("env_example") if isinstance(schedule_handoff.get("env_example"), dict) else None,
            "compose": schedule_handoff.get("compose") if isinstance(schedule_handoff.get("compose"), dict) else None,
            "inspect_call": inspect_schedule,
            "create_jobs_call": create_jobs,
        },
        "delivery": {
            "publish_call": publish_call,
            "submit_call": submit_call,
            "shortfall_call": shortfall_call,
            "requires_user_approval_before_submit": True,
        },
        "refill": {
            "loop_report": refill_loop_report or None,
            "loop_call": refill_call,
            "action": refill_loop_report.get("action") if refill_loop_report else None,
            "ready_shortfall_count": refill_loop_report.get("ready_shortfall_count") if refill_loop_report else None,
            "safe_to_submit_count": refill_loop_report.get("safe_to_submit_count") if refill_loop_report else None,
            "target_met": refill_loop_report.get("target_met") if refill_loop_report else None,
            "requires_user_approval_before_submit": True,
        },
        "next_step": next_step,
        "recommended_tool": next_step.get("tool") if isinstance(next_step, dict) else None,
        "recommended_endpoint": next_step.get("endpoint") if isinstance(next_step, dict) else None,
        "recommended_method": next_step.get("method") if isinstance(next_step, dict) else None,
        "recommended_request": next_step.get("request") if isinstance(next_step, dict) else None,
        "read_order": ["goal_handoff", "refill.loop_report", "daily_candidate_schedule_final_report", "schedule_handoff", "daily_candidate_final_report", "daily_candidate_delivery_final_report", "candidate_control_summary"],
        "continue_when": "schedule is configured, candidate jobs are created, digest is read, and explicit user approval is collected before submit_candidate.",
        "stop_when": [
            "goal_handoff.blockers is non-empty",
            "site policy gate is not ready",
            "duplicate_check.exists=true for a candidate",
            "candidate submission is attempted without explicit human approval and confirm_upload=true",
        ],
        "safety": {
            "mutates_state": False,
            "uploads": False,
            "creates_jobs_only_via_create_jobs_call": True,
            "submit_requires_human_approval": True,
            "does_not_bypass_site_rules": True,
        },
        "blockers": blockers,
        "next_actions": _goal_progress_daily_candidate_goal_next_actions(configured, blockers, create_jobs, publish_call, submit_call, shortfall_call, refill_call),
    }


def _goal_progress_daily_candidate_api_call(schedule_handoff: dict[str, Any], name: str) -> dict[str, Any] | None:
    api = schedule_handoff.get("api") if isinstance(schedule_handoff.get("api"), dict) else {}
    call = api.get(name) if isinstance(api.get(name), dict) else {}
    if not call:
        return None
    return {
        "tool": call.get("tool"),
        "endpoint": call.get("endpoint"),
        "method": call.get("method"),
        "request": call.get("request"),
    }


def _goal_progress_daily_candidate_recommended_call(*sources: dict[str, Any], action_hint: str) -> dict[str, Any] | None:
    for source in sources:
        if not isinstance(source, dict) or not source:
            continue
        action = str(source.get("action") or source.get("verdict") or "")
        if action_hint not in action and action_hint == "submit_candidate" and "approval" not in action:
            continue
        tool = source.get("recommended_tool")
        endpoint = source.get("recommended_endpoint")
        request = source.get("recommended_request")
        if tool or endpoint or request:
            return {"tool": tool, "endpoint": endpoint, "method": source.get("recommended_method") or ("POST" if endpoint else None), "request": request, "source_action": action or None}
    return None


def _goal_progress_daily_candidate_shortfall_call(*sources: dict[str, Any]) -> dict[str, Any] | None:
    for source in sources:
        if not isinstance(source, dict) or not source:
            continue
        recovery = source.get("shortfall_recovery") if isinstance(source.get("shortfall_recovery"), dict) else {}
        if not recovery:
            continue
        return {
            "tool": recovery.get("recommended_tool"),
            "endpoint": recovery.get("recommended_endpoint"),
            "method": recovery.get("recommended_method") or ("POST" if recovery.get("recommended_endpoint") else None),
            "request": recovery.get("recommended_request"),
            "action": recovery.get("action"),
        }
    return None


def _goal_progress_daily_candidate_refill_call(refill_loop_report: dict[str, Any]) -> dict[str, Any] | None:
    if not isinstance(refill_loop_report, dict) or not refill_loop_report:
        return None
    call = refill_loop_report.get("recommended_call") if isinstance(refill_loop_report.get("recommended_call"), dict) else {}
    tool = call.get("tool") or refill_loop_report.get("recommended_tool")
    endpoint = call.get("endpoint") or refill_loop_report.get("recommended_endpoint")
    request = call.get("request") if "request" in call else refill_loop_report.get("recommended_request")
    if not (tool or endpoint or request):
        return None
    return {
        "tool": tool,
        "endpoint": endpoint,
        "method": call.get("method") or refill_loop_report.get("recommended_method") or ("GET" if tool in {"list_jobs", "get_job_status", "get_job_summary"} else "POST"),
        "request": request,
        "action": refill_loop_report.get("action"),
        "safe_to_call_now": bool(call.get("safe_to_call_now")),
    }


def _goal_progress_daily_candidate_goal_next_actions(
    configured: bool,
    blockers: list[str],
    create_jobs: dict[str, Any] | None,
    publish_call: dict[str, Any] | None,
    submit_call: dict[str, Any] | None,
    shortfall_call: dict[str, Any] | None,
    refill_call: dict[str, Any] | None,
) -> list[str]:
    if blockers:
        return ["Resolve goal_handoff.blockers before creating or submitting daily candidate jobs."]
    if refill_call:
        action = refill_call.get("action")
        if action == "submit_available":
            return ["Ask the user to approve refill.loop_call.request, keep confirm_upload=true explicit, then call refill.loop_call."]
        return ["Call refill.loop_call, then read refill.loop_report and after_batch before deciding whether to refill again or request user approval."]
    if not configured:
        return ["Configure schedule.env_example.shell or POST schedule.inspect_call.request, then create daily candidate jobs only via schedule.create_jobs_call."]
    if create_jobs:
        return ["Call schedule.create_jobs_call, then read daily_candidate_final_report and daily_candidate_delivery_final_report."]
    if publish_call:
        return ["Publish delivery.publish_call if you only need a candidate digest; this does not upload or submit torrents."]
    if submit_call:
        return ["Ask the user to approve one candidate, keep confirm_upload=true explicit, then call delivery.submit_call."]
    if shortfall_call:
        return ["Use delivery.shortfall_call to refill the candidate list until target_count is met or scan is exhausted."]
    return ["Inspect goal_handoff.read_order before taking the next daily candidate action."]


def _goal_progress_qbittorrent_evidence(deployment: dict[str, Any], live_validation_evidence: dict[str, Any], live_validation_preflight: dict[str, Any]) -> dict[str, Any]:
    qbit = deployment.get("qbit") if isinstance(deployment.get("qbit"), dict) else {}
    best = live_validation_evidence.get("best") if isinstance(live_validation_evidence.get("best"), dict) else {}
    completion = live_validation_evidence.get("completion_evidence") if isinstance(live_validation_evidence.get("completion_evidence"), dict) else {}
    live_source = completion or best
    live_user_report = live_source.get("live_user_report") if isinstance(live_source.get("live_user_report"), dict) else {}
    live_qbit = live_user_report.get("qbit") if isinstance(live_user_report.get("qbit"), dict) else {}
    enforcement = live_source.get("qbit_enforcement_summary") if isinstance(live_source.get("qbit_enforcement_summary"), dict) else {}
    preflight_package = live_validation_preflight.get("live_execution_package") if isinstance(live_validation_preflight.get("live_execution_package"), dict) else {}
    configured = qbit.get("configured") is True
    enforcement_ready = enforcement.get("ready") is True
    live_ready = live_validation_evidence.get("ready") is True
    if enforcement_ready:
        status = "live_enforced"
    elif live_source:
        status = "live_evidence_pending"
    elif configured:
        status = "configured_unverified"
    else:
        status = "not_configured"
    next_step = _goal_progress_qbittorrent_next_step(configured, enforcement_ready, live_ready, preflight_package)
    blockers = [] if configured else ["qBittorrent client is not configured in data/config.py."]
    if live_source and not enforcement_ready:
        blockers.extend(_string_list(enforcement.get("blockers")))
    return {
        "kind": "ptcli.goal_qbittorrent_evidence",
        "ready": bool(configured and (enforcement_ready or live_ready)),
        "status": status,
        "configured": configured,
        "client": qbit.get("client"),
        "torrent_client": qbit.get("torrent_client"),
        "connectivity_checked": qbit.get("connectivity_checked") is True,
        "host_hint": qbit.get("qbit_url"),
        "port_hint": qbit.get("qbit_port"),
        "live_evidence_source": live_source.get("source") if live_source else None,
        "live_job_id": live_source.get("job_id") if live_source else None,
        "live_job_status": live_source.get("job_status") if live_source else None,
        "live_user_report_qbit": live_qbit or None,
        "qbit_enforcement_summary": enforcement or None,
        "live_execution_package_qbit_step": _goal_progress_qbittorrent_package_step(preflight_package),
        "next_step": next_step,
        "recommended_tool": next_step.get("tool"),
        "recommended_endpoint": next_step.get("endpoint"),
        "recommended_method": next_step.get("method"),
        "recommended_request": next_step.get("request"),
        "read_order": ["qbittorrent", "qbit_enforcement_summary", "live_user_report_qbit", "live_execution_package_qbit_step", "next_step"],
        "complete_when": "qbit_enforcement_summary.ready=true from a live job, or live_validation_completion_audit.report_allowed=true with qBittorrent evidence present.",
        "stop_when": ["configured=false", "qbit_enforcement_summary.blockers is non-empty", "live upload is attempted before qBittorrent injection/wait evidence is collected"],
        "blockers": list(dict.fromkeys(blocker for blocker in blockers if blocker)),
        "next_actions": _goal_progress_qbittorrent_next_actions(configured, enforcement_ready, live_source),
    }


def _goal_progress_qbittorrent_package_step(preflight_package: dict[str, Any]) -> dict[str, Any] | None:
    steps = preflight_package.get("steps") if isinstance(preflight_package.get("steps"), list) else []
    for step in steps:
        if not isinstance(step, dict):
            continue
        request = step.get("request") if isinstance(step.get("request"), dict) else {}
        argv = request.get("argv") if isinstance(request.get("argv"), list) else []
        if "--connect-qbit" in argv or "qbit" in str(step.get("name") or "").lower():
            return {
                "name": step.get("name"),
                "tool": step.get("tool"),
                "method": step.get("method"),
                "request": request,
                "continue_when": step.get("continue_when"),
                "stop_when": step.get("stop_when"),
            }
    return None


def _goal_progress_qbittorrent_next_step(configured: bool, enforcement_ready: bool, live_ready: bool, preflight_package: dict[str, Any]) -> dict[str, Any]:
    if not configured:
        return {"tool": "deployment_check", "endpoint": "/v1/deployment/check", "method": "GET", "request": None, "reason": "configure_qbittorrent"}
    if enforcement_ready or live_ready:
        return {"tool": "goal_progress", "endpoint": "/v1/goal/progress", "method": "GET", "request": None, "reason": "qbittorrent_evidence_ready"}
    qbit_step = _goal_progress_qbittorrent_package_step(preflight_package)
    if qbit_step:
        return {"tool": qbit_step.get("tool") or "ptcli_doctor", "endpoint": None, "method": qbit_step.get("method") or "CLI", "request": qbit_step.get("request"), "reason": "collect_qbittorrent_live_evidence"}
    return {"tool": "qbit_inspect", "endpoint": "/v1/qbit/inspect", "method": "GET", "request": None, "reason": "inspect_configured_qbittorrent"}


def _goal_progress_qbittorrent_next_actions(configured: bool, enforcement_ready: bool, live_source: dict[str, Any]) -> list[str]:
    if not configured:
        return ["Configure qBittorrent in data/config.py, then rerun goal_progress."]
    if enforcement_ready:
        return ["Use qbit_enforcement_summary as qBittorrent proof for upload-farming readiness."]
    if live_source:
        return ["Open qbit_enforcement_summary and live_user_report_qbit, resolve blockers, then rerun goal_progress with the same job evidence."]
    return ["Run the live validation doctor or qbit_inspect to collect qBittorrent connectivity, injection, wait, and rate-limit evidence."]


def _goal_progress_tracker_adapter_evidence(tracker_adapters: dict[str, Any]) -> dict[str, Any]:
    final_report = tracker_adapters.get("adapter_extension_final_report") if isinstance(tracker_adapters.get("adapter_extension_final_report"), dict) else {}
    readiness_final_report = tracker_adapters.get("site_extension_readiness_final_report") if isinstance(tracker_adapters.get("site_extension_readiness_final_report"), dict) else {}
    rollout = tracker_adapters.get("tracker_rollout_handoff") if isinstance(tracker_adapters.get("tracker_rollout_handoff"), dict) else {}
    coverage = tracker_adapters.get("adapter_coverage_summary") if isinstance(tracker_adapters.get("adapter_coverage_summary"), dict) else {}
    extension = tracker_adapters.get("extension_handoff") if isinstance(tracker_adapters.get("extension_handoff"), dict) else {}
    validation = tracker_adapters.get("extension_validation_matrix") if isinstance(tracker_adapters.get("extension_validation_matrix"), dict) else {}
    next_step = final_report.get("recommended_call") if isinstance(final_report.get("recommended_call"), dict) else rollout.get("next_step") if isinstance(rollout.get("next_step"), dict) else None
    return {
        "ready": final_report.get("ready") if final_report else tracker_adapters.get("ready"),
        "status": tracker_adapters.get("status"),
        "verdict": final_report.get("verdict"),
        "requested_trackers": final_report.get("requested_trackers") if isinstance(final_report.get("requested_trackers"), list) else tracker_adapters.get("sites"),
        "requested_flow": final_report.get("requested_flow") if isinstance(final_report.get("requested_flow"), dict) else coverage.get("requested_flow") if isinstance(coverage.get("requested_flow"), dict) else None,
        "adapter_extension_final_report": final_report or None,
        "site_extension_readiness_final_report": readiness_final_report or None,
        "tracker_rollout_handoff": rollout or None,
        "adapter_coverage_summary": {
            "ready": coverage.get("ready"),
            "coverage_counts": coverage.get("coverage_counts") if isinstance(coverage.get("coverage_counts"), dict) else {},
            "missing_by_tracker": coverage.get("missing_by_tracker") if isinstance(coverage.get("missing_by_tracker"), dict) else {},
            "priority_next": coverage.get("priority_next") if isinstance(coverage.get("priority_next"), dict) else None,
            "source_ready_trackers": _string_list(coverage.get("source_ready_trackers")),
            "target_ready_trackers": _string_list(coverage.get("target_ready_trackers")),
            "live_reference_sources_to_mteam": _string_list(coverage.get("live_reference_sources_to_mteam")),
        }
        if coverage
        else None,
        "extension_handoff": {
            "ready": extension.get("ready"),
            "phase": extension.get("phase"),
            "recommended_next_tracker": extension.get("recommended_next_tracker"),
            "implementation_order": extension.get("implementation_order") if isinstance(extension.get("implementation_order"), list) else [],
            "next_validation": extension.get("next_validation") if isinstance(extension.get("next_validation"), dict) else None,
        }
        if extension
        else None,
        "extension_validation_matrix": {
            "ready": validation.get("ready"),
            "ready_trackers": _string_list(validation.get("ready_trackers")),
            "blocked_trackers": _string_list(validation.get("blocked_trackers")),
            "next_item": validation.get("next_item") if isinstance(validation.get("next_item"), dict) else None,
        }
        if validation
        else None,
        "next_step": next_step,
        "recommended_tool": next_step.get("tool") if isinstance(next_step, dict) else final_report.get("recommended_tool"),
        "recommended_endpoint": next_step.get("endpoint") if isinstance(next_step, dict) else final_report.get("recommended_endpoint"),
        "recommended_request": next_step.get("request") if isinstance(next_step, dict) else final_report.get("recommended_request"),
        "blockers": _string_list(readiness_final_report.get("blockers")) or _string_list(final_report.get("blockers")) or _string_list(tracker_adapters.get("blockers")),
        "next_actions": _string_list(readiness_final_report.get("next_actions")) or _string_list(final_report.get("next_actions")) or _string_list(tracker_adapters.get("next_actions")),
    }


def _goal_progress_items(
    deployment: dict[str, Any],
    site_policies: dict[str, Any],
    tracker_adapters: dict[str, Any],
    tool_names: set[str],
    live_validation_evidence: dict[str, Any],
) -> list[dict[str, Any]]:
    docker_compose = deployment.get("docker_compose") if isinstance(deployment.get("docker_compose"), dict) else {}
    qbit = deployment.get("qbit") if isinstance(deployment.get("qbit"), dict) else {}
    policy_repair = site_policies.get("policy_repair_gate") if isinstance(site_policies.get("policy_repair_gate"), dict) else {}
    adapter_final_report = tracker_adapters.get("adapter_extension_final_report") if isinstance(tracker_adapters.get("adapter_extension_final_report"), dict) else {}
    live_verified = live_validation_evidence.get("ready") is True
    live_status = str(live_validation_evidence.get("status") or "")
    live_ready_to_submit = live_status == "ready_to_submit"
    live_submitted = live_status.startswith("submitted_")
    return [
        _goal_progress_item(
            "docker_compose_deployment",
            "Docker Compose local/seedbox deployment",
            "complete" if docker_compose.get("ptcli_api_service_ready") else "partial",
            10,
            ["/v1/deployment/check", "docker-compose.yml", "Dockerfile.ptcli"],
            blockers=[] if docker_compose.get("ptcli_api_service_ready") else ["ptcli-api compose service is not fully seedbox-ready."],
        ),
        _goal_progress_item(
            "ai_tool_contracts",
            "OpenAPI, /v1/tools, and OpenClaw/Hermes manifests",
            "complete" if {"agent_manifest", "source_url_check_and_submit", "readiness_bundle"}.issubset(tool_names) else "partial",
            10,
            ["/openapi.json", "/v1/tools", "/.well-known/ptcli-agent.json", "ai/openclaw/ptcli.skill.json", "ai/hermes/ptcli.skill.json"],
        ),
        _goal_progress_item(
            "task_api",
            "Queued job API, polling, summary, resume, and cancel",
            "complete" if {"retorrent_job", "get_job_status", "get_job_summary", "resume_job", "cancel_job"}.issubset(tool_names) else "partial",
            12,
            ["/v1/jobs/retorrent/from-url/check-and-submit", "/v1/jobs/{job_id}", "/v1/jobs/{job_id}/summary", "/v1/jobs/{job_id}/resume"],
        ),
        _goal_progress_item(
            "manual_source_url_retorrent",
            "Manual source-link to target-site retorrent workflow",
            "complete" if live_verified else "partial",
            18,
            ["source_url_check_and_submit", "retorrent_stage_handoff", "closure_handoff", "live_user_report", "seedbox_live_validation_completion_report"],
            blockers=[] if live_verified else ["Requires real seedbox live validation before this can be marked complete."],
        ),
        _goal_progress_item(
            "metadata_and_materials",
            "IMDb/TMDb/Douban/PTGen, MediaInfo/BDInfo, screenshots, and image-host materials",
            "complete" if live_verified else "partial" if {"metadata_prepare_job", "materials_prepare_job", "target_package_prepare_job"}.issubset(tool_names) else "missing",
            10,
            ["metadata_prepare_handoff", "materials_prepare_handoff", "target_package_handoff"],
            blockers=[] if live_verified else ["Material generation and description output still need live content validation across U2/CHD -> MTEAM."],
        ),
        _goal_progress_item(
            "daily_candidates",
            "Daily 10 candidate discovery, digest, and approved submission",
            "partial" if {"daily_candidates_schedule_job", "submit_daily_candidate_job", "daily_candidate_batch_status"}.issubset(tool_names) else "missing",
            10,
            ["daily_schedule_gate", "candidate_control_summary", "daily_candidate_batch_gate"],
            blockers=[] if (deployment.get("daily_candidates") or {}).get("configured") else ["Daily candidate schedule is not configured in env/request."],
        ),
        _goal_progress_item(
            "site_policy_config",
            "Configurable, auditable site rules, rate limits, and seeding requirements",
            "complete" if policy_repair.get("ready") else "partial",
            10,
            ["site_policies.policy_readiness_summary", "site_policies.policy_repair_gate", "site_policies.policy_execution_handoff"],
            blockers=_string_list(policy_repair.get("blockers")) or _string_list(site_policies.get("blockers")),
        ),
        _goal_progress_item(
            "qbittorrent_execution",
            "qBittorrent add/wait/export/inject/category/tag/rate-limit evidence",
            "complete" if live_verified and qbit.get("configured") else "partial" if qbit.get("configured") else "missing",
            8,
            ["qbit_plan", "qbit_limit_audit", "qbit_execution_gate", "/v1/qbit/*"],
            blockers=[] if qbit.get("configured") else ["qBittorrent client is not configured in data/config.py."],
        ),
        _goal_progress_item(
            "tracker_adapters",
            "Extensible Chinese PT tracker adapter/profile model",
            "complete" if adapter_final_report.get("ready") is True and adapter_final_report.get("report_allowed") is True else "partial",
            7,
            ["/v1/sites", "CHINESE_PT_TRACKERS", "extension_handoff", "adapter_extension_final_report"],
            blockers=_string_list(adapter_final_report.get("blockers"))
            or _string_list(tracker_adapters.get("blockers"))
            or ([] if adapter_final_report.get("ready") is True else ["Only U2/CHD -> MTEAM are priority reference flows; more Chinese PT sites still need full live adapter validation."]),
        ),
        _goal_progress_item(
            "seedbox_live_validation",
            "Real seedbox end-to-end live validation",
            "complete" if live_verified else live_status if live_submitted else "ready_to_submit" if live_ready_to_submit else "unverified",
            12,
            ["readiness_bundle.live_execution_package", "live_validation_sequence", "live_user_report", "seedbox_live_validation_completion_report"],
            blockers=[] if live_verified else _string_list(live_validation_evidence.get("blockers")) or ["No current-state evidence proves a real seedbox live run completed from source pull through uploaded torrent seeding."],
        ),
        _goal_progress_item(
            "legacy_cleanup",
            "Trim unrelated Web UI, Discord, overseas tracker, and legacy code",
            "not_started",
            3,
            ["legacy cleanup intentionally deferred until critical service workflow is live-verified"],
            blockers=["Cleanup is intentionally after live service capability, to avoid breaking inherited UA functionality early."],
        ),
    ]


def _goal_progress_item(identifier: str, name: str, status: str, weight: int, evidence: list[str], *, blockers: list[str] | None = None) -> dict[str, Any]:
    status_scores = {
        "complete": 1.0,
        "submitted_ready_to_report": 0.9,
        "submitted_running": 0.78,
        "submitted_needs_resume": 0.75,
        "submitted_blocked": 0.6,
        "submitted_failed": 0.5,
        "submitted_cancelled": 0.45,
        "submitted_incomplete": 0.65,
        "partial": 0.55,
        "ready_to_submit": 0.7,
        "unverified": 0.35,
        "missing": 0.0,
        "not_started": 0.0,
    }
    score = status_scores.get(status, 0.0)
    return {
        "id": identifier,
        "name": name,
        "status": status,
        "weight": weight,
        "score": round(weight * score, 2),
        "evidence": evidence,
        "blockers": blockers or [],
    }


def _goal_progress_estimate(items: list[dict[str, Any]]) -> dict[str, Any]:
    total_weight = sum(int(item.get("weight") or 0) for item in items)
    score = sum(float(item.get("score") or 0.0) for item in items)
    by_status: dict[str, int] = {}
    for item in items:
        by_status[str(item.get("status"))] = by_status.get(str(item.get("status")), 0) + 1
    percent = round((score / total_weight) * 100) if total_weight else 0
    critical_ids = {"manual_source_url_retorrent", "metadata_and_materials", "daily_candidates", "site_policy_config", "qbittorrent_execution", "seedbox_live_validation"}
    critical_ready = all(item.get("status") == "complete" for item in items if item.get("id") in critical_ids)
    return {
        "estimated_percent": percent,
        "implemented_or_partial_percent": percent,
        "total_weight": total_weight,
        "score": round(score, 2),
        "by_status": by_status,
        "critical_path_ready": critical_ready,
        "confidence": "medium",
        "note": "This is a current-state engineering estimate; live tracker and seedbox evidence are required before completion can be claimed.",
    }


def _goal_progress_remaining(items: list[dict[str, Any]]) -> list[dict[str, Any]]:
    remaining_statuses = {"partial", "ready_to_submit", "submitted_ready_to_report", "submitted_running", "submitted_needs_resume", "submitted_blocked", "submitted_failed", "submitted_cancelled", "submitted_incomplete", "missing", "unverified", "not_started"}
    return [
        {
            "id": item.get("id"),
            "status": item.get("status"),
            "blockers": item.get("blockers", []),
            "evidence_to_collect": item.get("evidence", []),
        }
        for item in items
        if item.get("status") in remaining_statuses
    ]


def _goal_progress_blockers(items: list[dict[str, Any]], deployment: dict[str, Any], site_policies: dict[str, Any], live_validation_evidence: dict[str, Any]) -> list[str]:
    blockers: list[str] = []
    blockers.extend(_string_list(deployment.get("blockers")))
    blockers.extend(_string_list(site_policies.get("blockers")))
    if live_validation_evidence.get("ready") is not True:
        blockers.extend(_string_list(live_validation_evidence.get("blockers")))
    for item in items:
        if item.get("id") in {"manual_source_url_retorrent", "metadata_and_materials", "site_policy_config", "qbittorrent_execution", "seedbox_live_validation"}:
            blockers.extend(_string_list(item.get("blockers")))
    return list(dict.fromkeys(blocker for blocker in blockers if blocker))


def _goal_progress_next_step(
    items: list[dict[str, Any]],
    blockers: list[str],
    site_policies: dict[str, Any] | None = None,
    live_validation_evidence: dict[str, Any] | None = None,
    live_validation_preflight: dict[str, Any] | None = None,
    daily_candidate_plan: dict[str, Any] | None = None,
) -> dict[str, Any]:
    by_id = {str(item.get("id")): item for item in items}
    if by_id.get("site_policy_config", {}).get("status") != "complete":
        policy_step = _goal_progress_site_policy_next_step(site_policies)
        if policy_step:
            return policy_step
        return {"tool": "site_policies", "endpoint": "/v1/site-policies", "method": "POST", "reason": "repair_site_policy_gate"}
    if by_id.get("qbittorrent_execution", {}).get("status") == "missing":
        return {"tool": "deployment_check", "endpoint": "/v1/deployment/check", "method": "GET", "reason": "configure_qbittorrent"}
    if by_id.get("seedbox_live_validation", {}).get("status") != "complete":
        live_evidence = live_validation_evidence if isinstance(live_validation_evidence, dict) else {}
        next_step = live_evidence.get("next_step") if isinstance(live_evidence.get("next_step"), dict) else {}
        if str(live_evidence.get("status") or "").startswith("submitted_") and next_step:
            return next_step
        if live_evidence.get("status") == "ready_to_submit" and next_step:
            return next_step
        preflight = live_validation_preflight if isinstance(live_validation_preflight, dict) else {}
        preflight_next = preflight.get("next_step") if isinstance(preflight.get("next_step"), dict) else {}
        if preflight_next:
            return {**preflight_next, "reason": preflight_next.get("reason") or "goal_live_validation_preflight"}
        return {"tool": "readiness_bundle", "endpoint": "/v1/readiness/bundle", "method": "POST", "request": None, "reason": "run_seedbox_live_validation_preflight"}
    if blockers:
        return {"tool": "goal_progress", "endpoint": "/v1/goal/progress", "method": "GET", "reason": "inspect_remaining_blockers"}
    daily_next_step = _goal_progress_daily_candidate_next_step(daily_candidate_plan)
    if daily_next_step:
        return daily_next_step
    return {"tool": "daily_candidates_schedule_job", "endpoint": "/v1/jobs/candidates/daily/schedule", "method": "POST", "reason": "exercise_daily_candidate_workflow"}


def _goal_progress_next_actions(
    items: list[dict[str, Any]],
    blockers: list[str],
    site_policies: dict[str, Any] | None = None,
    live_validation_evidence: dict[str, Any] | None = None,
    live_validation_preflight: dict[str, Any] | None = None,
) -> list[str]:
    next_step = _goal_progress_next_step(items, blockers, site_policies, live_validation_evidence, live_validation_preflight)
    actions = [f"Call {next_step['tool']} at {next_step['endpoint']} and inspect its blockers/next_actions."]
    if any(item.get("id") == "site_policy_config" and item.get("status") != "complete" for item in items):
        actions.append("Use evidence.site_policies.policy_repair_gate.next_step and rule_review_request before live retorrent automation.")
    if any(item.get("id") == "seedbox_live_validation" and item.get("status") == "ready_to_submit" for item in items):
        actions.append("Submit evidence.live_validation.live_submission_final_report.submission.request, then poll the returned job until live_validation_completion_audit.report_allowed=true.")
    elif any(item.get("id") == "seedbox_live_validation" and item.get("status") == "submitted_needs_resume" for item in items):
        actions.append("Read evidence.live_validation.job_lifecycle_final_report and call its recommended_call only when safe or after review before reporting live validation complete.")
    elif any(item.get("id") == "seedbox_live_validation" and str(item.get("status") or "").startswith("submitted_") for item in items):
        actions.append("Follow evidence.live_validation.job_lifecycle_final_report, then rerun goal_progress with the same live job id after the job state changes.")
    elif any(item.get("id") == "seedbox_live_validation" and item.get("status") != "complete" for item in items):
        actions.append("Use readiness_bundle.live_execution_package to run one real U2/CHD -> MTEAM seedbox validation until live_validation_completion_audit.report_allowed=true.")
    if any(item.get("id") == "daily_candidates" and item.get("status") != "complete" for item in items):
        actions.append("Configure a daily candidate schedule and validate a 10-item candidate digest before enabling push delivery.")
    return actions


def _goal_progress_site_policy_next_step(site_policies: dict[str, Any] | None) -> dict[str, Any] | None:
    if not isinstance(site_policies, dict):
        return None
    for container_name in ("policy_repair_gate", "policy_execution_handoff", "policy_config_handoff", "policy_handoff"):
        container = site_policies.get(container_name)
        if not isinstance(container, dict):
            continue
        step = container.get("next_step")
        if isinstance(step, dict) and step.get("tool"):
            return {**step, "reason": step.get("reason") or f"{container_name}.next_step"}
    tool = site_policies.get("recommended_tool")
    endpoint = site_policies.get("recommended_endpoint")
    request = site_policies.get("recommended_request")
    if tool:
        return {"tool": tool, "endpoint": endpoint, "method": "POST" if endpoint else None, "request": request, "reason": "site_policies.recommended"}
    return None


def _goal_progress_daily_candidate_next_step(daily_candidate_plan: dict[str, Any] | None) -> dict[str, Any] | None:
    if not isinstance(daily_candidate_plan, dict):
        return None
    refill_loop_report = daily_candidate_plan.get("refill_loop_report") if isinstance(daily_candidate_plan.get("refill_loop_report"), dict) else {}
    refill_call = _goal_progress_daily_candidate_refill_call(refill_loop_report)
    if refill_loop_report and refill_loop_report.get("action") in {"continue_refill", "submit_available", "poll_jobs", "deliver_digest", "blocked"} and refill_call:
        return {
            "tool": refill_call.get("tool"),
            "endpoint": refill_call.get("endpoint"),
            "method": refill_call.get("method"),
            "request": refill_call.get("request"),
            "reason": f"refill_loop_report.{refill_loop_report.get('action')}",
        }
    scheduler_report = daily_candidate_plan.get("daily_scheduler_final_report") if isinstance(daily_candidate_plan.get("daily_scheduler_final_report"), dict) else {}
    scheduler_call = scheduler_report.get("recommended_call") if isinstance(scheduler_report.get("recommended_call"), dict) else {}
    if scheduler_report and scheduler_report.get("action") in {"request_user_approval", "refill_shortfall", "poll_jobs", "publish_digest", "retry_delivery", "configure_delivery"}:
        tool = scheduler_call.get("tool") or scheduler_report.get("recommended_tool")
        endpoint = scheduler_call.get("endpoint") or scheduler_report.get("recommended_endpoint")
        request = scheduler_call.get("request") if "request" in scheduler_call else scheduler_report.get("recommended_request")
        if tool:
            return {
                "tool": tool,
                "endpoint": endpoint,
                "method": scheduler_call.get("method") or scheduler_report.get("recommended_method") or ("GET" if tool in {"list_jobs", "get_job_status", "get_job_summary"} else "POST"),
                "request": request,
                "reason": f"daily_scheduler_final_report.{scheduler_report.get('action')}",
            }
    handoff = daily_candidate_plan.get("schedule_handoff") if isinstance(daily_candidate_plan.get("schedule_handoff"), dict) else {}
    api = handoff.get("api") if isinstance(handoff.get("api"), dict) else {}
    if daily_candidate_plan.get("configured") and isinstance(api.get("create_jobs"), dict):
        create_jobs = api["create_jobs"]
        return {
            "tool": create_jobs.get("tool") or "daily_candidates_schedule_job",
            "endpoint": create_jobs.get("endpoint") or "/v1/jobs/candidates/daily/schedule",
            "method": create_jobs.get("method") or "POST",
            "request": create_jobs.get("request"),
            "reason": "daily_candidate_schedule_ready",
        }
    if isinstance(api.get("inspect_schedule"), dict):
        inspect_schedule = api["inspect_schedule"]
        return {
            "tool": inspect_schedule.get("tool") or "daily_candidates_schedule",
            "endpoint": inspect_schedule.get("endpoint") or "/v1/candidates/daily/schedule",
            "method": inspect_schedule.get("method") or "POST",
            "request": inspect_schedule.get("request"),
            "reason": "configure_daily_candidate_schedule",
        }
    return {
        "tool": "deployment_check",
        "endpoint": "/v1/deployment/check",
        "method": "GET",
        "request": None,
        "reason": "inspect_daily_candidate_schedule",
    }


