def _live_upload_safety_contract() -> dict[str, Any]:
    return {
        "mutates_state": True,
        "live_upload": True,
        "requires_confirmation": ["accept_rules=true", "confirm_upload=true"],
        "must_stop_when": ["duplicate_check.exists=true", "rule gate not ready", "site policy not ready", "uploaded target torrent cannot be injected for seeding"],
    }


def agent_manifest_payload(*, base_url: str | None = None) -> dict[str, Any]:
    public_base_url = (base_url or os.environ.get("PTCLI_PUBLIC_BASE_URL") or "http://127.0.0.1:8080").rstrip("/")
    tools = tools_payload()["tools"]
    return {
        "schema_version": "ptcli.agent_manifest.v1",
        "name": "ptcli-retorrent",
        "display_name": "PTCLI Retorrent Assistant",
        "description": "AI-callable Chinese PT retorrent, upload, qBittorrent, and daily-candidate automation service.",
        "audience": ["OpenClaw", "Hermes", "OpenAPI-compatible agents"],
        "base_url": public_base_url,
        "auth": {
            "type": "bearer",
            "header": "Authorization",
            "format": "Bearer <PTCLI_API_TOKEN>",
            "required_when": "PTCLI_API_TOKEN is configured on the service.",
            "env": "PTCLI_API_TOKEN",
        },
        "discovery": {
            "health": f"{public_base_url}/health",
            "goal_progress": f"{public_base_url}/v1/goal/progress",
            "deployment_check": f"{public_base_url}/v1/deployment/check",
            "source_url_preflight": f"{public_base_url}/v1/retorrent/source-url/preflight",
            "readiness_bundle": f"{public_base_url}/v1/readiness/bundle",
            "site_policy_rule_review": f"{public_base_url}/v1/site-policies/rule-review",
            "summary_check": f"{public_base_url}/v1/summary/check",
            "materials_prepare": f"{public_base_url}/v1/materials/prepare",
            "materials_prepare_job": f"{public_base_url}/v1/jobs/materials/prepare",
            "metadata_prepare": f"{public_base_url}/v1/metadata/prepare",
            "metadata_prepare_job": f"{public_base_url}/v1/jobs/metadata/prepare",
            "target_package_prepare": f"{public_base_url}/v1/target/package/prepare",
            "target_package_prepare_job": f"{public_base_url}/v1/jobs/target/package/prepare",
            "target_upload_preflight": f"{public_base_url}/v1/target/upload/preflight",
            "target_upload": f"{public_base_url}/v1/target/upload",
            "target_upload_job": f"{public_base_url}/v1/jobs/target/upload",
            "openapi": f"{public_base_url}/openapi.json",
            "tools": f"{public_base_url}/v1/tools",
            "manifest": f"{public_base_url}/.well-known/ptcli-agent.json",
        },
        "safety": {
            "live_upload_requires": ["accept_rules=true", "confirm_upload=true"],
            "never_skip": ["site rule gates", "target duplicate check", "uploaded torrent injection/seeding evidence"],
            "blocked_contract": "When rules, duplicate checks, qBittorrent evidence, or required confirmations are missing, APIs return status=blocked with blockers and next_actions.",
        },
        "skill_contract": _agent_skill_contract(public_base_url),
        "agent_instructions": _agent_instructions(),
        "tool_selection": _agent_tool_selection(),
        "closure_contract": _agent_closure_contract(),
        "default_workflows": _agent_default_workflows(),
        "tools": tools,
        "tool_count": len(tools),
        "openclaw": {
            "skill_id": "ptcli-retorrent",
            "entrypoint": f"{public_base_url}/openapi.json",
            "manifest_url": f"{public_base_url}/v1/openclaw/skill.json",
        },
        "hermes": {
            "skill_id": "ptcli-retorrent",
            "entrypoint": f"{public_base_url}/openapi.json",
            "manifest_url": f"{public_base_url}/v1/hermes/skill.json",
        },
    }


def _agent_skill_contract(public_base_url: str) -> dict[str, Any]:
    return {
        "kind": "ptcli.agent_skill_contract",
        "base_url": public_base_url,
        "load_order": [
            "GET /.well-known/ptcli-agent.json or /v1/openclaw/skill.json or /v1/hermes/skill.json",
            "GET /v1/tools to refresh tool contracts when the service may have changed",
            "POST /v1/deployment/check before live work",
            "POST /v1/readiness/bundle before manual retorrent or daily candidate submission",
        ],
        "primary_entrypoints": {
            "manual_source_url_retorrent": {
                "tool": "source_url_check_and_submit",
                "endpoint": "/v1/jobs/retorrent/from-url/check-and-submit",
                "method": "POST",
                "required": ["source_url", "target", "accept_rules=true", "confirm_upload=true"],
                "recommended": ["save_path or path", "uploaded_qbit_category", "uploaded_qbit_tags"],
            },
            "daily_candidate_digest": {
                "tool": "daily_candidates_schedule_job",
                "endpoint": "/v1/jobs/candidates/daily/schedule",
                "method": "POST",
                "required": ["source_tracker", "target"],
                "primary_control_field": "daily_candidate_operational_final_report",
                "read_result": ["daily_candidate_operational_final_report", "daily_candidate_final_report", "candidate_control_summary", "schedule_digest.daily_candidate_operational_final_report", "schedule_digest.daily_candidate_final_report", "schedule_digest.candidate_control_summary", "schedule_digest.daily_candidate_batch_report", "schedule_digest.approval_queue", "delivery_handoff"],
                "approval_flow": "Only submit candidates through submit_daily_candidate_job after human approval and confirm_upload=true.",
            },
            "resume": {
                "tool": "resume_job",
                "endpoint": "/v1/jobs/{job_id}/resume",
                "method": "POST",
                "required": ["job_id"],
                "restriction": "Use job_control_summary.dry_run_request/recommended_request first, or fall back to job_handoff.recommended_request plus allowlisted overrides.",
            },
        },
        "mandatory_preflight": ["goal_progress", "deployment_check", "readiness_bundle", "site_policies", "policy_application_handoff", "policy_application_report", "target duplicate check"],
        "completion_evidence": ["policy_application_handoff.ready=true", "policy_application_handoff.missing_request_fields=[]", "policy_application_report.ready_for_live_audit=true", "policy_application_report.qbit_evidence_ready=true", "live_validation_final_report.report_allowed=true", "live_validation_final_report.evidence.missing_evidence=[]", "live_validation_final_report.blockers=[]", "live_validation_completion_audit.report_allowed=true", "live_validation_completion_audit.failed_checks=[]", "live_validation_completion_audit.missing_evidence=[]", "live_validation_completion_audit.blockers=[]", "live_user_report.ready_for_user_report=true", "live_user_report.report_allowed=true", "seedbox_live_validation_completion_report.ready_for_user_report=true", "job_control_summary.action=read_summary", "closure_summary.complete=true", "target_upload_handoff.uploaded_seeding_ready=true", "qBittorrent hash/path/size evidence present"],
    }


def _agent_instructions() -> dict[str, Any]:
    return {
        "kind": "ptcli.agent_instructions",
        "role": "Operate ptcli as a cautious local Chinese PT retorrent assistant. Prefer structured JSON APIs and never infer success without reading the relevant handoff fields.",
        "must": [
            "Use source_url_check_and_submit for a user-provided source link plus target unless the user explicitly wants a dry run or split audit.",
            "Read policy_application_handoff, live_validation_completion_audit, live_validation_final_report, live_user_report, job_control_summary, blockers, next_actions, next_step, job_handoff, seedbox_live_validation_completion_report, closure_handoff, and closure_summary before choosing the next call.",
            "Ask for explicit user confirmation before setting accept_rules=true or confirm_upload=true when it was not already supplied by the user.",
            "Stop immediately when duplicate_check.exists=true and report duplicate_check.dupes.",
            "Treat status=blocked as recoverable only when job_control_summary.recommended_call, next_step, or job_handoff.recommended_request names a safe tool.",
            "Report final source, target, torrent hash, content path, uploaded torrent injection, seeding wait, summary_file, and blockers.",
        ],
        "must_not": [
            "Do not upload or submit a daily candidate without confirm_upload=true.",
            "Do not bypass site_policies, rule_obligations, policy_execution_handoff, policy_application_handoff, or duplicate_check.",
            "Do not assume rule_review_fingerprint placeholders satisfy manual review.",
            "Do not mark a job complete from status alone; verify live_validation_completion_audit.report_allowed=true, failed_checks=[], missing_evidence=[], blockers=[], and target uploaded seeding evidence.",
            "Do not retry live upload after a duplicate, rule blocker, or missing uploaded torrent evidence unless the next_step explicitly allows recovery.",
        ],
        "ask_user_when": [
            "accept_rules or confirm_upload is missing for live upload",
            "site policy config_audit reports missing_fields or placeholder_fields",
            "a rule obligation cannot be programmatically verified",
            "multiple target trackers are requested and the next live target is ambiguous",
        ],
        "reporting": {
            "blocked": ["status", "blockers", "next_actions", "next_step", "recommended_tool", "recommended_request"],
            "running": ["job_id", "status_endpoint", "poll_after_seconds", "job_handoff"],
            "complete": ["job_id", "summary_file", "live_validation_completion_audit", "live_validation_final_report", "seedbox_live_validation_completion_report", "closure_summary", "qbit evidence", "uploaded_torrent_hash", "content_path"],
        },
    }


